#define NS_CALC_MAX_DEPTH 64

typedef enum {
    CALC_LENGTH,
    CALC_NUMBER,
    CALC_ANGLE,
    CALC_TIME,
    CALC_RESOLUTION,
    CALC_FLEX,
} ns_calc_kind;

typedef struct ns_calc_linear {
    double px, pct, em, rem, lh, rlh, vw, vh, vmin, vmax;
} ns_calc_linear;

typedef struct ns_calc_term {
    ns_calc_kind kind;
    double px;
    double pct;
    double em;
    double rem;
    double lh;
    double rlh;
    double vw, vh, vmin, vmax;
    double num;
    gboolean unresolved;
    guint8 fn;
    guint8 n_args;
    guint8 arg_none;
    ns_calc_linear args[4];
} ns_calc_term;

static __thread gboolean calc_unresolved;

static gboolean calc_expr_parse(const char **pp, const char *end,
                                ns_calc_term *out, int depth);
