/* sRGB transfer-function decode, mirrored for negative (extended-range) components. */
static double
srgb_to_linear(double c)
{
    double a = fabs(c);
    double v = a <= 0.04045 ? a / 12.92 : pow((a + 0.055) / 1.055, 2.4);
    return c < 0 ? -v : v;
}

static double
srgb_from_linear(double c)
{
    double a = fabs(c);
    double v = a > 0.0031308 ? 1.055 * pow(a, 1.0 / 2.4) - 0.055 : 12.92 * a;
    return c < 0 ? -v : v;
}

static double
a98_to_linear(double c)
{
    double v = pow(fabs(c), 563.0 / 256.0);
    return c < 0 ? -v : v;
}

static double
a98_from_linear(double c)
{
    double v = pow(fabs(c), 256.0 / 563.0);
    return c < 0 ? -v : v;
}

static double
prophoto_to_linear(double c)
{
    double a = fabs(c);
    double v = a <= 16.0 / 512.0 ? a / 16.0 : pow(a, 1.8);
    return c < 0 ? -v : v;
}

static double
prophoto_from_linear(double c)
{
    double a = fabs(c);
    double v = a >= 1.0 / 512.0 ? pow(a, 1.0 / 1.8) : 16.0 * a;
    return c < 0 ? -v : v;
}

static double
rec2020_to_linear(double c)
{
    double v = pow(fabs(c), 2.4);
    return c < 0 ? -v : v;
}

static double
rec2020_from_linear(double c)
{
    double v = pow(fabs(c), 1.0 / 2.4);
    return c < 0 ? -v : v;
}

/* Converts HSL (deg, %, %) to sRGB 0..1 using the CSS Color 4 sample algorithm. */
static void
hsl_to_srgb(const double hsl[3], double rgb[3])
{
    static const double n[3] = { 0.0, 8.0, 4.0 };
    double h = color_hue_normalize(hsl[0]);
    double s = hsl[1] / 100.0, l = hsl[2] / 100.0;
    double a = s * MIN(l, 1.0 - l);
    for (int i = 0; i < 3; i++) {
        double k = fmod(n[i] + h / 30.0, 12.0);
        rgb[i] = l - a * MAX(-1.0, MIN(MIN(k - 3.0, 9.0 - k), 1.0));
    }
}

/* Returns the hue in degrees of an sRGB color, or NaN when achromatic. */
static double
srgb_hue(const double rgb[3])
{
    double r = rgb[0], g = rgb[1], b = rgb[2];
    double max = MAX(r, MAX(g, b)), min = MIN(r, MIN(g, b));
    double d = max - min;
    if (d == 0) return NAN;
    double h;
    if (max == r)      h = (g - b) / d + (g < b ? 6.0 : 0.0);
    else if (max == g) h = (b - r) / d + 2.0;
    else               h = (r - g) / d + 4.0;
    h *= 60.0;
    return h >= 360.0 ? h - 360.0 : h;
}

/* Converts sRGB to HSL (deg, %, %); a negative saturation flips the hue by 180 degrees. */
static void
srgb_to_hsl(const double rgb[3], double hsl[3])
{
    double max = MAX(rgb[0], MAX(rgb[1], rgb[2]));
    double min = MIN(rgb[0], MIN(rgb[1], rgb[2]));
    double l = (min + max) / 2.0;
    double h = srgb_hue(rgb), s = 0.0;
    if (max != min)
        s = (l == 0 || l == 1) ? 0.0 : (max - l) / MIN(l, 1.0 - l);
    if (s < 0) {
        h += 180.0;
        s = fabs(s);
    }
    if (h >= 360.0) h -= 360.0;
    hsl[0] = h;
    hsl[1] = s * 100.0;
    hsl[2] = l * 100.0;
}

/* Converts HWB to sRGB; whiteness + blackness >= 1 yields the normalized gray. */
static void
hwb_to_srgb(const double hwb[3], double rgb[3])
{
    double w = hwb[1] / 100.0, b = hwb[2] / 100.0;
    if (w + b >= 1.0) {
        double gray = w / (w + b);
        rgb[0] = rgb[1] = rgb[2] = gray;
        return;
    }
    double hsl[3] = { hwb[0], 100.0, 50.0 };
    hsl_to_srgb(hsl, rgb);
    for (int i = 0; i < 3; i++) rgb[i] = rgb[i] * (1.0 - w - b) + w;
}

static void
srgb_to_hwb(const double rgb[3], double hwb[3])
{
    hwb[0] = srgb_hue(rgb);
    hwb[1] = MIN(rgb[0], MIN(rgb[1], rgb[2])) * 100.0;
    hwb[2] = (1.0 - MAX(rgb[0], MAX(rgb[1], rgb[2]))) * 100.0;
}

static const double ns_d50_white[3] = {
    0.3457 / 0.3585, 1.0, (1.0 - 0.3457 - 0.3585) / 0.3585,
};

/* Converts CIE Lab to D50-relative XYZ per the CSS Color 4 sample code. */
static void
lab_to_xyz_d50(const double lab[3], double xyz[3])
{
    static const double kappa = 24389.0 / 27.0;
    static const double epsilon = 216.0 / 24389.0;
    double f1 = (lab[0] + 16.0) / 116.0;
    double f0 = lab[1] / 500.0 + f1;
    double f2 = f1 - lab[2] / 200.0;
    double x = f0 * f0 * f0 > epsilon ? f0 * f0 * f0 : (116.0 * f0 - 16.0) / kappa;
    double y = lab[0] > kappa * epsilon ? f1 * f1 * f1 : lab[0] / kappa;
    double z = f2 * f2 * f2 > epsilon ? f2 * f2 * f2 : (116.0 * f2 - 16.0) / kappa;
    xyz[0] = x * ns_d50_white[0];
    xyz[1] = y * ns_d50_white[1];
    xyz[2] = z * ns_d50_white[2];
}

/* Converts D50-relative XYZ to CIE Lab per the CSS Color 4 sample code. */
static void
xyz_d50_to_lab(const double xyz[3], double lab[3])
{
    static const double kappa = 24389.0 / 27.0;
    static const double epsilon = 216.0 / 24389.0;
    double f[3];
    for (int i = 0; i < 3; i++) {
        double v = xyz[i] / ns_d50_white[i];
        f[i] = v > epsilon ? cbrt(v) : (kappa * v + 16.0) / 116.0;
    }
    lab[0] = 116.0 * f[1] - 16.0;
    lab[1] = 500.0 * (f[0] - f[1]);
    lab[2] = 200.0 * (f[1] - f[2]);
}

/* Converts LCH-style polar coordinates to Lab-style rectangular; non-finite chroma is 0. */
static void
polar_to_rect(const double lch[3], double lab[3])
{
    double c = isfinite(lch[1]) ? lch[1] : 0.0;
    double rad = color_hue_normalize(lch[2]) * G_PI / 180.0;
    lab[0] = lch[0];
    lab[1] = c * cos(rad);
    lab[2] = c * sin(rad);
}

static void
rect_to_polar(const double lab[3], double lch[3])
{
    lch[0] = lab[0];
    lch[1] = hypot(lab[1], lab[2]);
    lch[2] = color_hue_normalize(atan2(lab[2], lab[1]) * 180.0 / G_PI);
}

/* Converts OKLab to D65 XYZ through the cubed LMS intermediate. */
static void
oklab_to_xyz(const double oklab[3], double xyz[3])
{
    double lms[3];
    mat3_apply(ns_oklab_to_lms, oklab, lms);
    for (int i = 0; i < 3; i++) lms[i] = lms[i] * lms[i] * lms[i];
    mat3_apply(ns_lms_to_xyz, lms, xyz);
}

static void
xyz_to_oklab(const double xyz[3], double oklab[3])
{
    double lms[3];
    mat3_apply(ns_xyz_to_lms, xyz, lms);
    for (int i = 0; i < 3; i++) lms[i] = cbrt(lms[i]);
    mat3_apply(ns_lms_to_oklab, lms, oklab);
}

static void
color_space_to_srgb(ns_css_color_space space, const double c[3], double rgb[3]);

/* Converts coordinates in any supported color space to D65 XYZ. */
static void
color_space_to_xyz(ns_css_color_space space, const double c[3], double xyz[3])
{
    double lin[3], tmp[3];
    switch (space) {
    case NS_CSS_COLOR_LEGACY:
    case NS_CSS_COLOR_SRGB:
        for (int i = 0; i < 3; i++) lin[i] = srgb_to_linear(c[i]);
        mat3_apply(ns_srgb_to_xyz, lin, xyz);
        return;
    case NS_CSS_COLOR_HSL:
    case NS_CSS_COLOR_HWB:
        color_space_to_srgb(space, c, tmp);
        color_space_to_xyz(NS_CSS_COLOR_SRGB, tmp, xyz);
        return;
    case NS_CSS_COLOR_SRGB_LINEAR:
        mat3_apply(ns_srgb_to_xyz, c, xyz);
        return;
    case NS_CSS_COLOR_DISPLAY_P3:
        for (int i = 0; i < 3; i++) lin[i] = srgb_to_linear(c[i]);
        mat3_apply(ns_p3_to_xyz, lin, xyz);
        return;
    case NS_CSS_COLOR_DISPLAY_P3_LINEAR:
        mat3_apply(ns_p3_to_xyz, c, xyz);
        return;
    case NS_CSS_COLOR_A98_RGB:
        for (int i = 0; i < 3; i++) lin[i] = a98_to_linear(c[i]);
        mat3_apply(ns_a98_to_xyz, lin, xyz);
        return;
    case NS_CSS_COLOR_PROPHOTO_RGB:
        for (int i = 0; i < 3; i++) lin[i] = prophoto_to_linear(c[i]);
        mat3_apply(ns_prophoto_to_xyz_d50, lin, tmp);
        mat3_apply(ns_d50_to_d65, tmp, xyz);
        return;
    case NS_CSS_COLOR_REC2020:
        for (int i = 0; i < 3; i++) lin[i] = rec2020_to_linear(c[i]);
        mat3_apply(ns_rec2020_to_xyz, lin, xyz);
        return;
    case NS_CSS_COLOR_XYZ_D65:
        for (int i = 0; i < 3; i++) xyz[i] = c[i];
        return;
    case NS_CSS_COLOR_XYZ_D50:
        mat3_apply(ns_d50_to_d65, c, xyz);
        return;
    case NS_CSS_COLOR_LAB:
        lab_to_xyz_d50(c, tmp);
        mat3_apply(ns_d50_to_d65, tmp, xyz);
        return;
    case NS_CSS_COLOR_LCH:
        polar_to_rect(c, lin);
        lab_to_xyz_d50(lin, tmp);
        mat3_apply(ns_d50_to_d65, tmp, xyz);
        return;
    case NS_CSS_COLOR_OKLAB:
        oklab_to_xyz(c, xyz);
        return;
    case NS_CSS_COLOR_OKLCH:
        polar_to_rect(c, lin);
        oklab_to_xyz(lin, xyz);
        return;
    }
}

/* Converts D65 XYZ to coordinates in the given color space. */
static void
color_space_from_xyz(ns_css_color_space space, const double xyz[3], double c[3])
{
    double lin[3], tmp[3];
    switch (space) {
    case NS_CSS_COLOR_LEGACY:
    case NS_CSS_COLOR_SRGB:
        mat3_apply(ns_xyz_to_srgb, xyz, lin);
        for (int i = 0; i < 3; i++) c[i] = srgb_from_linear(lin[i]);
        return;
    case NS_CSS_COLOR_HSL:
        color_space_from_xyz(NS_CSS_COLOR_SRGB, xyz, tmp);
        srgb_to_hsl(tmp, c);
        return;
    case NS_CSS_COLOR_HWB:
        color_space_from_xyz(NS_CSS_COLOR_SRGB, xyz, tmp);
        srgb_to_hwb(tmp, c);
        return;
    case NS_CSS_COLOR_SRGB_LINEAR:
        mat3_apply(ns_xyz_to_srgb, xyz, c);
        return;
    case NS_CSS_COLOR_DISPLAY_P3:
        mat3_apply_inverse(ns_p3_to_xyz, xyz, lin);
        for (int i = 0; i < 3; i++) c[i] = srgb_from_linear(lin[i]);
        return;
    case NS_CSS_COLOR_DISPLAY_P3_LINEAR:
        mat3_apply_inverse(ns_p3_to_xyz, xyz, c);
        return;
    case NS_CSS_COLOR_A98_RGB:
        mat3_apply_inverse(ns_a98_to_xyz, xyz, lin);
        for (int i = 0; i < 3; i++) c[i] = a98_from_linear(lin[i]);
        return;
    case NS_CSS_COLOR_PROPHOTO_RGB:
        mat3_apply(ns_d65_to_d50, xyz, tmp);
        mat3_apply_inverse(ns_prophoto_to_xyz_d50, tmp, lin);
        for (int i = 0; i < 3; i++) c[i] = prophoto_from_linear(lin[i]);
        return;
    case NS_CSS_COLOR_REC2020:
        mat3_apply_inverse(ns_rec2020_to_xyz, xyz, lin);
        for (int i = 0; i < 3; i++) c[i] = rec2020_from_linear(lin[i]);
        return;
    case NS_CSS_COLOR_XYZ_D65:
        for (int i = 0; i < 3; i++) c[i] = xyz[i];
        return;
    case NS_CSS_COLOR_XYZ_D50:
        mat3_apply(ns_d65_to_d50, xyz, c);
        return;
    case NS_CSS_COLOR_LAB:
        mat3_apply(ns_d65_to_d50, xyz, tmp);
        xyz_d50_to_lab(tmp, c);
        return;
    case NS_CSS_COLOR_LCH:
        mat3_apply(ns_d65_to_d50, xyz, tmp);
        xyz_d50_to_lab(tmp, lin);
        rect_to_polar(lin, c);
        return;
    case NS_CSS_COLOR_OKLAB:
        xyz_to_oklab(xyz, c);
        return;
    case NS_CSS_COLOR_OKLCH:
        xyz_to_oklab(xyz, lin);
        rect_to_polar(lin, c);
        return;
    }
}

/* Converts color coordinates to sRGB, directly for sRGB/HSL/HWB and otherwise via XYZ. */
static void
color_space_to_srgb(ns_css_color_space space, const double c[3], double rgb[3])
{
    double xyz[3];
    switch (space) {
    case NS_CSS_COLOR_LEGACY:
    case NS_CSS_COLOR_SRGB:
        for (int i = 0; i < 3; i++) rgb[i] = c[i];
        return;
    case NS_CSS_COLOR_HSL:
        hsl_to_srgb(c, rgb);
        return;
    case NS_CSS_COLOR_HWB:
        hwb_to_srgb(c, rgb);
        return;
    default:
        color_space_to_xyz(space, c, xyz);
        color_space_from_xyz(NS_CSS_COLOR_SRGB, xyz, rgb);
        return;
    }
}

/* Converts sRGB to the given space, directly for sRGB/HSL/HWB and otherwise via XYZ. */
static void
color_space_from_srgb(ns_css_color_space space, const double rgb[3], double c[3])
{
    double xyz[3];
    switch (space) {
    case NS_CSS_COLOR_LEGACY:
    case NS_CSS_COLOR_SRGB:
        for (int i = 0; i < 3; i++) c[i] = rgb[i];
        return;
    case NS_CSS_COLOR_HSL:
        srgb_to_hsl(rgb, c);
        return;
    case NS_CSS_COLOR_HWB:
        srgb_to_hwb(rgb, c);
        return;
    default:
        color_space_to_xyz(NS_CSS_COLOR_SRGB, rgb, xyz);
        color_space_from_xyz(space, xyz, c);
        return;
    }
}

/* Snaps near-zero saturation/chroma to zero and normalizes HWB grays before conversion. */
static void
color_make_achromatic(ns_css_color_space space, double c[3])
{
    switch (space) {
    case NS_CSS_COLOR_HSL:
        if (fabs(c[1]) <= 0.001) c[1] = 0.0;
        return;
    case NS_CSS_COLOR_HWB: {
        double sum = c[1] + c[2];
        if (sum >= 99.999 - 1e-9 && sum > 0) {
            c[1] = c[1] * 100.0 / sum;
            c[2] = c[2] * 100.0 / sum;
        }
        return;
    }
    case NS_CSS_COLOR_LCH:
        if (c[1] <= 0.0015) c[1] = 0.0;
        return;
    case NS_CSS_COLOR_OKLCH:
        if (c[1] <= 0.000004) c[1] = 0.0;
        return;
    default:
        return;
    }
}

/* Reports whether the hue is powerless (achromatic) in a polar space; zeroes tiny chroma. */
static gboolean
color_hue_powerless(ns_css_color_space space, double c[3])
{
    switch (space) {
    case NS_CSS_COLOR_HSL:
        if (!isnan(c[0]) && fabs(c[1]) > 0.001) return FALSE;
        c[1] = 0.0;
        return TRUE;
    case NS_CSS_COLOR_HWB:
        return isnan(c[0]) || c[1] + c[2] >= 99.999 - 1e-9;
    case NS_CSS_COLOR_LCH:
        if (c[1] > 0.0015) return FALSE;
        c[1] = 0.0;
        return TRUE;
    case NS_CSS_COLOR_OKLCH:
        if (c[1] > 0.000004) return FALSE;
        c[1] = 0.0;
        return TRUE;
    default:
        return FALSE;
    }
}

/* Computes extra missing-component bits implied when converting between polar/rect spaces. */
static guint8
color_missing_sets(ns_css_color_space from, guint8 none,
                   ns_css_color_space to)
{
    gboolean from_lab = from == NS_CSS_COLOR_LAB || from == NS_CSS_COLOR_OKLAB;
    gboolean to_lab = to == NS_CSS_COLOR_LAB || to == NS_CSS_COLOR_OKLAB;
    gboolean from_lch = from == NS_CSS_COLOR_LCH || from == NS_CSS_COLOR_OKLCH;
    if ((none & 7) == 7) return 7;
    if (from_lab && (none & 6) == 6) {
        switch (to) {
        case NS_CSS_COLOR_LCH:
        case NS_CSS_COLOR_OKLCH: return 6;
        case NS_CSS_COLOR_HSL:   return 3;
        case NS_CSS_COLOR_HWB:   return 1;
        default:                 return 0;
        }
    }
    if (to_lab && ((from_lch && (none & 6) == 6) ||
                   (from == NS_CSS_COLOR_HSL && (none & 3) == 3)))
        return 6;
    if ((none & 6) == 6 &&
        ((from == NS_CSS_COLOR_HWB && to == NS_CSS_COLOR_HSL) ||
         (from == NS_CSS_COLOR_HSL && to == NS_CSS_COLOR_HWB)))
        return 6;
    return 0;
}

/* Converts a color to target space, carrying forward missing components per CSS Color 4 §12. */
static void
color_convert(const ns_color *in, ns_css_color_space target, ns_color *out)
{
    *out = *in;
    out->legacy = FALSE;
    if (target == NS_CSS_COLOR_LEGACY) target = NS_CSS_COLOR_SRGB;
    ns_css_color_space from = in->space == NS_CSS_COLOR_LEGACY
        ? NS_CSS_COLOR_SRGB : in->space;
    if (from == target) {
        out->space = target;
        return;
    }
    double src[3] = { in->c[0], in->c[1], in->c[2] };
    for (int i = 0; i < 3; i++)
        if (in->none & (1 << i)) src[i] = 0.0;
    color_make_achromatic(from, src);
    if (color_space_is_srgb_family(from) && color_space_is_srgb_family(target)) {
        double rgb[3];
        color_space_to_srgb(from, src, rgb);
        color_space_from_srgb(target, rgb, out->c);
    } else {
        double xyz[3];
        color_space_to_xyz(from, src, xyz);
        color_space_from_xyz(target, xyz, out->c);
    }
    out->space = target;
    out->none = in->none & NS_COLOR_NONE_ALPHA;
    int hue = color_space_hue_index(target);
    if (hue >= 0 && color_hue_powerless(target, out->c)) {
        out->none |= (guint8)(1 << hue);
        out->c[hue] = 0.0;
    }
    ns_color_category src_cat[3], dst_cat[3];
    color_space_categories(from, src_cat);
    color_space_categories(target, dst_cat);
    for (int i = 0; i < 3; i++) {
        if (!(in->none & (1 << i)) || src_cat[i] == NS_COLOR_CAT_NONE) continue;
        for (int j = 0; j < 3; j++) {
            if (dst_cat[j] != src_cat[i]) continue;
            out->none |= (guint8)(1 << j);
            out->c[j] = 0.0;
        }
    }
    out->none |= color_missing_sets(from, in->none & 7, target);
    for (int i = 0; i < 3; i++)
        if (!isfinite(out->c[i]) || (out->none & (1 << i))) out->c[i] = 0.0;
}

/* Maps a 0..1 component to a rounded, clamped byte; NaN becomes 0, +inf 255. */
static guint8
color_unit_byte(double v)
{
    if (isnan(v)) return 0;
    if (!isfinite(v)) return v > 0 ? 255 : 0;
    double scaled = floor(v * 255.0 + 0.5 + 1e-7);
    return (guint8)CLAMP(scaled, 0.0, 255.0);
}

/* Converts a color to 8-bit sRGB RGBA, treating missing components as zero. */
static void
color_to_bytes(const ns_color *col, guint8 rgba[4])
{
    double c[3], rgb[3];
    for (int i = 0; i < 3; i++)
        c[i] = (col->none & (1 << i)) ? 0.0 : col->c[i];
    color_space_to_srgb(col->space, c, rgb);
    for (int i = 0; i < 3; i++) rgba[i] = color_unit_byte(rgb[i]);
    rgba[3] = (col->none & NS_COLOR_NONE_ALPHA)
        ? 0 : color_unit_byte(col->alpha);
}

/* Converts v to degrees per the deg/turn/grad/rad unit at *endp, consuming the unit. */
static double
css_angle_value_degrees(double v, char **endp)
{
    char *end = *endp;
    if (g_ascii_strncasecmp(end, "deg", 3) == 0 && !is_ident(end[3])) {
        *endp = end + 3;
    } else if (g_ascii_strncasecmp(end, "turn", 4) == 0 &&
               !is_ident(end[4])) {
        v *= 360.0;
        *endp = end + 4;
    } else if (g_ascii_strncasecmp(end, "grad", 4) == 0 &&
               !is_ident(end[4])) {
        v *= 0.9;
        *endp = end + 4;
    } else if (g_ascii_strncasecmp(end, "rad", 3) == 0 &&
               !is_ident(end[3])) {
        v = v * 180.0 / G_PI;
        *endp = end + 3;
    }
    return v;
}

static const char *
color_skip_ws(const char *p, const char *end)
{
    while (p < end && ns_is_ascii_ws(*p)) p++;
    return p;
}

/* Returns the end of a CSS number token (sign, digits, fraction, exponent), or p if none. */
static const char *
color_number_end(const char *p, const char *end)
{
    const char *q = p;
    if (q < end && (*q == '+' || *q == '-')) q++;
    const char *digits = q;
    while (q < end && g_ascii_isdigit(*q)) q++;
    gboolean whole = q > digits;
    gboolean frac = FALSE;
    if (q + 1 < end && *q == '.' && g_ascii_isdigit(q[1])) {
        q++;
        while (q < end && g_ascii_isdigit(*q)) q++;
        frac = TRUE;
    }
    if (!whole && !frac) return p;
    if (q < end && (*q == 'e' || *q == 'E')) {
        const char *e = q + 1;
        if (e < end && (*e == '+' || *e == '-')) e++;
        if (e < end && g_ascii_isdigit(*e)) {
            while (e < end && g_ascii_isdigit(*e)) e++;
            q = e;
        }
    }
    return q;
}

/* Evaluates a calc()-style color channel to a number, angle or percentage. */
static gboolean
color_math_arg(const char *start, const char *end, ns_color_arg *out)
{
    const char *p = start;
    ns_calc_term t;
    gboolean outer_unresolved = calc_unresolved;
    calc_unresolved = FALSE;
    gboolean ok = calc_expr_parse(&p, end, &t, 0);
    gboolean unresolved = calc_unresolved;
    calc_unresolved = outer_unresolved;
    if (!ok) return FALSE;
    calc_skip_ws(&p, end);
    if (p != end || (unresolved && !t.unresolved)) return FALSE;
    if (t.kind == CALC_NUMBER) {
        out->v = t.num;
        return TRUE;
    }
    if (t.kind == CALC_ANGLE) {
        out->v = t.num;
        out->angle = TRUE;
        return TRUE;
    }
    if (t.kind == CALC_LENGTH && t.px == 0 && t.em == 0 && t.rem == 0 &&
        t.lh == 0 && t.rlh == 0) {
        out->v = t.pct;
        out->percent = TRUE;
        return TRUE;
    }
    return FALSE;
}

/* Reads one color channel: number, percentage, angle, math function or none; advances *pp. */
static gboolean
color_read_arg(const char **pp, const char *end, ns_color_arg *out)
{
    const char *p = *pp;
    memset(out, 0, sizeof *out);
    const char *num_end = color_number_end(p, end);
    if (num_end != p) {
        char *text = g_strndup(p, (gsize)(num_end - p));
        double v = g_ascii_strtod(text, NULL);
        g_free(text);
        const char *q = num_end;
        if (q < end && *q == '%') {
            out->percent = TRUE;
            q++;
        } else if (q < end && is_ident_start(*q)) {
            const char *u = q;
            while (q < end && is_ident(*q)) q++;
            char *unit = g_strndup(u, (gsize)(q - u));
            char *unit_end = unit;
            double deg = css_angle_value_degrees(v, &unit_end);
            gboolean ok = unit_end != unit && *unit_end == '\0';
            g_free(unit);
            if (!ok) return FALSE;
            out->angle = TRUE;
            v = deg;
        }
        if (q < end && (is_ident(*q) || *q == '.' || *q == '%')) return FALSE;
        out->v = v;
        *pp = q;
        return TRUE;
    }
    if (p >= end || !is_ident_start(*p)) return FALSE;
    const char *id = p;
    while (p < end && is_ident(*p)) p++;
    gsize n = (gsize)(p - id);
    if (p < end && *p == '(') {
        const char *close = match_close_paren(p + 1, end);
        if (!close) return FALSE;
        gboolean ok = n == 4 && g_ascii_strncasecmp(id, "calc", 4) == 0
            ? color_math_arg(p + 1, close, out)
            : color_math_arg(id, close + 1, out);
        if (!ok) return FALSE;
        out->math = TRUE;
        *pp = close + 1;
        return TRUE;
    }
    if (n == 4 && g_ascii_strncasecmp(id, "none", 4) == 0) {
        out->none = TRUE;
        *pp = p;
        return TRUE;
    }
    return FALSE;
}

/* Parses color function channels in legacy comma or modern space/slash syntax. */
static gboolean
color_args_parse(const char *p, const char *end, ns_color_args *out)
{
    memset(out, 0, sizeof *out);
    int slash_at = -1;
    const char *prev_end = p;
    while (1) {
        p = color_skip_ws(p, end);
        if (p >= end) break;
        if (out->count > 0) {
            gboolean spaced = p != prev_end;
            if (*p == ',') {
                if (out->count == 1) out->legacy = TRUE;
                else if (!out->legacy) return FALSE;
                p = color_skip_ws(p + 1, end);
            } else if (out->legacy) {
                return FALSE;
            } else if (*p == '/') {
                if (slash_at >= 0 || out->count != 3) return FALSE;
                slash_at = out->count;
                p = color_skip_ws(p + 1, end);
            } else if (!spaced) {
                return FALSE;
            }
        }
        if (out->count >= 4 || p >= end) return FALSE;
        if (!color_read_arg(&p, end, &out->args[out->count])) return FALSE;
        prev_end = p;
        out->count++;
    }
    if (out->count < 3) return FALSE;
    if (!out->legacy && out->count == 4 && slash_at != 3) return FALSE;
    out->has_alpha = out->count == 4;
    if (out->legacy)
        for (int i = 0; i < out->count; i++)
            if (out->args[i].none) return FALSE;
    return TRUE;
}

/* Returns a channel's value with percentages scaled to percent_full; none and NaN yield 0. */
static double
color_arg_value(const ns_color_arg *a, double percent_full)
{
    if (a->none) return 0.0;
    double v = a->percent ? a->v * percent_full / 100.0 : a->v;
    return isnan(v) ? 0.0 : v;
}

/* Sets alpha from the optional fourth channel, clamped to 0..1; none marks alpha missing. */
static gboolean
color_alpha_from_args(const ns_color_args *args, ns_color *out)
{
    out->alpha = 1.0;
    if (!args->has_alpha) return TRUE;
    const ns_color_arg *a = &args->args[3];
    if (a->angle) return FALSE;
    if (a->none) {
        out->none |= NS_COLOR_NONE_ALPHA;
        out->alpha = 0.0;
        return TRUE;
    }
    out->alpha = CLAMP(color_arg_value(a, 1.0), 0.0, 1.0);
    return TRUE;
}

/* Builds an sRGB color from rgb()/rgba() channels; legacy syntax forbids mixed percentages. */
static gboolean
color_build_rgb(const ns_color_args *args, gboolean relative, ns_color *out)
{
    if (args->legacy) {
        if (relative) return FALSE;
        for (int i = 1; i < 3; i++)
            if (args->args[i].percent != args->args[0].percent) return FALSE;
    }
    out->space = NS_CSS_COLOR_SRGB;
    out->legacy = !relative;
    for (int i = 0; i < 3; i++) {
        const ns_color_arg *a = &args->args[i];
        if (a->angle) return FALSE;
        if (a->none) {
            out->none |= (guint8)(1 << i);
            out->c[i] = 0.0;
            continue;
        }
        double v = a->percent ? color_arg_value(a, 1.0)
                              : color_arg_value(a, 1.0) / 255.0;
        if (!relative || !isfinite(v)) v = CLAMP(v, 0.0, 1.0);
        out->c[i] = v;
    }
    return color_alpha_from_args(args, out);
}

/* Builds an HSL or HWB color from parsed channels, normalizing hue and clamping as required. */
static gboolean
color_build_hsl(const ns_color_args *args, gboolean hwb, gboolean relative,
                ns_color *out)
{
    if (args->legacy && (hwb || relative)) return FALSE;
    if (args->legacy && (!args->args[1].percent || !args->args[2].percent))
        return FALSE;
    const ns_color_arg *h = &args->args[0];
    if (h->percent) return FALSE;
    if (args->args[1].angle || args->args[2].angle) return FALSE;
    out->space = hwb ? NS_CSS_COLOR_HWB : NS_CSS_COLOR_HSL;
    out->legacy = !relative;
    if (h->none) {
        out->none |= 1;
        out->c[0] = 0.0;
    } else {
        out->c[0] = color_hue_normalize(color_arg_value(h, 1.0));
    }
    for (int i = 1; i < 3; i++) {
        const ns_color_arg *a = &args->args[i];
        if (a->none) {
            out->none |= (guint8)(1 << i);
            out->c[i] = 0.0;
            continue;
        }
        double v = color_arg_value(a, 100.0);
        if (!hwb && !relative) v = CLAMP(v, 0.0, 100.0);
        if (!isfinite(v)) v = v > 0 ? 100.0 : 0.0;
        out->c[i] = v;
    }
    return color_alpha_from_args(args, out);
}

/* Builds a lab/lch/oklab/oklch color, scaling percentages to each space's reference range. */
static gboolean
color_build_lab(const ns_color_args *args, ns_css_color_space space,
                ns_color *out)
{
    if (args->legacy) return FALSE;
    gboolean ok_space = space == NS_CSS_COLOR_OKLAB || space == NS_CSS_COLOR_OKLCH;
    gboolean polar = space == NS_CSS_COLOR_LCH || space == NS_CSS_COLOR_OKLCH;
    double l_full = ok_space ? 1.0 : 100.0;
    double ab_full = ok_space ? 0.4 : 125.0;
    double c_full = ok_space ? 0.4 : 150.0;
    out->space = space;
    out->legacy = FALSE;
    for (int i = 0; i < 3; i++) {
        const ns_color_arg *a = &args->args[i];
        gboolean hue = polar && i == 2;
        if (hue ? a->percent : a->angle) return FALSE;
        if (a->none) {
            out->none |= (guint8)(1 << i);
            out->c[i] = 0.0;
            continue;
        }
        if (i == 0) {
            out->c[0] = CLAMP(color_arg_value(a, l_full), 0.0, l_full);
        } else if (hue) {
            out->c[2] = color_hue_normalize(color_arg_value(a, 1.0));
        } else if (polar) {
            out->c[1] = MAX(color_arg_value(a, c_full), 0.0);
        } else {
            out->c[i] = color_arg_value(a, ab_full);
        }
    }
    return color_alpha_from_args(args, out);
}

/* Builds a color() function value in a predefined RGB or XYZ space. */
static gboolean
color_build_predefined(const ns_color_args *args, ns_css_color_space space,
                       ns_color *out)
{
    if (args->legacy) return FALSE;
    out->space = space;
    out->legacy = FALSE;
    for (int i = 0; i < 3; i++) {
        const ns_color_arg *a = &args->args[i];
        if (a->angle) return FALSE;
        if (a->none) {
            out->none |= (guint8)(1 << i);
            out->c[i] = 0.0;
            continue;
        }
        out->c[i] = color_arg_value(a, 1.0);
    }
    return color_alpha_from_args(args, out);
}

static gboolean color_parse_range(const char *s, const char *end,
                                  ns_color *out, int depth);

static ns_color_fn
color_fn_by_name(const char *name, gsize len)
{
    static const struct { const char *name; ns_color_fn fn; } fns[] = {
        { "rgb", NS_COLOR_FN_RGB },     { "rgba", NS_COLOR_FN_RGB },
        { "hsl", NS_COLOR_FN_HSL },     { "hsla", NS_COLOR_FN_HSL },
        { "hwb", NS_COLOR_FN_HWB },     { "lab", NS_COLOR_FN_LAB },
        { "lch", NS_COLOR_FN_LCH },     { "oklab", NS_COLOR_FN_OKLAB },
        { "oklch", NS_COLOR_FN_OKLCH }, { "color", NS_COLOR_FN_COLOR },
        { "color-mix", NS_COLOR_FN_MIX },
        { "light-dark", NS_COLOR_FN_LIGHT_DARK },
    };
    for (gsize i = 0; i < G_N_ELEMENTS(fns); i++)
        if (strlen(fns[i].name) == len &&
            g_ascii_strncasecmp(name, fns[i].name, len) == 0)
            return fns[i].fn;
    return NS_COLOR_FN_UNKNOWN;
}

static ns_css_color_space
color_fn_space(ns_color_fn fn)
{
    switch (fn) {
    case NS_COLOR_FN_HSL:   return NS_CSS_COLOR_HSL;
    case NS_COLOR_FN_HWB:   return NS_CSS_COLOR_HWB;
    case NS_COLOR_FN_LAB:   return NS_CSS_COLOR_LAB;
    case NS_COLOR_FN_LCH:   return NS_CSS_COLOR_LCH;
    case NS_COLOR_FN_OKLAB: return NS_CSS_COLOR_OKLAB;
    case NS_COLOR_FN_OKLCH: return NS_CSS_COLOR_OKLCH;
    default:                return NS_CSS_COLOR_SRGB;
    }
}

/* Dispatches parsed channels to the builder for the given color function. */
static gboolean
color_build(ns_color_fn fn, ns_css_color_space space,
            const ns_color_args *args, gboolean relative, ns_color *out)
{
    switch (fn) {
    case NS_COLOR_FN_RGB:
        return color_build_rgb(args, relative, out);
    case NS_COLOR_FN_HSL:
        return color_build_hsl(args, FALSE, relative, out);
    case NS_COLOR_FN_HWB:
        return color_build_hsl(args, TRUE, relative, out);
    case NS_COLOR_FN_LAB:
    case NS_COLOR_FN_LCH:
    case NS_COLOR_FN_OKLAB:
    case NS_COLOR_FN_OKLCH:
        return color_build_lab(args, color_fn_space(fn), out);
    case NS_COLOR_FN_COLOR:
        return color_build_predefined(args, space, out);
    default:
        return FALSE;
    }
}

/* Returns the end of a whitespace-delimited token, skipping over nested parentheses. */
static const char *
color_component_end(const char *p, const char *end)
{
    int depth = 0;
    while (p < end) {
        if (*p == '(') depth++;
        else if (*p == ')') depth--;
        else if (depth == 0 && ns_is_ascii_ws(*p)) break;
        p++;
    }
    return p;
}

static const char *
color_space_ident_end(const char *p, const char *end)
{
    while (p < end && (g_ascii_isalnum(*p) || *p == '-')) p++;
    return p;
}

/* Fills the channel keyword names (r g b, h s l, l c h, x y z, alpha) for relative colors. */
static void
color_channel_names(ns_color_fn fn, ns_css_color_space space,
                    const char *names[4])
{
    static const char *const rgb[] = { "r", "g", "b" };
    static const char *const hsl[] = { "h", "s", "l" };
    static const char *const hwb[] = { "h", "w", "b" };
    static const char *const lab[] = { "l", "a", "b" };
    static const char *const lch[] = { "l", "c", "h" };
    static const char *const xyz[] = { "x", "y", "z" };
    const char *const *pick = rgb;
    switch (fn) {
    case NS_COLOR_FN_HSL: pick = hsl; break;
    case NS_COLOR_FN_HWB: pick = hwb; break;
    case NS_COLOR_FN_LAB:
    case NS_COLOR_FN_OKLAB: pick = lab; break;
    case NS_COLOR_FN_LCH:
    case NS_COLOR_FN_OKLCH: pick = lch; break;
    case NS_COLOR_FN_COLOR:
        if (space == NS_CSS_COLOR_XYZ_D50 || space == NS_CSS_COLOR_XYZ_D65)
            pick = xyz;
        break;
    default:
        break;
    }
    for (int i = 0; i < 3; i++) names[i] = pick[i];
    names[3] = "alpha";
}

/* Rewrites relative-color channel keywords as origin values; returns a new string. */
static char *
color_relative_substitute(const char *p, const char *end,
                          const char *const names[4], const double vals[4],
                          guint8 none)
{
    GString *out = g_string_new(NULL);
    int depth = 0;
    const char *start = p;
    while (p < end) {
        char c = *p;
        if (c == '(' || c == ')') {
            depth += c == '(' ? 1 : -1;
            g_string_append_c(out, c);
            p++;
            continue;
        }
        const char *num_end = (p == start || !is_ident(p[-1]))
            ? color_number_end(p, end) : p;
        if (num_end != p) {
            const char *q = num_end;
            while (q < end && (is_ident(*q) || *q == '%')) q++;
            g_string_append_len(out, p, q - p);
            p = q;
            continue;
        }
        if (is_ident_start(c)) {
            const char *id = p;
            while (p < end && is_ident(*p)) p++;
            gsize n = (gsize)(p - id);
            int idx = -1;
            if (p >= end || *p != '(')
                for (int i = 0; i < 4; i++)
                    if (strlen(names[i]) == n &&
                        g_ascii_strncasecmp(id, names[i], n) == 0)
                        idx = i;
            if (idx < 0) {
                g_string_append_len(out, id, n);
            } else if (none & (1 << idx)) {
                g_string_append(out, depth == 0 ? "none" : "0");
            } else {
                char buf[G_ASCII_DTOSTR_BUF_SIZE];
                double v = isfinite(vals[idx]) ? vals[idx] : 0.0;
                g_ascii_formatd(buf, sizeof buf, "%.17g", v);
                g_string_append(out, buf);
            }
            continue;
        }
        g_string_append_c(out, c);
        p++;
    }
    return g_string_free(out, FALSE);
}

/* Parses relative color syntax ("from <color> ...") by substituting origin channel values. */
static gboolean
color_parse_relative(ns_color_fn fn, const char *p, const char *end,
                     ns_color *out, int depth)
{
    p = color_skip_ws(p, end);
    const char *origin_end = color_component_end(p, end);
    if (origin_end == p) return FALSE;
    ns_color origin;
    if (!color_parse_range(p, origin_end, &origin, depth + 1)) return FALSE;
    p = color_skip_ws(origin_end, end);
    ns_css_color_space space = color_fn_space(fn);
    if (fn == NS_COLOR_FN_COLOR) {
        const char *name_end = color_space_ident_end(p, end);
        if (!color_space_by_name(p, (gsize)(name_end - p), TRUE, &space))
            return FALSE;
        p = name_end;
    }
    ns_color converted;
    color_convert(&origin, space, &converted);
    double vals[4] = { converted.c[0], converted.c[1], converted.c[2],
                       converted.alpha };
    if (fn == NS_COLOR_FN_RGB)
        for (int i = 0; i < 3; i++) vals[i] *= 255.0;
    const char *names[4];
    color_channel_names(fn, space, names);
    char *text = color_relative_substitute(p, end, names, vals, converted.none);
    ns_color_args args;
    gboolean ok = color_args_parse(text, text + strlen(text), &args) &&
                  !args.legacy;
    g_free(text);
    if (!ok) return FALSE;
    memset(out, 0, sizeof *out);
    if (!color_build(fn, space, &args, TRUE, out)) return FALSE;
    if (!args.has_alpha) {
        out->alpha = converted.alpha;
        out->none = (guint8)((out->none & 7) |
                             (converted.none & NS_COLOR_NONE_ALPHA));
    }
    out->current = origin.current;
    return TRUE;
}

/* Parses the body of a color function, handling relative syntax and color() space names. */
static gboolean
color_parse_function(ns_color_fn fn, const char *p, const char *end,
                     ns_color *out, int depth)
{
    p = color_skip_ws(p, end);
    if (end - p > 4 && g_ascii_strncasecmp(p, "from", 4) == 0 && ns_is_ascii_ws(p[4]))
        return color_parse_relative(fn, p + 4, end, out, depth);
    ns_css_color_space space = NS_CSS_COLOR_SRGB;
    if (fn == NS_COLOR_FN_COLOR) {
        const char *name_end = color_space_ident_end(p, end);
        if (!color_space_by_name(p, (gsize)(name_end - p), TRUE, &space))
            return FALSE;
        if (name_end >= end || !ns_is_ascii_ws(*name_end)) return FALSE;
        p = name_end;
    }
    ns_color_args args;
    if (!color_args_parse(p, end, &args)) return FALSE;
    return color_build(fn, space, &args, FALSE, out);
}

/* Parses a color interpolation method ("in <space> [<hue> hue]") for color-mix(). */
static gboolean
color_parse_method(const char *text, ns_css_color_space *space,
                   ns_hue_method *hue)
{
    char *tok[5] = {0};
    int n = split_ws_limit(text, tok, G_N_ELEMENTS(tok));
    gboolean ok = n >= 2 && g_ascii_strcasecmp(tok[0], "in") == 0 &&
                  color_space_by_name(tok[1], strlen(tok[1]), FALSE, space);
    *hue = NS_HUE_SHORTER;
    if (ok && n == 4) {
        static const char *const methods[] = {
            "shorter", "longer", "increasing", "decreasing",
        };
        ok = color_space_hue_index(*space) >= 0 &&
             g_ascii_strcasecmp(tok[3], "hue") == 0;
        gboolean found = FALSE;
        for (int i = 0; ok && i < 4; i++)
            if (g_ascii_strcasecmp(tok[2], methods[i]) == 0) {
                *hue = (ns_hue_method)i;
                found = TRUE;
            }
        ok = ok && found;
    } else if (n != 2) {
        ok = FALSE;
    }
    for (int i = 0; i < n; i++) g_free(tok[i]);
    return ok;
}

/* Splits a color-mix() item into color and optional percentage in either order. */
static gboolean
color_mix_item_split(const char *s, const char **color_start,
                     const char **color_end, const char **pct_start,
                     const char **pct_end, double *pct)
{
    const char *s_end = s + strlen(s);
    const char *a = color_skip_ws(s, s_end);
    const char *a_end = color_component_end(a, s_end);
    const char *b = color_skip_ws(a_end, s_end);
    const char *b_end = color_component_end(b, s_end);
    ns_color_arg arg;
    const char *q = a;
    *color_start = a;
    *color_end = a_end;
    *pct_start = *pct_end = a_end;
    if (b < s_end && color_read_arg(&q, a_end, &arg) && q == a_end &&
        arg.percent) {
        *color_start = b;
        *color_end = b_end;
        *pct_start = a;
        *pct_end = a_end;
        *pct = isnan(arg.v) ? 0.0 : arg.v;
        return TRUE;
    }
    q = b;
    if (b < s_end && color_read_arg(&q, b_end, &arg) && q == b_end &&
        arg.percent) {
        *pct_start = b;
        *pct_end = b_end;
        *pct = isnan(arg.v) ? 0.0 : arg.v;
        return TRUE;
    }
    return FALSE;
}

/* Parses one color-mix() item; rejects trailing junk and percentages outside 0..100. */
static gboolean
color_mix_item_parse(const char *text, ns_color *col, double *pct,
                     gboolean *has_pct, int depth)
{
    const char *end = text + strlen(text);
    const char *cs, *ce, *ps, *pe;
    *has_pct = color_mix_item_split(text, &cs, &ce, &ps, &pe, pct);
    const char *last = *has_pct && pe > ce ? pe : ce;
    if (color_skip_ws(last, end) != end) return FALSE;
    if (*has_pct && (*pct < 0.0 || *pct > 100.0)) return FALSE;
    return color_parse_range(cs, ce, col, depth + 1);
}

/* Interpolates two colors with premultiplied alpha, missing-component and hue-method rules. */
static void
color_mix_pair(ns_color *acc, const ns_color *b, double t, ns_hue_method method)
{
    ns_color a = *acc;
    ns_color r = a;
    r.none = 0;
    int hue = color_space_hue_index(a.space);
    double aa = a.alpha, ab = b->alpha;
    gboolean alpha_none_a = a.none & NS_COLOR_NONE_ALPHA;
    gboolean alpha_none_b = b->none & NS_COLOR_NONE_ALPHA;
    if (alpha_none_a && alpha_none_b) {
        aa = ab = 1.0;
        r.none |= NS_COLOR_NONE_ALPHA;
    } else if (alpha_none_a) {
        aa = ab;
    } else if (alpha_none_b) {
        ab = aa;
    }
    double ca[3], cb[3];
    for (int i = 0; i < 3; i++) {
        gboolean na = a.none & (1 << i), nb = b->none & (1 << i);
        ca[i] = a.c[i];
        cb[i] = b->c[i];
        if (na && nb) r.none |= (guint8)(1 << i);
        else if (na) ca[i] = cb[i];
        else if (nb) cb[i] = ca[i];
    }
    if (hue >= 0 && !(r.none & (1 << hue))) {
        double h1 = color_hue_normalize(ca[hue]);
        double h2 = color_hue_normalize(cb[hue]);
        double d = h2 - h1;
        switch (method) {
        case NS_HUE_SHORTER:
            if (d > 180.0) h1 += 360.0;
            else if (d < -180.0) h2 += 360.0;
            break;
        case NS_HUE_LONGER:
            if (d > 0.0 && d < 180.0) h1 += 360.0;
            else if (d > -180.0 && d <= 0.0) h2 += 360.0;
            break;
        case NS_HUE_INCREASING:
            if (h2 < h1) h2 += 360.0;
            break;
        case NS_HUE_DECREASING:
            if (h1 < h2) h1 += 360.0;
            break;
        }
        ca[hue] = h1;
        cb[hue] = h2;
    }
    double alpha = aa * (1.0 - t) + ab * t;
    for (int i = 0; i < 3; i++) {
        if (r.none & (1 << i)) {
            r.c[i] = 0.0;
            continue;
        }
        if (i == hue) {
            r.c[i] = color_hue_normalize(ca[i] * (1.0 - t) + cb[i] * t);
            continue;
        }
        double v = ca[i] * aa * (1.0 - t) + cb[i] * ab * t;
        r.c[i] = alpha != 0.0 ? v / alpha : v;
    }
    r.alpha = (r.none & NS_COLOR_NONE_ALPHA) ? 0.0 : alpha;
    r.current = a.current || b->current;
    r.legacy = FALSE;
    *acc = r;
}

/* Implements color-mix(): normalizes percentages, mixes pairwise, scales leftover alpha. */
static gboolean
color_parse_mix(const char *p, const char *end, ns_color *out, int depth)
{
    char *parts[NS_COLOR_MIX_MAX + 1] = {0};
    int n = calc_split_args(p, end, parts, G_N_ELEMENTS(parts));
    gboolean ok = n >= 1 && n <= NS_COLOR_MIX_MAX;
    ns_css_color_space space = NS_CSS_COLOR_OKLAB;
    ns_hue_method method = NS_HUE_SHORTER;
    int first = 0;
    if (ok && g_ascii_strncasecmp(parts[0], "in", 2) == 0 &&
        ns_is_ascii_ws(parts[0][2])) {
        ok = color_parse_method(parts[0], &space, &method);
        first = 1;
    }
    int count = n - first;
    if (count < 1) ok = FALSE;
    ns_color cols[NS_COLOR_MIX_MAX];
    double pcts[NS_COLOR_MIX_MAX];
    gboolean given[NS_COLOR_MIX_MAX];
    double given_sum = 0.0;
    int omitted = 0;
    for (int i = 0; ok && i < count; i++) {
        ok = color_mix_item_parse(parts[first + i], &cols[i], &pcts[i],
                                  &given[i], depth);
        if (!ok) break;
        if (given[i]) given_sum += pcts[i];
        else omitted++;
    }
    for (int i = 0; i < n; i++) g_free(parts[i]);
    if (!ok) return FALSE;
    for (int i = 0; i < count; i++) {
        if (given[i]) continue;
        pcts[i] = omitted == count ? 100.0 / count
                                   : MAX(0.0, (100.0 - given_sum) / omitted);
    }
    double total = 0.0;
    for (int i = 0; i < count; i++) total += pcts[i];
    double alpha_mult = 1.0;
    if (total > 100.0) {
        for (int i = 0; i < count; i++) pcts[i] *= 100.0 / total;
    } else if (total < 100.0) {
        alpha_mult = total / 100.0;
    }
    ns_color acc;
    color_convert(&cols[0], space, &acc);
    double acc_pct = pcts[0];
    for (int i = 1; i < count; i++) {
        ns_color next;
        color_convert(&cols[i], space, &next);
        double sum = acc_pct + pcts[i];
        double t = sum > 0.0 ? pcts[i] / sum : 0.5;
        color_mix_pair(&acc, &next, t, method);
        acc_pct = sum;
    }
    if (!(acc.none & NS_COLOR_NONE_ALPHA)) acc.alpha *= alpha_mult;
    acc.legacy = FALSE;
    for (int i = 0; i < count; i++)
        if (cols[i].current) acc.current = TRUE;
    *out = acc;
    return TRUE;
}

/* Parses light-dark(), validating both colors and picking one by the current color scheme. */
static gboolean
color_parse_light_dark(const char *p, const char *end, ns_color *out,
                       int depth)
{
    char *parts[3] = {0};
    int n = calc_split_args(p, end, parts, G_N_ELEMENTS(parts));
    gboolean ok = n == 2;
    if (ok) {
        const char *choice =
            ns_css_get_color_scheme() == NS_CSS_COLOR_SCHEME_DARK
            ? parts[1] : parts[0];
        const char *other = choice == parts[0] ? parts[1] : parts[0];
        ns_color unused;
        ok = color_parse_range(other, other + strlen(other), &unused,
                               depth + 1) &&
             color_parse_range(choice, choice + strlen(choice), out,
                               depth + 1);
    }
    for (int i = 0; i < n; i++) g_free(parts[i]);
    return ok;
}

/* Parses 3/4/6/8-digit hex color digits (after #) into a legacy sRGB color. */
static gboolean
color_parse_hex(const char *s, const char *end, ns_color *out)
{
    gsize n = (gsize)(end - s);
    int v[8];
    if (n != 3 && n != 4 && n != 6 && n != 8) return FALSE;
    for (gsize i = 0; i < n; i++) {
        v[i] = g_ascii_xdigit_value(s[i]);
        if (v[i] < 0) return FALSE;
    }
    int ch[4] = { 0, 0, 0, 255 };
    if (n <= 4) {
        for (gsize i = 0; i < n; i++) ch[i] = v[i] * 17;
    } else {
        for (gsize i = 0; i < n / 2; i++) ch[i] = v[i * 2] * 16 + v[i * 2 + 1];
    }
    out->space = NS_CSS_COLOR_SRGB;
    out->legacy = TRUE;
    for (int i = 0; i < 3; i++) out->c[i] = ch[i] / 255.0;
    out->alpha = ch[3] / 255.0;
    return TRUE;
}

/* Parses any CSS color (hex, function, currentcolor, transparent, named) in [s, end). */
static gboolean
color_parse_range(const char *s, const char *end, ns_color *out, int depth)
{
    memset(out, 0, sizeof *out);
    out->alpha = 1.0;
    if (depth > NS_COLOR_MAX_DEPTH) return FALSE;
    s = color_skip_ws(s, end);
    while (end > s && ns_is_ascii_ws(end[-1])) end--;
    if (s >= end) return FALSE;
    if (*s == '#') return color_parse_hex(s + 1, end, out);
    const char *p = s;
    while (p < end && is_ident(*p)) p++;
    if (p == s) return FALSE;
    if (p < end && *p == '(') {
        const char *close = match_close_paren(p + 1, end);
        if (!close || close + 1 != end) return FALSE;
        ns_color_fn fn = color_fn_by_name(s, (gsize)(p - s));
        switch (fn) {
        case NS_COLOR_FN_UNKNOWN:
            return FALSE;
        case NS_COLOR_FN_MIX:
            return color_parse_mix(p + 1, close, out, depth);
        case NS_COLOR_FN_LIGHT_DARK:
            return color_parse_light_dark(p + 1, close, out, depth);
        default:
            return color_parse_function(fn, p + 1, close, out, depth);
        }
    }
    if (p != end) return FALSE;
    gsize n = (gsize)(end - s);
    if (n == 12 && g_ascii_strncasecmp(s, "currentcolor", 12) == 0) {
        if (color_current_ctx) {
            *out = *color_current_ctx;
        } else {
            out->space = NS_CSS_COLOR_SRGB;
            out->legacy = TRUE;
        }
        out->current = TRUE;
        return TRUE;
    }
    if (n == 11 && g_ascii_strncasecmp(s, "transparent", 11) == 0) {
        out->space = NS_CSS_COLOR_SRGB;
        out->legacy = TRUE;
        out->alpha = 0.0;
        return TRUE;
    }
    char *name = g_strndup(s, n);
    guint8 r, g, b;
    gboolean ok = named_color(name, &r, &g, &b);
    g_free(name);
    if (!ok) return FALSE;
    out->space = NS_CSS_COLOR_SRGB;
    out->legacy = TRUE;
    out->c[0] = r / 255.0;
    out->c[1] = g / 255.0;
    out->c[2] = b / 255.0;
    return TRUE;
}

/* Returns a copy of s with CSS comments removed; caller frees. */
static char *
color_strip_comments(const char *s)
{
    GString *out = g_string_new(NULL);
    while (*s) {
        if (s[0] == '/' && s[1] == '*') {
            const char *close = strstr(s + 2, "*/");
            s = close ? close + 2 : s + strlen(s);
            continue;
        }
        g_string_append_c(out, *s++);
    }
    return g_string_free(out, FALSE);
}

/* Parses a NUL-terminated CSS color string, stripping comments first if present. */
static gboolean
color_parse_text(const char *s, ns_color *out)
{
    if (!s) return FALSE;
    if (strstr(s, "/*")) {
        char *plain = color_strip_comments(s);
        gboolean ok = color_parse_range(plain, plain + strlen(plain), out, 0);
        g_free(plain);
        return ok;
    }
    return color_parse_range(s, s + strlen(s), out, 0);
}

/* Loads an ns_css_value color into the internal ns_color form; non-colors become black. */
static void
color_from_value(const ns_css_value *v, ns_color *out)
{
    memset(out, 0, sizeof *out);
    out->space = NS_CSS_COLOR_SRGB;
    out->alpha = 1.0;
    out->legacy = TRUE;
    if (!v || v->kind != NS_CSS_V_COLOR) return;
    if (v->u.color.space == NS_CSS_COLOR_LEGACY) {
        out->c[0] = v->u.color.r / 255.0;
        out->c[1] = v->u.color.g / 255.0;
        out->c[2] = v->u.color.b / 255.0;
        out->alpha = v->u.color.a / 255.0;
        return;
    }
    out->legacy = FALSE;
    out->space = (ns_css_color_space)v->u.color.space;
    out->none = v->u.color.none;
    for (int i = 0; i < 3; i++) out->c[i] = v->u.color.c[i];
    out->alpha = v->u.color.c[3];
}

/* Stores a color into a value: RGBA bytes, plus space coordinates for non-legacy colors. */
static void
color_value_store(ns_css_value *v, const ns_color *col)
{
    guint8 rgba[4];
    color_to_bytes(col, rgba);
    v->kind = NS_CSS_V_COLOR;
    v->u.color.r = rgba[0];
    v->u.color.g = rgba[1];
    v->u.color.b = rgba[2];
    v->u.color.a = rgba[3];
    v->u.color.current = col->current;
    v->u.color.none = 0;
    for (int i = 0; i < 4; i++) v->u.color.c[i] = 0.0;
    if (col->legacy && !col->none) {
        v->u.color.space = NS_CSS_COLOR_LEGACY;
        return;
    }
    ns_color norm = *col;
    if ((norm.space == NS_CSS_COLOR_HSL || norm.space == NS_CSS_COLOR_HWB) &&
        !norm.none) {
        double rgb[3];
        color_space_to_srgb(norm.space, norm.c, rgb);
        for (int i = 0; i < 3; i++) norm.c[i] = rgb[i];
        norm.space = NS_CSS_COLOR_SRGB;
    }
    v->u.color.space = (guint8)norm.space;
    v->u.color.none = norm.none;
    for (int i = 0; i < 3; i++) v->u.color.c[i] = norm.c[i];
    v->u.color.c[3] = norm.alpha;
}

/* Parses color text into a new value, keeping the text when it depends on currentcolor. */
static ns_css_value *
color_value_parse(const char *text)
{
    ns_color col;
    if (!color_parse_text(text, &col)) return NULL;
    ns_css_value *v = g_new0(ns_css_value, 1);
    color_value_store(v, &col);
    if (col.current) v->specified = g_strdup(text);
    return v;
}

/* Re-parses a currentcolor-dependent value against the given current color; TRUE on success. */
static gboolean
color_value_resolve_current(ns_css_value *v, const ns_css_value *current)
{
    if (!v || v->kind != NS_CSS_V_COLOR || !v->u.color.current ||
        !v->specified)
        return FALSE;
    ns_color ctx, col;
    color_from_value(current, &ctx);
    color_current_ctx = &ctx;
    gboolean ok = color_parse_text(v->specified, &col);
    color_current_ctx = NULL;
    if (ok) color_value_store(v, &col);
    return ok;
}

/* Appends a color channel number in shortest serialized form; infinities as calc(infinity). */
static void
color_append_number(GString *s, double v)
{
    if (isnan(v)) v = 0.0;
    if (isinf(v)) {
        g_string_append(s, v > 0 ? "calc(infinity)" : "calc(-infinity)");
        return;
    }
    char buf[G_ASCII_DTOSTR_BUF_SIZE];
    if (fabs(v) < 1.0) {
        g_ascii_formatd(buf, sizeof buf, "%.8f", v);
    } else {
        g_ascii_formatd(buf, sizeof buf, "%.6g", v);
        if (strchr(buf, 'e')) g_ascii_formatd(buf, sizeof buf, "%.0f", v);
    }
    char *dot = strchr(buf, '.');
    if (dot) {
        char *last = buf + strlen(buf) - 1;
        while (last > dot && *last == '0') *last-- = '\0';
        if (last == dot) *last = '\0';
    }
    g_string_append(s, strcmp(buf, "-0") == 0 ? "0" : buf);
}

static void ns_css_append_color(GString *s, guint8 r, guint8 g, guint8 b,
                                guint8 a);

/* Serializes a computed color value: legacy rgb(), lab()-family, or color(<space> ...). */
static void
color_append_value(GString *s, const ns_css_value *v)
{
    ns_css_color_space space = (ns_css_color_space)v->u.color.space;
    if (space == NS_CSS_COLOR_LEGACY) {
        ns_css_append_color(s, v->u.color.r, v->u.color.g, v->u.color.b,
                            v->u.color.a);
        return;
    }
    gboolean percent_units = FALSE;
    switch (space) {
    case NS_CSS_COLOR_LAB:
    case NS_CSS_COLOR_LCH:
    case NS_CSS_COLOR_OKLAB:
    case NS_CSS_COLOR_OKLCH:
        g_string_append_printf(s, "%s(", color_space_name(space));
        break;
    case NS_CSS_COLOR_HSL:
    case NS_CSS_COLOR_HWB:
        g_string_append_printf(s, "%s(", color_space_name(space));
        percent_units = TRUE;
        break;
    default:
        g_string_append_printf(s, "color(%s ", color_space_name(space));
        break;
    }
    for (int i = 0; i < 3; i++) {
        if (i) g_string_append_c(s, ' ');
        if (v->u.color.none & (1 << i)) {
            g_string_append(s, "none");
            continue;
        }
        color_append_number(s, v->u.color.c[i]);
        if (percent_units && i > 0) g_string_append_c(s, '%');
    }
    if (v->u.color.none & NS_COLOR_NONE_ALPHA) {
        g_string_append(s, " / none");
    } else if (v->u.color.c[3] < 1.0 - 1e-9) {
        g_string_append(s, " / ");
        color_append_number(s, v->u.color.c[3]);
    }
    g_string_append_c(s, ')');
}

static gboolean color_specified_append(GString *out, const char *s,
                                       const char *end, int depth);

static void
color_append_lower(GString *out, const char *p, const char *end)
{
    for (; p < end; p++) g_string_append_c(out, g_ascii_tolower(*p));
}

static const char *
color_fn_name(ns_color_fn fn)
{
    switch (fn) {
    case NS_COLOR_FN_RGB:   return "rgb";
    case NS_COLOR_FN_HSL:   return "hsl";
    case NS_COLOR_FN_HWB:   return "hwb";
    case NS_COLOR_FN_LAB:   return "lab";
    case NS_COLOR_FN_LCH:   return "lch";
    case NS_COLOR_FN_OKLAB: return "oklab";
    case NS_COLOR_FN_OKLCH: return "oklch";
    default:                return "color";
    }
}

/* Appends a relative-color token, normalizing numbers and lowercasing identifiers. */
static void
color_append_token(GString *out, const char *p, const char *end)
{
    const char *num_end = color_number_end(p, end);
    if (num_end != p) {
        char *text = g_strndup(p, (gsize)(num_end - p));
        color_append_number(out, g_ascii_strtod(text, NULL));
        g_free(text);
        color_append_lower(out, num_end, end);
        return;
    }
    const char *q = p;
    while (q < end && is_ident(*q)) q++;
    if (q < end && *q == '(') {
        g_string_append_len(out, p, end - p);
        return;
    }
    color_append_lower(out, p, end);
}

/* Serializes a relative color's specified value, preserving channel expressions. */
static gboolean
color_relative_specified_append(GString *out, ns_color_fn fn, const char *p,
                                const char *end, int depth)
{
    p = color_skip_ws(p, end);
    const char *origin_end = color_component_end(p, end);
    g_string_append_printf(out, "%s(from ", color_fn_name(fn));
    if (!color_specified_append(out, p, origin_end, depth + 1)) return FALSE;
    p = origin_end;
    while (1) {
        p = color_skip_ws(p, end);
        if (p >= end) break;
        if (*p == '/') {
            g_string_append(out, " /");
            p++;
            continue;
        }
        const char *e = p;
        int nest = 0;
        while (e < end) {
            if (*e == '(') nest++;
            else if (*e == ')') nest--;
            else if (nest == 0 && (ns_is_ascii_ws(*e) || *e == '/')) break;
            e++;
        }
        g_string_append_c(out, ' ');
        color_append_token(out, p, e);
        p = e;
    }
    g_string_append_c(out, ')');
    return TRUE;
}

/* Serializes a resolved math channel as calc(<number>[%|deg]). */
static void
color_append_math_arg(GString *out, const ns_color_arg *a)
{
    g_string_append(out, "calc(");
    if (isnan(a->v)) g_string_append(out, "NaN");
    else if (isinf(a->v)) g_string_append(out, a->v > 0 ? "infinity" : "-infinity");
    else color_append_number(out, a->v);
    if (a->percent) g_string_append_c(out, '%');
    else if (a->angle) g_string_append(out, "deg");
    g_string_append_c(out, ')');
}

/* Serializes a non-legacy color function specified value, keeping calc() channels. */
static gboolean
color_absolute_specified_append(GString *out, ns_color_fn fn, const char *p,
                                const char *end, const ns_color *col)
{
    if (fn == NS_COLOR_FN_COLOR) {
        p = color_space_ident_end(color_skip_ws(p, end), end);
        g_string_append_printf(out, "color(%s ", color_space_name(col->space));
    } else {
        g_string_append_printf(out, "%s(", color_fn_name(fn));
    }
    ns_color_args args;
    if (!color_args_parse(p, end, &args)) return FALSE;
    for (int i = 0; i < 3; i++) {
        if (i) g_string_append_c(out, ' ');
        if (args.args[i].math) color_append_math_arg(out, &args.args[i]);
        else if (col->none & (1 << i)) g_string_append(out, "none");
        else color_append_number(out, col->c[i]);
    }
    if (args.has_alpha && args.args[3].math) {
        g_string_append(out, " / ");
        color_append_math_arg(out, &args.args[3]);
    } else if (col->none & NS_COLOR_NONE_ALPHA) {
        g_string_append(out, " / none");
    } else if (col->alpha < 1.0) {
        g_string_append(out, " / ");
        color_append_number(out, col->alpha);
    }
    g_string_append_c(out, ')');
    return TRUE;
}

/* Serializes color-mix() specified value, omitting default method and equal percentages. */
static gboolean
color_mix_specified_append(GString *out, const char *p, const char *end,
                           int depth)
{
    char *parts[NS_COLOR_MIX_MAX + 1] = {0};
    int n = calc_split_args(p, end, parts, G_N_ELEMENTS(parts));
    gboolean ok = n >= 1 && n <= NS_COLOR_MIX_MAX;
    int first = 0;
    g_string_append(out, "color-mix(");
    if (ok && g_ascii_strncasecmp(parts[0], "in", 2) == 0 &&
        ns_is_ascii_ws(parts[0][2])) {
        static const char *const methods[] = {
            "shorter", "longer", "increasing", "decreasing",
        };
        ns_css_color_space space;
        ns_hue_method hue;
        ok = color_parse_method(parts[0], &space, &hue);
        if (ok && (space != NS_CSS_COLOR_OKLAB || hue != NS_HUE_SHORTER)) {
            g_string_append_printf(out, "in %s", color_space_name(space));
            if (hue != NS_HUE_SHORTER)
                g_string_append_printf(out, " %s hue", methods[hue]);
            g_string_append(out, ", ");
        }
        first = 1;
    }
    int count = ok ? n - first : 0;
    const char *color_start[NS_COLOR_MIX_MAX], *color_end[NS_COLOR_MIX_MAX];
    const char *pct_start[NS_COLOR_MIX_MAX], *pct_end[NS_COLOR_MIX_MAX];
    double pcts[NS_COLOR_MIX_MAX];
    gboolean given[NS_COLOR_MIX_MAX], math = FALSE;
    double given_sum = 0.0;
    int omitted = 0;
    for (int i = 0; i < count; i++) {
        given[i] = color_mix_item_split(parts[first + i], &color_start[i],
                                        &color_end[i], &pct_start[i],
                                        &pct_end[i], &pcts[i]);
        if (!given[i]) {
            omitted++;
            continue;
        }
        given_sum += pcts[i];
        for (const char *c = pct_start[i]; c < pct_end[i]; c++)
            if (*c == '(') math = TRUE;
    }
    gboolean print_pcts = FALSE;
    if (!math && omitted < count) {
        for (int i = 0; i < count; i++)
            if (!given[i])
                pcts[i] = MAX(0.0, (100.0 - given_sum) / omitted);
        for (int i = 0; i < count; i++)
            if (fabs(pcts[i] - 100.0 / count) > 1e-9) print_pcts = TRUE;
    }
    for (int i = 0; ok && i < count; i++) {
        if (i) g_string_append(out, ", ");
        ok = color_specified_append(out, color_start[i], color_end[i],
                                    depth + 1);
        if (!ok) break;
        if (math && given[i]) {
            g_string_append_c(out, ' ');
            g_string_append_len(out, pct_start[i], pct_end[i] - pct_start[i]);
        } else if (print_pcts) {
            g_string_append_c(out, ' ');
            color_append_number(out, pcts[i]);
            g_string_append_c(out, '%');
        }
    }
    g_string_append_c(out, ')');
    for (int i = 0; i < n; i++) g_free(parts[i]);
    return ok;
}

/* Serializes light-dark() specified value with both arguments canonicalized. */
static gboolean
color_light_dark_specified_append(GString *out, const char *p,
                                  const char *end, int depth)
{
    char *parts[2] = {0};
    int n = calc_split_args(p, end, parts, 2);
    gboolean ok = n == 2;
    g_string_append(out, "light-dark(");
    for (int i = 0; ok && i < 2; i++) {
        if (i) g_string_append(out, ", ");
        ok = color_specified_append(out, parts[i], parts[i] + strlen(parts[i]),
                                    depth + 1);
    }
    g_string_append_c(out, ')');
    for (int i = 0; i < n; i++) g_free(parts[i]);
    return ok;
}

/* Appends the canonical specified-value serialization of a color per CSSOM rules. */
static gboolean
color_specified_append(GString *out, const char *s, const char *end, int depth)
{
    if (depth > NS_COLOR_MAX_DEPTH) return FALSE;
    s = color_skip_ws(s, end);
    while (end > s && ns_is_ascii_ws(end[-1])) end--;
    ns_color col;
    if (!color_parse_range(s, end, &col, depth)) return FALSE;
    const char *p = s;
    while (p < end && is_ident(*p)) p++;
    if (*s != '#' && p == end) {
        color_append_lower(out, s, end);
        return TRUE;
    }
    ns_color_fn fn = *s == '#' ? NS_COLOR_FN_RGB
                               : color_fn_by_name(s, (gsize)(p - s));
    if (*s != '#') {
        const char *body = p + 1, *close = end - 1;
        if (fn == NS_COLOR_FN_MIX)
            return color_mix_specified_append(out, body, close, depth);
        if (fn == NS_COLOR_FN_LIGHT_DARK)
            return color_light_dark_specified_append(out, body, close, depth);
        const char *q = color_skip_ws(body, close);
        if (close - q > 4 && g_ascii_strncasecmp(q, "from", 4) == 0 &&
            ns_is_ascii_ws(q[4]))
            return color_relative_specified_append(out, fn, q + 4, close,
                                                   depth);
        gboolean legacy_fn = fn == NS_COLOR_FN_RGB || fn == NS_COLOR_FN_HSL ||
                             fn == NS_COLOR_FN_HWB;
        if (!legacy_fn ||
            (fn != NS_COLOR_FN_RGB && col.none && depth == 0))
            return color_absolute_specified_append(out, fn, body, close,
                                                   &col);
    }
    if (col.legacy) col.none = 0;
    ns_css_value tmp;
    memset(&tmp, 0, sizeof tmp);
    color_value_store(&tmp, &col);
    color_append_value(out, &tmp);
    return TRUE;
}

/* Serializes a color's specified value; NULL for var()/attr()/comments or invalid input. */
static char *
color_specified_serialize(const char *text)
{
    if (!text || strstr(text, "var(") || strstr(text, "attr(") ||
        strstr(text, "sibling-") || strstr(text, "/*"))
        return NULL;
    GString *out = g_string_new(NULL);
    if (!color_specified_append(out, text, text + strlen(text), 0)) {
        g_string_free(out, TRUE);
        return NULL;
    }
    return g_string_free(out, FALSE);
}

static gboolean
color_text_valid(const char *s)
{
    ns_color col;
    return color_parse_text(s, &col);
}

/* Parses a color into 8-bit RGBA; fails on currentcolor when no current color context. */
static gboolean
parse_color(const char *s, guint8 *r, guint8 *g, guint8 *b, guint8 *a)
{
    *a = 255;
    ns_color col;
    if (!color_parse_text(s, &col)) return FALSE;
    if (col.current && !color_current_ctx) return FALSE;
    guint8 rgba[4];
    color_to_bytes(&col, rgba);
    *r = rgba[0];
    *g = rgba[1];
    *b = rgba[2];
    *a = rgba[3];
    return TRUE;
}

gboolean
ns_css_parse_color(const char *s, guint8 *r, guint8 *g, guint8 *b, guint8 *a)
{
    return parse_color(s, r, g, b, a);
}

static void
ns_attr_pred_clear(gpointer p)
{
    ns_css_attr_pred *a = p;
    g_free(a->name);
    g_free(a->namespace_uri);
    g_free(a->value);
}

static void
matches_any_group_free(gpointer data)
{
    g_ptr_array_free((GPtrArray *)data, TRUE);
}

static void
ns_pseudo_pred_clear(gpointer p)
{
    ns_css_pseudo_pred *pc = p;
    g_free(pc->arg);
    if (pc->of_group) g_ptr_array_free(pc->of_group, TRUE);
}

static ns_css_simple *
ns_css_simple_new(void)
{
    ns_css_simple *s = g_new0(ns_css_simple, 1);
    s->classes = g_ptr_array_new_with_free_func(g_free);
    s->class_lens = g_array_new(FALSE, FALSE, sizeof(gsize));
    s->attrs   = g_array_new(FALSE, FALSE, sizeof(ns_css_attr_pred));
    g_array_set_clear_func(s->attrs, ns_attr_pred_clear);
    s->pseudos = g_array_new(FALSE, FALSE, sizeof(ns_css_pseudo_pred));
    g_array_set_clear_func(s->pseudos, ns_pseudo_pred_clear);
    return s;
}

static void
ns_css_simple_free(ns_css_simple *s)
{
    if (!s) return;
    g_free(s->type);
    g_free(s->type_lower);
    g_free(s->namespace_uri);
    g_free(s->id);
    g_ptr_array_free(s->classes, TRUE);
    g_array_free(s->class_lens, TRUE);
    if (s->attrs)   g_array_free(s->attrs,   TRUE);
    if (s->pseudos) g_array_free(s->pseudos, TRUE);
    if (s->matches_any)  g_ptr_array_free(s->matches_any,  TRUE);
    if (s->matches_none) g_ptr_array_free(s->matches_none, TRUE);
    if (s->has_groups)   g_ptr_array_free(s->has_groups,   TRUE);
    g_free(s);
}

static void
ns_css_selector_free(ns_css_selector *sel)
{
    if (!sel) return;
    for (guint i = 0; i < sel->compounds->len; i++)
        ns_css_simple_free(g_ptr_array_index(sel->compounds, i));
    g_ptr_array_free(sel->compounds, TRUE);
    g_array_free(sel->combinators, TRUE);
    g_free(sel);
}

typedef struct ns_css_scope {
    GPtrArray *roots;
    GPtrArray *limits;
} ns_css_scope;

typedef struct ns_css_scope_text {
    char *start;
    char *end;
} ns_css_scope_text;

#define NS_CSS_MAX_SELECTOR_NESTING 48
#define NS_CSS_MAX_AT_NESTING 32

static gboolean g_sel_parse_error;
static gboolean g_sel_ns_prefix;
static gboolean g_sel_has_hover;
static gboolean g_sel_has_active;
static gboolean g_sel_strict;
static int g_sel_has_depth;
static GHashTable *g_sel_namespaces;
static const char *g_sel_default_namespace;
static gboolean g_sel_namespace_locked;

static ns_css_selector *parse_one_selector_rel(const char **pp, const char *end,
                                               int depth, gboolean relative);
static ns_css_selector *parse_one_selector(const char **pp, const char *end,
                                           int depth);

/* Parses a comma-separated selector list into a new array; strict mode flags bad entries. */
static GPtrArray *
parse_selector_group_rel(const char *arg, gsize arg_n, int depth,
                         gboolean relative)
{
    GPtrArray *group = g_ptr_array_new_with_free_func(
        (GDestroyNotify)ns_css_selector_free);
    if (depth > NS_CSS_MAX_SELECTOR_NESTING)
        return group;
    const char *p = arg;
    const char *end = arg + arg_n;
    while (p < end) {
        const char *loop_start = p;
        p = css_skip_ws_comments(p, end);
        if (p >= end) break;
        ns_css_selector *sub = parse_one_selector_rel(&p, end, depth, relative);
        if (sub) g_ptr_array_add(group, sub);
        else if (g_sel_strict) g_sel_parse_error = TRUE;
        p = css_skip_ws_comments(p, end);
        if (p < end && *p == ',') { p++; continue; }
        if (p == loop_start) p++;
    }
    return group;
}

static GPtrArray *
parse_selector_group(const char *arg, gsize arg_n, int depth)
{
    return parse_selector_group_rel(arg, arg_n, depth, FALSE);
}

/* Finds the top-level "of" keyword in an :nth-child() argument, or NULL. */
static const char *
css_find_nth_of(const char *s, const char *end)
{
    char quote = 0;
    int paren = 0, bracket = 0;
    const char *p = s;
    while (p < end) {
        const char *next = css_skip_quoted_step(p, end, &quote, FALSE);
        if (next) {
            p = next;
            continue;
        }
        char c = *p;
        if (c == '[') bracket++;
        else if (c == ']' && bracket > 0) bracket--;
        else if (c == '(') paren++;
        else if (c == ')' && paren > 0) paren--;
        if (paren == 0 && bracket == 0 &&
            p + 2 <= end &&
            g_ascii_strncasecmp(p, "of", 2) == 0 &&
            (p == s || ns_is_ascii_ws(p[-1])) &&
            (p + 2 == end || ns_is_ascii_ws(p[2])))
            return p;
        p++;
    }
    return NULL;
}

/* Parses a signed integer that must consist entirely of digits. */
static gboolean
anb_int_strict(const char *str, int *out)
{
    const char *p = str;
    if (*p == '+' || *p == '-') p++;
    if (!g_ascii_isdigit(*p)) return FALSE;
    for (const char *q = p; *q; q++)
        if (!g_ascii_isdigit(*q)) return FALSE;
    *out = ns_parse_int(str, 0, -1000000, 1000000);
    return TRUE;
}

/* Parses an An+B microsyntax argument (odd, even, 2n+1, -n+3, ...) into a and b. */
static gboolean
parse_anb(const char *arg, gsize alen, int *out_a, int *out_b)
{
    char *raw = g_strndup(arg, alen);
    char *trimmed = g_strstrip(raw);
    char *s = g_malloc(strlen(trimmed) + 1);
    char *w = s;
    for (const char *r = trimmed; *r; r++)
        if (!ns_is_ascii_ws(*r)) *w++ = *r;
    *w = '\0';
    int a = 0, b = 0;
    gboolean ok = TRUE;
    if (g_ascii_strcasecmp(s, "odd") == 0) {
        a = 2;
        b = 1;
    } else if (g_ascii_strcasecmp(s, "even") == 0) {
        a = 2;
        b = 0;
    } else {
        char *n_pos = strchr(s, 'n');
        if (!n_pos) n_pos = strchr(s, 'N');
        if (n_pos) {
            *n_pos = '\0';
            const char *a_str = s;
            if (!*a_str || strcmp(a_str, "+") == 0) a = 1;
            else if (strcmp(a_str, "-") == 0) a = -1;
            else ok = anb_int_strict(a_str, &a);
            const char *b_str = n_pos + 1;
            if (*b_str) {
                if (*b_str != '+' && *b_str != '-') ok = FALSE;
                else ok = ok && anb_int_strict(b_str, &b);
            }
        } else {
            a = 0;
            ok = anb_int_strict(s, &b);
        }
    }
    g_free(s);
    g_free(raw);
    if (!ok) return FALSE;
    *out_a = a;
    *out_b = b;
    return TRUE;
}

/* Reports whether a pseudo-class name is standard but not otherwise implemented here. */
static gboolean
css_pseudo_class_is_standard(const char *name, gsize n)
{
    static const char *known[] = {
        "default", "indeterminate", "in-range", "out-of-range",
        "fullscreen", "modal", "autofill", "blank",
        "user-valid", "user-invalid", "target-within", "focus-visible",
        "local-link", "current", "past", "future",
        "playing", "paused", "muted", "seeking", "buffering", "stalled",
        "picture-in-picture", "volume-locked",
        "host", "host-context", "nth-col", "nth-last-col", "state",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(known); i++)
        if (strlen(known[i]) == n && g_ascii_strncasecmp(name, known[i], n) == 0)
            return TRUE;
    return FALSE;
}

/* Reports whether a functional/standard pseudo-element name is recognized as valid. */
static gboolean
css_pseudo_element_is_standard(const char *name, gsize n)
{
    static const char *known[] = {
        "part", "slotted", "cue", "cue-region", "highlight",
        "target-text", "spelling-error", "grammar-error",
        "file-selector-button", "details-content",
        "view-transition", "view-transition-group",
        "view-transition-image-pair", "view-transition-old",
        "view-transition-new",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(known); i++)
        if (strlen(known[i]) == n && g_ascii_strncasecmp(name, known[i], n) == 0)
            return TRUE;
    return FALSE;
}

/* Parses a pseudo-class name and argument (nth-*, :lang, :dir, :heading) into a predicate. */
static gboolean
parse_pseudo_keyword(const char *name, gsize n,
                     const char *arg, gsize alen,
                     ns_css_pseudo_pred *out)
{
    struct { const char *k; ns_css_pseudo v; } table[] = {
        { "first-child",   NS_CSS_PC_FIRST_CHILD },
        { "last-child",    NS_CSS_PC_LAST_CHILD },
        { "only-child",    NS_CSS_PC_ONLY_CHILD },
        { "first-of-type", NS_CSS_PC_FIRST_OF_TYPE },
        { "last-of-type",  NS_CSS_PC_LAST_OF_TYPE },
        { "only-of-type",  NS_CSS_PC_ONLY_OF_TYPE },
        { "empty",         NS_CSS_PC_EMPTY },
        { "root",          NS_CSS_PC_ROOT },
        { "checked",       NS_CSS_PC_CHECKED },
        { "disabled",      NS_CSS_PC_DISABLED },
        { "enabled",       NS_CSS_PC_ENABLED },
        { "required",      NS_CSS_PC_REQUIRED },
        { "optional",      NS_CSS_PC_OPTIONAL },
        { "valid",         NS_CSS_PC_VALID },
        { "invalid",       NS_CSS_PC_INVALID },
        { "in-range",      NS_CSS_PC_IN_RANGE },
        { "out-of-range",  NS_CSS_PC_OUT_OF_RANGE },
        { "default",       NS_CSS_PC_DEFAULT },
        { "indeterminate", NS_CSS_PC_INDETERMINATE },
        { "link",          NS_CSS_PC_LINK },
        { "visited",       NS_CSS_PC_VISITED },
        { "any-link",      NS_CSS_PC_ANY_LINK },
        { "hover",         NS_CSS_PC_HOVER },
        { "active",        NS_CSS_PC_ACTIVE },
        { "focus",         NS_CSS_PC_FOCUS },
        { "focus-visible", NS_CSS_PC_FOCUS_VISIBLE },
        { "focus-within",  NS_CSS_PC_FOCUS_WITHIN },
        { "target",        NS_CSS_PC_TARGET },
        { "target-within", NS_CSS_PC_TARGET_WITHIN },
        { "defined",       NS_CSS_PC_DEFINED },
        { "scope",         NS_CSS_PC_SCOPE },
        { "placeholder-shown", NS_CSS_PC_PLACEHOLDER_SHOWN },
        { "read-only",     NS_CSS_PC_READ_ONLY },
        { "read-write",    NS_CSS_PC_READ_WRITE },
        { "blank",         NS_CSS_PC_BLANK },
        { "open",          NS_CSS_PC_OPEN },
        { "popover-open",  NS_CSS_PC_POPOVER_OPEN },
        { "modal",         NS_CSS_PC_MODAL },
        { "user-valid",    NS_CSS_PC_USER_VALID },
        { "user-invalid",  NS_CSS_PC_USER_INVALID },
        { "autofill",      NS_CSS_PC_AUTOFILL },
        { "-webkit-autofill", NS_CSS_PC_AUTOFILL },
        { "playing",       NS_CSS_PC_PLAYING },
        { "paused",        NS_CSS_PC_PAUSED },
        { "muted",         NS_CSS_PC_MUTED },
        { "seeking",       NS_CSS_PC_SEEKING },
        { "buffering",     NS_CSS_PC_BUFFERING },
        { "stalled",       NS_CSS_PC_STALLED },
    };
    for (gsize i = 0; i < G_N_ELEMENTS(table); i++) {
        gsize klen = strlen(table[i].k);
        if (klen == n && g_ascii_strncasecmp(name, table[i].k, n) == 0) {
            out->kind = table[i].v;
            out->a = 0;
            out->b = 0;
            return TRUE;
        }
    }
    if (n == 7 && g_ascii_strncasecmp(name, "heading", 7) == 0) {
        out->kind = NS_CSS_PC_HEADING;
        out->a = 0;
        out->b = 0;
        if (!arg) {
            out->arg = NULL;
            return TRUE;
        }
        char *raw = g_strndup(arg, alen);
        char **items = g_strsplit(raw, ",", -1);
        gboolean ok = items[0] != NULL;
        for (int i = 0; ok && items[i]; i++) {
            int v = 0;
            if (!anb_int_strict(g_strstrip(items[i]), &v)) ok = FALSE;
        }
        g_strfreev(items);
        if (!ok) {
            g_free(raw);
            return FALSE;
        }
        out->arg = raw;
        return TRUE;
    }
    if (arg && ((n == 9 && g_ascii_strncasecmp(name, "nth-child", 9) == 0) ||
                (n == 14 && g_ascii_strncasecmp(name, "nth-last-child", 14) == 0) ||
                (n == 11 && g_ascii_strncasecmp(name, "nth-of-type", 11) == 0) ||
                (n == 16 && g_ascii_strncasecmp(name, "nth-last-of-type", 16) == 0))) {
        const char *as = arg;
        const char *ae = arg + alen;
        const char *of = (n == 9 || n == 14) ? css_find_nth_of(as, ae) : NULL;
        const char *anb_end = of ? of : ae;
        int a = 0, b = 0;
        if (!parse_anb(as, (gsize)(anb_end - as), &a, &b)) return FALSE;
        if (of) {
            const char *fs = css_skip_ws_comments(of + 2, ae);
            GPtrArray *group = parse_selector_group(fs, (gsize)(ae - fs), 1);
            if (!group || group->len == 0) {
                if (group) g_ptr_array_free(group, TRUE);
                return FALSE;
            }
            out->of_group = group;
        }
        if (n == 9) out->kind = NS_CSS_PC_NTH_CHILD;
        else if (n == 14) out->kind = NS_CSS_PC_NTH_LAST_CHILD;
        else if (n == 11) out->kind = NS_CSS_PC_NTH_OF_TYPE;
        else out->kind = NS_CSS_PC_NTH_LAST_OF_TYPE;
        out->a = a;
        out->b = b;
        return TRUE;
    }
    if (arg && n == 4 && g_ascii_strncasecmp(name, "lang", 4) == 0) {
        char *lang = css_trim_dup_range(arg, arg + alen);
        if (!lang || !*lang) {
            g_free(lang);
            return FALSE;
        }
        out->kind = NS_CSS_PC_LANG;
        out->arg = lang;
        return TRUE;
    }
    if (arg && n == 3 && g_ascii_strncasecmp(name, "dir", 3) == 0) {
        const char *end = arg + alen;
        const char *p = css_skip_ws_comments(arg, end);
        if (p >= end || (!is_ident_start(*p) && *p != '\\'))
            return FALSE;
        char *dir = read_css_ident(&p, end);
        p = css_skip_ws_comments(p, end);
        if (!*dir || p != end) {
            g_free(dir);
            return FALSE;
        }
        out->kind = NS_CSS_PC_DIR;
        out->arg = g_ascii_strdown(dir, -1);
        g_free(dir);
        return TRUE;
    }
    return FALSE;
}

/* Raises (a, b, c) to the highest specificity in a selector list, as :is()/:not() require. */
static void
selector_group_max_specificity(const GPtrArray *group, int *a, int *b, int *c)
{
    for (guint i = 0; group && i < group->len; i++) {
        const ns_css_selector *sub = g_ptr_array_index(group, i);
        if (sub->spec_a > *a ||
            (sub->spec_a == *a && sub->spec_b > *b) ||
            (sub->spec_a == *a && sub->spec_b == *b && sub->spec_c > *c)) {
            *a = sub->spec_a;
            *b = sub->spec_b;
            *c = sub->spec_c;
        }
    }
}

static ns_css_selector *
parse_one_selector(const char **pp, const char *end, int depth)
{
    return parse_one_selector_rel(pp, end, depth, FALSE);
}

/* FNV-1a hash of a kind tag plus ASCII-lowercased name, for ancestor bloom filtering. */
static guint32
css_identifier_hash(char kind, const char *name, gsize len)
{
    guint32 h = 2166136261u;
    h = (h ^ (guchar)kind) * 16777619u;
    for (gsize i = 0; i < len; i++)
        h = (h ^ (guchar)g_ascii_tolower(name[i])) * 16777619u;
    return h;
}

#define CSS_ATTR_HASH_MAX_VALUE 128

/* FNV-1a hash of an attribute name/value pair for [attr=value] ancestor filtering. */
static guint32
css_attr_value_hash(const char *name, const char *value, gsize value_len)
{
    guint32 h = css_identifier_hash('=', name, strlen(name));
    h = (h ^ (guchar)'=') * 16777619u;
    for (gsize i = 0; i < value_len; i++)
        h = (h ^ (guchar)g_ascii_tolower(value[i])) * 16777619u;
    return h;
}

/* Appends an ancestor hash to the selector's fixed-size list, dropping it when full. */
static void
css_selector_add_ancestor_hash(ns_css_selector *sel, guint32 hash)
{
    if (sel->n_ancestor_hashes < G_N_ELEMENTS(sel->ancestor_hashes))
        sel->ancestor_hashes[sel->n_ancestor_hashes++] = hash;
}

/* Collects id/class/type/attr hashes of ancestor compounds for fast rejection. */
static void
css_selector_collect_ancestor_hashes(ns_css_selector *sel)
{
    for (int k = (int)sel->compounds->len - 2; k >= 0; k--) {
        ns_css_comb right = g_array_index(sel->combinators, ns_css_comb, k + 1);
        if (right != NS_CSS_COMB_DESCENDANT && right != NS_CSS_COMB_CHILD)
            continue;
        const ns_css_simple *c = g_ptr_array_index(sel->compounds, k);
        if (c->id)
            css_selector_add_ancestor_hash(
                sel, css_identifier_hash('#', c->id, strlen(c->id)));
        for (guint i = 0; c->attrs && i < c->attrs->len; i++) {
            const ns_css_attr_pred *a =
                &g_array_index(c->attrs, ns_css_attr_pred, i);
            if (a->op != NS_CSS_ATTR_EQ || !a->name || !a->value ||
                a->namespace_uri || a->namespace_any)
                continue;
            gsize vlen = strlen(a->value);
            if (vlen > CSS_ATTR_HASH_MAX_VALUE) continue;
            css_selector_add_ancestor_hash(
                sel, css_attr_value_hash(a->name, a->value, vlen));
        }
        for (guint i = 0; i < c->classes->len; i++) {
            const char *cls = g_ptr_array_index(c->classes, i);
            css_selector_add_ancestor_hash(
                sel, css_identifier_hash('.', cls, strlen(cls)));
        }
        if (c->type_lower)
            css_selector_add_ancestor_hash(
                sel, css_identifier_hash('%', c->type_lower,
                                         strlen(c->type_lower)));
    }
}

/* Reports whether p names a user-action pseudo-class allowed after a pseudo-element. */
static gboolean
css_user_action_pseudo_at(const char *p, const char *end)
{
    static const char *const names[] = {
        "hover", "active", "focus", "focus-visible", "focus-within",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(names); i++) {
        gsize n = strlen(names[i]);
        if ((gsize)(end - p) >= n &&
            g_ascii_strncasecmp(p, names[i], n) == 0 &&
            (p + n == end || !is_ident(p[n])))
            return TRUE;
    }
    return FALSE;
}

/* Parses one complex selector, computing specificity; relative allows a leading combinator. */
static ns_css_selector *
parse_one_selector_rel(const char **pp, const char *end, int depth,
                       gboolean relative)
{
    ns_css_selector *sel = g_new0(ns_css_selector, 1);
    sel->compounds   = g_ptr_array_new();
    sel->combinators = g_array_new(FALSE, FALSE, sizeof(ns_css_comb));

    ns_css_comb pending = NS_CSS_COMB_NONE;
    gboolean expect_compound = TRUE;
    gboolean leading_comb_used = FALSE;
    const char *p = *pp;

    while (p < end) {

        gboolean had_ws = FALSE;
        const char *before_ws = p;
        p = css_skip_ws_comments(p, end);
        had_ws = p > before_ws;
        if (p >= end) break;
        char c = *p;

        if (c == ',' || c == '{') break;

        if (sel->pseudo_element != NS_CSS_PE_NONE)
            g_sel_parse_error = TRUE;

        if (c == '>' || c == '+' || c == '~') {
            if (relative && sel->compounds->len == 0 && !leading_comb_used)
                leading_comb_used = TRUE;
            else if (expect_compound || sel->compounds->len == 0)
                g_sel_parse_error = TRUE;
            pending = c == '>' ? NS_CSS_COMB_CHILD
                    : c == '+' ? NS_CSS_COMB_ADJACENT
                    : NS_CSS_COMB_SIBLING;
            expect_compound = TRUE;
            p++;
            continue;
        }

        if (had_ws && !expect_compound)
            pending = NS_CSS_COMB_DESCENDANT;

        ns_css_simple *cmp = ns_css_simple_new();
        if (g_sel_default_namespace)
            cmp->namespace_uri = g_strdup(g_sel_default_namespace);
        else
            cmp->namespace_any = TRUE;
        gboolean any = FALSE;
        while (p < end) {
            const char *tok_start = p;
            char cc = *p;
            if (ns_is_ascii_ws(cc) || cc == ',' || cc == '{' ||
                cc == '>' || cc == '+' || cc == '~')
                break;
            if (sel->pseudo_element != NS_CSS_PE_NONE &&
                !(cc == ':' && p + 1 < end && p[1] != ':' &&
                  css_user_action_pseudo_at(p + 1, end)))
                g_sel_parse_error = TRUE;
            if (cc == '*' || (cc == '|' && !(p + 1 < end && p[1] == '='))) {
                if (any) {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                }
                if (cc == '*') p++;
                if (p < end && *p == '|' && !(p + 1 < end && p[1] == '=')) {
                    g_clear_pointer(&cmp->namespace_uri, g_free);
                    cmp->namespace_any = cc == '*';
                    if (cc == '|')
                        cmp->namespace_any = FALSE;
                    p++;
                    if (p < end && *p == '*') {
                        p++;
                        g_free(cmp->type);
                        cmp->type = g_strdup("*");
                    }
                    else {
                        char *type = read_css_ident(&p, end);
                        if (type && *type) {
                            if (!cmp->type) {
                                cmp->type = g_strdup(type);
                                sel->spec_c += 1;
                            }
                        }
                        else {
                            g_sel_parse_error = TRUE;
                        }
                        g_free(type);
                    }
                }
                else {
                    if (cmp->type) {
                        g_sel_parse_error = TRUE;
                        cmp->never_match = TRUE;
                    }
                    g_free(cmp->type);
                    cmp->type = g_strdup("*");
                }
                any = TRUE;
            } else if (cc == '#') {
                p++;
                char *id_str = read_css_ident(&p, end);
                if (id_str && *id_str) {
                    g_free(cmp->id);
                    cmp->id = id_str;
                    sel->spec_a += 1;
                } else {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                    g_free(id_str);
                }
                any = TRUE;
            } else if (cc == '.') {
                p++;
                gboolean bad_start = FALSE;
                if (p < end) {
                    unsigned char nc = (unsigned char)*p;
                    if (g_ascii_isdigit(nc))
                        bad_start = TRUE;
                    else if (nc == '-' && p + 1 < end &&
                             g_ascii_isdigit((unsigned char)p[1]))
                        bad_start = TRUE;
                }
                char *cls = read_css_ident(&p, end);
                if (!bad_start && cls && *cls) {
                    gsize cls_len = strlen(cls);
                    g_ptr_array_add(cmp->classes, cls);
                    g_array_append_val(cmp->class_lens, cls_len);
                    sel->spec_b += 1;
                } else {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                    g_free(cls);
                }
                any = TRUE;
            } else if (is_ident_start(cc) || cc == '\\') {
                if (any) {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                }
                char *type = read_css_ident(&p, end);
                if (p < end && *p == '|' && !(p + 1 < end && p[1] == '=')) {
                    g_sel_ns_prefix = TRUE;
                    const char *namespace_uri = g_sel_namespaces
                        ? g_hash_table_lookup(g_sel_namespaces, type) : NULL;
                    if (!namespace_uri) {
                        g_sel_parse_error = TRUE;
                        cmp->never_match = TRUE;
                    } else {
                        g_clear_pointer(&cmp->namespace_uri, g_free);
                        cmp->namespace_uri = g_strdup(namespace_uri);
                        cmp->namespace_any = FALSE;
                    }
                    p++;
                    if (p < end && *p == '*') {
                        p++;
                        g_free(cmp->type);
                        cmp->type = g_strdup("*");
                    }
                    else {
                        char *local_name = read_css_ident(&p, end);
                        if (local_name && *local_name) {
                            g_free(cmp->type);
                            cmp->type = g_strdup(local_name);
                            sel->spec_c += 1;
                        } else {
                            g_sel_parse_error = TRUE;
                            cmp->never_match = TRUE;
                        }
                        g_free(local_name);
                    }
                }
                else if (!cmp->type) {
                    cmp->type = g_strdup(type);
                    sel->spec_c += 1;
                }
                else {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                }
                g_free(type);
                any = TRUE;
            } else if (cc == ':') {
                p++;
                gboolean is_element = (p < end && *p == ':');
                if (is_element) p++;
                char *pseudo_name = read_css_ident(&p, end);
                const char *name_s = pseudo_name;
                gsize name_n = strlen(pseudo_name);
                if (name_n == 0) {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                    g_free(pseudo_name);
                    any = TRUE;
                    continue;
                }
                const char *arg_s = NULL;
                gsize arg_n = 0;
                if (p < end && *p == '(') {
                    p++;
                    arg_s = p;
                    char term = 0;
                    const char *arg_end = css_scan_until(p, end, ")", &term);
                    arg_n = (gsize)(arg_end - arg_s);
                    p = term == ')' ? arg_end + 1 : arg_end;
                }
                if (is_element ||
                    (name_n == 6 && g_ascii_strncasecmp(name_s, "before", 6) == 0) ||
                    (name_n == 5 && g_ascii_strncasecmp(name_s, "after",  5) == 0) ||
                    (name_n == 10 && g_ascii_strncasecmp(name_s, "first-line", 10) == 0) ||
                    (name_n == 12 && g_ascii_strncasecmp(name_s, "first-letter", 12) == 0)) {
                    if (name_n == 6 && g_ascii_strncasecmp(name_s, "before", 6) == 0) {
                        sel->pseudo_element = NS_CSS_PE_BEFORE;
                        sel->spec_c += 1;
                    } else if (name_n == 5 && g_ascii_strncasecmp(name_s, "after", 5) == 0) {
                        sel->pseudo_element = NS_CSS_PE_AFTER;
                        sel->spec_c += 1;
                    } else if (name_n == 12 && g_ascii_strncasecmp(name_s, "first-letter", 12) == 0) {
                        sel->pseudo_element = NS_CSS_PE_FIRST_LETTER;
                        sel->spec_c += 1;
                    } else if (name_n == 10 && g_ascii_strncasecmp(name_s, "first-line", 10) == 0) {
                        sel->pseudo_element = NS_CSS_PE_FIRST_LINE;
                        sel->spec_c += 1;
                    } else if (name_n == 9 && g_ascii_strncasecmp(name_s, "selection", 9) == 0) {
                        sel->pseudo_element = NS_CSS_PE_SELECTION;
                        sel->spec_c += 1;
                    } else if (name_n == 6 && g_ascii_strncasecmp(name_s, "marker", 6) == 0) {
                        sel->pseudo_element = NS_CSS_PE_MARKER;
                        sel->spec_c += 1;
                    } else if (name_n == 8 && g_ascii_strncasecmp(name_s, "backdrop", 8) == 0) {
                        sel->pseudo_element = NS_CSS_PE_BACKDROP;
                        sel->spec_c += 1;
                    } else if (name_n == 20 &&
                               g_ascii_strncasecmp(name_s,
                                                   "file-selector-button",
                                                   20) == 0) {
                        sel->pseudo_element = NS_CSS_PE_FILE_SELECTOR_BUTTON;
                        sel->spec_c += 1;
                    } else if ((name_n == 11 &&
                                g_ascii_strncasecmp(name_s, "placeholder", 11) == 0) ||
                               (name_n == 25 &&
                                g_ascii_strncasecmp(name_s, "-webkit-input-placeholder", 25) == 0) ||
                               (name_n == 21 &&
                                g_ascii_strncasecmp(name_s, "-ms-input-placeholder", 21) == 0) ||
                               (name_n == 16 &&
                                g_ascii_strncasecmp(name_s, "-moz-placeholder", 16) == 0)) {
                        sel->pseudo_element = NS_CSS_PE_PLACEHOLDER;
                        sel->spec_c += 1;
                    } else {
                        cmp->never_match = TRUE;
                        if (name_s[0] != '-'
                            && !css_pseudo_element_is_standard(name_s, name_n))
                            g_sel_parse_error = TRUE;
                    }
                } else if (name_n == 3 && arg_s &&
                           g_ascii_strncasecmp(name_s, "has", 3) == 0 &&
                           g_sel_has_depth > 0) {
                    cmp->never_match = TRUE;
                    g_sel_parse_error = TRUE;
                } else if (name_n == 3 && arg_s &&
                           g_ascii_strncasecmp(name_s, "has", 3) == 0) {
                    g_sel_has_depth++;
                    GPtrArray *group = parse_selector_group_rel(arg_s, arg_n,
                                                                depth + 1, TRUE);
                    g_sel_has_depth--;
                    if (group->len == 0) {
                        g_ptr_array_free(group, TRUE);
                        cmp->never_match = TRUE;
                        g_sel_parse_error = TRUE;
                    } else {
                        if (!cmp->has_groups)
                            cmp->has_groups = g_ptr_array_new_with_free_func(
                                matches_any_group_free);
                        g_ptr_array_add(cmp->has_groups, group);
                        int ma = 0, mb = 0, mc = 0;
                        selector_group_max_specificity(group, &ma, &mb, &mc);
                        sel->spec_a += ma;
                        sel->spec_b += mb;
                        sel->spec_c += mc;
                    }
                } else if (name_n > 0 && arg_s &&
                           ((name_n == 2 && g_ascii_strncasecmp(name_s, "is",    2) == 0) ||
                            (name_n == 5 && g_ascii_strncasecmp(name_s, "where", 5) == 0))) {
                    gboolean is_where = (name_n == 5);
                    gboolean saved_err = g_sel_parse_error;
                    gboolean saved_ns = g_sel_ns_prefix;
                    GPtrArray *group = parse_selector_group(arg_s, arg_n, depth + 1);
                    if (!g_sel_strict) g_sel_parse_error = saved_err;
                    g_sel_ns_prefix = saved_ns;
                    if (group->len == 0) {
                        g_ptr_array_free(group, TRUE);
                        cmp->never_match = TRUE;
                    } else {
                        if (!cmp->matches_any)
                            cmp->matches_any = g_ptr_array_new_with_free_func(
                                matches_any_group_free);
                        g_ptr_array_add(cmp->matches_any, group);
                        if (!is_where) {
                            int ma = 0, mb = 0, mc = 0;
                            selector_group_max_specificity(group, &ma, &mb, &mc);
                            sel->spec_a += ma;
                            sel->spec_b += mb;
                            sel->spec_c += mc;
                        }
                    }
                } else if (name_n == 3 && arg_s &&
                           g_ascii_strncasecmp(name_s, "not", 3) == 0) {
                    GPtrArray *group = parse_selector_group(arg_s, arg_n, depth + 1);
                    if (group->len == 0) {
                        g_ptr_array_free(group, TRUE);
                        cmp->never_match = TRUE;
                        g_sel_parse_error = TRUE;
                    } else {
                        if (!cmp->matches_none)
                            cmp->matches_none = g_ptr_array_new_with_free_func(
                                matches_any_group_free);
                        g_ptr_array_add(cmp->matches_none, group);
                        int ma = 0, mb = 0, mc = 0;
                        selector_group_max_specificity(group, &ma, &mb, &mc);
                        sel->spec_a += ma;
                        sel->spec_b += mb;
                        sel->spec_c += mc;
                    }
                } else if (name_n > 0) {
                    ns_css_pseudo_pred pc = {0};
                    if (parse_pseudo_keyword(name_s, name_n, arg_s, arg_n, &pc)) {
                        g_array_append_val(cmp->pseudos, pc);
                        if (pc.kind == NS_CSS_PC_HOVER)
                            g_sel_has_hover = TRUE;
                        if (pc.kind == NS_CSS_PC_ACTIVE)
                            g_sel_has_active = TRUE;
                        sel->spec_b += 1;
                        int ma = 0, mb = 0, mc = 0;
                        selector_group_max_specificity(pc.of_group, &ma, &mb, &mc);
                        sel->spec_a += ma;
                        sel->spec_b += mb;
                        sel->spec_c += mc;
                    } else {
                        cmp->never_match = TRUE;
                        if (!css_pseudo_class_is_standard(name_s, name_n))
                            g_sel_parse_error = TRUE;
                    }
                } else {
                    cmp->never_match = TRUE;
                    g_sel_parse_error = TRUE;
                }
                g_free(pseudo_name);
                any = TRUE;
            } else if (cc == '[') {
                p++;
                p = css_skip_ws_comments(p, end);
                gboolean attr_namespace_any = FALSE;
                char *attr_namespace_uri = NULL;
                char *attr_name = NULL;
                if (p + 1 < end && *p == '*' && p[1] == '|') {
                    attr_namespace_any = TRUE;
                    p += 2;
                    attr_name = read_css_ident(&p, end);
                } else if (p < end && *p == '|' &&
                           !(p + 1 < end && p[1] == '=')) {
                    p++;
                    attr_name = read_css_ident(&p, end);
                } else {
                    char *first = read_css_ident(&p, end);
                    if (first && *first && p < end && *p == '|' &&
                        !(p + 1 < end && p[1] == '=')) {
                        g_sel_ns_prefix = TRUE;
                        const char *resolved = g_sel_namespaces
                            ? g_hash_table_lookup(g_sel_namespaces, first)
                            : NULL;
                        if (!resolved) {
                            g_sel_parse_error = TRUE;
                            cmp->never_match = TRUE;
                        } else {
                            attr_namespace_uri = g_strdup(resolved);
                        }
                        p++;
                        attr_name = read_css_ident(&p, end);
                        g_free(first);
                    } else {
                        attr_name = first;
                    }
                }
                if (!attr_name || !*attr_name) {
                    g_free(attr_name);
                    g_free(attr_namespace_uri);
                    char term = 0;
                    const char *close = css_scan_until(p, end, "]", &term);
                    p = term == ']' ? close + 1 : close;
                    continue;
                }
                ns_css_attr_pred ap = {0};
                ap.name = g_strdup(attr_name);
                ap.namespace_uri = attr_namespace_uri;
                ap.namespace_any = attr_namespace_any;
                if (!ap.namespace_any && !ap.namespace_uri) {
                    char *lower_name = ascii_lower(attr_name,
                                                   strlen(attr_name));
                    ap.name_bit = ns_attr_name_bloom_bit(attr_name) |
                                  ns_attr_name_bloom_bit(lower_name);
                    g_free(lower_name);
                }
                g_free(attr_name);
                ap.op   = NS_CSS_ATTR_PRESENT;
                p = css_skip_ws_comments(p, end);
                if (p < end && (*p == '=' || *p == '^' || *p == '$' ||
                                *p == '*' || *p == '~' || *p == '|')) {
                    char op_c = *p;
                    if (op_c == '=')      ap.op = NS_CSS_ATTR_EQ;
                    else if (op_c == '^') { p++; if (p < end && *p == '=') ap.op = NS_CSS_ATTR_PREFIX; }
                    else if (op_c == '$') { p++; if (p < end && *p == '=') ap.op = NS_CSS_ATTR_SUFFIX; }
                    else if (op_c == '*') { p++; if (p < end && *p == '=') ap.op = NS_CSS_ATTR_SUBSTR; }
                    else if (op_c == '~') { p++; if (p < end && *p == '=') ap.op = NS_CSS_ATTR_WORD;   }
                    else if (op_c == '|') { p++; if (p < end && *p == '=') ap.op = NS_CSS_ATTR_HYPHEN; }
                    if (p < end && *p == '=') p++;
                    p = css_skip_ws_comments(p, end);
                    char q = (p < end) ? *p : 0;
                    if (q == '"' || q == '\'') {
                        ap.value = read_css_string(&p, end);
                    } else {
                        ap.value = read_css_ident(&p, end);
                    }
                }
                p = css_skip_ws_comments(p, end);
                if (p < end && *p != ']') {
                    const char *flag_start = p;
                    char *flag = read_css_ident(&p, end);
                    if (flag && g_ascii_strcasecmp(flag, "i") == 0) {
                        if (ap.op == NS_CSS_ATTR_PRESENT) g_sel_parse_error = TRUE;
                        ap.case_insensitive = TRUE;
                    } else if (flag && g_ascii_strcasecmp(flag, "s") == 0) {
                        if (ap.op == NS_CSS_ATTR_PRESENT) g_sel_parse_error = TRUE;
                        ap.case_sensitive = TRUE;
                    } else {
                        p = flag_start;
                        g_sel_parse_error = TRUE;
                    }
                    g_free(flag);
                }
                p = css_skip_ws_comments(p, end);
                if (p < end && *p != ']')
                    g_sel_parse_error = TRUE;
                char term = 0;
                const char *close = css_scan_until(p, end, "]", &term);
                p = term == ']' ? close + 1 : close;
                g_array_append_val(cmp->attrs, ap);
                sel->spec_b += 1;
                any = TRUE;
            } else {
                break;
            }
            if (p == tok_start) break;
        }
        if (!any) { ns_css_simple_free(cmp); break; }
        if (cmp->type && strcmp(cmp->type, "*") != 0) {
            cmp->type_lower = g_ascii_strdown(cmp->type, -1);
            cmp->type_has_colon = strchr(cmp->type, ':') != NULL;
        }
        g_ptr_array_add(sel->compounds, cmp);
        g_array_append_val(sel->combinators, pending);
        pending = NS_CSS_COMB_NONE;
        expect_compound = FALSE;
    }
    *pp = p;
    if (pending != NS_CSS_COMB_NONE)
        g_sel_parse_error = TRUE;
    if (sel->compounds->len == 0) {
        ns_css_selector_free(sel);
        return NULL;
    }
    if (!relative) css_selector_collect_ancestor_hashes(sel);
    return sel;
}

/* Parses a number with optional unit; absolute units (pt, pc, cm, mm, q, in) become px. */
static gboolean
parse_length(const char *text, double *out_v, ns_css_unit *out_unit)
{
    if (!text || !*text) return FALSE;
    const char *p = text;
    if (*p == '-' || *p == '+') p++;
    const char *num_start = p;
    while (*p && (g_ascii_isdigit(*p) || *p == '.')) p++;
    if (p == num_start) return FALSE;
    char *end = NULL;
    double v = g_ascii_strtod(text, &end);
    if (!end || end == text) return FALSE;
    *out_v = v;
    if (*end == '\0') { *out_unit = NS_CSS_UNIT_NUMBER; return TRUE; }
    if (g_ascii_strcasecmp(end, "px") == 0) { *out_unit = NS_CSS_UNIT_PX; return TRUE; }
    if (g_ascii_strcasecmp(end, "em")  == 0) { *out_unit = NS_CSS_UNIT_EM;  return TRUE; }
    if (g_ascii_strcasecmp(end, "rem") == 0) { *out_unit = NS_CSS_UNIT_REM; return TRUE; }
    if (g_ascii_strcasecmp(end, "%")   == 0) { *out_unit = NS_CSS_UNIT_PERCENT; return TRUE; }
    if (g_ascii_strcasecmp(end, "vw") == 0) { *out_unit = NS_CSS_UNIT_VW; return TRUE; }
    if (g_ascii_strcasecmp(end, "vh") == 0) { *out_unit = NS_CSS_UNIT_VH; return TRUE; }
    if (g_ascii_strcasecmp(end, "svw") == 0) { *out_unit = NS_CSS_UNIT_SVW; return TRUE; }
    if (g_ascii_strcasecmp(end, "lvw") == 0) { *out_unit = NS_CSS_UNIT_LVW; return TRUE; }
    if (g_ascii_strcasecmp(end, "dvw") == 0) { *out_unit = NS_CSS_UNIT_DVW; return TRUE; }
    if (g_ascii_strcasecmp(end, "svh") == 0) { *out_unit = NS_CSS_UNIT_SVH; return TRUE; }
    if (g_ascii_strcasecmp(end, "lvh") == 0) { *out_unit = NS_CSS_UNIT_LVH; return TRUE; }
    if (g_ascii_strcasecmp(end, "dvh") == 0) { *out_unit = NS_CSS_UNIT_DVH; return TRUE; }
    if (g_ascii_strcasecmp(end, "vi") == 0) { *out_unit = NS_CSS_UNIT_VI; return TRUE; }
    if (g_ascii_strcasecmp(end, "svi") == 0) { *out_unit = NS_CSS_UNIT_SVI; return TRUE; }
    if (g_ascii_strcasecmp(end, "lvi") == 0) { *out_unit = NS_CSS_UNIT_LVI; return TRUE; }
    if (g_ascii_strcasecmp(end, "dvi") == 0) { *out_unit = NS_CSS_UNIT_DVI; return TRUE; }
    if (g_ascii_strcasecmp(end, "vb") == 0) { *out_unit = NS_CSS_UNIT_VB; return TRUE; }
    if (g_ascii_strcasecmp(end, "svb") == 0) { *out_unit = NS_CSS_UNIT_SVB; return TRUE; }
    if (g_ascii_strcasecmp(end, "lvb") == 0) { *out_unit = NS_CSS_UNIT_LVB; return TRUE; }
    if (g_ascii_strcasecmp(end, "dvb") == 0) { *out_unit = NS_CSS_UNIT_DVB; return TRUE; }
    if (g_ascii_strcasecmp(end, "cqw") == 0) { *out_unit = NS_CSS_UNIT_CQW; return TRUE; }
    if (g_ascii_strcasecmp(end, "cqh") == 0) { *out_unit = NS_CSS_UNIT_CQH; return TRUE; }
    if (g_ascii_strcasecmp(end, "cqi") == 0) { *out_unit = NS_CSS_UNIT_CQI; return TRUE; }
    if (g_ascii_strcasecmp(end, "cqb") == 0) { *out_unit = NS_CSS_UNIT_CQB; return TRUE; }
    if (g_ascii_strcasecmp(end, "vmin") == 0) { *out_unit = NS_CSS_UNIT_VMIN; return TRUE; }
    if (g_ascii_strcasecmp(end, "vmax") == 0) { *out_unit = NS_CSS_UNIT_VMAX; return TRUE; }
    if (g_ascii_strcasecmp(end, "svmin") == 0) { *out_unit = NS_CSS_UNIT_SVMIN; return TRUE; }
    if (g_ascii_strcasecmp(end, "lvmin") == 0) { *out_unit = NS_CSS_UNIT_LVMIN; return TRUE; }
    if (g_ascii_strcasecmp(end, "dvmin") == 0) { *out_unit = NS_CSS_UNIT_DVMIN; return TRUE; }
    if (g_ascii_strcasecmp(end, "svmax") == 0) { *out_unit = NS_CSS_UNIT_SVMAX; return TRUE; }
    if (g_ascii_strcasecmp(end, "lvmax") == 0) { *out_unit = NS_CSS_UNIT_LVMAX; return TRUE; }
    if (g_ascii_strcasecmp(end, "dvmax") == 0) { *out_unit = NS_CSS_UNIT_DVMAX; return TRUE; }
    if (g_ascii_strcasecmp(end, "cqmin") == 0) { *out_unit = NS_CSS_UNIT_CQMIN; return TRUE; }
    if (g_ascii_strcasecmp(end, "cqmax") == 0) { *out_unit = NS_CSS_UNIT_CQMAX; return TRUE; }
    if (g_ascii_strcasecmp(end, "pt")  == 0) {
        *out_v = v * (96.0 / 72.0);
        *out_unit = NS_CSS_UNIT_PX;
        return TRUE;
    }
    if (g_ascii_strcasecmp(end, "pc")  == 0) {
        *out_v = v * 16.0;
        *out_unit = NS_CSS_UNIT_PX;
        return TRUE;
    }
    if (g_ascii_strcasecmp(end, "ex")   == 0) { *out_unit = NS_CSS_UNIT_EX;   return TRUE; }
    if (g_ascii_strcasecmp(end, "ch")   == 0) { *out_unit = NS_CSS_UNIT_CH;   return TRUE; }
    if (g_ascii_strcasecmp(end, "cap")  == 0) { *out_unit = NS_CSS_UNIT_CAP;  return TRUE; }
    if (g_ascii_strcasecmp(end, "ic")   == 0) { *out_unit = NS_CSS_UNIT_IC;   return TRUE; }
    if (g_ascii_strcasecmp(end, "rex")  == 0) { *out_unit = NS_CSS_UNIT_REX;  return TRUE; }
    if (g_ascii_strcasecmp(end, "rch")  == 0) { *out_unit = NS_CSS_UNIT_RCH;  return TRUE; }
    if (g_ascii_strcasecmp(end, "rcap") == 0) { *out_unit = NS_CSS_UNIT_RCAP; return TRUE; }
    if (g_ascii_strcasecmp(end, "ric")  == 0) { *out_unit = NS_CSS_UNIT_RIC;  return TRUE; }
    if (g_ascii_strcasecmp(end, "lh") == 0) {
        *out_unit = NS_CSS_UNIT_LH;
        return TRUE;
    }
    if (g_ascii_strcasecmp(end, "rlh") == 0) {
        *out_unit = NS_CSS_UNIT_RLH;
        return TRUE;
    }
    if (g_ascii_strcasecmp(end, "cm")  == 0) { *out_v = v * (96.0 / 2.54); *out_unit = NS_CSS_UNIT_PX; return TRUE; }
    if (g_ascii_strcasecmp(end, "mm")  == 0) { *out_v = v * (96.0 / 25.4); *out_unit = NS_CSS_UNIT_PX; return TRUE; }
    if (g_ascii_strcasecmp(end, "q")   == 0) { *out_v = v * (96.0 / 101.6); *out_unit = NS_CSS_UNIT_PX; return TRUE; }
    if (g_ascii_strcasecmp(end, "in")  == 0) { *out_v = v * 96.0;   *out_unit = NS_CSS_UNIT_PX; return TRUE; }
    return FALSE;
}

/* Maps absolute font-size keywords (xx-small..xxx-large) to px; -1 if not a keyword. */
static double
font_size_keyword_px(const char *t)
{
    if (!t) return -1;
    if (g_ascii_strcasecmp(t, "xx-small")  == 0) return 9;
    if (g_ascii_strcasecmp(t, "x-small")   == 0) return 10;
    if (g_ascii_strcasecmp(t, "small")     == 0) return 13;
    if (g_ascii_strcasecmp(t, "medium")    == 0) return 16;
    if (g_ascii_strcasecmp(t, "large")     == 0) return 18;
    if (g_ascii_strcasecmp(t, "x-large")   == 0) return 24;
    if (g_ascii_strcasecmp(t, "xx-large")  == 0) return 32;
    if (g_ascii_strcasecmp(t, "xxx-large") == 0) return 48;
    return -1;
}

static ns_css_value *parse_calc(const char *text);
static ns_css_value *parse_calc_any(const char *text);
static ns_css_value *parse_calc_inner(const char *text);

typedef struct { double em, rem, lh, rlh, vw, vh, vmin, vmax; } ns_font_units;

/* Records an em/rem/lh/rlh amount in font, or approximates it to px when font is NULL. */
static void
font_units_set(ns_font_units *font, ns_css_unit unit, double v,
               double *out_px)
{
    if (!font) {
        *out_px = v * (unit == NS_CSS_UNIT_EM || unit == NS_CSS_UNIT_REM
                       ? 16.0 : 19.2);
        return;
    }
    if (unit == NS_CSS_UNIT_EM) font->em = v;
    else if (unit == NS_CSS_UNIT_REM) font->rem = v;
    else if (unit == NS_CSS_UNIT_LH) font->lh = v;
    else font->rlh = v;
}

/* Resolves a length/calc into px and percent parts; can keep font/viewport terms. */
static gboolean
resolve_to_px_pct_font(const char *text, gsize len, double *out_px,
                       double *out_pct, ns_font_units *font)
{
    char *s = g_strndup(text, len);
    g_strstrip(s);
    *out_px = 0;
    *out_pct = 0;
    ns_css_value *v = parse_calc(s);
    if (!v) {
        char *wrapped = g_strdup_printf("calc(%s)", s);
        v = parse_calc(wrapped);
        g_free(wrapped);
    }
    if (v && v->kind == NS_CSS_V_CALC) {
        if (font) {
            font->em = v->u.calc.em;
            font->rem = v->u.calc.rem;
            font->lh = v->u.calc.lh;
            font->rlh = v->u.calc.rlh;
            font->vw = v->u.calc.vw;
            font->vh = v->u.calc.vh;
            font->vmin = v->u.calc.vmin;
            font->vmax = v->u.calc.vmax;
            *out_px = v->u.calc.px;
        } else {
            *out_px = v->u.calc.px + v->u.calc.em * 16.0 +
                      v->u.calc.rem * calc_rem_px() +
                      (v->u.calc.lh + v->u.calc.rlh) * 19.2;
        }
        *out_pct = v->u.calc.pct;
        ns_css_value_free(v);
        g_free(s);
        return TRUE;
    }
    if (v && v->kind == NS_CSS_V_LENGTH) {
        switch (v->u.length.unit) {
        case NS_CSS_UNIT_PERCENT:
            *out_pct = v->u.length.v;
            break;
        case NS_CSS_UNIT_EM:
        case NS_CSS_UNIT_REM:
        case NS_CSS_UNIT_LH:
        case NS_CSS_UNIT_RLH:
            font_units_set(font, v->u.length.unit, v->u.length.v, out_px);
            break;
        NS_CSS_CASE_VIEWPORT_UNITS:
            *out_px = viewport_resolve(v->u.length.v, v->u.length.unit);
            if (font)
                viewport_unit_coeff(v->u.length.unit, v->u.length.v,
                                    &font->vw, &font->vh, &font->vmin,
                                    &font->vmax);
            break;
        case NS_CSS_UNIT_DEG:
        case NS_CSS_UNIT_MS:
        case NS_CSS_UNIT_DPPX:
        case NS_CSS_UNIT_FR:
            ns_css_value_free(v);
            g_free(s);
            return FALSE;
        default:
            *out_px = v->u.length.v;
            break;
        }
        ns_css_value_free(v);
        g_free(s);
        return TRUE;
    }
    if (v) ns_css_value_free(v);
    double num;
    ns_css_unit u;
    if (parse_length(s, &num, &u)) {
        switch (u) {
        case NS_CSS_UNIT_PERCENT: *out_pct = num; break;
        case NS_CSS_UNIT_EM:
        case NS_CSS_UNIT_REM:
        case NS_CSS_UNIT_LH:
        case NS_CSS_UNIT_RLH:     font_units_set(font, u, num, out_px); break;
        NS_CSS_CASE_VIEWPORT_UNITS:
            *out_px = viewport_resolve(num, u);
            if (font)
                viewport_unit_coeff(u, num, &font->vw, &font->vh,
                                    &font->vmin, &font->vmax);
            break;
        case NS_CSS_UNIT_CQW:
        case NS_CSS_UNIT_CQI:
        case NS_CSS_UNIT_CQH:
        case NS_CSS_UNIT_CQB:
        case NS_CSS_UNIT_CQMIN:
        case NS_CSS_UNIT_CQMAX:
            *out_px = container_unit_resolve(num, u);
            break;
        default:                  *out_px = num; break;
        }
        g_free(s);
        return TRUE;
    }
    g_free(s);
    return FALSE;
}

static gboolean
resolve_to_px_pct(const char *text, gsize len, double *out_px, double *out_pct)
{
    return resolve_to_px_pct_font(text, len, out_px, out_pct, NULL);
}

/* Returns the ')' matching an already-consumed '(' at depth 1, or NULL if unbalanced. */
static const char *
match_close_paren(const char *p, const char *end)
{
    int depth = 1;
    while (p < end && depth > 0) {
        if (*p == '(') depth++;
        else if (*p == ')') { depth--; if (depth == 0) return p; }
        p++;
    }
    return NULL;
}

static void
calc_skip_ws(const char **pp, const char *end)
{
    const char *p = *pp;
    while (p < end && ns_is_ascii_ws(*p)) p++;
    *pp = p;
}

/* Adds sign times a term's linear unit coefficients into an accumulator. */
static void
calc_linear_add(ns_calc_linear *l, const ns_calc_term *t, double sign)
{
    l->px += sign * t->px;
    l->pct += sign * t->pct;
    l->em += sign * t->em;
    l->rem += sign * t->rem;
    l->lh += sign * t->lh;
    l->rlh += sign * t->rlh;
    l->vw += sign * t->vw;
    l->vh += sign * t->vh;
    l->vmin += sign * t->vmin;
    l->vmax += sign * t->vmax;
}

/* Scales a deferred math function's args; a negative factor swaps min/max or clamp bounds. */
static void
calc_term_fn_scale(ns_calc_term *v, double m)
{
    if (!v->fn) return;
    if (!isfinite(m)) {
        v->fn = 0;
        return;
    }
    for (int i = 0; i < v->n_args; i++) {
        ns_calc_linear *l = &v->args[i];
        l->px *= m;
        l->pct *= m;
        l->em *= m;
        l->rem *= m;
        l->lh *= m;
        l->rlh *= m;
        l->vw *= m;
        l->vh *= m;
        l->vmin *= m;
        l->vmax *= m;
    }
    if (m >= 0) return;
    if (v->fn == 1 || v->fn == 2) {
        v->fn = v->fn == 1 ? 2 : 1;
        return;
    }
    ns_calc_linear lo = v->args[0];
    v->args[0] = v->args[2];
    v->args[2] = lo;
    guint8 none = v->arg_none;
    v->arg_none = (guint8)((none & 2u) | ((none & 1u) << 2) | ((none & 4u) >> 2));
}

/* Folds a linear term into a deferred math function's args; two functions drop the deferral. */
static void
calc_term_fn_add(ns_calc_term *out, const ns_calc_term *rhs, double sign)
{
    if (out->fn && rhs->fn) {
        out->fn = 0;
        return;
    }
    if (out->fn) {
        for (int i = 0; i < out->n_args; i++)
            calc_linear_add(&out->args[i], rhs, sign);
        return;
    }
    if (!rhs->fn) return;
    ns_calc_term r = *rhs;
    calc_term_fn_scale(&r, sign);
    for (int i = 0; i < r.n_args; i++)
        calc_linear_add(&r.args[i], out, 1.0);
    out->fn = r.fn;
    out->n_args = r.n_args;
    out->arg_none = r.arg_none;
    memcpy(out->args, r.args, sizeof out->args);
}

/* Multiplies a calc term by m; non-finite m scales only nonzero parts, drops viewport. */
static void
calc_term_scale(ns_calc_term *v, double m)
{
    calc_term_fn_scale(v, m);
    if (v->kind != CALC_LENGTH) {
        v->num *= m;
    } else if (isfinite(m)) {
        v->px *= m;
        v->pct *= m;
        v->em *= m;
        v->rem *= m;
        v->lh *= m;
        v->rlh *= m;
        v->vw *= m;
        v->vh *= m;
        v->vmin *= m;
        v->vmax *= m;
    } else {
        if (v->px  != 0) v->px  *= m;
        if (v->pct != 0) v->pct *= m;
        if (v->em  != 0) v->em  *= m;
        if (v->rem != 0) v->rem *= m;
        if (v->lh  != 0) v->lh  *= m;
        if (v->rlh != 0) v->rlh *= m;
        v->vw = 0;
        v->vh = 0;
        v->vmin = 0;
        v->vmax = 0;
    }
}

/* Converts angle/time/resolution/flex units to canonical deg, ms, dppx or fr terms. */
static gboolean
calc_scalar_unit_value(const char *unit, double num, ns_calc_term *out)
{
    static const struct { const char *unit; ns_calc_kind kind; double scale; } units[] = {
        { "deg", CALC_ANGLE, 1.0 }, { "grad", CALC_ANGLE, 0.9 },
        { "rad", CALC_ANGLE, 180.0 / G_PI }, { "turn", CALC_ANGLE, 360.0 },
        { "ms", CALC_TIME, 1.0 }, { "s", CALC_TIME, 1000.0 },
        { "dppx", CALC_RESOLUTION, 1.0 }, { "x", CALC_RESOLUTION, 1.0 },
        { "dpi", CALC_RESOLUTION, 1.0 / 96.0 },
        { "dpcm", CALC_RESOLUTION, 2.54 / 96.0 },
        { "fr", CALC_FLEX, 1.0 },
    };
    if (!unit || !*unit) return FALSE;
    for (gsize i = 0; i < G_N_ELEMENTS(units); i++) {
        if (g_ascii_strcasecmp(unit, units[i].unit) != 0) continue;
        memset(out, 0, sizeof(*out));
        out->kind = units[i].kind;
        out->num = num * units[i].scale;
        return TRUE;
    }
    return FALSE;
}

/* Builds a calc term from a number and unit, splitting font, viewport and container parts. */
static gboolean
calc_unit_value(const char *unit, double num, ns_calc_term *out)
{
    memset(out, 0, sizeof(*out));
    if (!isfinite(num) && (!unit || !*unit)) {
        out->num = num;
        out->kind = CALC_NUMBER;
        return TRUE;
    }
    char number[G_ASCII_DTOSTR_BUF_SIZE];
    g_ascii_dtostr(number, sizeof(number), num);
    char *text = g_strconcat(number, unit ? unit : "", NULL);
    double v = 0;
    ns_css_unit u = NS_CSS_UNIT_NUMBER;
    gboolean ok = parse_length(text, &v, &u);
    g_free(text);
    if (!ok) return calc_scalar_unit_value(unit, num, out);
    switch (u) {
    case NS_CSS_UNIT_NUMBER:
        out->num = v;
        out->kind = CALC_NUMBER;
        break;
    case NS_CSS_UNIT_PERCENT:
        out->pct = v;
        break;
    case NS_CSS_UNIT_EM:
        out->em = v;
        break;
    case NS_CSS_UNIT_EX:
    case NS_CSS_UNIT_CH:
        out->em = v * 0.5;
        break;
    case NS_CSS_UNIT_CAP:
        out->em = v * 0.7;
        break;
    case NS_CSS_UNIT_IC:
        out->em = v;
        break;
    case NS_CSS_UNIT_REM:
        out->rem = v;
        break;
    case NS_CSS_UNIT_LH:
        out->lh = v;
        break;
    case NS_CSS_UNIT_RLH:
        out->rlh = v;
        break;
    NS_CSS_CASE_VIEWPORT_UNITS:
        out->px = viewport_resolve(v, u);
        viewport_unit_coeff(u, v, &out->vw, &out->vh, &out->vmin, &out->vmax);
        break;
    case NS_CSS_UNIT_CQW:
    case NS_CSS_UNIT_CQI:
    case NS_CSS_UNIT_CQH:
    case NS_CSS_UNIT_CQB:
    case NS_CSS_UNIT_CQMIN:
    case NS_CSS_UNIT_CQMAX:
        out->px = container_unit_resolve(v, u);
        break;
    default:
        out->px = v;
        break;
    }
    return TRUE;
}

/* Parses a calc primary: number with unit, constant, parenthesized expr or nested math fn. */
static gboolean
calc_primary_parse(const char **pp, const char *end, ns_calc_term *out,
                   int depth)
{
    if (depth > NS_CALC_MAX_DEPTH) return FALSE;
    const char *p = *pp;
    calc_skip_ws(&p, end);
    if (p >= end) return FALSE;
    if ((gsize)(end - p) > 4 && g_ascii_strncasecmp(p, "env(", 4) == 0) {
        const char *args = p + 4;
        const char *close = match_close_paren(args, end);
        if (!close) return FALSE;
        char *parts[2] = {0};
        int n = calc_split_args(args, close, parts, G_N_ELEMENTS(parts));
        memset(out, 0, sizeof(*out));
        if (n >= 2)
            resolve_to_px_pct(parts[1], strlen(parts[1]), &out->px, &out->pct);
        for (int i = 0; i < n; i++) g_free(parts[i]);
        *pp = close + 1;
        return TRUE;
    }
    if (*p == '(') {
        p++;
        if (!calc_expr_parse(&p, end, out, depth + 1)) return FALSE;
        calc_skip_ws(&p, end);
        if (p >= end || *p != ')') return FALSE;
        p++;
        *pp = p;
        return TRUE;
    }
    static const char *const tree_funcs[] = { "sibling-index(", "sibling-count(" };
    for (gsize i = 0; i < G_N_ELEMENTS(tree_funcs); i++) {
        gsize L = strlen(tree_funcs[i]);
        if ((gsize)(end - p) < L || g_ascii_strncasecmp(p, tree_funcs[i], L) != 0)
            continue;
        const char *close = match_close_paren(p + L, end);
        if (!close) return FALSE;
        memset(out, 0, sizeof(*out));
        out->kind = CALC_NUMBER;
        out->num = 1;
        out->unresolved = TRUE;
        calc_unresolved = TRUE;
        *pp = close + 1;
        return TRUE;
    }
    static const struct { const char *name; gsize len; } funcs[] = {
        { "calc", 4 }, { "min", 3 }, { "max", 3 }, { "clamp", 5 },
        { "round", 5 }, { "mod", 3 }, { "rem", 3 }, { "abs", 3 },
        { "hypot", 5 }, { "pow", 3 }, { "sqrt", 4 }, { "atan2", 5 },
        { "atan", 4 }, { "asin", 4 }, { "acos", 4 }, { "sign", 4 },
        { "sin", 3 }, { "cos", 3 }, { "tan", 3 }, { "exp", 3 },
        { "log", 3 }, { "progress", 8 },
    };
    for (gsize i = 0; i < G_N_ELEMENTS(funcs); i++) {
        if ((gsize)(end - p) <= funcs[i].len + 1 ||
            g_ascii_strncasecmp(p, funcs[i].name, funcs[i].len) != 0 ||
            p[funcs[i].len] != '(')
            continue;
        const char *args = p + funcs[i].len + 1;
        const char *close = match_close_paren(args, end);
        if (!close) return FALSE;
        char *frag = g_strndup(p, (gsize)(close + 1 - p));
        ns_css_value *v = parse_calc_any(frag);
        g_free(frag);
        if (!v) return FALSE;
        memset(out, 0, sizeof(*out));
        if (v->kind == NS_CSS_V_CALC) {
            out->px = v->u.calc.px;
            out->pct = v->u.calc.pct;
            out->em = v->u.calc.em;
            out->rem = v->u.calc.rem;
            out->lh = v->u.calc.lh;
            out->rlh = v->u.calc.rlh;
            out->vw = v->u.calc.vw;
            out->vh = v->u.calc.vh;
            out->vmin = v->u.calc.vmin;
            out->vmax = v->u.calc.vmax;
            if (v->u.calc.fn >= 1 && v->u.calc.fn <= 3 &&
                v->u.calc.n_args > 0 && v->u.calc.n_args <= 4) {
                out->fn = v->u.calc.fn;
                out->n_args = v->u.calc.n_args;
                out->arg_none = v->u.calc.arg_none;
                for (int k = 0; k < out->n_args; k++) {
                    out->args[k].px = v->u.calc.args[k].px;
                    out->args[k].pct = v->u.calc.args[k].pct;
                    out->args[k].em = v->u.calc.args[k].em;
                    out->args[k].rem = v->u.calc.args[k].rem;
                    out->args[k].lh = v->u.calc.args[k].lh;
                    out->args[k].rlh = v->u.calc.args[k].rlh;
                    out->args[k].vw = v->u.calc.args[k].vw;
                    out->args[k].vh = v->u.calc.args[k].vh;
                    out->args[k].vmin = v->u.calc.args[k].vmin;
                    out->args[k].vmax = v->u.calc.args[k].vmax;
                }
            }
        } else if (v->kind == NS_CSS_V_LENGTH) {
            double num = v->u.length.v;
            switch (v->u.length.unit) {
            case NS_CSS_UNIT_PERCENT: out->pct = num; break;
            case NS_CSS_UNIT_EM:      out->em = num; break;
            case NS_CSS_UNIT_EX:      out->em = num * 0.5; break;
            case NS_CSS_UNIT_CH:      out->em = num * 0.5; break;
            case NS_CSS_UNIT_CAP:     out->em = num * 0.7; break;
            case NS_CSS_UNIT_IC:      out->em = num; break;
            case NS_CSS_UNIT_REM:     out->rem = num; break;
            case NS_CSS_UNIT_LH:      out->lh = num; break;
            case NS_CSS_UNIT_RLH:     out->rlh = num; break;
            NS_CSS_CASE_VIEWPORT_UNITS:
                out->px = viewport_resolve(num, v->u.length.unit);
                viewport_unit_coeff(v->u.length.unit, num, &out->vw, &out->vh,
                                    &out->vmin, &out->vmax);
                break;
            case NS_CSS_UNIT_CQW:
            case NS_CSS_UNIT_CQI:
            case NS_CSS_UNIT_CQH:
            case NS_CSS_UNIT_CQB:
            case NS_CSS_UNIT_CQMIN:
            case NS_CSS_UNIT_CQMAX:
                out->px = container_unit_resolve(num, v->u.length.unit);
                break;
            case NS_CSS_UNIT_NUMBER:
                out->num = num;
                out->kind = CALC_NUMBER;
                break;
            case NS_CSS_UNIT_DEG:  out->kind = CALC_ANGLE;      out->num = num; break;
            case NS_CSS_UNIT_MS:   out->kind = CALC_TIME;       out->num = num; break;
            case NS_CSS_UNIT_DPPX: out->kind = CALC_RESOLUTION; out->num = num; break;
            case NS_CSS_UNIT_FR:   out->kind = CALC_FLEX;       out->num = num; break;
            default:                  out->px = num; break;
            }
        } else {
            ns_css_value_free(v);
            return FALSE;
        }
        ns_css_value_free(v);
        *pp = close + 1;
        return TRUE;
    }
    {
        static const struct { const char *name; gsize len; double val; } consts[] = {
            { "infinity", 8, INFINITY }, { "pi", 2, G_PI }, { "e", 1, G_E },
            { "nan", 3, NAN },
        };
        for (gsize i = 0; i < G_N_ELEMENTS(consts); i++) {
            gsize L = consts[i].len;
            if ((gsize)(end - p) < L ||
                g_ascii_strncasecmp(p, consts[i].name, L) != 0)
                continue;
            const char *after = p + L;
            if (after < end && (g_ascii_isalnum(*after) || *after == '.' ||
                                *after == '%' || *after == '('))
                continue;
            memset(out, 0, sizeof(*out));
            out->num = consts[i].val;
            out->kind = CALC_NUMBER;
            *pp = after;
            return TRUE;
        }
    }
    char *num_end = NULL;
    double num = g_ascii_strtod(p, &num_end);
    if (!num_end || num_end == p) return FALSE;
    const char *u = num_end;
    while (u < end && (g_ascii_isalpha(*u) || *u == '%')) u++;
    char *unit = g_strndup(num_end, (gsize)(u - num_end));
    gboolean ok = calc_unit_value(unit, num, out);
    g_free(unit);
    if (!ok) return FALSE;
    *pp = u;
    return TRUE;
}

/* Parses a calc product (* and /), requiring at least one side of each step to be a number. */
static gboolean
calc_product_parse(const char **pp, const char *end, ns_calc_term *out,
                   int depth)
{
    if (!calc_primary_parse(pp, end, out, depth)) return FALSE;
    while (1) {
        const char *p = *pp;
        calc_skip_ws(&p, end);
        if (p >= end || (*p != '*' && *p != '/')) {
            *pp = p;
            return TRUE;
        }
        char op = *p++;
        ns_calc_term rhs;
        if (!calc_primary_parse(&p, end, &rhs, depth)) return FALSE;
        gboolean unresolved = out->unresolved || rhs.unresolved;
        if (op == '*') {
            if (out->kind == CALC_NUMBER && rhs.kind == CALC_NUMBER) {
                out->num *= rhs.num;
            } else if (out->kind == CALC_NUMBER) {
                double m = out->num;
                *out = rhs;
                calc_term_scale(out, m);
            } else if (rhs.kind == CALC_NUMBER) {
                calc_term_scale(out, rhs.num);
            } else {
                return FALSE;
            }
        } else {
            if (rhs.kind != CALC_NUMBER) return FALSE;
            calc_term_scale(out, 1.0 / rhs.num);
        }
        out->unresolved = unresolved;
        *pp = p;
    }
}

/* Parses a calc sum (+ and -) of type-matching products into a linear term. */
static gboolean
calc_expr_parse(const char **pp, const char *end, ns_calc_term *out,
                int depth)
{
    if (!calc_product_parse(pp, end, out, depth)) return FALSE;
    while (1) {
        const char *p = *pp;
        calc_skip_ws(&p, end);
        if (p >= end || (*p != '+' && *p != '-')) {
            *pp = p;
            return TRUE;
        }
        char op = *p++;
        ns_calc_term rhs;
        if (!calc_product_parse(&p, end, &rhs, depth)) return FALSE;
        if (out->kind != rhs.kind) return FALSE;
        out->unresolved = out->unresolved || rhs.unresolved;
        if (out->kind != CALC_LENGTH) {
            if (op == '+') out->num += rhs.num;
            else           out->num -= rhs.num;
            *pp = p;
            continue;
        }
        calc_term_fn_add(out, &rhs, op == '+' ? 1.0 : -1.0);
        if (op == '+') {
            out->px += rhs.px;
            out->pct += rhs.pct;
            out->em += rhs.em;
            out->rem += rhs.rem;
            out->lh += rhs.lh;
            out->rlh += rhs.rlh;
            out->vw += rhs.vw;
            out->vh += rhs.vh;
            out->vmin += rhs.vmin;
            out->vmax += rhs.vmax;
        } else {
            out->px -= rhs.px;
            out->pct -= rhs.pct;
            out->em -= rhs.em;
            out->rem -= rhs.rem;
            out->lh -= rhs.lh;
            out->rlh -= rhs.rlh;
            out->vw -= rhs.vw;
            out->vh -= rhs.vh;
            out->vmin -= rhs.vmin;
            out->vmax -= rhs.vmax;
        }
        *pp = p;
    }
}

/* Splits math function arguments at top-level commas into trimmed new strings. */
static int
calc_split_args(const char *args, const char *body_end, char *out[], int max)
{
    int n = 0;
    const char *seg = args;
    while (seg < body_end && n < max) {
        char term = 0;
        const char *next = css_scan_until(seg, body_end, ",", &term);
        out[n++] = css_trim_dup_range(seg, next);
        seg = term == ',' ? next + 1 : next;
        if (term != ',') break;
    }
    return n;
}

static ns_css_value *calc_px_value(double px);
static ns_css_value *calc_num_value(double n);

/* Evaluates a full calc expression string, failing on trailing text. */
static gboolean
calc_eval_arg(const char *text, ns_calc_term *out)
{
    const char *p = text;
    const char *end = text + strlen(text);
    if (!calc_expr_parse(&p, end, out, 0)) return FALSE;
    calc_skip_ws(&p, end);
    return p == end;
}

/* Approximates a calc term to a comparable number using 16px em and viewport-width percent. */
static double
calc_term_key(const ns_calc_term *t)
{
    if (t->kind != CALC_LENGTH) return t->num;
    if (t->pct != 0) ns_css_media_record_viewport_use();
    return t->px + t->em * 16.0 + t->rem * calc_rem_px() +
           (t->lh + t->rlh) * 19.2 + t->pct * 0.01 * g_viewport_w;
}

/* Evaluates a calc() in a media query to px, number or resolution; percentages fail. */
gboolean
ns_css_calc_media(const char *text, gsize len, gboolean resolution, double *out)
{
    char *s = g_strndup(text, len);
    g_strstrip(s);
    ns_calc_term t;
    gboolean ok = calc_eval_arg(s, &t);
    g_free(s);
    if (!ok) return FALSE;
    if (resolution) {
        if (t.kind != CALC_RESOLUTION) return FALSE;
        *out = t.num;
        return TRUE;
    }
    if (t.kind == CALC_NUMBER) {
        *out = t.num;
        return TRUE;
    }
    if (t.kind != CALC_LENGTH || t.pct != 0) return FALSE;
    *out = t.px + (t.em + t.rem) * 16.0 + (t.lh + t.rlh) * 19.2;
    return TRUE;
}

/* Reports whether a length term depends on font size or a percentage basis. */
static gboolean
calc_term_basis_dependent(const ns_calc_term *t)
{
    return t->kind == CALC_LENGTH &&
           (t->em != 0 || t->rem != 0 || t->lh != 0 || t->rlh != 0 ||
            t->pct != 0);
}

static gboolean
calc_eval_number(const char *text, double *out)
{
    ns_calc_term t;
    if (!calc_eval_arg(text, &t) || t.kind != CALC_NUMBER) return FALSE;
    *out = t.num;
    return TRUE;
}

/* Converts a number or angle term to radians for trig functions. */
static gboolean
calc_term_radians(const ns_calc_term *t, double *out)
{
    if (t->kind == CALC_NUMBER) *out = t->num;
    else if (t->kind == CALC_ANGLE) *out = t->num * G_PI / 180.0;
    else return FALSE;
    return TRUE;
}

/* Builds a length value tagged with the canonical unit for a non-length calc kind. */
static ns_css_value *
calc_scalar_value(ns_calc_kind kind, double v)
{
    ns_css_value *out = g_new0(ns_css_value, 1);
    out->kind = NS_CSS_V_LENGTH;
    out->u.length.v = v;
    out->u.length.unit = kind == CALC_ANGLE      ? NS_CSS_UNIT_DEG
                       : kind == CALC_TIME       ? NS_CSS_UNIT_MS
                       : kind == CALC_RESOLUTION ? NS_CSS_UNIT_DPPX
                       : kind == CALC_FLEX       ? NS_CSS_UNIT_FR
                                                 : NS_CSS_UNIT_NUMBER;
    return out;
}

/* Builds a number, px or scalar value of the same kind as like. */
static ns_css_value *
calc_value_like(const ns_calc_term *like, double v)
{
    if (like->kind == CALC_NUMBER) return calc_num_value(v);
    if (like->kind == CALC_LENGTH) return calc_px_value(v);
    return calc_scalar_value(like->kind, v);
}

/* Reports whether text is a plain number or a calc expression yielding a number. */
static gboolean
calc_arg_is_number(const char *text)
{
    char *s = g_strdup(text);
    g_strstrip(s);
    char *endp = NULL;
    g_ascii_strtod(s, &endp);
    gboolean num = endp && endp != s && *endp == '\0';
    if (!num) {
        ns_css_value *v = parse_calc(s);
        if (!v) {
            char *wrapped = g_strdup_printf("calc(%s)", s);
            v = parse_calc(wrapped);
            g_free(wrapped);
        }
        num = v && v->kind == NS_CSS_V_LENGTH &&
              v->u.length.unit == NS_CSS_UNIT_NUMBER;
        if (v) ns_css_value_free(v);
    }
    g_free(s);
    return num;
}

static ns_css_value *
calc_px_value(double px)
{
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_LENGTH;
    v->u.length.v = px;
    v->u.length.unit = NS_CSS_UNIT_PX;
    return v;
}

static ns_css_value *
calc_num_value(double n)
{
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_LENGTH;
    v->u.length.v = n;
    v->u.length.unit = NS_CSS_UNIT_NUMBER;
    return v;
}

/* Less-than that orders -0 before +0, as CSS math functions require. */
static gboolean
css_less_signed(double a, double b)
{
    return a < b || (a == 0 && b == 0 && signbit(a) && !signbit(b));
}

/* Clamps val to [lo, hi] respecting signed zero; lo wins when bounds cross. */
static double
css_clamp_signed(double lo, double val, double hi)
{
    double out = css_less_signed(hi, val) ? hi : val;
    return css_less_signed(out, lo) ? lo : out;
}

/* Implements round() strategies (nearest, up, down, to-zero) with CSS NaN/infinity rules. */
static double
css_round_step(int strategy, double a, double b)
{
    if (isnan(a) || isnan(b) || b == 0) return NAN;
    if (isinf(a)) return isinf(b) ? NAN : a;
    if (isinf(b)) {
        if (strategy == 1) return a > 0 ? INFINITY : copysign(0.0, a);
        if (strategy == 2) return a < 0 ? -INFINITY : copysign(0.0, a);
        return copysign(0.0, a);
    }
    double q = a / fabs(b);
    double rq = strategy == 1 ? ceil(q) :
                strategy == 2 ? floor(q) :
                strategy == 3 ? trunc(q) : round(q);
    return rq * fabs(b);
}

/* Implements mod() (sign of divisor) and rem() (sign of dividend) with CSS edge cases. */
static double
css_mod_rem(gboolean is_mod, double a, double b)
{
    if (isnan(a) || isnan(b) || b == 0 || isinf(a)) return NAN;
    if (isinf(b)) {
        if (!is_mod) return a;
        return signbit(a) == signbit(b) ? a : NAN;
    }
    double r = fmod(a, b);
    if (is_mod && r != 0 && (r < 0) != (b < 0)) r += b;
    if (r == 0) r = copysign(0.0, is_mod ? b : a);
    return r;
}

/* Reports whether a length term needs layout-time context (font, percent or viewport). */
static gboolean
calc_term_defers_to_layout(const ns_calc_term *t)
{
    return t->kind == CALC_LENGTH && !t->fn &&
           (calc_term_basis_dependent(t) || t->vw != 0 || t->vh != 0 ||
            t->vmin != 0 || t->vmax != 0);
}

static void
calc_arg_from_term(ns_css_value *v, int i, const ns_calc_term *t)
{
    v->u.calc.args[i].px = t->px;
    v->u.calc.args[i].pct = t->pct;
    v->u.calc.args[i].em = t->em;
    v->u.calc.args[i].rem = t->rem;
    v->u.calc.args[i].lh = t->lh;
    v->u.calc.args[i].rlh = t->rlh;
    v->u.calc.args[i].vw = t->vw;
    v->u.calc.args[i].vh = t->vh;
    v->u.calc.args[i].vmin = t->vmin;
    v->u.calc.args[i].vmax = t->vmax;
}

/* Returns a folded math result, or a deferred calc value when args need layout context. */
static ns_css_value *
calc_stepped_value(ns_css_math_fn fn, const ns_calc_term *a,
                   const ns_calc_term *b, double folded)
{
    gboolean nested = a->fn || (b && b->fn);
    gboolean deferred = calc_term_defers_to_layout(a) ||
                        (b && calc_term_defers_to_layout(b));
    if (nested || !deferred) return calc_value_like(a, folded);
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_CALC;
    v->u.calc.px = folded;
    v->u.calc.fn = (guint8)fn;
    v->u.calc.n_args = b ? 2 : 1;
    v->u.calc.parsed_vw = g_viewport_w;
    v->u.calc.parsed_vh = g_viewport_h;
    calc_arg_from_term(v, 0, a);
    if (b) calc_arg_from_term(v, 1, b);
    return v;
}

/* Parses any math expression with a per-thread recursion depth guard. */
static ns_css_value *
parse_calc_any(const char *text)
{
    static __thread int depth;
    if (depth > NS_CALC_MAX_DEPTH) return NULL;
    depth++;
    ns_css_value *v = parse_calc_inner(text);
    depth--;
    return v;
}

static gboolean
value_is_scalar_dimension(const ns_css_value *v)
{
    return v && v->kind == NS_CSS_V_LENGTH &&
           (v->u.length.unit == NS_CSS_UNIT_DEG ||
            v->u.length.unit == NS_CSS_UNIT_MS ||
            v->u.length.unit == NS_CSS_UNIT_DPPX ||
            v->u.length.unit == NS_CSS_UNIT_FR);
}

/* Parses a math expression, rejecting results that are angles, times, resolutions or flex. */
static ns_css_value *
parse_calc(const char *text)
{
    ns_css_value *v = parse_calc_any(text);
    if (value_is_scalar_dimension(v)) {
        ns_css_value_free(v);
        return NULL;
    }
    return v;
}

const char *
ns_css_unit_suffix(int unit)
{
    switch (unit) {
    case NS_CSS_UNIT_PX:      return "px";
    case NS_CSS_UNIT_EM:      return "em";
    case NS_CSS_UNIT_REM:     return "rem";
    case NS_CSS_UNIT_LH:      return "lh";
    case NS_CSS_UNIT_RLH:     return "rlh";
    case NS_CSS_UNIT_PERCENT: return "%";
    case NS_CSS_UNIT_NUMBER:  return "";
    case NS_CSS_UNIT_VW:      return "vw";
    case NS_CSS_UNIT_SVW:     return "svw";
    case NS_CSS_UNIT_LVW:     return "lvw";
    case NS_CSS_UNIT_DVW:     return "dvw";
    case NS_CSS_UNIT_VH:      return "vh";
    case NS_CSS_UNIT_SVH:     return "svh";
    case NS_CSS_UNIT_LVH:     return "lvh";
    case NS_CSS_UNIT_DVH:     return "dvh";
    case NS_CSS_UNIT_VI:      return "vi";
    case NS_CSS_UNIT_SVI:     return "svi";
    case NS_CSS_UNIT_LVI:     return "lvi";
    case NS_CSS_UNIT_DVI:     return "dvi";
    case NS_CSS_UNIT_VB:      return "vb";
    case NS_CSS_UNIT_SVB:     return "svb";
    case NS_CSS_UNIT_LVB:     return "lvb";
    case NS_CSS_UNIT_DVB:     return "dvb";
    case NS_CSS_UNIT_VMIN:    return "vmin";
    case NS_CSS_UNIT_SVMIN:   return "svmin";
    case NS_CSS_UNIT_LVMIN:   return "lvmin";
    case NS_CSS_UNIT_DVMIN:   return "dvmin";
    case NS_CSS_UNIT_VMAX:    return "vmax";
    case NS_CSS_UNIT_SVMAX:   return "svmax";
    case NS_CSS_UNIT_LVMAX:   return "lvmax";
    case NS_CSS_UNIT_DVMAX:   return "dvmax";
    case NS_CSS_UNIT_CQW:     return "cqw";
    case NS_CSS_UNIT_CQH:     return "cqh";
    case NS_CSS_UNIT_CQI:     return "cqi";
    case NS_CSS_UNIT_CQB:     return "cqb";
    case NS_CSS_UNIT_CQMIN:   return "cqmin";
    case NS_CSS_UNIT_CQMAX:   return "cqmax";
    case NS_CSS_UNIT_EX:      return "ex";
    case NS_CSS_UNIT_CH:      return "ch";
    case NS_CSS_UNIT_CAP:     return "cap";
    case NS_CSS_UNIT_IC:      return "ic";
    case NS_CSS_UNIT_REX:     return "rex";
    case NS_CSS_UNIT_RCH:     return "rch";
    case NS_CSS_UNIT_RCAP:    return "rcap";
    case NS_CSS_UNIT_RIC:     return "ric";
    case NS_CSS_UNIT_DEG:     return "deg";
    case NS_CSS_UNIT_MS:      return "ms";
    case NS_CSS_UNIT_DPPX:    return "dppx";
    case NS_CSS_UNIT_FR:      return "fr";
    default:                  return "px";
    }
}

/* Formats a number for serialization, with NaN and infinity spelled per CSS; caller frees. */
static char *
ns_css_number_str(double n)
{
    if (isnan(n)) return g_strdup("NaN");
    if (isinf(n)) return g_strdup(n < 0 ? "-infinity" : "infinity");
    if (n == 0) return g_strdup("0");
    return g_strdup_printf("%g", n);
}

/* Reports whether text contains a font-, viewport- or container-relative unit token. */
static gboolean
ns_value_has_relative_unit(const char *s)
{
    static const char *const rel[] = {
        "em", "rem", "ex", "rex", "ch", "rch", "cap", "rcap", "ic", "ric",
        "lh", "rlh", "vw", "vh", "vi", "vb", "vmin", "vmax",
        "svw", "svh", "svmin", "svmax", "lvw", "lvh", "lvmin", "lvmax",
        "dvw", "dvh", "dvmin", "dvmax",
        "cqw", "cqh", "cqi", "cqb", "cqmin", "cqmax",
    };
    while (*s) {
        if (g_ascii_isalpha(*s)) {
            const char *start = s;
            while (g_ascii_isalpha(*s) || *s == '-') s++;
            gsize len = (gsize)(s - start);
            if (*s == '(') continue;
            for (gsize i = 0; i < G_N_ELEMENTS(rel); i++)
                if (strlen(rel[i]) == len &&
                    g_ascii_strncasecmp(start, rel[i], len) == 0)
                    return TRUE;
        } else {
            s++;
        }
    }
    return FALSE;
}

/* Serializes a non-finite length as calc(infinity * 1unit) or similar; caller frees. */
static char *
serialize_nonfinite_length(double v, const char *unit)
{
    const char *nf = isnan(v) ? "NaN" : v < 0 ? "-infinity" : "infinity";
    if (!unit || !*unit)
        return g_strdup_printf("calc(%s)", nf);
    return g_strdup_printf("calc(%s * 1%s)", nf, unit);
}

/* Serializes an absolute math expression as calc(<value><unit>); NULL if relative or mixed. */
static char *
ns_css_math_canonical(const char *value)
{
    if (!value) return NULL;
    while (*value && ns_is_ascii_ws(*value)) value++;
    if (ns_value_has_relative_unit(value)) return NULL;
    static const char *const fns[] = {
        "calc(", "min(", "max(", "clamp(", "round(", "mod(", "rem(",
        "abs(", "hypot(", "pow(", "sqrt(", "sin(", "cos(", "tan(",
        "sign(", "exp(", "log(", "progress(", "atan2(", "atan(", "asin(",
        "acos(",
    };
    gboolean is_math = FALSE;
    for (gsize i = 0; i < G_N_ELEMENTS(fns); i++)
        if (g_ascii_strncasecmp(value, fns[i], strlen(fns[i])) == 0) {
            is_math = TRUE;
            break;
        }
    if (!is_math) return NULL;
    gboolean has_pct = strchr(value, '%') != NULL;
    ns_css_value *v = parse_calc_any(value);
    if (!v) return NULL;
    char *out = NULL;
    gboolean nonfinite = FALSE;
    gboolean number_result = v->kind == NS_CSS_V_LENGTH &&
                             v->u.length.unit == NS_CSS_UNIT_NUMBER &&
                             g_ascii_strncasecmp(value, "progress(", 9) == 0;
    if (v->kind == NS_CSS_V_LENGTH) {
        double lv = v->u.length.v;
        const char *suf = ns_css_unit_suffix(v->u.length.unit);
        if (!isfinite(lv)) {
            out = serialize_nonfinite_length(lv, suf);
            nonfinite = TRUE;
        } else {
            char *num = ns_css_number_str(lv);
            out = g_strdup_printf("calc(%s%s)", num, suf);
            g_free(num);
        }
    } else if (v->kind == NS_CSS_V_CALC) {
        int nonzero = 0;
        double val = 0;
        const char *unit = "px";
        if (v->u.calc.px != 0)  { nonzero++; val = v->u.calc.px;  unit = "px"; }
        if (v->u.calc.pct != 0) { nonzero++; val = v->u.calc.pct; unit = "%"; }
        if (v->u.calc.em != 0)  { nonzero++; val = v->u.calc.em;  unit = "em"; }
        if (v->u.calc.rem != 0) { nonzero++; val = v->u.calc.rem; unit = "rem"; }
        if (nonzero == 0) {
            out = g_strdup("calc(0px)");
        } else if (nonzero == 1) {
            if (!isfinite(val)) {
                out = serialize_nonfinite_length(val, unit);
                nonfinite = TRUE;
            } else {
                char *num = ns_css_number_str(val);
                out = g_strdup_printf("calc(%s%s)", num, unit);
                g_free(num);
            }
        }
    }
    ns_css_value_free(v);
    if (has_pct && !nonfinite && !number_result) {
        g_free(out);
        out = NULL;
    }
    return out;
}

/* Evaluates min/max/clamp over angle, time, resolution or flex args; NULL for lengths. */
static ns_css_value *
calc_compare_scalar(int fn, char *const *parts, int n)
{
    ns_calc_term terms[8];
    gboolean none[8] = {0};
    ns_calc_kind kind = CALC_NUMBER;
    gboolean have_kind = FALSE;
    for (int i = 0; i < n; i++) {
        char *part = g_strstrip(g_strdup(parts[i]));
        gboolean is_none = g_ascii_strcasecmp(part, "none") == 0;
        gboolean ok = is_none ? fn == 3 : calc_eval_arg(part, &terms[i]);
        g_free(part);
        if (!ok) return NULL;
        none[i] = is_none;
        if (is_none) continue;
        if (terms[i].kind == CALC_NUMBER || terms[i].kind == CALC_LENGTH)
            return NULL;
        if (have_kind && terms[i].kind != kind) return NULL;
        kind = terms[i].kind;
        have_kind = TRUE;
    }
    if (!have_kind || (fn == 3 && (n != 3 || none[1]))) return NULL;
    double result;
    if (fn == 3) {
        double lo = none[0] ? -HUGE_VAL : terms[0].num;
        double val = terms[1].num;
        double hi = none[2] ? HUGE_VAL : terms[2].num;
        result = isnan(lo) || isnan(val) || isnan(hi) ? NAN
               : css_clamp_signed(lo, val, hi);
    } else {
        result = terms[0].num;
        for (int i = 1; i < n; i++) {
            if (isnan(terms[i].num)) result = NAN;
            else if (fn == 1 && css_less_signed(terms[i].num, result))
                result = terms[i].num;
            else if (fn == 2 && css_less_signed(result, terms[i].num))
                result = terms[i].num;
        }
    }
    return calc_scalar_value(kind, result);
}

/* Evaluates min/max/clamp over lengths, deferring to a calc value when args need layout. */
static ns_css_value *
calc_compare_lengths(int fn, char *const *parts, int n)
{
    double values_px[8] = {0};
    double values_pct[8] = {0};
    ns_font_units values_font[8] = {{0}};
    gboolean is_none[8] = {0};
    int num_count = 0;
    int none_count = 0;
    for (int i = 0; i < n; i++) {
        char *part = g_strstrip(g_strdup(parts[i]));
        gboolean ok = TRUE;
        if (g_ascii_strcasecmp(part, "none") == 0) {
            is_none[i] = TRUE;
            none_count++;
            ok = fn == 3;
        } else if (!resolve_to_px_pct_font(part, strlen(part), &values_px[i],
                                           &values_pct[i], &values_font[i])) {
            ok = FALSE;
        } else if (calc_arg_is_number(part)) {
            num_count++;
        }
        g_free(part);
        if (!ok) return NULL;
    }
    if (n == 0) return NULL;
    int non_none = n - none_count;
    if (num_count != 0 && num_count != non_none) return NULL;
    if (fn == 3 && (n != 3 || is_none[1])) return NULL;
    gboolean all_numbers = non_none > 0 && num_count == non_none;
    double keys[8] = {0};
    gboolean font_dependent = FALSE;
    for (int i = 0; i < n; i++) {
        const ns_font_units *f = &values_font[i];
        if (f->em != 0 || f->rem != 0 || f->lh != 0 || f->rlh != 0 ||
            f->vw != 0 || f->vh != 0 || f->vmin != 0 || f->vmax != 0)
            font_dependent = TRUE;
        double relative = f->em * 16.0 + f->rem * calc_rem_px() +
                          (f->lh + f->rlh) * 19.2 +
                          values_pct[i] * 0.01 * g_viewport_w;
        keys[i] = relative != 0 ? values_px[i] + relative : values_px[i];
    }
    double out_px;
    if (fn == 3) {
        double min_v = is_none[0] ? -HUGE_VAL : keys[0];
        double val_v = keys[1];
        double max_v = is_none[2] ? HUGE_VAL : keys[2];
        if (isnan(min_v) || isnan(val_v) || isnan(max_v)) {
            out_px = NAN;
        } else {
            out_px = css_clamp_signed(min_v, val_v, max_v);
        }
    } else {
        out_px = keys[0];
        gboolean any_nan = isnan(keys[0]);
        for (int i = 1; i < n; i++) {
            if (isnan(keys[i])) any_nan = TRUE;
            if (fn == 1 && css_less_signed(keys[i], out_px)) out_px = keys[i];
            if (fn == 2 && css_less_signed(out_px, keys[i])) out_px = keys[i];
        }
        if (any_nan) out_px = NAN;
    }
    if (all_numbers) return calc_num_value(out_px);
    gboolean basis_dependent = n <= 4 && font_dependent;
    for (int i = 0; n <= 4 && i < n; i++)
        if (values_pct[i] != 0) basis_dependent = TRUE;
    if (!basis_dependent) return calc_px_value(out_px);
    ns_css_value *mv = g_new0(ns_css_value, 1);
    mv->kind = NS_CSS_V_CALC;
    mv->u.calc.px = out_px;
    mv->u.calc.fn = (guint8)fn;
    mv->u.calc.n_args = (guint8)n;
    mv->u.calc.parsed_vw = g_viewport_w;
    mv->u.calc.parsed_vh = g_viewport_h;
    for (int i = 0; i < n; i++) {
        mv->u.calc.args[i].px  = values_px[i];
        mv->u.calc.args[i].pct = values_pct[i];
        mv->u.calc.args[i].em  = values_font[i].em;
        mv->u.calc.args[i].rem = values_font[i].rem;
        mv->u.calc.args[i].lh  = values_font[i].lh;
        mv->u.calc.args[i].rlh = values_font[i].rlh;
        mv->u.calc.args[i].vw  = values_font[i].vw;
        mv->u.calc.args[i].vh  = values_font[i].vh;
        mv->u.calc.args[i].vmin = values_font[i].vmin;
        mv->u.calc.args[i].vmax = values_font[i].vmax;
        if (is_none[i]) mv->u.calc.arg_none |= (guint8)(1u << i);
    }
    return mv;
}

/* Parses one CSS math function (calc, min, round, trig, log, progress...) into a value. */
static ns_css_value *
parse_calc_inner(const char *text)
{
    while (*text && ns_is_ascii_ws(*text)) text++;
    int fn = -1;
    const char *args = NULL;
    if      (g_ascii_strncasecmp(text, "calc(",  5) == 0) { fn = 0; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "clamp(", 6) == 0) { fn = 3; args = text + 6; }
    else if (g_ascii_strncasecmp(text, "min(",   4) == 0) { fn = 1; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "max(",   4) == 0) { fn = 2; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "round(", 6) == 0) { fn = 4; args = text + 6; }
    else if (g_ascii_strncasecmp(text, "mod(",   4) == 0) { fn = 5; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "rem(",   4) == 0) { fn = 6; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "abs(",   4) == 0) { fn = 7; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "hypot(", 6) == 0) { fn = 8; args = text + 6; }
    else if (g_ascii_strncasecmp(text, "pow(",   4) == 0) { fn = 9; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "sqrt(",  5) == 0) { fn = 10; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "sin(",   4) == 0) { fn = 11; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "cos(",   4) == 0) { fn = 12; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "tan(",   4) == 0) { fn = 13; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "atan2(", 6) == 0) { fn = 14; args = text + 6; }
    else if (g_ascii_strncasecmp(text, "atan(",  5) == 0) { fn = 15; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "asin(",  5) == 0) { fn = 16; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "acos(",  5) == 0) { fn = 17; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "sign(",  5) == 0) { fn = 18; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "exp(",   4) == 0) { fn = 19; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "log(",   4) == 0) { fn = 20; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "progress(", 9) == 0) { fn = 21; args = text + 9; }
    else return NULL;
    const char *body_end = match_close_paren(args, args + strlen(args));
    if (!body_end) return NULL;
    for (const char *tail = body_end + 1; *tail; tail++)
        if (!ns_is_ascii_ws(*tail)) return NULL;
    if (fn >= 4) {
        char *parts[4] = {0};
        int n = calc_split_args(args, body_end, parts, G_N_ELEMENTS(parts));
        ns_css_value *out = NULL;
        ns_calc_term a, b;
        double x = 0, y = 0;
        if (fn == 7 && n == 1) {
            if (calc_eval_arg(parts[0], &a))
                out = calc_stepped_value(NS_CSS_MATH_ABS, &a, NULL,
                                         fabs(calc_term_key(&a)));
        } else if (fn == 4 && n >= 1) {
            int vi = 0;
            int strategy = 0;
            if (g_ascii_strcasecmp(parts[0], "nearest") == 0) {
                strategy = 0; vi = 1;
            } else if (g_ascii_strcasecmp(parts[0], "up") == 0) {
                strategy = 1; vi = 1;
            } else if (g_ascii_strcasecmp(parts[0], "down") == 0) {
                strategy = 2; vi = 1;
            } else if (g_ascii_strcasecmp(parts[0], "to-zero") == 0) {
                strategy = 3; vi = 1;
            }
            if (vi < n && n <= vi + 2 && calc_eval_arg(parts[vi], &a)) {
                gboolean has_step = vi + 1 < n;
                gboolean ok = has_step
                    ? calc_eval_arg(parts[vi + 1], &b) && b.kind == a.kind
                    : a.kind == CALC_NUMBER;
                if (ok && has_step)
                    out = calc_stepped_value(NS_CSS_MATH_ROUND_NEAREST + strategy,
                                             &a, &b,
                                             css_round_step(strategy,
                                                            calc_term_key(&a),
                                                            calc_term_key(&b)));
                else if (ok)
                    out = calc_num_value(css_round_step(strategy, a.num, 1));
            }
        } else if ((fn == 5 || fn == 6) && n == 2) {
            if (calc_eval_arg(parts[0], &a) && calc_eval_arg(parts[1], &b) &&
                a.kind == b.kind)
                out = calc_stepped_value(fn == 5 ? NS_CSS_MATH_MOD
                                                 : NS_CSS_MATH_REM,
                                         &a, &b,
                                         css_mod_rem(fn == 5,
                                                     calc_term_key(&a),
                                                     calc_term_key(&b)));
        } else if (fn == 8 && n >= 1) {
            double sum = 0;
            gboolean ok = TRUE;
            for (int i = 0; i < n && ok; i++) {
                ok = calc_eval_arg(parts[i], &b) && (i == 0 || b.kind == a.kind);
                if (i == 0) a = b;
                double k = calc_term_key(&b);
                sum += k * k;
            }
            if (ok) out = calc_value_like(&a, sqrt(sum));
        } else if (fn == 9 && n == 2) {
            if (calc_eval_number(parts[0], &x) && calc_eval_number(parts[1], &y))
                out = calc_num_value(pow(x, y));
        } else if (fn == 10 && n == 1) {
            if (calc_eval_number(parts[0], &x))
                out = calc_num_value(sqrt(x));
        } else if (fn >= 11 && fn <= 13 && n == 1) {
            if (calc_eval_arg(parts[0], &a) && calc_term_radians(&a, &x))
                out = calc_num_value(fn == 11 ? sin(x)
                                  : fn == 12 ? cos(x) : tan(x));
        } else if (fn == 14 && n == 2) {
            if (calc_eval_arg(parts[0], &a) && calc_eval_arg(parts[1], &b) &&
                a.kind == b.kind)
                out = calc_scalar_value(CALC_ANGLE,
                                        atan2(calc_term_key(&a),
                                              calc_term_key(&b)) * 180.0 / G_PI);
        } else if (fn >= 15 && fn <= 17 && n == 1) {
            if (calc_eval_number(parts[0], &x))
                out = calc_scalar_value(CALC_ANGLE,
                                        (fn == 15 ? atan(x)
                                         : fn == 16 ? asin(x) : acos(x)) *
                                            180.0 / G_PI);
        } else if (fn == 18 && n == 1) {
            if (calc_eval_arg(parts[0], &a)) {
                x = calc_term_key(&a);
                out = calc_num_value(isnan(x) ? NAN : x > 0 ? 1 : x < 0 ? -1 : x);
                if (calc_term_basis_dependent(&a)) calc_unresolved = TRUE;
            }
        } else if (fn == 19 && n == 1) {
            if (calc_eval_number(parts[0], &x))
                out = calc_num_value(exp(x));
        } else if (fn == 20 && n >= 1) {
            if (calc_eval_number(parts[0], &x)) {
                if (n >= 2 && calc_eval_number(parts[1], &y))
                    out = calc_num_value(log(x) / log(y));
                else if (n == 1)
                    out = calc_num_value(log(x));
            }
        } else if (fn == 21 && n == 3) {
            const char *first = parts[0];
            while (*first && ns_is_ascii_ws(*first)) first++;
            gboolean no_clamp = FALSE;
            if (g_ascii_strncasecmp(first, "no-clamp", 8) == 0 &&
                (first[8] == '\0' || ns_is_ascii_ws(first[8]))) {
                no_clamp = TRUE;
                first += 8;
                while (*first && ns_is_ascii_ws(*first)) first++;
            }
            ns_calc_term c;
            if (calc_eval_arg(first, &a) && calc_eval_arg(parts[1], &b) &&
                calc_eval_arg(parts[2], &c) && a.kind == b.kind &&
                b.kind == c.kind) {
                double A = calc_term_key(&a), B = calc_term_key(&b);
                double den = calc_term_key(&c) - B;
                double num = A - B;
                double pr;
                if (den == 0) {
                    pr = !no_clamp ? 0.0
                       : num > 0 ? INFINITY : num < 0 ? -INFINITY : NAN;
                } else {
                    pr = num / den;
                    if (!no_clamp)
                        pr = isnan(pr) ? 0.0 : pr < 0 ? 0.0 : pr > 1 ? 1.0 : pr;
                }
                out = calc_num_value(pr);
            }
        }
        for (int i = 0; i < n; i++) g_free(parts[i]);
        return out;
    }
    if (fn != 0) {
        char *parts[8] = {0};
        int n = calc_split_args(args, body_end, parts, G_N_ELEMENTS(parts));
        ns_css_value *out = calc_compare_scalar(fn, parts, n);
        if (!out) out = calc_compare_lengths(fn, parts, n);
        for (int i = 0; i < n; i++) g_free(parts[i]);
        return out;
    }
    const char *p = args;
    ns_calc_term term;
    if (!calc_expr_parse(&p, body_end, &term, 0)) return NULL;
    calc_skip_ws(&p, body_end);
    if (p != body_end) return NULL;
    if (term.kind == CALC_NUMBER) return calc_num_value(term.num);
    if (term.kind != CALC_LENGTH) return calc_scalar_value(term.kind, term.num);
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_CALC;
    v->u.calc.parsed_vw = g_viewport_w;
    v->u.calc.parsed_vh = g_viewport_h;
    if (term.fn) {
        v->u.calc.px = calc_term_key(&term);
        v->u.calc.fn = term.fn;
        v->u.calc.n_args = term.n_args;
        v->u.calc.arg_none = term.arg_none;
        for (int k = 0; k < term.n_args; k++) {
            v->u.calc.args[k].px = term.args[k].px;
            v->u.calc.args[k].pct = term.args[k].pct;
            v->u.calc.args[k].em = term.args[k].em;
            v->u.calc.args[k].rem = term.args[k].rem;
            v->u.calc.args[k].lh = term.args[k].lh;
            v->u.calc.args[k].rlh = term.args[k].rlh;
            v->u.calc.args[k].vw = term.args[k].vw;
            v->u.calc.args[k].vh = term.args[k].vh;
            v->u.calc.args[k].vmin = term.args[k].vmin;
            v->u.calc.args[k].vmax = term.args[k].vmax;
        }
        return v;
    }
    v->u.calc.pct = term.pct;
    v->u.calc.px  = term.px;
    v->u.calc.em  = term.em;
    v->u.calc.rem = term.rem;
    v->u.calc.lh  = term.lh;
    v->u.calc.rlh = term.rlh;
    v->u.calc.vw = term.vw;
    v->u.calc.vh = term.vh;
    v->u.calc.vmin = term.vmin;
    v->u.calc.vmax = term.vmax;
    return v;
}

static int split_ws(const char *s, char *out[4]);

/* Parses a background-size length or calc into a value and unit, flattening font units. */
static gboolean
parse_bg_size_component(const char *tok, double *out_v, ns_css_unit *out_unit)
{
    if (parse_length(tok, out_v, out_unit)) return TRUE;
    ns_css_value *cv = parse_calc(tok);
    if (!cv) return FALSE;
    gboolean ok = TRUE;
    if (cv->kind == NS_CSS_V_LENGTH) {
        *out_v = cv->u.length.v;
        *out_unit = cv->u.length.unit;
    } else if (cv->kind == NS_CSS_V_CALC) {
        if (cv->u.calc.pct != 0 && cv->u.calc.px == 0 &&
            cv->u.calc.em == 0 && cv->u.calc.rem == 0 &&
            cv->u.calc.lh == 0 && cv->u.calc.rlh == 0) {
            *out_v = cv->u.calc.pct;
            *out_unit = NS_CSS_UNIT_PERCENT;
        } else {
            *out_v = cv->u.calc.px +
                     (cv->u.calc.em + cv->u.calc.rem) * 16.0 +
                     (cv->u.calc.lh + cv->u.calc.rlh) * 19.2;
            *out_unit = NS_CSS_UNIT_PX;
        }
    } else {
        ok = FALSE;
    }
    ns_css_value_free(cv);
    return ok;
}

/* Parses a single grid track size keyword, fr, percentage or length into a track. */
static gboolean
parse_track_token(const char *tok, ns_css_track *out)
{
    if (!tok || !*tok) return FALSE;
    if (g_ascii_strcasecmp(tok, "auto") == 0) {
        out->kind = NS_CSS_TRACK_AUTO;
        out->v = 0;
        return TRUE;
    }
    if (g_ascii_strcasecmp(tok, "min-content") == 0) {
        out->kind = NS_CSS_TRACK_MIN_CONTENT;
        out->v = 0;
        return TRUE;
    }
    if (g_ascii_strcasecmp(tok, "max-content") == 0) {
        out->kind = NS_CSS_TRACK_MAX_CONTENT;
        out->v = 0;
        return TRUE;
    }
    char *endp = NULL;
    double v = g_ascii_strtod(tok, &endp);
    if (!endp || endp == tok) return FALSE;
    if (g_ascii_strcasecmp(endp, "fr") == 0) {
        if (v < 0) return FALSE;
        out->kind = NS_CSS_TRACK_FR; out->v = v; return TRUE;
    }
    ns_css_unit unit = NS_CSS_UNIT_NUMBER;
    if (!parse_length(tok, &v, &unit)) return FALSE;
    if (v < 0) return FALSE;
    switch (unit) {
    case NS_CSS_UNIT_PERCENT:
        out->kind = NS_CSS_TRACK_PERCENT; out->v = v; return TRUE;
    case NS_CSS_UNIT_NUMBER:
    case NS_CSS_UNIT_PX:
        out->kind = NS_CSS_TRACK_PX; out->v = v; return TRUE;
    case NS_CSS_UNIT_EM:
    case NS_CSS_UNIT_IC:
        out->kind = NS_CSS_TRACK_PX; out->v = 0; out->em = v; return TRUE;
    case NS_CSS_UNIT_REM:
        out->kind = NS_CSS_TRACK_PX; out->v = 0; out->rem = v; return TRUE;
    case NS_CSS_UNIT_LH:
    case NS_CSS_UNIT_RLH:
        out->kind = NS_CSS_TRACK_PX; out->v = v * 19.2; return TRUE;
    case NS_CSS_UNIT_EX:
    case NS_CSS_UNIT_CH:
        out->kind = NS_CSS_TRACK_PX; out->v = v * 8; return TRUE;
    case NS_CSS_UNIT_CAP:
        out->kind = NS_CSS_TRACK_PX; out->v = v * 11.2; return TRUE;
    case NS_CSS_UNIT_CQW:
    case NS_CSS_UNIT_CQH:
    case NS_CSS_UNIT_CQI:
    case NS_CSS_UNIT_CQB:
    case NS_CSS_UNIT_CQMIN:
    case NS_CSS_UNIT_CQMAX:
        out->kind = NS_CSS_TRACK_PX;
        out->v = container_unit_resolve(v, unit);
        return TRUE;
    default:
        out->kind = NS_CSS_TRACK_PX;
        out->v = viewport_resolve(v, unit);
        return TRUE;
    }
}

#define NS_CSS_TRACK_MAX_DEPTH 32

static gboolean parse_one_track(const char *start, gsize len,
                                ns_css_track *out);
static gboolean parse_one_track_depth(const char *start, gsize len,
                                      ns_css_track *out, int depth);

/* Parses a math-function track size into px, percent, or mixed px/em/rem/percent parts. */
static gboolean
parse_math_track(const char *start, gsize len, ns_css_track *out)
{
    char *tok = g_strndup(start, len);
    ns_css_value *cv = parse_calc(tok);
    g_free(tok);
    if (!cv) return FALSE;
    gboolean ok = FALSE;
    if (cv->kind == NS_CSS_V_LENGTH &&
        (cv->u.length.unit == NS_CSS_UNIT_PX ||
         cv->u.length.unit == NS_CSS_UNIT_NUMBER)) {
        out->kind = NS_CSS_TRACK_PX;
        out->v = cv->u.length.v;
        ok = TRUE;
    } else if (cv->kind == NS_CSS_V_CALC) {
        if (cv->u.calc.pct != 0 && cv->u.calc.px == 0 &&
            cv->u.calc.em == 0 && cv->u.calc.rem == 0 &&
            cv->u.calc.lh == 0 && cv->u.calc.rlh == 0) {
            out->kind = NS_CSS_TRACK_PERCENT;
            out->v = cv->u.calc.pct;
        } else {
            out->kind = NS_CSS_TRACK_PX;
            out->v = cv->u.calc.px +
                     (cv->u.calc.lh + cv->u.calc.rlh) * 19.2;
            out->em = cv->u.calc.em;
            out->rem = cv->u.calc.rem;
            out->pct = cv->u.calc.pct;
        }
        ok = TRUE;
    }
    ns_css_value_free(cv);
    return ok;
}

/* Parses minmax(min, max) into a track; a flexible min is only valid with a flexible max. */
static gboolean
parse_minmax_token(const char *body, gsize len, ns_css_track *out, int depth)
{
    const char *p = body;
    const char *end = body + len;
    while (p < end && ns_is_ascii_ws(*p)) p++;
    const char *as = p;
    char term = 0;
    const char *comma = css_scan_until(p, end, ",", &term);
    if (term != ',') return FALSE;
    p = comma;
    gsize alen = (gsize)(p - as);
    while (alen > 0 && ns_is_ascii_ws(as[alen - 1])) alen--;
    p++;
    while (p < end && ns_is_ascii_ws(*p)) p++;
    const char *bs = p;
    gsize blen = (gsize)(end - p);
    while (blen > 0 && ns_is_ascii_ws(bs[blen - 1])) blen--;
    ns_css_track mn = {0}, mx = {0};
    gboolean ok = parse_one_track_depth(as, alen, &mn, depth) &&
                  parse_one_track_depth(bs, blen, &mx, depth);
    if (!ok) return FALSE;
    if (mn.kind == NS_CSS_TRACK_FR) {
        if (mx.kind != NS_CSS_TRACK_FR) return FALSE;
        *out = mx;
        return TRUE;
    }
    *out = mx;
    out->min_kind = mn.kind;
    out->min_v    = mn.v;
    out->min_em   = mn.em;
    out->min_rem  = mn.rem;
    out->min_pct  = mn.pct;
    out->has_min  = TRUE;
    return TRUE;
}

/* Parses one track size incl. minmax() and fit-content(), bounded by recursion depth. */
static gboolean
parse_one_track_depth(const char *start, gsize len, ns_css_track *out, int depth)
{
    if (depth >= NS_CSS_TRACK_MAX_DEPTH) return FALSE;
    while (len > 0 && ns_is_ascii_ws(*start)) { start++; len--; }
    while (len > 0 && ns_is_ascii_ws(start[len - 1])) len--;
    if (len == 0) return FALSE;
    if (len > 7 && g_ascii_strncasecmp(start, "minmax(", 7) == 0 &&
        start[len - 1] == ')') {
        return parse_minmax_token(start + 7, len - 8, out, depth + 1);
    }
    if (len > 12 && g_ascii_strncasecmp(start, "fit-content(", 12) == 0 &&
        start[len - 1] == ')') {
        ns_css_track inner = {0};
        if (!parse_one_track_depth(start + 12, len - 13, &inner, depth + 1))
            return FALSE;
        *out = inner;
        out->min_kind = NS_CSS_TRACK_AUTO;
        out->min_v    = 0;
        out->has_min  = TRUE;
        out->fit_content = TRUE;
        return TRUE;
    }
    if (start[len - 1] == ')' &&
        (g_ascii_strncasecmp(start, "min(", 4) == 0 ||
         g_ascii_strncasecmp(start, "max(", 4) == 0 ||
         g_ascii_strncasecmp(start, "clamp(", 6) == 0 ||
         g_ascii_strncasecmp(start, "calc(", 5) == 0))
        return parse_math_track(start, len, out);
    char *tok = g_strndup(start, len);
    gboolean ok = parse_track_token(tok, out);
    g_free(tok);
    return ok;
}

static gboolean
parse_one_track(const char *start, gsize len, ns_css_track *out)
{
    return parse_one_track_depth(start, len, out, 0);
}

/* Splits a track list at whitespace/commas outside parentheses into start/length pairs. */
static int
split_tracks_top(const char *text, gsize len, const char **starts, gsize *lens, int max)
{
    int n = 0;
    const char *p = text;
    const char *end = text + len;
    while (p < end && n < max) {
        while (p < end && ns_is_ascii_ws(*p)) p++;
        if (p >= end) break;
        const char *tok_start = p;
        char term = 0;
        p = css_scan_until(p, end, " \t\n\r\f,", &term);
        starts[n] = tok_start;
        lens[n]   = (gsize)(p - tok_start);
        n++;
        if (p < end && *p == ',') p++;
    }
    return n;
}

/* Checks whether a token is a valid CSS identifier for an unquoted font family name. */
static gboolean
font_family_ident_valid(const char *tok, gsize len)
{
    if (len == 0) return FALSE;
    gsize i = 0;
    if (tok[0] == '-') {
        i = 1;
        if (len == 1) return FALSE;
        if (tok[1] == '-') i = 2;
    }
    if (i >= len) return FALSE;
    unsigned char first = (unsigned char)tok[i];
    if (!(g_ascii_isalpha(first) || first == '_' || first >= 0x80 || first == '\\'))
        return FALSE;
    for (gsize k = i; k < len; k++) {
        unsigned char c = (unsigned char)tok[k];
        if (c == '\\') { k++; continue; }
        if (!(g_ascii_isalnum(c) || c == '-' || c == '_' || c >= 0x80))
            return FALSE;
    }
    return TRUE;
}

/* Reports whether a token is a generic family or reserved keyword that cannot be unquoted. */
static gboolean
font_family_is_generic(const char *tok, gsize len)
{
    static const char *const generic[] = {
        "serif", "sans-serif", "cursive", "fantasy", "monospace",
        "system-ui", "ui-serif", "ui-sans-serif", "ui-monospace",
        "ui-rounded", "math", "emoji", "fangsong", "inherit", "initial",
        "unset", "revert", "revert-layer", "default",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(generic); i++)
        if (strlen(generic[i]) == len &&
            g_ascii_strncasecmp(tok, generic[i], len) == 0)
            return TRUE;
    return FALSE;
}

static gboolean is_font_stretch_keyword(const char *s);
static ns_css_value *parse_value_for(ns_css_prop prop, const char *text);

/* Splits text at top-level whitespace, respecting parens, quotes and escapes; new strings. */
static int
split_ws_paren(const char *text, char **out, int max)
{
    int n = 0;
    const char *p = text, *end = text + strlen(text);
    while (p < end && n < max) {
        while (p < end && ns_is_ascii_ws(*p)) p++;
        if (p >= end) break;
        const char *start = p;
        int depth = 0;
        char quote = 0;
        while (p < end) {
            char c = *p;
            if (quote) { if (c == quote) quote = 0; p++; continue; }
            if (c == '\\' && p + 1 < end) { p += 2; continue; }
            if (c == '"' || c == '\'') { quote = c; p++; continue; }
            if (c == '(') depth++;
            else if (c == ')') { if (depth) depth--; }
            else if (ns_is_ascii_ws(c) && depth == 0) break;
            p++;
        }
        out[n++] = g_strndup(start, (gsize)(p - start));
    }
    return n;
}

/* Validates a font-size token: keyword, larger/smaller, math fn or non-negative length. */
static gboolean
font_size_token_valid(const char *tok)
{
    if (font_size_keyword_px(tok) > 0) return TRUE;
    if (g_ascii_strcasecmp(tok, "larger") == 0 ||
        g_ascii_strcasecmp(tok, "smaller") == 0)
        return TRUE;
    if (g_ascii_strncasecmp(tok, "calc(", 5) == 0 ||
        g_ascii_strncasecmp(tok, "min(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "max(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "clamp(", 6) == 0) {
        ns_css_value *cv = parse_calc(tok);
        if (!cv) return FALSE;
        ns_css_value_free(cv);
        return TRUE;
    }
    double v; ns_css_unit u;
    return parse_length(tok, &v, &u) && u != NS_CSS_UNIT_NUMBER && v >= 0;
}

/* Validates a font shorthand line-height token: normal, math fn or non-negative value. */
static gboolean
font_line_height_token_valid(const char *tok)
{
    if (g_ascii_strcasecmp(tok, "normal") == 0) return TRUE;
    if (g_ascii_strncasecmp(tok, "calc(", 5) == 0 ||
        g_ascii_strncasecmp(tok, "min(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "max(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "clamp(", 6) == 0) {
        ns_css_value *cv = parse_calc(tok);
        if (!cv) return FALSE;
        ns_css_value_free(cv);
        return TRUE;
    }
    double v; ns_css_unit u;
    return parse_length(tok, &v, &u) && v >= 0;
}

/* Returns the first top-level '/' in a token (size/line-height split), or NULL. */
static char *
font_shorthand_slash(char *tok)
{
    int depth = 0;
    for (char *q = tok; *q; q++) {
        if (*q == '(') depth++;
        else if (*q == ')') { if (depth) depth--; }
        else if (*q == '/' && depth == 0) return q;
    }
    return NULL;
}

/* Reports whether a token can be the font shorthand's size, excluding bare numbers. */
static gboolean
font_shorthand_is_size_token(const char *tok)
{
    char *copy = g_strdup(tok);
    char *slash = font_shorthand_slash(copy);
    if (slash) *slash = '\0';
    gboolean ok = *copy && font_size_token_valid(copy) &&
                  !(g_ascii_isdigit((guchar)copy[0]) &&
                    strspn(copy, "0123456789.") == strlen(copy));
    g_free(copy);
    return ok;
}

/* Builds the font-size value from a shorthand size token; larger/smaller map to em ratios. */
static ns_css_value *
font_shorthand_size_value(const char *size_only)
{
    double kw = font_size_keyword_px(size_only);
    ns_css_value *v = NULL;
    if (kw > 0 || g_ascii_strcasecmp(size_only, "larger") == 0 ||
        g_ascii_strcasecmp(size_only, "smaller") == 0) {
        v = g_new0(ns_css_value, 1);
        v->kind = NS_CSS_V_LENGTH;
        if (kw > 0) {
            v->u.length.v = kw;
            v->u.length.unit = NS_CSS_UNIT_PX;
        } else {
            v->u.length.v = g_ascii_strcasecmp(size_only, "larger") == 0
                ? 1.2 : 0.833333333333;
            v->u.length.unit = NS_CSS_UNIT_EM;
        }
        return v;
    }
    return parse_value_for(NS_CSS_FONT_SIZE, size_only);
}

/* Canonicalizes a font shorthand to style variant weight stretch size/lh family order. */
static char *
ns_css_font_shorthand_canonical(const char *text)
{
    if (!text) return NULL;
    char *tokens[24] = {0};
    int n = split_ws_paren(text, tokens, 24);
    char *result = NULL;
    const char *style = NULL, *variant = NULL, *weight = NULL, *stretch = NULL;
    int prefix = 0;
    int i = 0;
    for (; i < n && prefix < 4; i++) {
        const char *t = tokens[i];
        if (g_ascii_strcasecmp(t, "normal") == 0) { prefix++; continue; }
        if (g_ascii_strcasecmp(t, "italic") == 0 ||
            g_ascii_strcasecmp(t, "oblique") == 0) {
            if (style) goto done;
            style = t; prefix++; continue;
        }
        if (g_ascii_strcasecmp(t, "small-caps") == 0) {
            if (variant) goto done;
            variant = t; prefix++; continue;
        }
        if (g_ascii_strcasecmp(t, "bold") == 0 ||
            g_ascii_strcasecmp(t, "bolder") == 0 ||
            g_ascii_strcasecmp(t, "lighter") == 0) {
            if (weight) goto done;
            weight = t; prefix++; continue;
        }
        if (g_ascii_isdigit((guchar)t[0])) {
            char *endp = NULL;
            double w = g_ascii_strtod(t, &endp);
            if (endp && *endp == '\0' && w >= 1 && w <= 1000 &&
                !(i + 1 < n && FALSE)) {
                if (weight) goto done;
                weight = t; prefix++; continue;
            }
        }
        if (is_font_stretch_keyword(t)) {
            if (stretch) goto done;
            stretch = t; prefix++; continue;
        }
        break;
    }
    if (i >= n) goto done;
    char *size_tok = tokens[i];
    char *lh_tok = NULL;
    char *slash = NULL;
    {
        int depth = 0;
        for (char *q = size_tok; *q; q++) {
            if (*q == '(') depth++;
            else if (*q == ')') { if (depth) depth--; }
            else if (*q == '/' && depth == 0) { slash = q; break; }
        }
    }
    char *size_only = slash ? g_strndup(size_tok, (gsize)(slash - size_tok))
                            : g_strdup(size_tok);
    int fam_start = i + 1;
    if (slash) {
        if (slash[1]) lh_tok = g_strdup(slash + 1);
        else if (fam_start < n) lh_tok = g_strdup(tokens[fam_start++]);
        else { g_free(size_only); goto done; }
    } else if (fam_start < n && tokens[fam_start][0] == '/') {
        if (tokens[fam_start][1]) lh_tok = g_strdup(tokens[fam_start] + 1);
        else if (fam_start + 1 < n) { lh_tok = g_strdup(tokens[fam_start + 1]); fam_start++; }
        fam_start++;
    }
    if (!*size_only || !font_size_token_valid(size_only) ||
        (lh_tok && !font_line_height_token_valid(lh_tok)) || fam_start >= n) {
        g_free(size_only);
        g_free(lh_tok);
        goto done;
    }
    GString *fam = g_string_new(NULL);
    for (int j = fam_start; j < n; j++) {
        if (j > fam_start) g_string_append_c(fam, ' ');
        g_string_append(fam, tokens[j]);
    }
    char *family = ns_css_font_family_canonical(fam->str);
    g_string_free(fam, TRUE);
    if (!family) {
        g_free(size_only);
        g_free(lh_tok);
        goto done;
    }
    GString *out = g_string_new(NULL);
    if (style) { g_string_append(out, g_ascii_strcasecmp(style, "italic") == 0 ? "italic" : "oblique"); }
    if (variant) { if (out->len) g_string_append_c(out, ' '); g_string_append(out, "small-caps"); }
    if (weight) {
        if (out->len) g_string_append_c(out, ' ');
        char *lw = g_ascii_strdown(weight, -1);
        g_string_append(out, lw);
        g_free(lw);
    }
    if (stretch) {
        if (out->len) g_string_append_c(out, ' ');
        char *ls = g_ascii_strdown(stretch, -1);
        g_string_append(out, ls);
        g_free(ls);
    }
    if (out->len) g_string_append_c(out, ' ');
    {
        char *ls = font_size_keyword_px(size_only) > 0 ||
                   g_ascii_strcasecmp(size_only, "larger") == 0 ||
                   g_ascii_strcasecmp(size_only, "smaller") == 0
            ? g_ascii_strdown(size_only, -1) : g_strdup(size_only);
        g_string_append(out, ls);
        g_free(ls);
    }
    if (lh_tok && g_ascii_strcasecmp(lh_tok, "normal") != 0) {
        g_string_append(out, " / ");
        g_string_append(out, lh_tok);
    }
    g_string_append_c(out, ' ');
    g_string_append(out, family);
    g_free(family);
    g_free(size_only);
    g_free(lh_tok);
    result = g_string_free(out, FALSE);
done:
    for (int k = 0; k < n; k++) g_free(tokens[k]);
    return result;
}

#define NS_CSS_RANDOM_ITEM_MAX_DEPTH 16

/* Validates a random-item() font family entry and each of its nested family lists. */
static gboolean
font_family_random_item_valid(const char *item, gsize ilen)
{
    static __thread int nesting;
    if (nesting >= NS_CSS_RANDOM_ITEM_MAX_DEPTH) return FALSE;
    const char *open = memchr(item, '(', ilen);
    if (!open || item[ilen - 1] != ')') return FALSE;
    char *body = g_strndup(open + 1, (gsize)(item + ilen - 1 - (open + 1)));
    GPtrArray *args = g_ptr_array_new_with_free_func(g_free);
    const char *seg = body;
    int depth = 0;
    for (const char *q = body; ; q++) {
        if (*q == '(' || *q == '{' || *q == '[') depth++;
        else if ((*q == ')' || *q == '}' || *q == ']') && depth > 0) depth--;
        if ((*q == ',' && depth == 0) || !*q) {
            char *piece = g_strndup(seg, (gsize)(q - seg));
            g_strstrip(piece);
            g_ptr_array_add(args, piece);
            if (!*q) break;
            seg = q + 1;
        }
    }
    g_free(body);
    gboolean ok = args->len >= 2;
    if (ok) {
        const char *first = args->pdata[0];
        char *tok[3] = {0};
        int n = split_ws_limit(first, tok, 3);
        ok = n >= 1 && n <= 2;
        for (int i = 0; i < n && ok; i++) {
            const char *t = tok[i];
            if (i == 1 && g_ascii_strcasecmp(tok[0], "fixed") == 0) {
                char *endp = NULL;
                g_ascii_strtod(t, &endp);
                ok = endp && *endp == '\0';
            } else {
                ok = font_family_ident_valid(t, strlen(t)) ||
                     (g_str_has_prefix(t, "--") && t[2]);
            }
        }
        for (int i = 0; i < n; i++) g_free(tok[i]);
    }
    for (guint i = 1; i < args->len && ok; i++) {
        const char *a = args->pdata[i];
        gsize alen = strlen(a);
        if (!alen) continue;
        char *inner = NULL;
        if (a[0] == '{') {
            if (a[alen - 1] != '}') { ok = FALSE; break; }
            inner = g_strndup(a + 1, alen - 2);
        } else if (memchr(a, '{', alen) || memchr(a, '}', alen)) {
            ok = FALSE;
            break;
        } else {
            inner = g_strdup(a);
        }
        nesting++;
        char *canon = ns_css_font_family_canonical(inner);
        nesting--;
        ok = canon != NULL;
        g_free(canon);
        g_free(inner);
    }
    g_ptr_array_free(args, TRUE);
    return ok;
}

/* Serializes a font-family list, unquoting ident-like names; NULL if invalid. Caller frees. */
static char *
ns_css_font_family_canonical(const char *text)
{
    if (!text) return NULL;
    GString *out = g_string_new(NULL);
    const char *p = text;
    const char *end = text + strlen(text);
    gboolean any = FALSE;
    while (p <= end) {
        while (p < end && ns_is_ascii_ws(*p)) p++;
        const char *item_start = p;
        char term = 0;
        const char *item_end = css_scan_until(p, end, ",", &term);
        gsize ilen = (gsize)(item_end - item_start);
        while (ilen > 0 && ns_is_ascii_ws(item_start[ilen - 1])) ilen--;
        if (ilen == 0) { g_string_free(out, TRUE); return NULL; }
        if (any) g_string_append(out, ", ");
        any = TRUE;
        if (item_start[0] == '"' || item_start[0] == '\'') {
            char q = item_start[0];
            if (ilen < 2 || item_start[ilen - 1] != q) {
                g_string_free(out, TRUE);
                return NULL;
            }
            const char *body = item_start + 1;
            gsize blen = ilen - 2;
            gboolean ident_like = blen > 0 && !ns_is_ascii_ws(body[0]) &&
                                  !ns_is_ascii_ws(body[blen - 1]) &&
                                  !memchr(body, '\\', blen);
            if (ident_like) {
                const char *w = body, *wend = body + blen;
                while (w < wend && ident_like) {
                    const char *tok = w;
                    while (w < wend && !ns_is_ascii_ws(*w)) w++;
                    gsize tlen = (gsize)(w - tok);
                    if (!font_family_ident_valid(tok, tlen) ||
                        font_family_is_generic(tok, tlen))
                        ident_like = FALSE;
                    if (w < wend && (w + 1 >= wend || ns_is_ascii_ws(w[1])))
                        ident_like = FALSE;
                    w++;
                }
            }
            if (ident_like) {
                g_string_append_len(out, body, (gssize)blen);
            } else {
                g_string_append_c(out, '"');
                for (gsize k = 0; k < blen; k++) {
                    char c = body[k];
                    if (c == '\\' && k + 1 < blen) {
                        g_string_append_c(out, c);
                        g_string_append_c(out, body[++k]);
                        continue;
                    }
                    if (c == '"') g_string_append_c(out, '\\');
                    g_string_append_c(out, c);
                }
                g_string_append_c(out, '"');
            }
        } else if (item_start[ilen - 1] == ')' &&
                   (g_ascii_strncasecmp(item_start, "random-item(", 12) == 0 ||
                    g_ascii_strncasecmp(item_start, "-webkit-generic(", 16) == 0)) {
            if (g_ascii_strncasecmp(item_start, "random-item(", 12) == 0 &&
                !font_family_random_item_valid(item_start, ilen)) {
                g_string_free(out, TRUE);
                return NULL;
            }
            g_string_append_len(out, item_start, (gssize)ilen);
        } else {
            const char *q = item_start, *qend = item_start + ilen;
            gboolean first = TRUE;
            {
                static const char *const reserved[] = {
                    "inherit", "initial", "unset", "revert", "revert-layer",
                    "default",
                };
                for (gsize k = 0; k < G_N_ELEMENTS(reserved); k++)
                    if (strlen(reserved[k]) == ilen &&
                        g_ascii_strncasecmp(item_start, reserved[k], ilen) == 0) {
                        g_string_free(out, TRUE);
                        return NULL;
                    }
            }
            while (q < qend) {
                while (q < qend && ns_is_ascii_ws(*q)) q++;
                const char *tok = q;
                while (q < qend && !ns_is_ascii_ws(*q)) q++;
                gsize tlen = (gsize)(q - tok);
                if (tlen == 0) break;
                static const char *const strict_generic[] = {
                    "serif", "sans-serif", "cursive", "fantasy", "monospace",
                };
                gboolean strict = FALSE;
                for (gsize k = 0; k < G_N_ELEMENTS(strict_generic); k++)
                    if (strlen(strict_generic[k]) == tlen &&
                        g_ascii_strncasecmp(tok, strict_generic[k], tlen) == 0)
                        strict = TRUE;
                if (!font_family_ident_valid(tok, tlen) ||
                    ((!first || q < qend) && strict)) {
                    g_string_free(out, TRUE);
                    return NULL;
                }
                if (!first) g_string_append_c(out, ' ');
                if (first && q >= qend && font_family_is_generic(tok, tlen)) {
                    char *lower = g_ascii_strdown(tok, (gssize)tlen);
                    g_string_append(out, lower);
                    g_free(lower);
                } else {
                    g_string_append_len(out, tok, (gssize)tlen);
                }
                first = FALSE;
            }
        }
        if (term != ',') break;
        p = item_end + 1;
        if (p >= end) { g_string_free(out, TRUE); return NULL; }
    }
    if (!any) { g_string_free(out, TRUE); return NULL; }
    return g_string_free(out, FALSE);
}

/* Validates a grid line name as a custom-ident, rejecting span, auto and CSS-wide keywords. */
static gboolean
line_name_is_custom_ident(const char *ns, gsize nlen)
{
    if (nlen == 0) return FALSE;
    gsize i = 0;
    if (ns[0] == '-') {
        i = 1;
        if (nlen == 1) return FALSE;
    }
    if (g_ascii_isdigit(ns[i])) return FALSE;
    for (gsize k = i; k < nlen; k++) {
        char c = ns[k];
        if (!(g_ascii_isalnum(c) || c == '-' || c == '_' || (unsigned char)c >= 0x80))
            return FALSE;
    }
    static const char *const reserved[] = {
        "span", "auto", "initial", "inherit", "unset", "revert",
        "revert-layer", "default",
    };
    for (gsize k = 0; k < G_N_ELEMENTS(reserved); k++)
        if (strlen(reserved[k]) == nlen &&
            g_ascii_strncasecmp(ns, reserved[k], nlen) == 0)
            return FALSE;
    return TRUE;
}

/* Records bracketed grid line names for the given line; FALSE on invalid names. */
static gboolean
tracks_add_names(ns_css_tracks *tk, const char *names, gsize names_len, int line)
{
    if (memchr(names, ',', names_len)) return FALSE;
    const char *q = names, *qend = names + names_len;
    while (q < qend) {
        while (q < qend && ns_is_ascii_ws(*q)) q++;
        const char *ns = q;
        while (q < qend && !ns_is_ascii_ws(*q)) q++;
        gsize nlen = (gsize)(q - ns);
        if (nlen > 0 && !line_name_is_custom_ident(ns, nlen)) return FALSE;
        if (nlen > 0 && nlen < NS_CSS_LINE_NAME_MAX &&
            tk->n_line_names < NS_CSS_LINE_NAMES_MAX) {
            ns_css_line_name *ln = &tk->line_names[tk->n_line_names++];
            memcpy(ln->name, ns, nlen);
            ln->name[nlen] = '\0';
            ln->line = line;
        }
    }
    return TRUE;
}

/* Reports whether a track is a fixed size (or has a fixed minimum), as auto-repeat requires. */
static gboolean
track_is_fixed_size(const ns_css_track *t)
{
    gboolean main_fixed = t->kind == NS_CSS_TRACK_PX || t->kind == NS_CSS_TRACK_PERCENT;
    if (!t->has_min) return main_fixed;
    gboolean min_fixed = t->min_kind == NS_CSS_TRACK_PX ||
                         t->min_kind == NS_CSS_TRACK_PERCENT;
    return main_fixed || min_fixed;
}

/* Expands a repeat() body into tracks and line names repeats times. */
static gboolean
tracks_append_repeat_body(ns_css_tracks *tk, const char *body, gsize body_len,
                          long repeats, int *out_tracks_per_repeat)
{
    const char *tstarts[32];
    gsize tlens[32];
    int nb = 0;
    const char *p = body, *end = body + body_len;
    while (p < end && nb < 32) {
        while (p < end && ns_is_ascii_ws(*p)) p++;
        if (p >= end) break;
        const char *tok_start = p;
        if (*p == '[') {
            while (p < end && *p != ']') p++;
            if (p < end) p++;
        } else {
            char term = 0;
            p = css_scan_until(p, end, " \t\n\r\f,[", &term);
        }
        tstarts[nb] = tok_start;
        tlens[nb] = (gsize)(p - tok_start);
        nb++;
        if (p < end && *p == ',') p++;
    }
    int per = 0;
    for (int i = 0; i < nb; i++)
        if (tstarts[i][0] != '[') per++;
    if (per == 0) return FALSE;
    if (out_tracks_per_repeat) *out_tracks_per_repeat = per;
    for (long r = 0; r < repeats; r++) {
        gboolean last_names = FALSE;
        for (int i = 0; i < nb; i++) {
            if (tstarts[i][0] == '[') {
                if (last_names || tlens[i] < 2) return FALSE;
                if (!tracks_add_names(tk, tstarts[i] + 1, tlens[i] - 2, tk->n + 1))
                    return FALSE;
                last_names = TRUE;
                continue;
            }
            last_names = FALSE;
            if (tk->n >= NS_CSS_TRACKS_MAX) return TRUE;
            ns_css_track t = {0};
            if (!parse_one_track(tstarts[i], tlens[i], &t)) return FALSE;
            tk->tracks[tk->n++] = t;
        }
    }
    return TRUE;
}

/* Parses grid-template-rows/columns: line names, repeat(), auto-fill/fit and subgrid. */
static ns_css_value *
parse_tracks(const char *text)
{
    if (!text || !*text) return NULL;
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_TRACKS;
    const char *p = text;
    const char *full_end = text + strlen(text);
    while (p < full_end && ns_is_ascii_ws(*p)) p++;
    if (g_ascii_strncasecmp(p, "subgrid", 7) == 0 &&
        (p + 7 >= full_end || ns_is_ascii_ws(p[7]) || p[7] == '[')) {
        v->u.tracks.subgrid = TRUE;
        return v;
    }
    gboolean last_was_names = FALSE;
    while (p < full_end && v->u.tracks.n < NS_CSS_TRACKS_MAX) {
        while (p < full_end && ns_is_ascii_ws(*p)) p++;
        if (p >= full_end) break;
        if (*p == '[') {
            const char *names = ++p;
            while (p < full_end && *p != ']') p++;
            gsize names_len = (gsize)(p - names);
            if (p >= full_end || last_was_names ||
                memchr(names, ',', names_len)) {
                g_free(v);
                return NULL;
            }
            last_was_names = TRUE;
            p++;
            if (!tracks_add_names(&v->u.tracks, names, names_len,
                                  v->u.tracks.n + 1)) {
                g_free(v);
                return NULL;
            }
            continue;
        }
        last_was_names = FALSE;
        if (g_ascii_strncasecmp(p, "repeat(", 7) == 0) {
            p += 7;
            while (p < full_end && ns_is_ascii_ws(*p)) p++;
            const char *count_s = p;
            while (p < full_end && *p != ',' && *p != ')') p++;
            gsize count_len = (gsize)(p - count_s);
            while (count_len > 0 && ns_is_ascii_ws(count_s[count_len - 1])) count_len--;
            if (p < full_end && *p == ',') p++;
            const char *body = p;
            int depth = 1;
            while (p < full_end && depth > 0) {
                if (*p == '(') depth++;
                else if (*p == ')') { depth--; if (depth == 0) break; }
                p++;
            }
            gsize body_len = (gsize)(p - body);
            if (p < full_end && *p == ')') p++;
            ns_css_auto_repeat ar = NS_CSS_AUTO_REPEAT_NONE;
            long n = 0;
            if (count_len == 8 && g_ascii_strncasecmp(count_s, "auto-fit", 8) == 0)
                ar = NS_CSS_AUTO_REPEAT_FIT;
            else if (count_len == 9 && g_ascii_strncasecmp(count_s, "auto-fill", 9) == 0)
                ar = NS_CSS_AUTO_REPEAT_FILL;
            else {
                char *cstr = g_strndup(count_s, count_len);
                n = strtol(cstr, NULL, 10);
                g_free(cstr);
                if (n <= 0) continue;
                if (n > NS_CSS_TRACKS_MAX) n = NS_CSS_TRACKS_MAX;
            }
            if (ar != NS_CSS_AUTO_REPEAT_NONE) {
                if (v->u.tracks.auto_repeat != NS_CSS_AUTO_REPEAT_NONE) {
                    g_free(v);
                    return NULL;
                }
                v->u.tracks.auto_repeat = ar;
                v->u.tracks.auto_repeat_start = v->u.tracks.n;
                v->u.tracks.auto_repeat_names_start = v->u.tracks.n_line_names;
                int cnt = 0;
                if (!tracks_append_repeat_body(&v->u.tracks, body, body_len,
                                               1, &cnt)) {
                    g_free(v);
                    return NULL;
                }
                v->u.tracks.auto_repeat_names_end = v->u.tracks.n_line_names;
                for (int k = v->u.tracks.auto_repeat_start; k < v->u.tracks.n; k++)
                    if (!track_is_fixed_size(&v->u.tracks.tracks[k])) {
                        g_free(v);
                        return NULL;
                    }
                if (cnt > v->u.tracks.n - v->u.tracks.auto_repeat_start)
                    cnt = v->u.tracks.n - v->u.tracks.auto_repeat_start;
                v->u.tracks.auto_repeat_count = cnt;
                continue;
            }
            if (!tracks_append_repeat_body(&v->u.tracks, body, body_len, n, NULL)) {
                g_free(v);
                return NULL;
            }
            continue;
        }
        const char *tstarts[1];
        gsize tlens[1];
        int n = split_tracks_top(p, (gsize)(full_end - p), tstarts, tlens, 1);
        if (n == 0) break;
        {
            const char *after = tstarts[0] + tlens[0];
            while (after < full_end && ns_is_ascii_ws(*after)) after++;
            if (after < full_end && *after == ',') {
                g_free(v);
                return NULL;
            }
        }
        last_was_names = FALSE;
        ns_css_track t = {0};
        if (!parse_one_track(tstarts[0], tlens[0], &t)) {
            g_free(v);
            return NULL;
        }
        v->u.tracks.tracks[v->u.tracks.n++] = t;
        const char *next = tstarts[0] + tlens[0];
        while (next < full_end && ns_is_ascii_ws(*next)) next++;
        if (next < full_end && *next == ',') next++;
        if (next <= p) next = p + 1;
        p = next;
    }
    if (v->u.tracks.n == 0) { g_free(v); return NULL; }
    if (v->u.tracks.n == 0 && v->u.tracks.n_line_names > 0) {
        g_free(v);
        return NULL;
    }
    if (v->u.tracks.auto_repeat != NS_CSS_AUTO_REPEAT_NONE) {
        for (int k = 0; k < v->u.tracks.n; k++) {
            if (k >= v->u.tracks.auto_repeat_start &&
                k < v->u.tracks.auto_repeat_start + v->u.tracks.auto_repeat_count)
                continue;
            if (!track_is_fixed_size(&v->u.tracks.tracks[k])) {
                g_free(v);
                return NULL;
            }
        }
    }
    return v;
}

/* Parses grid-template-areas strings into named rectangles; rows must have equal columns. */
static ns_css_value *
parse_areas(const char *text)
{
    if (!text || !*text) return NULL;
    char *grid[NS_CSS_TRACKS_MAX][NS_CSS_TRACKS_MAX] = {{0}};
    int rows = 0;
    int cols = -1;
    const char *p = text;
    while (*p && rows < NS_CSS_TRACKS_MAX) {
        while (*p && ns_is_ascii_ws(*p)) p++;
        if (!*p) break;
        if (*p != '"' && *p != '\'') {
            for (int r = 0; r < rows; r++)
                for (int k = 0; k < NS_CSS_TRACKS_MAX; k++)
                    g_free(grid[r][k]);
            return NULL;
        }
        const char *row_start = p;
        char *row = read_css_string(&p, p + strlen(p));
        if (p == row_start) {
            g_free(row);
            for (int r = 0; r < rows; r++)
                for (int k = 0; k < NS_CSS_TRACKS_MAX; k++)
                    g_free(grid[r][k]);
            return NULL;
        }
        char **toks = g_strsplit_set(row, " \t\r\n", -1);
        int c = 0;
        for (int i = 0; toks[i]; i++) {
            if (!*toks[i]) continue;
            if (c >= NS_CSS_TRACKS_MAX) break;
            grid[rows][c++] = g_strdup(toks[i]);
        }
        g_strfreev(toks);
        g_free(row);
        if (cols < 0) cols = c;
        else if (c != cols) {
            for (int r = 0; r <= rows; r++)
                for (int k = 0; k < NS_CSS_TRACKS_MAX; k++)
                    g_free(grid[r][k]);
            return NULL;
        }
        rows++;
    }
    if (rows == 0 || cols <= 0) {
        for (int r = 0; r < rows; r++)
            for (int k = 0; k < NS_CSS_TRACKS_MAX; k++)
                g_free(grid[r][k]);
        return NULL;
    }
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_AREAS;
    v->u.areas.n_rows = rows;
    v->u.areas.n_cols = cols;
    gboolean used[NS_CSS_TRACKS_MAX][NS_CSS_TRACKS_MAX] = {{0}};
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (used[r][c]) continue;
            const char *name = grid[r][c];
            if (!name || strcmp(name, ".") == 0) { used[r][c] = TRUE; continue; }
            int c1 = c;
            while (c1 + 1 < cols && grid[r][c1 + 1] &&
                   strcmp(grid[r][c1 + 1], name) == 0) c1++;
            int r1 = r;
            while (r1 + 1 < rows) {
                gboolean ok = TRUE;
                for (int k = c; k <= c1; k++) {
                    if (!grid[r1 + 1][k] || strcmp(grid[r1 + 1][k], name) != 0) {
                        ok = FALSE; break;
                    }
                }
                if (!ok) break;
                r1++;
            }
            if (v->u.areas.n_rects < NS_CSS_AREAS_MAX) {
                ns_css_area_rect *rect = &v->u.areas.rects[v->u.areas.n_rects++];
                rect->name = g_strdup(name);
                rect->r0 = r; rect->r1 = r1;
                rect->c0 = c; rect->c1 = c1;
            }
            for (int rr = r; rr <= r1; rr++)
                for (int cc = c; cc <= c1; cc++)
                    used[rr][cc] = TRUE;
        }
    }
    for (int r = 0; r < rows; r++)
        for (int k = 0; k < NS_CSS_TRACKS_MAX; k++)
            g_free(grid[r][k]);
    return v;
}

static gboolean text_is_ident(const char *t);
static gboolean bg_repeat_token(const char *tok, gboolean allow_axis);
static char *bg_repeat_canonical(const char *a, const char *b);
static char *bg_position_zip(const char *xs, const char *ys);
static gboolean bg_token_is_box(const char *tok);
static char *position_from_edge(const char *edge, const char *offset);
static char *quad_text_collapse(char *const v[4]);
static int css_ws_token_count(const char *s);
static char *transform_list_canonical(const char *value);
static char *individual_transform_canonical(const char *value, ns_css_prop prop);
static char *transform_origin_canonical(const char *value, gboolean two_only);
static char *border_image_longhand_canonical(ns_css_prop prop, const char *text);
static gboolean inline_css_wide_value(const char *value);
static char *bg_clip_canonical(const char *text);
static char *css_add_leading_zeros(char *v);
static char *css_normalize_negative_zero(char *value);

/* Canonicalizes one shadow length (no percentages, optional no-negatives) into out. */
static gboolean
shadow_length_token(const char *tok, gboolean allow_negative, GString *out)
{
    double num;
    ns_css_unit unit;
    if (parse_length(tok, &num, &unit)) {
        if (unit == NS_CSS_UNIT_PERCENT) return FALSE;
        if (unit == NS_CSS_UNIT_NUMBER && num != 0) return FALSE;
        if (!allow_negative && num < 0) return FALSE;
        if (num == 0) {
            g_string_append(out, "0px");
            return TRUE;
        }
        char *canon = css_normalize_negative_zero(
            css_add_leading_zeros(g_strdup(tok)));
        char *suffix = canon + strlen(canon);
        while (suffix > canon && g_ascii_isalpha((guchar)suffix[-1]))
            suffix--;
        for (char *c = suffix; *c; c++) *c = g_ascii_tolower((guchar)*c);
        g_string_append(out, canon);
        g_free(canon);
        return TRUE;
    }
    ns_css_value *calc = parse_calc(tok);
    if (!calc) return FALSE;
    gboolean ok = (calc->kind == NS_CSS_V_CALC && calc->u.calc.pct == 0) ||
                  (calc->kind == NS_CSS_V_LENGTH &&
                   calc->u.length.unit != NS_CSS_UNIT_PERCENT &&
                   calc->u.length.unit != NS_CSS_UNIT_NUMBER);
    ns_css_value_free(calc);
    if (!ok) return FALSE;
    char *canon = ns_css_math_canonical(tok);
    if (!canon) canon = css_add_leading_zeros(g_strdup(tok));
    g_string_append(out, canon);
    g_free(canon);
    return TRUE;
}

/* Canonicalizes one shadow layer as color, lengths, inset; FALSE when invalid. */
static gboolean
shadow_specified_one(const char *text, gboolean is_text, GString *out)
{
    char *tokens[8] = {0};
    int n = split_ws_limit(text, tokens, G_N_ELEMENTS(tokens));
    GString *color = NULL;
    GString *lengths = g_string_new(NULL);
    int n_lengths = 0;
    gboolean lengths_closed = FALSE;
    gboolean inset = FALSE, ok = n > 0;
    for (int i = 0; ok && i < n; i++) {
        const char *tok = tokens[i];
        guint8 r = 0, g = 0, b = 0, a = 255;
        if (g_ascii_strcasecmp(tok, "inset") == 0) {
            if (is_text || inset) ok = FALSE;
            inset = TRUE;
            if (n_lengths) lengths_closed = TRUE;
            continue;
        }
        if (parse_color(tok, &r, &g, &b, &a) ||
            g_ascii_strcasecmp(tok, "currentcolor") == 0) {
            if (color) {
                ok = FALSE;
                continue;
            }
            color = g_string_new(NULL);
            if (text_is_ident(tok)) {
                char *lower = g_ascii_strdown(tok, -1);
                g_string_append(color, lower);
                g_free(lower);
            } else {
                ns_css_append_color(color, r, g, b, a);
            }
            if (n_lengths) lengths_closed = TRUE;
            continue;
        }
        if (lengths_closed || n_lengths >= (is_text ? 3 : 4)) {
            ok = FALSE;
            continue;
        }
        if (lengths->len) g_string_append_c(lengths, ' ');
        if (!shadow_length_token(tok, n_lengths != 2, lengths)) ok = FALSE;
        n_lengths++;
    }
    if (n_lengths < 2) ok = FALSE;
    if (ok) {
        if (color) {
            g_string_append(out, color->str);
            g_string_append_c(out, ' ');
        }
        g_string_append(out, lengths->str);
        if (inset) g_string_append(out, " inset");
    }
    if (color) g_string_free(color, TRUE);
    g_string_free(lengths, TRUE);
    for (int i = 0; i < n; i++) g_free(tokens[i]);
    return ok;
}

/* Serializes a box-shadow/text-shadow specified value layer by layer; NULL if invalid. */
static char *
shadow_specified_canonical(const char *value, gboolean is_text)
{
    if (!value) return NULL;
    while (*value && ns_is_ascii_ws(*value)) value++;
    if (!*value || strstr(value, "var(")) return NULL;
    if (g_ascii_strcasecmp(value, "none") == 0) return g_strdup("none");
    GString *out = g_string_new(NULL);
    const char *end = value + strlen(value);
    const char *p = value;
    gboolean ok = TRUE;
    while (ok && p < end) {
        char term = 0;
        const char *seg_end = css_scan_until(p, end, ",", &term);
        char *layer = css_trim_dup_range(p, seg_end);
        if (out->len) g_string_append(out, ", ");
        ok = shadow_specified_one(layer, is_text, out);
        g_free(layer);
        p = term == ',' ? seg_end + 1 : seg_end;
        if (term == ',' && p >= end) ok = FALSE;
    }
    if (!ok) {
        g_string_free(out, TRUE);
        return NULL;
    }
    return g_string_free(out, FALSE);
}

/* Parses one shadow layer into offsets, blur, spread, color and inset; em/rem kept apart. */
static gboolean
parse_one_shadow(const char *text, ns_css_shadow *out)
{
    char *tokens[8] = {0};
    int n = split_ws_limit(text, tokens, G_N_ELEMENTS(tokens));
    gboolean inset = FALSE;
    guint8 cr = 0, cg = 0, cb = 0, ca = 255;
    gboolean has_color = FALSE;
    double lens[4] = {0}, ems[4] = {0}, rems[4] = {0};
    int n_lens = 0;
    for (int i = 0; i < n; i++) {
        const char *tok = tokens[i];
        guint8 r, g, b, a;
        double num;
        ns_css_unit u;
        if (parse_color(tok, &r, &g, &b, &a)) {
            cr = r; cg = g; cb = b; ca = a; has_color = TRUE;
        } else if (n_lens < 4 && parse_length(tok, &num, &u)) {
            if (u == NS_CSS_UNIT_EM) { ems[n_lens] = num; num = 0; }
            else if (u == NS_CSS_UNIT_REM) { rems[n_lens] = num; num = 0; }
            else if (u == NS_CSS_UNIT_EX || u == NS_CSS_UNIT_CH) num *= 8;
            else if (u == NS_CSS_UNIT_CAP) num *= 11.2;
            else if (u == NS_CSS_UNIT_IC) num *= 16;
            lens[n_lens++] = num;
        } else if (n_lens < 4 && g_ascii_strncasecmp(tok, "calc(", 5) == 0) {
            ns_css_value *cv = parse_calc(tok);
            if (cv && cv->kind == NS_CSS_V_CALC) {
                lens[n_lens] = cv->u.calc.px;
                ems[n_lens] = cv->u.calc.em;
                rems[n_lens] = cv->u.calc.rem;
                n_lens++;
            }
            ns_css_value_free(cv);
        } else if (g_ascii_strcasecmp(tok, "inset") == 0) {
            inset = TRUE;
        }
    }
    for (int i = 0; i < n; i++) g_free(tokens[i]);
    if (n_lens < 2) return FALSE;
    memset(out, 0, sizeof *out);
    out->x = lens[0];
    out->y = lens[1];
    out->blur   = n_lens >= 3 ? CLAMP(lens[2], 0.0, 1000.0) : 0;
    out->spread = n_lens >= 4 ? CLAMP(lens[3], -1000.0, 1000.0) : 0;
    for (int k = 0; k < 4; k++) {
        out->em[k] = ems[k];
        out->rem[k] = rems[k];
    }
    out->r = cr; out->g = cg; out->b = cb;
    out->a = ca;
    out->currentcolor = !has_color;
    out->inset = inset;
    return TRUE;
}

/* Parses a comma-separated shadow list into a value, skipping invalid layers. */
static ns_css_value *
parse_box_shadow(const char *text)
{
    while (*text && ns_is_ascii_ws(*text)) text++;
    if (!*text) return NULL;
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_SHADOW;
    char *copy = g_strdup(text);
    int depth = 0;
    char *seg = copy;
    for (char *q = copy; ; q++) {
        if (*q == '(') depth++;
        else if (*q == ')') { if (depth > 0) depth--; }
        gboolean at_end = (*q == '\0');
        if ((*q == ',' && depth == 0) || at_end) {
            char saved = *q;
            *q = '\0';
            if (v->u.shadow.n < NS_CSS_SHADOWS_MAX) {
                if (parse_one_shadow(seg, &v->u.shadow.s[v->u.shadow.n]))
                    v->u.shadow.n++;
            }
            if (at_end) break;
            *q = saved;
            seg = q + 1;
        }
    }
    g_free(copy);
    if (v->u.shadow.n == 0) { g_free(v); return NULL; }
    return v;
}

static gboolean position_is_h_edge(const char *t);
static gboolean position_is_v_edge(const char *t);
static gboolean math_text_mixes_angle_and_length(const char *t);
static void position_split(const char *text, char **out_x, char **out_y);
static double parse_angle_deg(const char *s);

typedef struct ns_gradient_parse {
    ns_css_gradient gr;
    char *angle_text;
    char *size_text;
    char *position_text;
    gboolean interp_explicit;
    gboolean all_legacy;
    GPtrArray *stop_texts;
} ns_gradient_parse;

static void
gradient_parse_clear(ns_gradient_parse *gp)
{
    g_free(gp->angle_text);
    g_free(gp->size_text);
    g_free(gp->position_text);
    if (gp->stop_texts) g_ptr_array_free(gp->stop_texts, TRUE);
    memset(gp, 0, sizeof *gp);
}

static gboolean
token_eq(const char *t, const char *kw)
{
    return g_ascii_strcasecmp(t, kw) == 0;
}

static gboolean
token_is_math_fn(const char *t)
{
    return g_ascii_strncasecmp(t, "calc(", 5) == 0 ||
           g_ascii_strncasecmp(t, "min(", 4) == 0 ||
           g_ascii_strncasecmp(t, "max(", 4) == 0 ||
           g_ascii_strncasecmp(t, "clamp(", 6) == 0;
}

static gboolean
text_is_math_fn(const char *t)
{
    static const char *const fns[] = {
        "calc(", "min(", "max(", "clamp(", "round(", "mod(", "rem(",
        "abs(", "hypot(", "pow(", "sqrt(", "sin(", "cos(", "tan(",
        "sign(", "exp(", "log(", "progress(", "atan2(", "atan(", "asin(",
        "acos(",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(fns); i++)
        if (g_ascii_strncasecmp(t, fns[i], strlen(fns[i])) == 0) return TRUE;
    return FALSE;
}

/* Reports whether a token is a length, percentage, zero or length-valued math function. */
static gboolean
token_is_length_pct(const char *t)
{
    if (token_is_math_fn(t)) {
        ns_css_value *cv = parse_calc(t);
        if (!cv) return FALSE;
        gboolean ok = cv->kind == NS_CSS_V_CALC || cv->kind == NS_CSS_V_LENGTH;
        ns_css_value_free(cv);
        return ok;
    }
    double v; ns_css_unit u;
    if (!parse_length(t, &v, &u)) return FALSE;
    return u != NS_CSS_UNIT_NUMBER || v == 0;
}

/* Reports whether a token is an angle, unitless zero, or math fn mentioning angle units. */
static gboolean
token_is_angle(const char *t)
{
    if (token_is_math_fn(t)) {
        char *lower = g_ascii_strdown(t, -1);
        gboolean ok = strstr(lower, "deg") || strstr(lower, "rad") ||
                      strstr(lower, "turn") || strstr(lower, "grad");
        g_free(lower);
        return ok;
    }
    if (strcmp(t, "0") == 0) return TRUE;
    char *end = NULL;
    double v = g_ascii_strtod(t, &end);
    (void)v;
    if (!end || end == t) return FALSE;
    return token_eq(end, "deg") || token_eq(end, "grad") ||
           token_eq(end, "rad") || token_eq(end, "turn");
}

/* Serializes a gradient stop color: legacy colors resolved to rgb(), others kept as text. */
static char *
gradient_stop_color_specified(const char *tok)
{
    guint8 r, g, b, a;
    gboolean legacy_syntax = tok[0] == '#' ||
        g_ascii_strncasecmp(tok, "rgb(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "rgba(", 5) == 0 ||
        g_ascii_strncasecmp(tok, "hsl(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "hsla(", 5) == 0;
    if (legacy_syntax && parse_color(tok, &r, &g, &b, &a)) {
        ns_css_value cv = { .kind = NS_CSS_V_COLOR };
        cv.u.color.r = r;
        cv.u.color.g = g;
        cv.u.color.b = b;
        cv.u.color.a = a;
        return ns_css_value_serialize(&cv);
    }
    if (strchr(tok, '(')) return g_strdup(tok);
    return g_ascii_strdown(tok, -1);
}

/* Reports whether color text uses legacy syntax (hex, keyword, rgb/rgba/hsl/hsla). */
static gboolean
color_text_is_legacy(const char *t)
{
    if (t[0] == '#') return TRUE;
    if (!strchr(t, '(')) return TRUE;
    return g_ascii_strncasecmp(t, "rgb(", 4) == 0 ||
           g_ascii_strncasecmp(t, "rgba(", 5) == 0 ||
           g_ascii_strncasecmp(t, "hsl(", 4) == 0 ||
           g_ascii_strncasecmp(t, "hsla(", 5) == 0;
}

/* Parses a gradient "in <space> [<hue> hue]" method into out; returns tokens consumed. */
static int
gradient_interp_parse(char **tok, int n, char out[NS_CSS_GRADIENT_INTERP_MAX])
{
    if (n < 1) return 0;
    static const char *rect[] = {
        "srgb", "srgb-linear", "display-p3", "a98-rgb", "prophoto-rgb",
        "rec2020", "lab", "oklab", "xyz", "xyz-d50", "xyz-d65",
    };
    static const char *polar[] = { "hsl", "hwb", "lch", "oklch" };
    char *space = g_ascii_strdown(tok[0], -1);
    gboolean is_rect = FALSE, is_polar = FALSE;
    for (gsize i = 0; i < G_N_ELEMENTS(rect); i++)
        if (strcmp(space, rect[i]) == 0) is_rect = TRUE;
    for (gsize i = 0; i < G_N_ELEMENTS(polar); i++)
        if (strcmp(space, polar[i]) == 0) is_polar = TRUE;
    if (!is_rect && !is_polar) { g_free(space); return 0; }
    if (strcmp(space, "xyz") == 0) { g_free(space); space = g_strdup("xyz-d65"); }
    int used = 1;
    const char *hue = NULL;
    if (is_polar && n >= 3 && token_eq(tok[2], "hue")) {
        if (token_eq(tok[1], "shorter")) hue = NULL;
        else if (token_eq(tok[1], "longer")) hue = "longer";
        else if (token_eq(tok[1], "increasing")) hue = "increasing";
        else if (token_eq(tok[1], "decreasing")) hue = "decreasing";
        else { g_free(space); return 0; }
        used = 3;
    } else if (n >= 2 && (token_eq(tok[1], "hue") || token_eq(tok[1], "shorter") ||
                          token_eq(tok[1], "longer") || token_eq(tok[1], "increasing") ||
                          token_eq(tok[1], "decreasing"))) {
        g_free(space);
        return 0;
    }
    if (hue) g_snprintf(out, NS_CSS_GRADIENT_INTERP_MAX, "%s %s hue", space, hue);
    else g_strlcpy(out, space, NS_CSS_GRADIENT_INTERP_MAX);
    g_free(space);
    return used;
}

/* Canonicalizes a 1-4 token <position> into x-then-y order; NULL if invalid. Caller frees. */
static char *
position_canonical_ex(const char *text, gboolean expand_single,
                      gboolean allow_three)
{
    char *tok[8] = {0};
    int m = split_ws_paren(text, tok, 8);
    char *spec = NULL;
    if (m == 0 || m > 4 || (m == 3 && !allow_three)) goto done;
    gboolean h0 = position_is_h_edge(tok[0]), v0 = position_is_v_edge(tok[0]);
    gboolean c0 = token_eq(tok[0], "center");
    if (m == 1) {
        if (!(h0 || v0 || c0 || token_is_length_pct(tok[0]))) goto done;
        if (!expand_single) spec = g_strdup(tok[0]);
        else if (v0) spec = g_strdup_printf("center %s", tok[0]);
        else spec = g_strdup_printf("%s center", tok[0]);
    } else if (m == 3) {
        gboolean off_after_first = token_is_length_pct(tok[1]);
        const char *ek = off_after_first ? tok[0] : tok[1];
        const char *off = off_after_first ? tok[1] : tok[2];
        const char *other = off_after_first ? tok[2] : tok[0];
        gboolean eh = position_is_h_edge(ek), ev = position_is_v_edge(ek);
        gboolean oh = position_is_h_edge(other), ov = position_is_v_edge(other);
        gboolean oc = token_eq(other, "center");
        if (!(eh || ev) || !token_is_length_pct(off) || !(oh || ov || oc))
            goto done;
        if ((eh && oh) || (ev && ov)) goto done;
        if (eh) spec = g_strdup_printf("%s %s %s", ek, off, other);
        else spec = g_strdup_printf("%s %s %s", other, ek, off);
    } else if (m == 2) {
        gboolean h1 = position_is_h_edge(tok[1]), v1 = position_is_v_edge(tok[1]);
        gboolean c1 = token_eq(tok[1], "center");
        gboolean k0 = h0 || v0 || c0, k1 = h1 || v1 || c1;
        if (k0 && k1) {
            if ((h0 && h1) || (v0 && v1)) goto done;
            if ((v0 && (h1 || c1) && !(c0 && c1)) || (c0 && h1))
                spec = g_strdup_printf("%s %s", tok[1], tok[0]);
            else
                spec = g_strdup_printf("%s %s", tok[0], tok[1]);
        } else if (k0 && !k1) {
            if (!v0 && token_is_length_pct(tok[1]))
                spec = g_strdup_printf("%s %s", tok[0], tok[1]);
        } else if (!k0 && k1) {
            if (!h1 && token_is_length_pct(tok[0]))
                spec = g_strdup_printf("%s %s", tok[0], tok[1]);
        } else if (token_is_length_pct(tok[0]) && token_is_length_pct(tok[1])) {
            spec = g_strdup_printf("%s %s", tok[0], tok[1]);
        }
    } else {
        gboolean h2 = position_is_h_edge(tok[2]), v2 = position_is_v_edge(tok[2]);
        if (!token_is_length_pct(tok[1]) || !token_is_length_pct(tok[3]))
            goto done;
        if (h0 && v2)
            spec = g_strdup_printf("%s %s %s %s", tok[0], tok[1], tok[2], tok[3]);
        else if (v0 && h2)
            spec = g_strdup_printf("%s %s %s %s", tok[2], tok[3], tok[0], tok[1]);
    }
done:
    for (int k = 0; k < m; k++) g_free(tok[k]);
    return spec;
}

static char *
position_canonical(const char *text)
{
    return position_canonical_ex(text, FALSE, FALSE);
}

/* Parses a radial/conic "at <position>" into the gradient center; returns tokens consumed. */
static int
gradient_position_parse(char **tok, int n, ns_gradient_parse *gp)
{
    int m = 0;
    while (m < n && m < 4 && !token_eq(tok[m], "in")) m++;
    if (m == 0) return 0;
    GString *joined = g_string_new(NULL);
    for (int k = 0; k < m; k++) {
        if (k) g_string_append_c(joined, ' ');
        g_string_append(joined, tok[k]);
    }
    char *spec = position_canonical(joined->str);
    g_string_free(joined, TRUE);
    if (!spec) return 0;
    char *xs = NULL, *ys = NULL;
    position_split(spec, &xs, &ys);
    double px = 0, pct = 0;
    if (resolve_to_px_pct(xs, strlen(xs), &px, &pct)) {
        gp->gr.center_x = pct / 100.0;
        gp->gr.center_x_px = px;
    }
    if (resolve_to_px_pct(ys, strlen(ys), &px, &pct)) {
        gp->gr.center_y = pct / 100.0;
        gp->gr.center_y_px = px;
    }
    g_free(xs);
    g_free(ys);
    gp->gr.has_center = !(gp->gr.center_x == 0.5 && gp->gr.center_x_px == 0 &&
                          gp->gr.center_y == 0.5 && gp->gr.center_y_px == 0);
    g_free(gp->position_text);
    gp->position_text = spec;
    return m;
}

/* Parses a gradient's first argument: direction/angle, shape, size, at, from and in parts. */
static gboolean
gradient_parse_prelude(ns_gradient_parse *gp, char **tok, int n)
{
    ns_css_gradient *gr = &gp->gr;
    gboolean seen_dir = FALSE, seen_shape = FALSE, seen_size = FALSE;
    gboolean seen_at = FALSE, seen_in = FALSE, seen_from = FALSE;
    int explicit_lengths = 0;
    int i = 0;
    while (i < n) {
        const char *t = tok[i];
        if (token_eq(t, "in")) {
            if (seen_in) return FALSE;
            int used = gradient_interp_parse(tok + i + 1, n - i - 1, gr->interp);
            if (!used) return FALSE;
            seen_in = TRUE;
            gp->interp_explicit = TRUE;
            i += 1 + used;
            continue;
        }
        if (!gr->radial && !gr->conic) {
            if (token_eq(t, "to")) {
                if (seen_dir) return FALSE;
                int sides = 0;
                for (int k = i + 1; k < n && k <= i + 2; k++) {
                    int bit = 0;
                    if (token_eq(tok[k], "top")) bit = NS_CSS_GRADIENT_TO_TOP;
                    else if (token_eq(tok[k], "bottom")) bit = NS_CSS_GRADIENT_TO_BOTTOM;
                    else if (token_eq(tok[k], "left")) bit = NS_CSS_GRADIENT_TO_LEFT;
                    else if (token_eq(tok[k], "right")) bit = NS_CSS_GRADIENT_TO_RIGHT;
                    if (!bit) break;
                    if (gr->to_side & bit) return FALSE;
                    gr->to_side |= bit;
                    sides++;
                }
                if (!sides) return FALSE;
                if ((gr->to_side & (NS_CSS_GRADIENT_TO_TOP | NS_CSS_GRADIENT_TO_BOTTOM)) ==
                    (NS_CSS_GRADIENT_TO_TOP | NS_CSS_GRADIENT_TO_BOTTOM))
                    return FALSE;
                if ((gr->to_side & (NS_CSS_GRADIENT_TO_LEFT | NS_CSS_GRADIENT_TO_RIGHT)) ==
                    (NS_CSS_GRADIENT_TO_LEFT | NS_CSS_GRADIENT_TO_RIGHT))
                    return FALSE;
                seen_dir = TRUE;
                i += 1 + sides;
                continue;
            }
            if (token_is_angle(t)) {
                if (seen_dir) return FALSE;
                gr->has_angle = TRUE;
                gr->angle_deg = parse_angle_deg(t);
                g_free(gp->angle_text);
                gp->angle_text = g_ascii_strdown(t, -1);
                seen_dir = TRUE;
                i++;
                continue;
            }
            return FALSE;
        }
        if (token_eq(t, "at")) {
            if (seen_at) return FALSE;
            int used = gradient_position_parse(tok + i + 1, n - i - 1, gp);
            if (!used) return FALSE;
            seen_at = TRUE;
            i += 1 + used;
            continue;
        }
        if (gr->conic) {
            if (token_eq(t, "from")) {
                if (seen_from || i + 1 >= n || !token_is_angle(tok[i + 1]) ||
                    strchr(tok[i + 1], '%') ||
                    math_text_mixes_angle_and_length(tok[i + 1]))
                    return FALSE;
                gr->has_from = TRUE;
                gr->from_deg = parse_angle_deg(tok[i + 1]);
                g_free(gp->angle_text);
                gp->angle_text = g_ascii_strdown(tok[i + 1], -1);
                seen_from = TRUE;
                i += 2;
                continue;
            }
            return FALSE;
        }
        if (token_eq(t, "circle") || token_eq(t, "ellipse")) {
            if (seen_shape) return FALSE;
            gr->circle = token_eq(t, "circle");
            seen_shape = TRUE;
            i++;
            continue;
        }
        static const struct { const char *kw; ns_css_gradient_size size; } sizes[] = {
            { "closest-side", NS_CSS_GRADIENT_CLOSEST_SIDE },
            { "farthest-side", NS_CSS_GRADIENT_FARTHEST_SIDE },
            { "closest-corner", NS_CSS_GRADIENT_CLOSEST_CORNER },
            { "farthest-corner", NS_CSS_GRADIENT_FARTHEST_CORNER },
        };
        gboolean size_kw = FALSE;
        for (gsize k = 0; k < G_N_ELEMENTS(sizes); k++) {
            if (!token_eq(t, sizes[k].kw)) continue;
            if (seen_size) return FALSE;
            gr->size = sizes[k].size;
            seen_size = TRUE;
            size_kw = TRUE;
        }
        if (size_kw) { i++; continue; }
        if (token_is_length_pct(t)) {
            if (seen_size) return FALSE;
            int j = 0;
            double px[2] = { 0, 0 }, pct[2] = { 0, 0 };
            while (i + j < n && j < 2 && token_is_length_pct(tok[i + j])) {
                resolve_to_px_pct(tok[i + j], strlen(tok[i + j]), &px[j], &pct[j]);
                if (px[j] < 0 || pct[j] < 0) return FALSE;
                j++;
            }
            if (i + j < n && token_is_length_pct(tok[i + j])) return FALSE;
            gr->size = NS_CSS_GRADIENT_EXPLICIT_SIZE;
            gr->size_x = px[0];
            gr->size_x_pct = pct[0];
            gr->size_y = j == 2 ? px[1] : px[0];
            gr->size_y_pct = j == 2 ? pct[1] : pct[0];
            explicit_lengths = j;
            if (j == 1 && strchr(tok[i], '%')) return FALSE;
            g_free(gp->size_text);
            gp->size_text = j == 2 ? g_strdup_printf("%s %s", tok[i], tok[i + 1])
                                   : g_strdup(tok[i]);
            seen_size = TRUE;
            i += j;
            continue;
        }
        return FALSE;
    }
    if (explicit_lengths) {
        if (seen_shape && gr->circle != (explicit_lengths == 1)) return FALSE;
        gr->circle = explicit_lengths == 1;
    }
    return TRUE;
}

/* Reports whether math text contains a number followed by one of the given unit suffixes. */
static gboolean
math_text_has_unit(const char *t, const char *const *units, gsize n_units)
{
    char *lower = g_ascii_strdown(t, -1);
    gboolean found = FALSE;
    for (const char *p = lower; *p && !found; p++) {
        if (!g_ascii_isdigit((guchar)*p) && *p != '.') continue;
        while (g_ascii_isdigit((guchar)*p) || *p == '.') p++;
        for (gsize k = 0; k < n_units && !found; k++) {
            gsize len = strlen(units[k]);
            if (g_ascii_strncasecmp(p, units[k], len) == 0 &&
                !g_ascii_isalpha((guchar)p[len]))
                found = TRUE;
        }
        if (!*p) break;
    }
    g_free(lower);
    return found;
}

/* Reports whether a math expression mixes angle and length units (invalid for angles). */
static gboolean
math_text_mixes_angle_and_length(const char *t)
{
    static const char *const angles[] = { "deg", "grad", "rad", "turn" };
    static const char *const lengths[] = { "px", "em", "rem", "vw", "vh",
                                           "vmin", "vmax", "ch", "ex", "cm",
                                           "mm", "in", "pt", "pc", "lh" };
    return math_text_has_unit(t, angles, G_N_ELEMENTS(angles)) &&
           math_text_has_unit(t, lengths, G_N_ELEMENTS(lengths));
}

/* Reorders a conic stop calc(<angle> + <pct>) to calc(<pct> + <angle>) for serialization. */
static char *
conic_calc_canonical(const char *t)
{
    if (g_ascii_strncasecmp(t, "calc(", 5) != 0) return g_strdup(t);
    gsize len = strlen(t);
    if (len < 7 || t[len - 1] != ')') return g_strdup(t);
    char *inner = g_strndup(t + 5, len - 6);
    char *plus = strstr(inner, " + ");
    char *out = NULL;
    if (plus && !strchr(inner, '(')) {
        *plus = '\0';
        char *a = g_strstrip(inner), *b = g_strstrip(plus + 3);
        gboolean a_angle = !strchr(a, '%'), b_pct = strchr(b, '%') != NULL;
        if (a_angle && b_pct) out = g_strdup_printf("calc(%s + %s)", b, a);
    }
    g_free(inner);
    return out ? out : g_strdup(t);
}

/* Parses a stop or hint position: lengths/percents, or angles/percents for conic gradients. */
static gboolean
gradient_stop_pos_parse(const char *t, gboolean conic, ns_css_gradient_stop *st)
{
    st->pos = 0;
    st->pos_px = 0;
    st->pos_is_angle = FALSE;
    if (token_is_math_fn(t)) {
        static const char *const angles[] = { "deg", "grad", "rad", "turn" };
        static const char *const lengths[] = { "px", "em", "rem", "vw", "vh",
                                               "vmin", "vmax", "ch", "ex",
                                               "cm", "mm", "in", "pt", "pc",
                                               "lh" };
        gboolean has_angle = math_text_has_unit(t, angles, G_N_ELEMENTS(angles));
        gboolean has_len = math_text_has_unit(t, lengths, G_N_ELEMENTS(lengths));
        if (conic ? has_len : has_angle) return FALSE;
        if (conic && !has_angle && !strchr(t, '%')) return FALSE;
    }
    if (conic) {
        if (token_is_angle(t)) {
            st->pos = parse_angle_deg(t) / 360.0;
            st->pos_is_angle = TRUE;
            st->has_pos = TRUE;
            return TRUE;
        }
        if (token_is_math_fn(t)) {
            double px = 0, pct = 0;
            if (!resolve_to_px_pct(t, strlen(t), &px, &pct)) return FALSE;
            st->pos = pct / 100.0;
            st->has_pos = TRUE;
            return TRUE;
        }
        double v; ns_css_unit u;
        if (parse_length(t, &v, &u) && u == NS_CSS_UNIT_PERCENT) {
            st->pos = v / 100.0;
            st->has_pos = TRUE;
            return TRUE;
        }
        return FALSE;
    }
    if (!token_is_length_pct(t)) return FALSE;
    double px = 0, pct = 0;
    resolve_to_px_pct(t, strlen(t), &px, &pct);
    st->pos = pct / 100.0;
    st->pos_px = px;
    st->has_pos = TRUE;
    return TRUE;
}

/* Parses one color stop (with up to two positions) or a hint, optionally keeping its text. */
static gboolean
gradient_stop_parse(ns_gradient_parse *gp, const char *seg, gboolean *is_hint)
{
    char *tok[8] = {0};
    int n = split_ws_paren(seg, tok, 8);
    gboolean ok = FALSE;
    gboolean conic = gp->gr.conic;
    ns_css_gradient *gr = &gp->gr;
    *is_hint = FALSE;
    if (n < 1) goto done;
    guint8 r, g, b, a;
    if (parse_color(tok[0], &r, &g, &b, &a)) {
        if (n > 3) goto done;
        ns_css_gradient_stop first = { .r = r, .g = g, .b = b, .a = a };
        ns_css_gradient_stop second = first;
        if (n >= 2 && !gradient_stop_pos_parse(tok[1], conic, &first)) goto done;
        if (n == 3 && !gradient_stop_pos_parse(tok[2], conic, &second)) goto done;
        if (!color_text_is_legacy(tok[0])) gp->all_legacy = FALSE;
        if (gr->n_stops < NS_CSS_GRADIENT_STOPS_MAX)
            gr->stops[gr->n_stops++] = first;
        if (n == 3 && gr->n_stops < NS_CSS_GRADIENT_STOPS_MAX) {
            second.pair_with_prev = TRUE;
            gr->stops[gr->n_stops++] = second;
        }
        if (gp->stop_texts) {
            GString *s = g_string_new(NULL);
            char *color_text = gradient_stop_color_specified(tok[0]);
            g_string_append(s, color_text);
            g_free(color_text);
            for (int k = 1; k < n; k++) {
                g_string_append_c(s, ' ');
                char *pos_text = conic ? conic_calc_canonical(tok[k]) : g_strdup(tok[k]);
                g_string_append(s, pos_text);
                g_free(pos_text);
            }
            g_ptr_array_add(gp->stop_texts, g_string_free(s, FALSE));
        }
        ok = TRUE;
        goto done;
    }
    if (n != 1) goto done;
    ns_css_gradient_stop hint = { .is_hint = TRUE };
    if (!gradient_stop_pos_parse(tok[0], conic, &hint)) goto done;
    if (gr->n_stops < NS_CSS_GRADIENT_STOPS_MAX)
        gr->stops[gr->n_stops++] = hint;
    if (gp->stop_texts)
        g_ptr_array_add(gp->stop_texts,
                        conic ? conic_calc_canonical(tok[0]) : g_strdup(tok[0]));
    *is_hint = TRUE;
    ok = TRUE;
done:
    for (int k = 0; k < n; k++) g_free(tok[k]);
    return ok;
}

/* Fixes up stop positions per CSS Images: clamps order, spreads unpositioned stops evenly. */
static void
gradient_finish_stops(ns_css_gradient *gr)
{
    int n = gr->n_stops;
    if (n == 0) return;
    ns_css_gradient_stop *st = gr->stops;
    gboolean fixed[NS_CSS_GRADIENT_STOPS_MAX] = { FALSE };
    for (int i = 0; i < n; i++) fixed[i] = st[i].has_pos;
    if (!fixed[0]) { st[0].pos = 0; st[0].pos_px = 0; fixed[0] = TRUE; }
    if (!fixed[n - 1]) { st[n - 1].pos = 1; st[n - 1].pos_px = 0; fixed[n - 1] = TRUE; }
    for (int i = 1; i < n; i++)
        if (fixed[i] && fixed[i - 1] && st[i].pos_px == 0 &&
            st[i - 1].pos_px == 0 && st[i].pos < st[i - 1].pos)
            st[i].pos = st[i - 1].pos;
    for (int i = 0; i < n; ) {
        if (fixed[i]) { i++; continue; }
        int j = i;
        while (j < n && !fixed[j]) j++;
        double lo = st[i - 1].pos, hi = st[j].pos;
        for (int k = i; k < j; k++) {
            st[k].pos = lo + (hi - lo) * (double)(k - i + 1) / (double)(j - i + 1);
            st[k].pos_px = 0;
        }
        i = j;
    }
    for (int i = 1; i + 1 < n; i++) {
        if (!st[i].is_hint) continue;
        st[i].r = (guint8)((st[i - 1].r + st[i + 1].r) / 2);
        st[i].g = (guint8)((st[i - 1].g + st[i + 1].g) / 2);
        st[i].b = (guint8)((st[i - 1].b + st[i + 1].b) / 2);
        st[i].a = (guint8)((st[i - 1].a + st[i + 1].a) / 2);
    }
}

/* Parses linear/radial/conic gradient text, optionally recording specified-value texts. */
static gboolean
gradient_parse(const char *text, ns_gradient_parse *gp, const char **out_end,
               gboolean keep_texts)
{
    memset(gp, 0, sizeof *gp);
    const char *p = text;
    while (*p && ns_is_ascii_ws(*p)) p++;
    if (g_ascii_strncasecmp(p, "repeating-", 10) == 0) {
        gp->gr.repeating = TRUE;
        p += 10;
    }
    if (g_ascii_strncasecmp(p, "linear-gradient", 15) == 0) p += 15;
    else if (g_ascii_strncasecmp(p, "radial-gradient", 15) == 0) { gp->gr.radial = TRUE; p += 15; }
    else if (g_ascii_strncasecmp(p, "conic-gradient", 14) == 0) { gp->gr.conic = TRUE; p += 14; }
    else return FALSE;
    while (*p && ns_is_ascii_ws(*p)) p++;
    if (*p != '(') return FALSE;
    p++;
    const char *body_start = p;
    int depth = 0;
    const char *end = NULL;
    for (const char *q = p; *q; q++) {
        if (*q == '(') depth++;
        else if (*q == ')') {
            if (depth == 0) { end = q; break; }
            depth--;
        }
    }
    if (!end) return FALSE;
    if (out_end) *out_end = end + 1;
    gp->gr.center_x = 0.5;
    gp->gr.center_y = 0.5;
    gp->all_legacy = TRUE;
    if (keep_texts) gp->stop_texts = g_ptr_array_new_with_free_func(g_free);

    GPtrArray *parts = g_ptr_array_new_with_free_func(g_free);
    const char *seg = body_start;
    depth = 0;
    for (const char *q = body_start; ; q++) {
        if (*q == '(') depth++;
        else if (*q == ')' && depth > 0) depth--;
        if ((*q == ',' && depth == 0) || q == end) {
            char *piece = g_strndup(seg, (gsize)(q - seg));
            g_strstrip(piece);
            g_ptr_array_add(parts, piece);
            if (q == end) break;
            seg = q + 1;
        }
    }
    gboolean ok = TRUE;
    for (guint i = 0; i < parts->len && ok; i++)
        if (!*(char *)parts->pdata[i]) ok = FALSE;
    guint start = 0;
    if (ok && parts->len > 0) {
        char *tok[24] = {0};
        int n = split_ws_paren(parts->pdata[0], tok, 24);
        ns_css_gradient saved = gp->gr;
        gboolean saved_explicit = gp->interp_explicit;
        if (n > 0 && gradient_parse_prelude(gp, tok, n)) {
            start = 1;
        } else {
            gp->gr = saved;
            gp->interp_explicit = saved_explicit;
            g_free(gp->angle_text); gp->angle_text = NULL;
            g_free(gp->size_text); gp->size_text = NULL;
            g_free(gp->position_text); gp->position_text = NULL;
        }
        for (int k = 0; k < n; k++) g_free(tok[k]);
    }
    if (ok && start >= parts->len) ok = FALSE;
    gboolean prev_hint = TRUE;
    int color_stops = 0;
    for (guint i = start; i < parts->len && ok; i++) {
        gboolean hint = FALSE;
        if (!gradient_stop_parse(gp, parts->pdata[i], &hint)) { ok = FALSE; break; }
        if (hint && prev_hint) { ok = FALSE; break; }
        if (!hint) color_stops++;
        prev_hint = hint;
    }
    if (ok && (prev_hint || color_stops < 1)) ok = FALSE;
    g_ptr_array_free(parts, TRUE);
    if (!ok) {
        gradient_parse_clear(gp);
        return FALSE;
    }
    if (gp->interp_explicit) {
        const char *def = gp->all_legacy ? "srgb" : "oklab";
        if (strcmp(gp->gr.interp, def) == 0) gp->gr.interp[0] = '\0';
    }
    gradient_finish_stops(&gp->gr);
    return TRUE;
}

/* Serializes a stop position as deg, %, px or calc(% +/- px). */
static void
gradient_append_stop_pos(GString *s, const ns_css_gradient_stop *st)
{
    if (st->pos_is_angle) {
        g_string_append_printf(s, "%gdeg", st->pos * 360.0);
    } else if (st->pos_px == 0) {
        g_string_append_printf(s, "%g%%", st->pos * 100.0);
    } else if (st->pos == 0) {
        g_string_append_printf(s, "%gpx", st->pos_px);
    } else {
        g_string_append_printf(s, "calc(%g%% %c %gpx)", st->pos * 100.0,
                               st->pos_px < 0 ? '-' : '+', fabs(st->pos_px));
    }
}

/* Serializes a gradient coordinate as %, px or calc(% +/- px). */
static void
gradient_append_center_coord(GString *s, double frac, double px)
{
    if (px == 0) g_string_append_printf(s, "%g%%", frac * 100.0);
    else if (frac == 0) g_string_append_printf(s, "%gpx", px);
    else g_string_append_printf(s, "calc(%g%% %c %gpx)", frac * 100.0,
                                px < 0 ? '-' : '+', fabs(px));
}

static void
gradient_append_to_side(GString *s, int to_side)
{
    g_string_append(s, "to");
    if (to_side & NS_CSS_GRADIENT_TO_LEFT) g_string_append(s, " left");
    if (to_side & NS_CSS_GRADIENT_TO_RIGHT) g_string_append(s, " right");
    if (to_side & NS_CSS_GRADIENT_TO_TOP) g_string_append(s, " top");
    if (to_side & NS_CSS_GRADIENT_TO_BOTTOM) g_string_append(s, " bottom");
}

static void
gradient_append_name(GString *s, const ns_css_gradient *gr)
{
    if (gr->repeating) g_string_append(s, "repeating-");
    g_string_append(s, gr->conic ? "conic-gradient(" :
                       gr->radial ? "radial-gradient(" : "linear-gradient(");
}

static void
gradient_append_prelude_part(GString *prelude, const char *part)
{
    if (prelude->len) g_string_append_c(prelude, ' ');
    g_string_append(prelude, part);
}

/* Serializes a parsed gradient's computed value, omitting default direction and center. */
static void
gradient_serialize_computed(GString *s, const ns_css_gradient *gr)
{
    gradient_append_name(s, gr);
    GString *pre = g_string_new(NULL);
    if (gr->conic) {
        if (gr->has_from) {
            char *t = g_strdup_printf("from %gdeg", gr->from_deg);
            gradient_append_prelude_part(pre, t);
            g_free(t);
        }
    } else if (gr->radial) {
        if (gr->size == NS_CSS_GRADIENT_EXPLICIT_SIZE) {
            GString *sz = g_string_new(NULL);
            gradient_append_center_coord(sz, gr->size_x_pct / 100.0, gr->size_x);
            if (!gr->circle) {
                g_string_append_c(sz, ' ');
                gradient_append_center_coord(sz, gr->size_y_pct / 100.0, gr->size_y);
            }
            gradient_append_prelude_part(pre, sz->str);
            g_string_free(sz, TRUE);
        } else {
            if (gr->circle) gradient_append_prelude_part(pre, "circle");
            static const char *kws[] = { NULL, "closest-side", "farthest-side",
                                         "closest-corner", NULL };
            if (kws[gr->size]) gradient_append_prelude_part(pre, kws[gr->size]);
        }
    } else {
        if (gr->has_angle) {
            char *t = g_strdup_printf("%gdeg", gr->angle_deg);
            gradient_append_prelude_part(pre, t);
            g_free(t);
        } else if (gr->to_side && gr->to_side != NS_CSS_GRADIENT_TO_BOTTOM) {
            GString *t = g_string_new(NULL);
            gradient_append_to_side(t, gr->to_side);
            gradient_append_prelude_part(pre, t->str);
            g_string_free(t, TRUE);
        }
    }
    if ((gr->radial || gr->conic) && gr->has_center) {
        GString *at = g_string_new("at ");
        gradient_append_center_coord(at, gr->center_x, gr->center_x_px);
        g_string_append_c(at, ' ');
        gradient_append_center_coord(at, gr->center_y, gr->center_y_px);
        gradient_append_prelude_part(pre, at->str);
        g_string_free(at, TRUE);
    }
    if (gr->interp[0]) {
        char *t = g_strdup_printf("in %s", gr->interp);
        gradient_append_prelude_part(pre, t);
        g_free(t);
    }
    if (pre->len) {
        g_string_append(s, pre->str);
        g_string_append(s, ", ");
    }
    g_string_free(pre, TRUE);
    for (int i = 0; i < gr->n_stops; i++) {
        const ns_css_gradient_stop *st = &gr->stops[i];
        if (st->pair_with_prev) {
            g_string_append_c(s, ' ');
            gradient_append_stop_pos(s, st);
            continue;
        }
        if (i > 0) g_string_append(s, ", ");
        if (st->is_hint) {
            gradient_append_stop_pos(s, st);
            continue;
        }
        ns_css_append_color(s, st->r, st->g, st->b, st->a);
        if (st->has_pos) {
            g_string_append_c(s, ' ');
            gradient_append_stop_pos(s, st);
        }
    }
    g_string_append_c(s, ')');
}

/* Serializes a gradient's specified value from retained prelude and stop texts. */
static char *
gradient_serialize_specified(const ns_gradient_parse *gp)
{
    const ns_css_gradient *gr = &gp->gr;
    GString *s = g_string_new(NULL);
    gradient_append_name(s, gr);
    GString *pre = g_string_new(NULL);
    if (gr->conic) {
        if (gr->has_from) {
            char *t = g_strdup_printf("from %s", gp->angle_text);
            gradient_append_prelude_part(pre, t);
            g_free(t);
        }
    } else if (gr->radial) {
        if (gr->size == NS_CSS_GRADIENT_EXPLICIT_SIZE) {
            gradient_append_prelude_part(pre, gp->size_text);
        } else {
            if (gr->circle) gradient_append_prelude_part(pre, "circle");
            static const char *kws[] = { NULL, "closest-side", "farthest-side",
                                         "closest-corner", NULL };
            if (kws[gr->size]) gradient_append_prelude_part(pre, kws[gr->size]);
        }
    } else {
        if (gr->has_angle) {
            gradient_append_prelude_part(pre, gp->angle_text);
        } else if (gr->to_side && gr->to_side != NS_CSS_GRADIENT_TO_BOTTOM) {
            GString *t = g_string_new(NULL);
            gradient_append_to_side(t, gr->to_side);
            gradient_append_prelude_part(pre, t->str);
            g_string_free(t, TRUE);
        }
    }
    if ((gr->radial || gr->conic) && gp->position_text &&
        g_ascii_strcasecmp(gp->position_text, "center") != 0 &&
        g_ascii_strcasecmp(gp->position_text, "center center") != 0) {
        char *t = g_strdup_printf("at %s", gp->position_text);
        gradient_append_prelude_part(pre, t);
        g_free(t);
    }
    if (gr->interp[0]) {
        char *t = g_strdup_printf("in %s", gr->interp);
        gradient_append_prelude_part(pre, t);
        g_free(t);
    }
    if (pre->len) {
        g_string_append(s, pre->str);
        g_string_append(s, ", ");
    }
    g_string_free(pre, TRUE);
    for (guint i = 0; gp->stop_texts && i < gp->stop_texts->len; i++) {
        if (i > 0) g_string_append(s, ", ");
        g_string_append(s, gp->stop_texts->pdata[i]);
    }
    g_string_append_c(s, ')');
    return g_string_free(s, FALSE);
}

/* Reports whether text begins with a (repeating-) linear, radial or conic gradient function. */
static gboolean
text_starts_gradient(const char *p)
{
    while (*p && ns_is_ascii_ws(*p)) p++;
    if (g_ascii_strncasecmp(p, "repeating-", 10) == 0) p += 10;
    return g_ascii_strncasecmp(p, "linear-gradient", 15) == 0 ||
           g_ascii_strncasecmp(p, "radial-gradient", 15) == 0 ||
           g_ascii_strncasecmp(p, "conic-gradient", 14) == 0;
}

static char *image_set_canonical(const char *text, gboolean computed);
static gboolean text_starts_image_set(const char *p);
static const char *cq_match_paren(const char *p, const char *end);

/* Canonicalizes an image list, re-serializing gradients and image-set(); NULL if invalid. */
static char *
ns_css_image_value_canonical(const char *text)
{
    if (!text) return NULL;
    GString *out = g_string_new(NULL);
    const char *p = text;
    const char *end = text + strlen(text);
    gboolean first = TRUE;
    while (p < end) {
        char term = 0;
        const char *seg_end = css_scan_until(p, end, ",", &term);
        char *layer = css_trim_dup_range(p, seg_end);
        char *canon = NULL;
        if (text_starts_gradient(layer)) {
            ns_gradient_parse gp;
            const char *gend = NULL;
            if (gradient_parse(layer, &gp, &gend, TRUE)) {
                while (gend && *gend && ns_is_ascii_ws(*gend)) gend++;
                if (!gend || !*gend) canon = gradient_serialize_specified(&gp);
                gradient_parse_clear(&gp);
            }
            if (!canon) {
                g_free(layer);
                g_string_free(out, TRUE);
                return NULL;
            }
        } else if (text_starts_image_set(layer)) {
            canon = image_set_canonical(layer, FALSE);
            if (!canon) {
                g_free(layer);
                g_string_free(out, TRUE);
                return NULL;
            }
        }
        if (!first) g_string_append(out, ", ");
        first = FALSE;
        g_string_append(out, canon ? canon : layer);
        g_free(canon);
        g_free(layer);
        p = term == ',' ? seg_end + 1 : seg_end;
    }
    return g_string_free(out, FALSE);
}

/* Returns a linear gradient's angle in degrees; corner directions depend on box aspect. */
double
ns_css_gradient_angle(const ns_css_gradient *gr, double w, double h)
{
    if (gr->has_angle) return gr->angle_deg;
    int side = gr->to_side ? gr->to_side : NS_CSS_GRADIENT_TO_BOTTOM;
    gboolean horiz = side & (NS_CSS_GRADIENT_TO_LEFT | NS_CSS_GRADIENT_TO_RIGHT);
    gboolean vert = side & (NS_CSS_GRADIENT_TO_TOP | NS_CSS_GRADIENT_TO_BOTTOM);
    if (!horiz) return side & NS_CSS_GRADIENT_TO_TOP ? 0 : 180;
    if (!vert) return side & NS_CSS_GRADIENT_TO_LEFT ? 270 : 90;
    double corner = w > 0 && h > 0 ? atan2(w, h) * 180.0 / G_PI : 45.0;
    gboolean right = side & NS_CSS_GRADIENT_TO_RIGHT;
    gboolean top = side & NS_CSS_GRADIENT_TO_TOP;
    if (right && top) return corner;
    if (right) return 180.0 - corner;
    if (top) return 360.0 - corner;
    return 180.0 + corner;
}

/* Computes radial gradient ending-shape radii for the box and center per size keyword. */
void
ns_css_gradient_radii(const ns_css_gradient *gr, double w, double h,
                      double cx, double cy, double *rx, double *ry)
{
    double dl = fabs(cx), dr = fabs(w - cx), dt = fabs(cy), db = fabs(h - cy);
    switch (gr->size) {
    case NS_CSS_GRADIENT_EXPLICIT_SIZE:
        *rx = gr->size_x + gr->size_x_pct / 100.0 * w;
        *ry = gr->circle ? *rx : gr->size_y + gr->size_y_pct / 100.0 * h;
        break;
    case NS_CSS_GRADIENT_CLOSEST_SIDE:
        *rx = MIN(dl, dr);
        *ry = MIN(dt, db);
        if (gr->circle) *rx = *ry = MIN(*rx, *ry);
        break;
    case NS_CSS_GRADIENT_FARTHEST_SIDE:
        *rx = MAX(dl, dr);
        *ry = MAX(dt, db);
        if (gr->circle) *rx = *ry = MAX(*rx, *ry);
        break;
    case NS_CSS_GRADIENT_CLOSEST_CORNER:
        if (gr->circle) {
            *rx = *ry = sqrt(MIN(dl, dr) * MIN(dl, dr) + MIN(dt, db) * MIN(dt, db));
        } else {
            *rx = MIN(dl, dr) * G_SQRT2;
            *ry = MIN(dt, db) * G_SQRT2;
        }
        break;
    case NS_CSS_GRADIENT_FARTHEST_CORNER:
    default:
        if (gr->circle) {
            *rx = *ry = sqrt(MAX(dl, dr) * MAX(dl, dr) + MAX(dt, db) * MAX(dt, db));
        } else {
            *rx = MAX(dl, dr) * G_SQRT2;
            *ry = MAX(dt, db) * G_SQRT2;
        }
        break;
    }
    if (*rx <= 0) *rx = 1;
    if (*ry <= 0) *ry = 1;
}

typedef enum {
    CONTENT_TOK_STRING,
    CONTENT_TOK_IDENT,
    CONTENT_TOK_FUNC,
    CONTENT_TOK_SLASH,
} content_tok_kind;

typedef struct {
    content_tok_kind kind;
    char *text;
    char *args;
} content_tok;

static void
content_tok_clear(gpointer data)
{
    content_tok *t = data;
    g_free(t->text);
    g_free(t->args);
}

/* Decodes escapes in a content string and re-quotes it with double quotes; caller frees. */
static char *
content_string_canonical(const char *raw, gsize len)
{
    GString *decoded = g_string_new(NULL);
    char *inner = g_strndup(raw, len);
    for (const char *p = inner; *p; )
        ns_css_append_unescaped(decoded, &p);
    g_free(inner);
    GString *out = g_string_new("\"");
    for (const char *p = decoded->str; *p; p++) {
        if (*p == '"' || *p == '\\') g_string_append_c(out, '\\');
        g_string_append_c(out, *p);
    }
    g_string_append_c(out, '"');
    g_string_free(decoded, TRUE);
    return g_string_free(out, FALSE);
}

/* Returns the closing quote of a string starting at p, honoring escapes; NULL if open. */
static const char *
content_scan_string_end(const char *p)
{
    char q = *p++;
    while (*p) {
        if (*p == '\\' && p[1]) { p += 2; continue; }
        if (*p == q) return p;
        p++;
    }
    return NULL;
}

/* Tokenizes a content value into strings, idents, functions and slashes; NULL on error. */
static GArray *
content_tokenize(const char *text)
{
    GArray *toks = g_array_new(FALSE, TRUE, sizeof(content_tok));
    g_array_set_clear_func(toks, content_tok_clear);
    const char *p = text;
    while (*p) {
        if (ns_is_ascii_ws(*p)) { p++; continue; }
        content_tok t = { 0 };
        if (*p == '"' || *p == '\'') {
            const char *e = content_scan_string_end(p);
            if (!e) goto fail;
            t.kind = CONTENT_TOK_STRING;
            t.text = content_string_canonical(p + 1, (gsize)(e - p - 1));
            p = e + 1;
        } else if (*p == '/') {
            t.kind = CONTENT_TOK_SLASH;
            t.text = g_strdup("/");
            p++;
        } else if (g_ascii_isalpha((guchar)*p) || *p == '-' || *p == '_' ||
                   *p == '\\' || (guchar)*p >= 0x80) {
            const char *s = p;
            while (*p && (g_ascii_isalnum((guchar)*p) || *p == '-' ||
                          *p == '_' || (guchar)*p >= 0x80 || *p == '\\')) {
                if (*p == '\\' && p[1]) p += 2;
                else p++;
            }
            t.text = g_strndup(s, (gsize)(p - s));
            if (*p == '(') {
                int depth = 0;
                const char *a = p + 1;
                const char *q = p;
                for (; *q; q++) {
                    if (*q == '"' || *q == '\'') {
                        q = content_scan_string_end(q);
                        if (!q) break;
                        continue;
                    }
                    if (*q == '(') depth++;
                    else if (*q == ')' && --depth == 0) break;
                }
                if (!q || *q != ')') { g_free(t.text); goto fail; }
                t.kind = CONTENT_TOK_FUNC;
                t.args = g_strndup(a, (gsize)(q - a));
                g_strstrip(t.args);
                char *lower = g_ascii_strdown(t.text, -1);
                g_free(t.text);
                t.text = lower;
                p = q + 1;
            } else {
                t.kind = CONTENT_TOK_IDENT;
            }
        } else {
            goto fail;
        }
        g_array_append_val(toks, t);
    }
    return toks;
fail:
    g_array_free(toks, TRUE);
    return NULL;
}

/* Splits function args at top-level commas, skipping quoted strings; NULL if unterminated. */
static GPtrArray *
content_split_args(const char *args)
{
    GPtrArray *out = g_ptr_array_new_with_free_func(g_free);
    const char *seg = args;
    int depth = 0;
    for (const char *q = args; ; q++) {
        if (*q == '"' || *q == '\'') {
            const char *e = content_scan_string_end(q);
            if (!e) { g_ptr_array_free(out, TRUE); return NULL; }
            q = e;
            continue;
        }
        if (*q == '(') depth++;
        else if (*q == ')' && depth > 0) depth--;
        if ((*q == ',' && depth == 0) || !*q) {
            char *piece = g_strndup(seg, (gsize)(q - seg));
            g_strstrip(piece);
            g_ptr_array_add(out, piece);
            if (!*q) break;
            seg = q + 1;
        }
    }
    return out;
}

static gboolean css_wide_keyword_or_default(const char *item);
static gboolean attr_functions_syntax_valid(const char *text);

/* Validates a counter or attribute name as a CSS identifier (escapes allowed). */
static gboolean
content_ident_valid(const char *s)
{
    if (!s || !*s) return FALSE;
    if (g_ascii_isdigit((guchar)s[0])) return FALSE;
    for (const char *p = s; *p; p++) {
        if (*p == '\\') { if (!p[1]) return FALSE; p++; continue; }
        if (!(g_ascii_isalnum((guchar)*p) || *p == '-' || *p == '_' ||
              (guchar)*p >= 0x80))
            return FALSE;
    }
    return TRUE;
}

static gboolean
content_is_string_token(const char *s)
{
    if (!s || (s[0] != '"' && s[0] != '\'')) return FALSE;
    const char *e = content_scan_string_end(s);
    return e && e[1] == '\0';
}

/* Canonicalizes symbols() arguments; drops default symbolic and rejects invalid systems. */
static char *
content_symbols_canonical(const char *args)
{
    GArray *toks = content_tokenize(args);
    if (!toks) return NULL;
    const char *system = NULL;
    guint i = 0;
    if (toks->len > 0) {
        content_tok *t = &g_array_index(toks, content_tok, 0);
        if (t->kind == CONTENT_TOK_IDENT) {
            static const char *systems[] = { "cyclic", "numeric", "alphabetic",
                                             "symbolic", "additive", "fixed" };
            for (gsize k = 0; k < G_N_ELEMENTS(systems); k++)
                if (g_ascii_strcasecmp(t->text, systems[k]) == 0)
                    system = systems[k];
            if (!system) { g_array_free(toks, TRUE); return NULL; }
            i = 1;
        }
    }
    GString *out = g_string_new(NULL);
    if (system && strcmp(system, "symbolic") != 0) g_string_append(out, system);
    int n_symbols = 0;
    for (; i < toks->len; i++) {
        content_tok *t = &g_array_index(toks, content_tok, i);
        gboolean image = t->kind == CONTENT_TOK_FUNC &&
                         (strcmp(t->text, "url") == 0 ||
                          strcmp(t->text, "image") == 0 ||
                          strstr(t->text, "gradient"));
        if (t->kind != CONTENT_TOK_STRING && !image) {
            g_string_free(out, TRUE);
            g_array_free(toks, TRUE);
            return NULL;
        }
        if (out->len) g_string_append_c(out, ' ');
        if (image) g_string_append_printf(out, "%s(%s)", t->text, t->args);
        else g_string_append(out, t->text);
        n_symbols++;
    }
    g_array_free(toks, TRUE);
    gboolean ok = n_symbols >= 1;
    if (system && (strcmp(system, "numeric") == 0 ||
                   strcmp(system, "alphabetic") == 0) && n_symbols < 2)
        ok = FALSE;
    if (system && strcmp(system, "additive") == 0) ok = FALSE;
    if (!ok) { g_string_free(out, TRUE); return NULL; }
    return g_string_free(out, FALSE);
}

/* Canonicalizes a counter style argument; decimal becomes "" so it is omitted. */
static char *
content_counter_style_canonical(const char *style)
{
    if (g_ascii_strncasecmp(style, "symbols(", 8) == 0 &&
        style[strlen(style) - 1] == ')') {
        char *inner = g_strndup(style + 8, strlen(style) - 9);
        char *canon = content_symbols_canonical(inner);
        g_free(inner);
        if (!canon) return NULL;
        char *res = g_strdup_printf("symbols(%s)", canon);
        g_free(canon);
        return res;
    }
    if (!content_ident_valid(style) || css_wide_keyword_or_default(style) ||
        g_ascii_strcasecmp(style, "none") == 0) return NULL;
    if (g_ascii_strcasecmp(style, "decimal") == 0) return g_strdup("");
    return g_strdup(style);
}

/* Validates and serializes counter()/counters() with canonical separator and style. */
static char *
content_counter_canonical(const content_tok *t)
{
    gboolean counters = strcmp(t->text, "counters") == 0;
    GPtrArray *args = content_split_args(t->args);
    if (!args) return NULL;
    guint min_args = counters ? 2 : 1, max_args = counters ? 3 : 2;
    char *res = NULL;
    if (args->len < min_args || args->len > max_args) goto done;
    const char *name = args->pdata[0];
    if (!content_ident_valid(name) || g_ascii_strcasecmp(name, "none") == 0)
        goto done;
    char *sep = NULL;
    if (counters) {
        const char *s = args->pdata[1];
        if (!content_is_string_token(s)) goto done;
        sep = content_string_canonical(s + 1, strlen(s) - 2);
    }
    char *style = NULL;
    if (args->len == max_args) {
        style = content_counter_style_canonical(args->pdata[max_args - 1]);
        if (!style) { g_free(sep); goto done; }
    }
    GString *out = g_string_new(t->text);
    g_string_append_c(out, '(');
    g_string_append(out, name);
    if (sep) { g_string_append(out, ", "); g_string_append(out, sep); }
    if (style && *style) { g_string_append(out, ", "); g_string_append(out, style); }
    g_string_append_c(out, ')');
    g_free(sep);
    g_free(style);
    res = g_string_free(out, FALSE);
done:
    g_ptr_array_free(args, TRUE);
    return res;
}

static gboolean
content_func_is_image(const content_tok *t)
{
    return strcmp(t->text, "url") == 0 || strcmp(t->text, "image") == 0 ||
           strcmp(t->text, "image-set") == 0 ||
           strcmp(t->text, "cross-fade") == 0 ||
           strcmp(t->text, "element") == 0 ||
           g_str_has_suffix(t->text, "-gradient");
}

/* Serializes one content item; alt text after "/" allows only strings, counters and attr(). */
static char *
content_item_canonical(const content_tok *t, gboolean alt)
{
    if (t->kind == CONTENT_TOK_STRING) return g_strdup(t->text);
    if (t->kind == CONTENT_TOK_IDENT) {
        if (alt) return NULL;
        static const char *kws[] = { "open-quote", "close-quote",
                                     "no-open-quote", "no-close-quote",
                                     "contents" };
        for (gsize k = 0; k < G_N_ELEMENTS(kws); k++)
            if (g_ascii_strcasecmp(t->text, kws[k]) == 0)
                return g_strdup(kws[k]);
        return NULL;
    }
    if (t->kind != CONTENT_TOK_FUNC) return NULL;
    if (strcmp(t->text, "counter") == 0 || strcmp(t->text, "counters") == 0)
        return content_counter_canonical(t);
    if (strcmp(t->text, "attr") == 0) {
        GPtrArray *args = content_split_args(t->args);
        gboolean ok = args && args->len >= 1 && args->len <= 2 &&
                      *(char *)args->pdata[0];
        if (ok) {
            char *first = g_strdup(args->pdata[0]);
            char *sp = strpbrk(first, " \t");
            if (sp) *sp = '\0';
            ok = content_ident_valid(first);
            g_free(first);
        }
        if (args) g_ptr_array_free(args, TRUE);
        return ok ? g_strdup_printf("attr(%s)", t->args) : NULL;
    }
    if (alt) return NULL;
    if (strcmp(t->text, "image-set") == 0 || strcmp(t->text, "-webkit-image-set") == 0) {
        char *raw = g_strdup_printf("%s(%s)", t->text, t->args);
        char *canon = image_set_canonical(raw, FALSE);
        g_free(raw);
        return canon;
    }
    if (content_func_is_image(t) || strcmp(t->text, "leader") == 0 ||
        g_str_has_prefix(t->text, "target-") || strcmp(t->text, "var") == 0 ||
        strcmp(t->text, "string") == 0 || strcmp(t->text, "content") == 0)
        return g_strdup_printf("%s(%s)", t->text, t->args);
    return NULL;
}

/* Serializes the content property's specified value incl. alt text; NULL if invalid. */
static char *
ns_css_content_canonical(const char *text)
{
    if (!text) return NULL;
    GArray *toks = content_tokenize(text);
    if (!toks || toks->len == 0) {
        if (toks) g_array_free(toks, TRUE);
        return NULL;
    }
    if (toks->len == 1) {
        content_tok *t = &g_array_index(toks, content_tok, 0);
        if (t->kind == CONTENT_TOK_IDENT &&
            (g_ascii_strcasecmp(t->text, "normal") == 0 ||
             g_ascii_strcasecmp(t->text, "none") == 0)) {
            char *r = g_ascii_strdown(t->text, -1);
            g_array_free(toks, TRUE);
            return r;
        }
    }
    GString *out = g_string_new(NULL);
    gboolean alt = FALSE, ok = TRUE;
    int main_items = 0, alt_items = 0;
    for (guint i = 0; i < toks->len && ok; i++) {
        content_tok *t = &g_array_index(toks, content_tok, i);
        if (t->kind == CONTENT_TOK_SLASH) {
            if (alt || main_items == 0) { ok = FALSE; break; }
            alt = TRUE;
            g_string_append(out, " /");
            continue;
        }
        char *item = content_item_canonical(t, alt);
        if (!item) { ok = FALSE; break; }
        if (out->len) g_string_append_c(out, ' ');
        g_string_append(out, item);
        g_free(item);
        if (alt) alt_items++; else main_items++;
    }
    g_array_free(toks, TRUE);
    if (!ok || main_items == 0 || (alt && alt_items == 0)) {
        g_string_free(out, TRUE);
        return NULL;
    }
    return g_string_free(out, FALSE);
}

/* Splits an image-set option at top-level whitespace, skipping strings; -1 if unterminated. */
static int
image_set_split_ws(const char *text, char **out, int max)
{
    int n = 0;
    const char *p = text;
    while (*p && n < max) {
        while (*p && ns_is_ascii_ws(*p)) p++;
        if (!*p) break;
        const char *start = p;
        int depth = 0;
        while (*p) {
            if (*p == '"' || *p == '\'') {
                const char *e = content_scan_string_end(p);
                if (!e) return -1;
                p = e + 1;
                continue;
            }
            if (*p == '(') depth++;
            else if (*p == ')') { if (depth) depth--; }
            else if (ns_is_ascii_ws(*p) && depth == 0) break;
            p++;
        }
        out[n++] = g_strndup(start, (gsize)(p - start));
    }
    return n;
}

/* Canonicalizes an image-set resolution; computed form is always dppx. */
static char *
image_set_resolution_canonical(const char *tok, gboolean computed)
{
    ns_calc_term t;
    if (text_is_math_fn(tok)) {
        calc_unresolved = FALSE;
        if (!calc_eval_arg(tok, &t) || t.kind != CALC_RESOLUTION) return NULL;
        if (t.unresolved || calc_unresolved) return g_strdup(tok);
        return computed ? g_strdup_printf("%gdppx", t.num)
                        : g_strdup_printf("calc(%gdppx)", t.num);
    }
    char *endp = NULL;
    double v = g_ascii_strtod(tok, &endp);
    if (!endp || endp == tok || !*endp) return NULL;
    if (!calc_scalar_unit_value(endp, v, &t) || t.kind != CALC_RESOLUTION ||
        v < 0)
        return NULL;
    if (computed) return g_strdup_printf("%gdppx", t.num);
    char *unit = g_ascii_strdown(endp, -1);
    char *res = g_strdup_printf("%g%s", v, unit);
    g_free(unit);
    return res;
}

/* Serializes image-set() options as image resolution [type]; defaults resolution to 1x. */
static char *
image_set_canonical(const char *text, gboolean computed)
{
    const char *p = text;
    while (*p && ns_is_ascii_ws(*p)) p++;
    if (g_ascii_strncasecmp(p, "-webkit-image-set(", 18) == 0) p += 18;
    else if (g_ascii_strncasecmp(p, "image-set(", 10) == 0) p += 10;
    else return NULL;
    const char *end = p + strlen(p);
    const char *close = cq_match_paren(p - 1, end);
    if (!close) return NULL;
    const char *after = close + 1;
    while (*after && ns_is_ascii_ws(*after)) after++;
    if (*after) return NULL;
    char *body = g_strndup(p, (gsize)(close - p));
    GPtrArray *options = content_split_args(body);
    g_free(body);
    if (!options) return NULL;
    GString *out = g_string_new("image-set(");
    gboolean ok = options->len > 0;
    for (guint i = 0; i < options->len && ok; i++) {
        char *tok[6] = {0};
        int n = image_set_split_ws(options->pdata[i], tok, 6);
        char *image = NULL, *res = NULL, *type = NULL;
        if (n < 1) ok = FALSE;
        for (int k = 0; k < n && ok; k++) {
            const char *t = tok[k];
            if (k == 0) {
                if (content_is_string_token(t)) {
                    char *inner = content_string_canonical(t + 1, strlen(t) - 2);
                    image = g_strdup_printf("url(%s)", inner);
                    g_free(inner);
                } else if (g_ascii_strncasecmp(t, "url(", 4) == 0 ||
                           g_ascii_strncasecmp(t, "src(", 4) == 0 ||
                           g_ascii_strncasecmp(t, "image(", 6) == 0 ||
                           g_ascii_strncasecmp(t, "cross-fade(", 11) == 0) {
                    image = g_strdup(t);
                } else if (text_starts_gradient(t)) {
                    ns_gradient_parse gp;
                    const char *gend = NULL;
                    if (gradient_parse(t, &gp, &gend, TRUE)) {
                        image = gradient_serialize_specified(&gp);
                        gradient_parse_clear(&gp);
                    }
                    if (!image) ok = FALSE;
                } else {
                    ok = FALSE;
                }
            } else if (g_ascii_strncasecmp(t, "type(", 5) == 0) {
                if (type) ok = FALSE;
                else type = g_strdup(t);
            } else {
                if (res) ok = FALSE;
                else res = image_set_resolution_canonical(t, computed);
                if (!res) ok = FALSE;
            }
        }
        if (ok) {
            if (i) g_string_append(out, ", ");
            g_string_append(out, image);
            g_string_append_c(out, ' ');
            g_string_append(out, res ? res : computed ? "1dppx" : "1x");
            if (type) { g_string_append_c(out, ' '); g_string_append(out, type); }
        }
        g_free(image);
        g_free(res);
        g_free(type);
        for (int k = 0; k < n; k++) g_free(tok[k]);
    }
    g_ptr_array_free(options, TRUE);
    if (!ok) { g_string_free(out, TRUE); return NULL; }
    g_string_append_c(out, ')');
    return g_string_free(out, FALSE);
}

static gboolean
text_starts_image_set(const char *p)
{
    while (*p && ns_is_ascii_ws(*p)) p++;
    return g_ascii_strncasecmp(p, "image-set(", 10) == 0 ||
           g_ascii_strncasecmp(p, "-webkit-image-set(", 18) == 0;
}

/* Validates and serializes a unicode-range list as uppercase U+X or U+X-Y ranges. */
static char *
ns_css_unicode_range_canonical(const char *text)
{
    if (!text) return NULL;
    GString *clean = g_string_new(NULL);
    for (const char *p = text; *p; ) {
        if (p[0] == '/' && p[1] == '*') {
            const char *e = strstr(p + 2, "*/");
            if (!e) { g_string_free(clean, TRUE); return NULL; }
            p = e + 2;
            continue;
        }
        g_string_append_c(clean, *p++);
    }
    GString *out = g_string_new(NULL);
    gboolean ok = TRUE;
    char **parts = g_strsplit(clean->str, ",", -1);
    for (int i = 0; parts[i] && ok; i++) {
        char *r = g_strstrip(parts[i]);
        if (!*r || (r[0] != 'u' && r[0] != 'U') || r[1] != '+') { ok = FALSE; break; }
        const char *q = r + 2;
        guint32 start = 0, endv = 0;
        int hex = 0, wild = 0;
        while (g_ascii_isxdigit((guchar)*q) && hex < 7) {
            start = start * 16 + g_ascii_xdigit_value(*q);
            hex++; q++;
        }
        while (*q == '?' && wild < 7) { wild++; q++; }
        if (hex + wild == 0 || hex + wild > 6) { ok = FALSE; break; }
        if (wild) {
            if (*q) { ok = FALSE; break; }
            endv = start;
            for (int k = 0; k < wild; k++) { start *= 16; endv = endv * 16 + 15; }
        } else if (*q == '-') {
            q++;
            int hex2 = 0;
            while (g_ascii_isxdigit((guchar)*q) && hex2 < 7) {
                endv = endv * 16 + g_ascii_xdigit_value(*q);
                hex2++; q++;
            }
            if (hex2 == 0 || hex2 > 6 || *q) { ok = FALSE; break; }
        } else if (*q) {
            ok = FALSE;
            break;
        } else {
            endv = start;
        }
        if (start > endv || endv > 0x10FFFF) { ok = FALSE; break; }
        if (out->len) g_string_append(out, ", ");
        if (start == endv) g_string_append_printf(out, "U+%X", start);
        else g_string_append_printf(out, "U+%X-%X", start, endv);
    }
    g_strfreev(parts);
    g_string_free(clean, TRUE);
    if (!ok || out->len == 0) { g_string_free(out, TRUE); return NULL; }
    return g_string_free(out, FALSE);
}

/* Returns the closing quote in u honoring backslash escapes, or NULL. */
static const char *
css_quoted_end(const char *u, char quote)
{
    const char *p = u;
    while (*p) {
        if (*p == '\\' && p[1]) { p += 2; continue; }
        if (*p == quote) return p;
        p++;
    }
    return NULL;
}

/* Copies a URL dropping backslashes before escaped characters; caller frees. */
static char *
css_unescape_url(const char *u, gsize len)
{
    GString *out = g_string_sized_new(len);
    for (gsize i = 0; i < len; i++) {
        if (u[i] == '\\' && i + 1 < len) i++;
        g_string_append_c(out, u[i]);
    }
    return g_string_free(out, FALSE);
}

/* Picks the image-set() url() whose resolution is closest to 1x; caller frees. */
static char *
pick_image_set_url(const char *t)
{
    const char *p = t;
    while (*p && ns_is_ascii_ws(*p)) p++;
    if (g_ascii_strncasecmp(p, "-webkit-image-set(", 18) == 0)
        p += 18;
    else if (g_ascii_strncasecmp(p, "image-set(", 10) == 0)
        p += 10;
    else
        return NULL;

    const double target = 1.0;
    char *best = NULL;
    double best_res = 0;
    while (*p && *p != ')') {
        while (*p && (ns_is_ascii_ws(*p) || *p == ',')) p++;
        if (!*p || *p == ')') break;
        char *url = NULL;
        if (g_ascii_strncasecmp(p, "url(", 4) == 0) {
            const char *u = p + 4;
            while (*u && ns_is_ascii_ws(*u)) u++;
            char q = 0;
            if (*u == '"' || *u == '\'') { q = *u; u++; }
            const char *end;
            if (q) end = css_quoted_end(u, q);
            else { end = u; while (*end && *end != ')' && !ns_is_ascii_ws(*end)) end++; }
            if (end && end > u) url = css_unescape_url(u, (gsize)(end - u));
            p = end ? end : p + 4;
            while (*p && *p != ')') p++;
            if (*p == ')') p++;
        }
        double res = 1.0;
        while (*p && ns_is_ascii_ws(*p)) p++;
        if (*p && *p != ',' && *p != ')') {
            res = g_ascii_strtod(p, NULL);
            while (*p && *p != ',' && *p != ')') p++;
        }
        if (url) {
            if (!best || fabs(res - target) < fabs(best_res - target)) {
                g_free(best);
                best = url;
                best_res = res;
            } else {
                g_free(url);
            }
        } else {
            while (*p && *p != ',' && *p != ')') p++;
        }
    }
    return best;
}

/* Parses gradient text into a value; allow_trailing permits text after the closing paren. */
static ns_css_value *
parse_gradient_text(const char *t, gboolean allow_trailing)
{
    ns_gradient_parse gp;
    const char *gend = NULL;
    if (!gradient_parse(t, &gp, &gend, FALSE)) return NULL;
    while (gend && *gend && ns_is_ascii_ws(*gend)) gend++;
    if (!allow_trailing && gend && *gend) {
        gradient_parse_clear(&gp);
        return NULL;
    }
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_GRADIENT;
    v->u.gradient = gp.gr;
    gradient_parse_clear(&gp);
    return v;
}

static ns_css_value *
parse_any_gradient(const char *t)
{
    return parse_gradient_text(t, FALSE);
}

/* Converts an angle string to degrees (deg, rad, turn, grad); unitless taken as degrees. */
static double
parse_angle_deg(const char *s)
{
    if (!s) return 0;
    char *end = NULL;
    double v = g_ascii_strtod(s, &end);
    if (!end || end == s) return 0;
    while (*end && ns_is_ascii_ws(*end)) end++;
    if (g_ascii_strncasecmp(end, "rad", 3) == 0) return v * 180.0 / G_PI;
    if (g_ascii_strncasecmp(end, "turn", 4) == 0) return v * 360.0;
    if (g_ascii_strncasecmp(end, "grad", 4) == 0) return v * 0.9;
    return v;
}

/* Parses a transform length to px or a pure percentage, flagging which via is_percent. */
static gboolean
parse_transform_len(const char *s, double *out, gboolean *is_percent)
{
    if (!s) return FALSE;
    double px = 0, pct = 0;
    if (resolve_to_px_pct(s, strlen(s), &px, &pct)) {
        if (pct != 0 && px == 0) {
            *out = pct;
            *is_percent = TRUE;
        } else {
            *out = px;
            *is_percent = FALSE;
        }
        return TRUE;
    }
    char *end = NULL;
    double v = g_ascii_strtod(s, &end);
    if (!end || end == s) return FALSE;
    while (*end && ns_is_ascii_ws(*end)) end++;
    *out = v;
    *is_percent = (*end == '%');
    return TRUE;
}

/* Parses one translate axis into px, percent and em/rem parts; z rejects percentages. */
static gboolean
parse_translate_len(const char *s, ns_css_transform_op *op, int axis)
{
    if (!s) return FALSE;
    double *field = axis == 0 ? &op->a : axis == 1 ? &op->b : &op->c;
    gboolean *is_percent = axis == 0 ? &op->a_is_percent
                         : axis == 1 ? &op->b_is_percent : NULL;
    double px = 0, pct = 0;
    ns_font_units font = { 0 };
    if (!resolve_to_px_pct_font(s, strlen(s), &px, &pct, &font)) {
        gboolean fallback_pct = FALSE;
        if (!parse_transform_len(s, field, &fallback_pct)) return FALSE;
        if (is_percent) *is_percent = fallback_pct;
        return is_percent || !fallback_pct;
    }
    px += (font.lh + font.rlh) * 19.2;
    op->em[axis] = font.em;
    op->rem[axis] = font.rem;
    if (!is_percent) {
        *field = px;
        return pct == 0;
    }
    if (pct != 0 && px == 0 && font.em == 0 && font.rem == 0) {
        *field = pct;
        *is_percent = TRUE;
        return TRUE;
    }
    *field = px;
    *is_percent = FALSE;
    if (axis == 0) op->a_pct = pct;
    else op->b_pct = pct;
    return TRUE;
}

/* Parses an angle or angle-valued math expression to degrees. */
static gboolean
parse_angle_any(const char *s, double *deg_out)
{
    if (!s) return FALSE;
    while (*s && ns_is_ascii_ws(*s)) s++;
    if (!*s) return FALSE;
    if (text_is_math_fn(s)) {
        ns_calc_term t;
        if (!calc_eval_arg(s, &t)) return FALSE;
        if (t.kind != CALC_ANGLE && t.kind != CALC_NUMBER) return FALSE;
        *deg_out = t.num;
        return TRUE;
    }
    char *end = NULL;
    g_ascii_strtod(s, &end);
    if (!end || end == s) return FALSE;
    *deg_out = parse_angle_deg(s);
    return TRUE;
}

static gboolean parse_scale_number(const char *s, double *out);

/* Parses a transform function list into ops (translate, rotate, scale, skew, matrix, 3D). */
static ns_css_value *
parse_transform(const char *text)
{
    while (*text && ns_is_ascii_ws(*text)) text++;
    if (!*text) return NULL;
    if (g_ascii_strncasecmp(text, "none", 4) == 0) return NULL;
    ns_css_transform tf = {0};
    const char *p = text;
    while (*p && tf.n_ops < NS_CSS_TRANSFORM_OPS_MAX) {
        while (*p && (ns_is_ascii_ws(*p) || *p == ',')) p++;
        if (!*p) break;
        const char *name_start = p;
        while (*p && *p != '(') p++;
        if (*p != '(') break;
        gsize name_len = (gsize)(p - name_start);
        char *fn = g_strndup(name_start, name_len);
        g_strstrip(fn);
        char *fn_lc = g_ascii_strdown(fn, -1);
        g_free(fn);
        p++;
        const char *args_start = p;
        int depth = 1;
        while (*p && depth > 0) {
            if (*p == '(') depth++;
            else if (*p == ')') depth--;
            if (depth > 0) p++;
        }
        if (depth != 0) { g_free(fn_lc); break; }
        gsize args_len = (gsize)(p - args_start);
        char *args = g_strndup(args_start, args_len);
        if (*p == ')') p++;

        char *targs[16] = {0};
        int nt = 0;
        char *seg = args;
        int adepth = 0;
        for (char *q = args; ; q++) {
            if (*q == '(') adepth++;
            else if (*q == ')') adepth--;
            if ((*q == ',' && adepth == 0) || *q == '\0') {
                int saved = *q;
                *q = '\0';
                if (nt < 16) {
                    char *piece = g_strdup(seg);
                    g_strstrip(piece);
                    targs[nt++] = piece;
                }
                if (saved == '\0') break;
                seg = q + 1;
            }
        }

        ns_css_transform_op *op = &tf.ops[tf.n_ops];
        gboolean accept = FALSE;
        gboolean dummy_pct = FALSE;
        if (strcmp(fn_lc, "translate") == 0 ||
            strcmp(fn_lc, "translatex") == 0 ||
            strcmp(fn_lc, "translatey") == 0 ||
            strcmp(fn_lc, "translatez") == 0) {
            op->kind = NS_CSS_TFN_TRANSLATE;
            op->a = 0; op->b = 0; op->c = 0;
            op->a_is_percent = FALSE; op->b_is_percent = FALSE;
            if (strcmp(fn_lc, "translatey") == 0) {
                if (nt >= 1) parse_translate_len(targs[0], op, 1);
            } else if (strcmp(fn_lc, "translatez") == 0) {
                if (nt >= 1) parse_translate_len(targs[0], op, 2);
                op->is_3d = TRUE;
            } else {
                if (nt >= 1) parse_translate_len(targs[0], op, 0);
                if (nt >= 2) parse_translate_len(targs[1], op, 1);
            }
            accept = TRUE;
        } else if (strcmp(fn_lc, "rotate") == 0 ||
                   strcmp(fn_lc, "rotatez") == 0) {
            op->kind = NS_CSS_TFN_ROTATE;
            op->a = 0;
            op->b = 0;
            accept = nt == 1 && parse_angle_any(targs[0], &op->a);
        } else if (strcmp(fn_lc, "rotatex") == 0 ||
                   strcmp(fn_lc, "rotatey") == 0) {
            op->kind = NS_CSS_TFN_ROTATE3D;
            op->a = strcmp(fn_lc, "rotatex") == 0 ? 1 : 0;
            op->b = strcmp(fn_lc, "rotatey") == 0 ? 1 : 0;
            op->c = 0;
            op->d = 0;
            op->is_3d = TRUE;
            accept = nt == 1 && parse_angle_any(targs[0], &op->d);
        } else if (strcmp(fn_lc, "rotate3d") == 0 && nt == 4) {
            op->kind = NS_CSS_TFN_ROTATE3D;
            op->a = g_ascii_strtod(targs[0], NULL);
            op->b = g_ascii_strtod(targs[1], NULL);
            op->c = g_ascii_strtod(targs[2], NULL);
            op->d = 0;
            op->is_3d = TRUE;
            accept = parse_angle_any(targs[3], &op->d);
        } else if (strcmp(fn_lc, "perspective") == 0 && nt >= 1) {
            op->kind = NS_CSS_TFN_PERSPECTIVE;
            op->a = 0;
            parse_transform_len(targs[0], &op->a, &dummy_pct);
            op->is_3d = TRUE;
            accept = TRUE;
        } else if (strcmp(fn_lc, "scale") == 0 ||
                   strcmp(fn_lc, "scalex") == 0 ||
                   strcmp(fn_lc, "scaley") == 0 ||
                   strcmp(fn_lc, "scalez") == 0) {
            op->kind = NS_CSS_TFN_SCALE;
            double sa = 1, sb;
            if (nt >= 1 && !parse_scale_number(targs[0], &sa)) sa = 0;
            sb = sa;
            if (nt >= 2 && !parse_scale_number(targs[1], &sb)) sb = 0;
            op->c = 1;
            if (strcmp(fn_lc, "scalex") == 0) { op->a = sa; op->b = 1; }
            else if (strcmp(fn_lc, "scaley") == 0) { op->a = 1; op->b = sa; }
            else if (strcmp(fn_lc, "scalez") == 0) {
                op->a = 1; op->b = 1; op->c = sa; op->is_3d = TRUE;
            }
            else { op->a = sa; op->b = sb; }
            accept = TRUE;
        } else if (strcmp(fn_lc, "skew") == 0 ||
                   strcmp(fn_lc, "skewx") == 0 ||
                   strcmp(fn_lc, "skewy") == 0) {
            op->kind = NS_CSS_TFN_SKEW;
            double aa = 0, bb = 0;
            if (nt >= 1) parse_angle_any(targs[0], &aa);
            if (nt >= 2) parse_angle_any(targs[1], &bb);
            if (strcmp(fn_lc, "skewx") == 0) { op->a = aa; op->b = 0; }
            else if (strcmp(fn_lc, "skewy") == 0) { op->a = 0; op->b = aa; }
            else { op->a = aa; op->b = bb; }
            accept = TRUE;
        } else if (strcmp(fn_lc, "matrix") == 0 && nt == 6) {
            op->kind = NS_CSS_TFN_MATRIX;
            op->a = g_ascii_strtod(targs[0], NULL);
            op->b = g_ascii_strtod(targs[1], NULL);
            op->c = g_ascii_strtod(targs[2], NULL);
            op->d = g_ascii_strtod(targs[3], NULL);
            op->e = g_ascii_strtod(targs[4], NULL);
            op->f = g_ascii_strtod(targs[5], NULL);
            accept = TRUE;
        } else if (strcmp(fn_lc, "matrix3d") == 0 && nt == 16) {
            op->kind = NS_CSS_TFN_MATRIX3D;
            for (int k = 0; k < 16; k++)
                op->m3d[k] = g_ascii_strtod(targs[k], NULL);
            op->is_3d = TRUE;
            accept = TRUE;
        } else if ((strcmp(fn_lc, "translate3d") == 0 && nt >= 2)) {
            op->kind = NS_CSS_TFN_TRANSLATE;
            op->a = 0; op->b = 0; op->c = 0;
            op->a_is_percent = FALSE; op->b_is_percent = FALSE;
            parse_translate_len(targs[0], op, 0);
            parse_translate_len(targs[1], op, 1);
            if (nt >= 3) parse_translate_len(targs[2], op, 2);
            op->is_3d = TRUE;
            accept = TRUE;
        } else if (strcmp(fn_lc, "scale3d") == 0 && nt >= 2) {
            op->kind = NS_CSS_TFN_SCALE;
            op->a = 0; op->b = 0; op->c = 1;
            parse_scale_number(targs[0], &op->a);
            parse_scale_number(targs[1], &op->b);
            if (nt >= 3) parse_scale_number(targs[2], &op->c);
            op->is_3d = TRUE;
            accept = TRUE;
        }
        if (accept) tf.n_ops++;
        for (int k = 0; k < 16; k++) g_free(targs[k]);
        g_free(args);
        g_free(fn_lc);
    }
    if (tf.n_ops == 0) return NULL;
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_TRANSFORM;
    v->u.transform = tf;
    return v;
}

/* Parses a transform-origin axis keyword or length into a value and percent flag. */
static gboolean
parse_origin_axis(const char *tok, gboolean is_y,
                  double *out, gboolean *is_percent)
{
    if (!tok || !*tok) return FALSE;
    char *lc = ascii_lower(tok, strlen(tok));
    gboolean ok = TRUE;
    if (strcmp(lc, "center") == 0)      { *out = 50; *is_percent = TRUE; }
    else if (!is_y && strcmp(lc, "left")  == 0)  { *out = 0;   *is_percent = TRUE; }
    else if (!is_y && strcmp(lc, "right") == 0)  { *out = 100; *is_percent = TRUE; }
    else if ( is_y && strcmp(lc, "top")   == 0)  { *out = 0;   *is_percent = TRUE; }
    else if ( is_y && strcmp(lc, "bottom") == 0) { *out = 100; *is_percent = TRUE; }
    else ok = parse_transform_len(tok, out, is_percent);
    g_free(lc);
    return ok;
}

/* Parses transform-origin into a single translate op (x, y as px/%, optional z length). */
static ns_css_value *
parse_transform_origin(const char *text)
{
    if (!text || !*text) return NULL;
    char *edge_canon = css_ws_token_count(text) >= 3 &&
                       position_canonical_ex(text, TRUE, FALSE)
        ? position_canonical_ex(text, TRUE, FALSE) : NULL;
    if (edge_canon) {
        char *xs = NULL, *ys = NULL;
        position_split(edge_canon, &xs, &ys);
        g_free(edge_canon);
        ns_css_transform tf;
        memset(&tf, 0, sizeof(tf));
        tf.n_ops = 1;
        ns_css_transform_op *op = &tf.ops[0];
        op->kind = NS_CSS_TFN_TRANSLATE;
        op->a = 50; op->b = 50; op->c = 0;
        op->a_is_percent = TRUE; op->b_is_percent = TRUE;
        if (xs) parse_origin_axis(xs, FALSE, &op->a, &op->a_is_percent);
        if (ys) parse_origin_axis(ys, TRUE, &op->b, &op->b_is_percent);
        g_free(xs);
        g_free(ys);
        ns_css_value *v = g_new0(ns_css_value, 1);
        v->kind = NS_CSS_V_TRANSFORM;
        v->u.transform = tf;
        return v;
    }
    char *toks[4] = {0};
    int nt = split_ws_limit(text, toks, 3);
    char *a = nt >= 1 ? toks[0] : NULL;
    char *b = nt >= 2 ? toks[1] : NULL;
    char *zc = nt >= 3 ? toks[2] : NULL;
    ns_css_transform tf;
    memset(&tf, 0, sizeof(tf));
    tf.n_ops = 1;
    ns_css_transform_op *op = &tf.ops[0];
    op->kind = NS_CSS_TFN_TRANSLATE;
    op->a = 50; op->b = 50; op->c = 0;
    op->a_is_percent = TRUE; op->b_is_percent = TRUE;
    gboolean swap = FALSE;
    if (a) {
        char *alc = ascii_lower(a, strlen(a));
        if (strcmp(alc, "top") == 0 || strcmp(alc, "bottom") == 0) swap = TRUE;
        g_free(alc);
    }
    if (swap) {
        if (a) parse_origin_axis(a, TRUE,  &op->b, &op->b_is_percent);
        if (b) parse_origin_axis(b, FALSE, &op->a, &op->a_is_percent);
    } else {
        if (a) parse_origin_axis(a, FALSE, &op->a, &op->a_is_percent);
        if (b) parse_origin_axis(b, TRUE,  &op->b, &op->b_is_percent);
        else if (a) {
            char *alc = ascii_lower(a, strlen(a));
            if (strcmp(alc, "left") == 0 || strcmp(alc, "right") == 0) {
                op->b = 50; op->b_is_percent = TRUE;
            }
            g_free(alc);
        }
    }
    if (zc) {
        gboolean zpct = FALSE;
        parse_transform_len(zc, &op->c, &zpct);
        if (zpct) op->c = 0;
    }
    for (int i = 0; i < nt; i++) g_free(toks[i]);
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_TRANSFORM;
    v->u.transform = tf;
    return v;
}

static ns_css_value *
transform_value_one_op(const ns_css_transform_op *op)
{
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_TRANSFORM;
    v->u.transform.n_ops = 1;
    v->u.transform.ops[0] = *op;
    return v;
}

/* Parses the individual translate property (up to three lengths) into one translate op. */
static ns_css_value *
parse_translate_prop(const char *text)
{
    while (*text && ns_is_ascii_ws(*text)) text++;
    if (!*text || g_ascii_strcasecmp(text, "none") == 0) return NULL;
    char *toks[4] = {0};
    int nt = split_ws_limit(text, toks, 3);
    if (nt == 0) return NULL;
    ns_css_transform_op op;
    memset(&op, 0, sizeof(op));
    op.kind = NS_CSS_TFN_TRANSLATE;
    gboolean ok = parse_translate_len(toks[0], &op, 0);
    if (ok && nt >= 2) ok = parse_translate_len(toks[1], &op, 1);
    if (ok && nt >= 3) ok = parse_translate_len(toks[2], &op, 2);
    for (int i = 0; i < nt; i++) g_free(toks[i]);
    if (!ok) return NULL;
    return transform_value_one_op(&op);
}

/* Parses the individual rotate property: angle, axis keyword plus angle, or x y z angle. */
static ns_css_value *
parse_rotate_prop(const char *text)
{
    while (*text && ns_is_ascii_ws(*text)) text++;
    if (!*text || g_ascii_strcasecmp(text, "none") == 0) return NULL;
    char *toks[5] = {0};
    int nt = split_ws_limit(text, toks, 4);
    ns_css_value *v = NULL;
    ns_css_transform_op op;
    memset(&op, 0, sizeof(op));
    if (nt == 1) {
        op.kind = NS_CSS_TFN_ROTATE;
        if (parse_angle_any(toks[0], &op.a)) v = transform_value_one_op(&op);
    } else if (nt == 2) {
        op.kind = NS_CSS_TFN_ROTATE3D;
        char *axis = ascii_lower(toks[0], strlen(toks[0]));
        gboolean ok = TRUE;
        if      (strcmp(axis, "x") == 0) op.a = 1;
        else if (strcmp(axis, "y") == 0) op.b = 1;
        else if (strcmp(axis, "z") == 0) op.c = 1;
        else ok = FALSE;
        g_free(axis);
        if (ok && parse_angle_any(toks[1], &op.d)) {
            if (op.c == 1 && op.a == 0 && op.b == 0) {
                op.kind = NS_CSS_TFN_ROTATE;
                op.a = op.d;
                op.b = 0; op.c = 0; op.d = 0;
            }
            v = transform_value_one_op(&op);
        }
    } else if (nt == 4) {
        op.kind = NS_CSS_TFN_ROTATE3D;
        op.a = g_ascii_strtod(toks[0], NULL);
        op.b = g_ascii_strtod(toks[1], NULL);
        op.c = g_ascii_strtod(toks[2], NULL);
        if (parse_angle_any(toks[3], &op.d)) v = transform_value_one_op(&op);
    }
    for (int i = 0; i < nt; i++) g_free(toks[i]);
    return v;
}

/* Parses a scale factor from a number, percentage or math expression. */
static gboolean
parse_scale_number(const char *s, double *out)
{
    if (!s) return FALSE;
    while (*s && ns_is_ascii_ws(*s)) s++;
    if (!*s) return FALSE;
    char *end = NULL;
    double v = g_ascii_strtod(s, &end);
    if (end && end != s) {
        const char *p = end;
        while (*p && ns_is_ascii_ws(*p)) p++;
        if (*p == '\0') { *out = v; return TRUE; }
        if (*p == '%' && p[1] == '\0') { *out = v / 100.0; return TRUE; }
    }
    double px = 0, pct = 0;
    if (resolve_to_px_pct(s, strlen(s), &px, &pct)) {
        *out = px + pct / 100.0;
        return TRUE;
    }
    ns_css_value *cv = parse_calc(s);
    if (!cv) {
        char *w = g_strdup_printf("calc(%s)", s);
        cv = parse_calc(w);
        g_free(w);
    }
    if (cv && cv->kind == NS_CSS_V_LENGTH) {
        double val = cv->u.length.unit == NS_CSS_UNIT_PERCENT
                   ? cv->u.length.v / 100.0 : cv->u.length.v;
        ns_css_value_free(cv);
        *out = isnan(val) ? 0.0 : val;
        return TRUE;
    }
    if (cv) ns_css_value_free(cv);
    return FALSE;
}

/* Parses the individual scale property (one to three factors) into one scale op. */
static ns_css_value *
parse_scale_prop(const char *text)
{
    while (*text && ns_is_ascii_ws(*text)) text++;
    if (!*text || g_ascii_strcasecmp(text, "none") == 0) return NULL;
    char *toks[4] = {0};
    int nt = split_ws_limit(text, toks, 3);
    if (nt == 0) return NULL;
    ns_css_transform_op op;
    memset(&op, 0, sizeof(op));
    op.kind = NS_CSS_TFN_SCALE;
    gboolean ok = parse_scale_number(toks[0], &op.a);
    op.b = op.a;
    op.c = 1;
    if (ok && nt >= 2) ok = parse_scale_number(toks[1], &op.b);
    if (ok && nt >= 3) ok = parse_scale_number(toks[2], &op.c);
    for (int i = 0; i < nt; i++) g_free(toks[i]);
    if (!ok) return NULL;
    return transform_value_one_op(&op);
}

/* Appends a number for transform serialization; NaN as 0, infinities as calc(infinity). */
static void
append_scale_number(GString *s, double n)
{
    if (isnan(n)) {
        g_string_append_c(s, '0');
        return;
    }
    if (!isfinite(n)) {
        g_string_append(s, n < 0 ? "calc(-infinity)" : "calc(infinity)");
        return;
    }
    char *t = ns_css_number_str(n);
    g_string_append(s, t);
    g_free(t);
}

/* Reports whether a translate axis mixes percent or em/rem parts with px. */
static gboolean
translate_axis_is_mixed(const ns_css_transform_op *op, int axis)
{
    double pct = axis == 0 ? op->a_pct : axis == 1 ? op->b_pct : 0;
    return pct != 0 || op->em[axis] != 0 || op->rem[axis] != 0;
}

/* Serializes one translate axis as px, % or a calc() of its %/px/em/rem parts. */
static void
append_translate_length(GString *s, const ns_css_transform_op *op, int axis)
{
    double v = axis == 0 ? op->a : axis == 1 ? op->b : op->c;
    gboolean is_percent = axis == 0 ? op->a_is_percent
                        : axis == 1 && op->b_is_percent;
    if (is_percent || !translate_axis_is_mixed(op, axis)) {
        char *t = ns_css_number_str(v);
        g_string_append(s, t);
        g_free(t);
        g_string_append(s, is_percent ? "%" : "px");
        return;
    }
    const double parts[4] = {
        axis == 0 ? op->a_pct : axis == 1 ? op->b_pct : 0,
        v, op->em[axis], op->rem[axis],
    };
    static const char *const units[4] = { "%", "px", "em", "rem" };
    gboolean first = TRUE;
    g_string_append(s, "calc(");
    for (int k = 0; k < 4; k++) {
        if (parts[k] == 0) continue;
        if (!first) g_string_append(s, parts[k] < 0 ? " - " : " + ");
        char *t = ns_css_number_str(first ? parts[k] : fabs(parts[k]));
        g_string_append(s, t);
        g_free(t);
        g_string_append(s, units[k]);
        first = FALSE;
    }
    g_string_append_c(s, ')');
}

/* Serializes a translate, rotate or scale property value, omitting defaulted components. */
char *
ns_css_individual_transform_serialize(const ns_css_value *v, int prop)
{
    if (!v) return NULL;
    if (v->kind == NS_CSS_V_KEYWORD)
        return g_strdup(v->u.keyword);
    if (v->kind != NS_CSS_V_TRANSFORM || v->u.transform.n_ops < 1)
        return NULL;
    const ns_css_transform_op *op = &v->u.transform.ops[0];
    GString *s = g_string_new(NULL);
    if (prop == NS_CSS_SCALE) {
        gboolean ab_same = (op->a == op->b) || (isnan(op->a) && isnan(op->b));
        append_scale_number(s, op->a);
        if (op->c != 1) {
            g_string_append_c(s, ' ');
            append_scale_number(s, op->b);
            g_string_append_c(s, ' ');
            append_scale_number(s, op->c);
        } else if (!ab_same) {
            g_string_append_c(s, ' ');
            append_scale_number(s, op->b);
        }
    } else if (prop == NS_CSS_ROTATE) {
        if (op->kind == NS_CSS_TFN_ROTATE3D) {
            const char *axis = NULL;
            if (op->a == 1 && op->b == 0 && op->c == 0) axis = "x";
            else if (op->a == 0 && op->b == 1 && op->c == 0) axis = "y";
            else if (op->a == 0 && op->b == 0 && op->c == 1) axis = NULL;
            if (axis) {
                g_string_append(s, axis);
                g_string_append_c(s, ' ');
            } else if (!(op->a == 0 && op->b == 0 && op->c == 1)) {
                append_scale_number(s, op->a);
                g_string_append_c(s, ' ');
                append_scale_number(s, op->b);
                g_string_append_c(s, ' ');
                append_scale_number(s, op->c);
                g_string_append_c(s, ' ');
            }
            append_scale_number(s, op->d);
            g_string_append(s, "deg");
        } else {
            append_scale_number(s, op->a);
            g_string_append(s, "deg");
        }
    } else if (prop == NS_CSS_TRANSLATE) {
        append_translate_length(s, op, 0);
        gboolean need_c = op->c != 0 || translate_axis_is_mixed(op, 2);
        gboolean need_b = need_c || op->b != 0 || op->b_is_percent ||
                          translate_axis_is_mixed(op, 1);
        if (need_b) {
            g_string_append_c(s, ' ');
            append_translate_length(s, op, 1);
        }
        if (need_c) {
            g_string_append_c(s, ' ');
            append_translate_length(s, op, 2);
        }
    } else {
        g_string_free(s, TRUE);
        return NULL;
    }
    return g_string_free(s, FALSE);
}

gboolean
ns_css_transform_has_3d_function(const ns_css_transform *tf)
{
    if (!tf) return FALSE;
    for (int i = 0; i < tf->n_ops; i++)
        if (tf->ops[i].is_3d) return TRUE;
    return FALSE;
}

/* Reports whether a transform has a real 3D effect (z offset, z scale, off-axis rotation). */
gboolean
ns_css_transform_is_3d(const ns_css_transform *tf)
{
    if (!tf) return FALSE;
    for (int i = 0; i < tf->n_ops; i++) {
        const ns_css_transform_op *op = &tf->ops[i];
        switch (op->kind) {
        case NS_CSS_TFN_TRANSLATE:
            if (op->c != 0 || translate_axis_is_mixed(op, 2)) return TRUE;
            break;
        case NS_CSS_TFN_SCALE:
            if (op->c != 0 && op->c != 1) return TRUE;
            break;
        case NS_CSS_TFN_ROTATE3D:
            if (fabs(op->d) > 1e-12 && (op->a != 0 || op->b != 0)) return TRUE;
            break;
        case NS_CSS_TFN_MATRIX3D:
        case NS_CSS_TFN_PERSPECTIVE:
            return TRUE;
        default:
            break;
        }
    }
    return FALSE;
}

/* Concatenates translate, rotate, scale and then transform (or the override) into one list. */
void
ns_css_style_effective_transform(const ns_style *st,
                                 const ns_css_transform *transform_override,
                                 ns_css_transform *out)
{
    memset(out, 0, sizeof(*out));
    static const ns_css_prop independent[3] = {
        NS_CSS_TRANSLATE, NS_CSS_ROTATE, NS_CSS_SCALE,
    };
    for (int i = 0; i < 3; i++) {
        const ns_css_value *v = st ? st->values[independent[i]] : NULL;
        if (v && v->kind == NS_CSS_V_TRANSFORM && v->u.transform.n_ops > 0 &&
            out->n_ops < NS_CSS_TRANSFORM_OPS_MAX)
            out->ops[out->n_ops++] = v->u.transform.ops[0];
    }
    const ns_css_transform *tf = transform_override;
    if (!tf && st && st->values[NS_CSS_TRANSFORM] &&
        st->values[NS_CSS_TRANSFORM]->kind == NS_CSS_V_TRANSFORM)
        tf = &st->values[NS_CSS_TRANSFORM]->u.transform;
    if (tf)
        for (int i = 0; i < tf->n_ops && out->n_ops < NS_CSS_TRANSFORM_OPS_MAX; i++)
            out->ops[out->n_ops++] = tf->ops[i];
}

/* Builds a 4x4 matrix from transform ops; percentages resolve against the box size. */
void
ns_css_transform_to_mat4(const ns_css_transform *tf,
                         double bw, double bh, ns_mat4 *out)
{
    ns_mat4_identity(out);
    if (!tf) return;
    for (int i = 0; i < tf->n_ops; i++) {
        ns_css_transform_op sane = tf->ops[i];
        double dflt = sane.kind == NS_CSS_TFN_SCALE ? 1.0 : 0.0;
        double *fields[] = { &sane.a, &sane.b, &sane.c, &sane.d,
                             &sane.e, &sane.f, &sane.a_pct, &sane.b_pct,
                             &sane.em[0], &sane.em[1], &sane.em[2],
                             &sane.rem[0], &sane.rem[1], &sane.rem[2] };
        for (gsize k = 0; k < G_N_ELEMENTS(fields); k++)
            if (!isfinite(*fields[k])) *fields[k] = dflt;
        const ns_css_transform_op *op = &sane;
        switch (op->kind) {
        case NS_CSS_TFN_TRANSLATE: {
            double dx = (op->a_is_percent ? op->a / 100.0 * bw : op->a) +
                        op->a_pct / 100.0 * bw +
                        (op->em[0] + op->rem[0]) * 16.0;
            double dy = (op->b_is_percent ? op->b / 100.0 * bh : op->b) +
                        op->b_pct / 100.0 * bh +
                        (op->em[1] + op->rem[1]) * 16.0;
            double dz = op->c + (op->em[2] + op->rem[2]) * 16.0;
            ns_mat4_translate(out, dx, dy, dz);
            break;
        }
        case NS_CSS_TFN_ROTATE:
            ns_mat4_rotate_axis(out, 0, 0, 1, op->a);
            break;
        case NS_CSS_TFN_ROTATE3D:
            ns_mat4_rotate_axis(out, op->a, op->b, op->c, op->d);
            break;
        case NS_CSS_TFN_SCALE:
            ns_mat4_scale(out, op->a, op->b, op->c == 0 ? 1 : op->c);
            break;
        case NS_CSS_TFN_SKEW:
            ns_mat4_skew(out, op->a, op->b);
            break;
        case NS_CSS_TFN_MATRIX:
            ns_mat4_affine2d(out, op->a, op->b, op->c, op->d, op->e, op->f);
            break;
        case NS_CSS_TFN_MATRIX3D: {
            ns_mat4 t;
            for (int row = 0; row < 4; row++)
                for (int col = 0; col < 4; col++)
                    t.m[row * 4 + col] = op->m3d[col * 4 + row];
            ns_mat4_multiply(out, &t, out);
            break;
        }
        case NS_CSS_TFN_PERSPECTIVE:
            ns_mat4_perspective(out, op->a);
            break;
        }
    }
}

/* Maps an easing keyword (linear, ease*, step-start/end) to a timing function; default ease. */
static ns_css_timing
parse_timing_keyword(const char *kw)
{
    ns_css_timing t = { .kind = NS_CSS_TIMING_EASE };
    if (!kw) return t;
    if (g_ascii_strcasecmp(kw, "linear") == 0)        t.kind = NS_CSS_TIMING_LINEAR;
    else if (g_ascii_strcasecmp(kw, "ease") == 0)     t.kind = NS_CSS_TIMING_EASE;
    else if (g_ascii_strcasecmp(kw, "ease-in") == 0)  t.kind = NS_CSS_TIMING_EASE_IN;
    else if (g_ascii_strcasecmp(kw, "ease-out") == 0) t.kind = NS_CSS_TIMING_EASE_OUT;
    else if (g_ascii_strcasecmp(kw, "ease-in-out") == 0) t.kind = NS_CSS_TIMING_EASE_IN_OUT;
    else if (g_ascii_strcasecmp(kw, "step-start") == 0) {
        t.kind = NS_CSS_TIMING_STEPS; t.steps = 1; t.step_pos = NS_CSS_STEP_JUMP_START;
    } else if (g_ascii_strcasecmp(kw, "step-end") == 0) {
        t.kind = NS_CSS_TIMING_STEPS; t.steps = 1; t.step_pos = NS_CSS_STEP_JUMP_END;
    }
    return t;
}

static gboolean
timing_keyword_matches(const char *kw)
{
    return g_ascii_strcasecmp(kw, "linear") == 0 ||
           g_ascii_strcasecmp(kw, "ease") == 0 ||
           g_ascii_strcasecmp(kw, "ease-in") == 0 ||
           g_ascii_strcasecmp(kw, "ease-out") == 0 ||
           g_ascii_strcasecmp(kw, "ease-in-out") == 0 ||
           g_ascii_strcasecmp(kw, "step-start") == 0 ||
           g_ascii_strcasecmp(kw, "step-end") == 0;
}

/* Parses a time token with s or ms units into milliseconds. */
static gboolean
parse_time_ms(const char *tok, double *out_ms)
{
    if (!tok) return FALSE;
    char *end = NULL;
    double v = g_ascii_strtod(tok, &end);
    if (end == tok) return FALSE;
    if (g_ascii_strcasecmp(end, "ms") == 0)      *out_ms = v;
    else if (g_ascii_strcasecmp(end, "s") == 0)  *out_ms = v * 1000.0;
    else return FALSE;
    return TRUE;
}

static gboolean css_time_seconds(const char *s, const char *e, double *out);
static gboolean css_starts_math_fn(const char *s, const char *e);
static char *css_time_text(double ms);
static char *anim_string_decode(const char *tok);
static gboolean list_style_split(const char *text, char **out_type,
                                 char **out_position, char **out_image);
static char *css_inline_value_canonical(const char *prop, char *value);
static char *anim_ident_decode(const char *tok);
static int prop_id(const char *name);
static ns_css_value *parse_anim_value(const char *text, gboolean is_animation);
static const char *anim_target_text(const ns_css_anim_entry *e);
static char *anim_entry_longhand_text(const ns_css_anim_entry *e, ns_css_prop lh);
static gboolean anim_range_shorthand_expand(const char *text, char **out_start, char **out_end);
static gboolean anim_range_item_canonical(const char *item, gboolean is_end, char **out);
static gboolean css_time_value(const char *s, const char *e, double *out_ms);

/* Splits a comma-separated animation/transition list into trimmed new strings. */
static int
anim_list_split(const char *text, char *items[], int max)
{
    int n = 0;
    if (!text) return 0;
    const char *end = text + strlen(text);
    const char *p = text;
    while (p <= end && n < max) {
        char term = 0;
        const char *seg = css_scan_until(p, end, ",", &term);
        items[n++] = css_trim_dup_range(p, seg);
        if (term != ',') break;
        p = seg + 1;
    }
    return n;
}

static gboolean timing_item_parse(const char *item, ns_css_timing *out);

/* Parses an easing function string (keyword, linear(), steps(), cubic-bezier()). */
gboolean
ns_css_timing_parse(const char *text, ns_css_timing *out)
{
    if (!text || !out) return FALSE;
    char *t = g_strstrip(g_strdup(text));
    gboolean ok = timing_item_parse(t, out);
    g_free(t);
    return ok;
}

/* Parses one easing function; steps() validates jump keyword and cubic-bezier x range. */
static gboolean
timing_item_parse(const char *item, ns_css_timing *out)
{
    if (!item || !*item) return FALSE;
    if (timing_keyword_matches(item)) {
        *out = parse_timing_keyword(item);
        return TRUE;
    }
    if (g_ascii_strncasecmp(item, "linear(", 7) == 0 && item[strlen(item) - 1] == ')') {
        *out = (ns_css_timing){ .kind = NS_CSS_TIMING_LINEAR };
        return TRUE;
    }
    gboolean is_steps = g_ascii_strncasecmp(item, "steps(", 6) == 0;
    gboolean is_cubic = g_ascii_strncasecmp(item, "cubic-bezier(", 13) == 0;
    if ((!is_steps && !is_cubic) || item[strlen(item) - 1] != ')') return FALSE;
    char *body = g_strndup(item + (is_steps ? 6 : 13), strlen(item) - (is_steps ? 7 : 14));
    char **parts = g_strsplit(body, ",", -1);
    guint np = g_strv_length(parts);
    gboolean ok = FALSE;
    if (is_steps && (np == 1 || np == 2)) {
        char *e = NULL;
        long n = strtol(g_strstrip(parts[0]), &e, 10);
        if (e != parts[0] && *e == '\0' && n >= 1) {
            ns_css_step_pos pos = NS_CSS_STEP_JUMP_END;
            ok = TRUE;
            gboolean jump_kw = FALSE;
            if (np == 2) {
                const char *k = g_strstrip(parts[1]);
                jump_kw = g_ascii_strncasecmp(k, "jump-", 5) == 0;
                if (g_ascii_strcasecmp(k, "jump-start") == 0 ||
                    g_ascii_strcasecmp(k, "start") == 0) pos = NS_CSS_STEP_JUMP_START;
                else if (g_ascii_strcasecmp(k, "jump-end") == 0 ||
                         g_ascii_strcasecmp(k, "end") == 0) pos = NS_CSS_STEP_JUMP_END;
                else if (g_ascii_strcasecmp(k, "jump-none") == 0) pos = NS_CSS_STEP_JUMP_NONE;
                else if (g_ascii_strcasecmp(k, "jump-both") == 0) pos = NS_CSS_STEP_JUMP_BOTH;
                else ok = FALSE;
            }
            if (ok && pos == NS_CSS_STEP_JUMP_NONE && n < 2) ok = FALSE;
            if (ok) *out = (ns_css_timing){ .kind = NS_CSS_TIMING_STEPS,
                                            .steps = (int)n, .step_pos = pos,
                                            .jump_keyword = jump_kw };
        }
    } else if (is_cubic && np == 4) {
        double cb[4];
        ok = TRUE;
        for (int i = 0; i < 4 && ok; i++) {
            char *e = NULL;
            cb[i] = g_ascii_strtod(g_strstrip(parts[i]), &e);
            if (e == parts[i] || *e != '\0') ok = FALSE;
        }
        if (ok && (cb[0] < 0 || cb[0] > 1 || cb[2] < 0 || cb[2] > 1)) ok = FALSE;
        if (ok) {
            *out = (ns_css_timing){ .kind = NS_CSS_TIMING_CUBIC };
            memcpy(out->cb, cb, sizeof cb);
        }
    }
    g_strfreev(parts);
    g_free(body);
    return ok;
}

/* Reports whether item is a CSS-wide keyword or "default" (invalid as a custom-ident). */
static gboolean
css_wide_keyword_or_default(const char *item)
{
    static const char *const words[] = { "initial", "inherit", "unset", "revert",
                                         "revert-layer", "default" };
    for (gsize i = 0; i < G_N_ELEMENTS(words); i++)
        if (g_ascii_strcasecmp(item, words[i]) == 0) return TRUE;
    return FALSE;
}

/* Validates one list item for an animation or transition longhand. */
static gboolean
anim_longhand_item_valid(ns_css_prop prop, const char *item)
{
    ns_css_timing tm;
    char *e = NULL;
    double num;
    switch (prop) {
    case NS_CSS_ANIMATION_NAME:
        if (g_ascii_strcasecmp(item, "none") == 0) return TRUE;
        if (item[0] == '"' || item[0] == '\'') return strlen(item) >= 3 &&
            item[strlen(item) - 1] == item[0];
        {
            char *ident = anim_ident_decode(item);
            gboolean ok = ident && *ident && !css_wide_keyword_or_default(ident) &&
                          !g_ascii_isdigit((guchar)item[0]) &&
                          !(item[0] == '-' && g_ascii_isdigit((guchar)item[1]));
            g_free(ident);
            return ok;
        }
    case NS_CSS_ANIMATION_TIMING_FUNCTION:
    case NS_CSS_TRANSITION_TIMING_FUNCTION:
        return timing_item_parse(item, &tm);
    case NS_CSS_ANIMATION_ITERATION_COUNT:
        if (g_ascii_strcasecmp(item, "infinite") == 0) return TRUE;
        num = g_ascii_strtod(item, &e);
        return e != item && *e == '\0' && num >= 0;
    case NS_CSS_ANIMATION_DIRECTION:
        return g_ascii_strcasecmp(item, "normal") == 0 ||
               g_ascii_strcasecmp(item, "reverse") == 0 ||
               g_ascii_strcasecmp(item, "alternate") == 0 ||
               g_ascii_strcasecmp(item, "alternate-reverse") == 0;
    case NS_CSS_ANIMATION_FILL_MODE:
        return g_ascii_strcasecmp(item, "none") == 0 ||
               g_ascii_strcasecmp(item, "forwards") == 0 ||
               g_ascii_strcasecmp(item, "backwards") == 0 ||
               g_ascii_strcasecmp(item, "both") == 0;
    case NS_CSS_TRANSITION_PROPERTY:
        return g_ascii_strcasecmp(item, "none") == 0 ||
               g_ascii_strcasecmp(item, "all") == 0 ||
               (content_ident_valid(item) && !css_wide_keyword_or_default(item));
    case NS_CSS_TRANSITION_BEHAVIOR:
        return g_ascii_strcasecmp(item, "normal") == 0 ||
               g_ascii_strcasecmp(item, "allow-discrete") == 0;
    case NS_CSS_ANIMATION_PLAY_STATE:
        return g_ascii_strcasecmp(item, "running") == 0 ||
               g_ascii_strcasecmp(item, "paused") == 0;
    case NS_CSS_ANIMATION_COMPOSITION:
        return g_ascii_strcasecmp(item, "replace") == 0 ||
               g_ascii_strcasecmp(item, "add") == 0 ||
               g_ascii_strcasecmp(item, "accumulate") == 0;
    case NS_CSS_ANIMATION_TIMELINE:
        if (g_ascii_strcasecmp(item, "auto") == 0 ||
            g_ascii_strcasecmp(item, "none") == 0) return TRUE;
        if (item[0] == '-' && item[1] == '-') return content_ident_valid(item);
        return (g_ascii_strncasecmp(item, "scroll(", 7) == 0 ||
                g_ascii_strncasecmp(item, "view(", 5) == 0) &&
               item[strlen(item) - 1] == ')';
    case NS_CSS_ANIMATION_RANGE_START:
    case NS_CSS_ANIMATION_RANGE_END:
        return anim_range_item_canonical(item, prop == NS_CSS_ANIMATION_RANGE_END,
                                         NULL);
    default:
        return FALSE;
    }
}

static const char *const kTimelineRangeNames[] = {
    "cover", "contain", "entry", "exit", "entry-crossing", "exit-crossing",
};

static gboolean
anim_range_is_name(const char *tok)
{
    for (gsize i = 0; i < G_N_ELEMENTS(kTimelineRangeNames); i++)
        if (g_ascii_strcasecmp(tok, kTimelineRangeNames[i]) == 0) return TRUE;
    return FALSE;
}

/* Canonicalizes an animation-range length-percentage, rejecting time and angle units. */
static char *
anim_range_lp_canonical(const char *tok)
{
    if (!tok || !*tok) return NULL;
    if (css_starts_math_fn(tok, tok + strlen(tok))) {
        char *m = ns_css_math_canonical(tok);
        if (!m) {
            gsize len = strlen(tok);
            if (len < 3 || tok[len - 1] != ')' || strstr(tok, "s)") || strstr(tok, "deg"))
                return NULL;
            return g_strdup(tok);
        }
        static const char *const bad_units[] = { "s", "ms", "deg", "rad", "turn", "hz" };
        if (math_text_has_unit(m, bad_units, G_N_ELEMENTS(bad_units))) {
            g_free(m);
            return NULL;
        }
        return m;
    }
    double v;
    ns_css_unit u;
    if (!parse_length(tok, &v, &u)) return NULL;
    if (u == NS_CSS_UNIT_NUMBER) {
        if (v != 0) return NULL;
        return g_strdup("0px");
    }
    char *unit_start = NULL;
    g_ascii_strtod(tok, &unit_start);
    char *num = ns_css_number_str(v);
    char *unit = g_ascii_strdown(unit_start, -1);
    char *r = g_strconcat(num, unit, NULL);
    g_free(num);
    g_free(unit);
    return r;
}

/* Canonicalizes an animation-range-start/end item; drops the default 0%/100% offset. */
static gboolean
anim_range_item_canonical(const char *item, gboolean is_end, char **out)
{
    char *toks[4] = { 0 };
    int n = split_ws_limit(item, toks, 4);
    gboolean ok = FALSE;
    char *result = NULL;
    if (n == 1 && g_ascii_strcasecmp(toks[0], "normal") == 0) {
        ok = TRUE;
        result = g_strdup("normal");
    } else if (n == 1 && anim_range_is_name(toks[0])) {
        ok = TRUE;
        result = g_ascii_strdown(toks[0], -1);
    } else if (n == 1) {
        result = anim_range_lp_canonical(toks[0]);
        ok = result != NULL;
    } else if (n == 2 && anim_range_is_name(toks[0])) {
        char *lp = anim_range_lp_canonical(toks[1]);
        if (lp) {
            ok = TRUE;
            const char *dflt = is_end ? "100%" : "0%";
            char *name = g_ascii_strdown(toks[0], -1);
            result = strcmp(lp, dflt) == 0 ? g_strdup(name)
                                           : g_strconcat(name, " ", lp, NULL);
            g_free(name);
            g_free(lp);
        }
    }
    for (int i = 0; i < n; i++) g_free(toks[i]);
    if (out) *out = ok ? result : NULL;
    else g_free(result);
    return ok;
}

/* Validates animation-duration items (auto or time) and stores the canonical list text. */
static ns_css_value *
parse_animation_duration(const char *t)
{
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = anim_list_split(t, items, (int)G_N_ELEMENTS(items));
    gboolean ok = n > 0;
    GString *canon = g_string_new(NULL);
    for (int i = 0; i < n; i++) {
        if (ok) {
            if (i) g_string_append(canon, ", ");
            char *spec = NULL;
            if (g_ascii_strcasecmp(items[i], "auto") == 0) {
                g_string_append(canon, "auto");
            } else if ((spec = ns_css_time_specified(items[i]))) {
                g_string_append(canon, spec);
                g_free(spec);
            } else if (css_time_value(items[i], items[i] + strlen(items[i]), NULL)) {
                g_string_append(canon, items[i]);
            } else {
                ok = FALSE;
            }
        }
        g_free(items[i]);
    }
    if (!ok) {
        g_string_free(canon, TRUE);
        return NULL;
    }
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_KEYWORD;
    v->u.keyword = g_string_free(canon, FALSE);
    return v;
}

/* Serializes an identifier per CSSOM, escaping leading digits and special characters. */
static char *
ns_css_ident_serialize(const char *name)
{
    if (!name) return g_strdup("");
    GString *out = g_string_new(NULL);
    for (const char *p = name; *p; p++) {
        guchar c = (guchar)*p;
        gboolean first = p == name;
        if (c == '\0') {
            g_string_append(out, "\xef\xbf\xbd");
        } else if (c <= 0x1f || c == 0x7f) {
            g_string_append_printf(out, "\\%x ", c);
        } else if (first && g_ascii_isdigit(c)) {
            g_string_append_printf(out, "\\%x ", c);
        } else if (first && c == '-' && g_ascii_isdigit((guchar)p[1])) {
            g_string_append_c(out, '-');
            p++;
            g_string_append_printf(out, "\\%x ", (guchar)*p);
        } else if (first && c == '-' && !p[1]) {
            g_string_append(out, "\\-");
        } else if (c >= 0x80 || c == '-' || c == '_' || g_ascii_isalnum(c)) {
            g_string_append_c(out, (char)c);
        } else {
            g_string_append_c(out, '\\');
            g_string_append_c(out, (char)c);
        }
    }
    return g_string_free(out, FALSE);
}

/* Validates and canonicalizes an animation/transition longhand list into keyword text. */
static ns_css_value *
parse_anim_longhand(ns_css_prop prop, const char *t)
{
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = anim_list_split(t, items, (int)G_N_ELEMENTS(items));
    gboolean ok = n > 0;
    gboolean lower = prop != NS_CSS_ANIMATION_NAME && prop != NS_CSS_ANIMATION_TIMELINE;
    gboolean range = prop == NS_CSS_ANIMATION_RANGE_START ||
                     prop == NS_CSS_ANIMATION_RANGE_END;
    GString *canon = g_string_new(NULL);
    for (int i = 0; i < n; i++) {
        if (!*items[i] || !anim_longhand_item_valid(prop, items[i])) ok = FALSE;
        if (ok && n > 1 && prop == NS_CSS_TRANSITION_PROPERTY &&
            g_ascii_strcasecmp(items[i], "none") == 0) ok = FALSE;
        if (ok) {
            if (i) g_string_append(canon, ", ");
            if (range) {
                char *c = NULL;
                anim_range_item_canonical(items[i], prop == NS_CSS_ANIMATION_RANGE_END, &c);
                g_string_append(canon, c ? c : items[i]);
                g_free(c);
            } else if (prop == NS_CSS_ANIMATION_NAME) {
                if (g_ascii_strcasecmp(items[i], "none") == 0) g_string_append(canon, "none");
                else if (items[i][0] == '"' || items[i][0] == '\'') {
                    char *inner = anim_string_decode(items[i]);
                    if (css_wide_keyword_or_default(inner) ||
                        g_ascii_strcasecmp(inner, "none") == 0) {
                        g_string_append_c(canon, '"');
                        g_string_append(canon, inner);
                        g_string_append_c(canon, '"');
                    } else {
                        char *ident = ns_css_ident_serialize(inner);
                        g_string_append(canon, ident);
                        g_free(ident);
                    }
                    g_free(inner);
                } else {
                    char *ident = anim_ident_decode(items[i]);
                    char *ser = ns_css_ident_serialize(ident ? ident : items[i]);
                    g_string_append(canon, ser);
                    g_free(ser);
                    g_free(ident);
                }
            } else if (lower) {
                char *l = g_ascii_strdown(items[i], -1);
                g_string_append(canon, l);
                g_free(l);
            } else {
                g_string_append(canon, items[i]);
            }
        }
        g_free(items[i]);
    }
    if (!ok) {
        g_string_free(canon, TRUE);
        return NULL;
    }
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_KEYWORD;
    v->u.keyword = g_string_free(canon, FALSE);
    return v;
}

/* Resets an animation entry to defaults: target all, ease timing, one iteration. */
static void
anim_entry_init(ns_css_anim_entry *e)
{
    memset(e, 0, sizeof *e);
    e->target = NS_CSS_ANIM_TARGET_ALL;
    e->timing = (ns_css_timing){ .kind = NS_CSS_TIMING_EASE };
    e->iterations = 1;
}

/* Sets an entry's animation name or transition-property target from a token. */
static void
anim_entry_set_target(ns_css_anim_entry *e, const char *tok, gboolean is_animation)
{
    g_free(e->name);
    e->name = NULL;
    if (is_animation) {
        e->target = NS_CSS_ANIM_TARGET_ALL;
        if (g_ascii_strcasecmp(tok, "none") != 0) {
            if ((tok[0] == '"' || tok[0] == '\'') && strlen(tok) >= 2)
                e->name = anim_string_decode(tok);
            else {
                e->name = anim_ident_decode(tok);
                if (!e->name) e->name = g_strdup(tok);
            }
        }
        return;
    }
    if (g_ascii_strcasecmp(tok, "none") == 0) e->target = NS_CSS_ANIM_TARGET_NONE;
    else if (g_ascii_strcasecmp(tok, "all") == 0) e->target = NS_CSS_ANIM_TARGET_ALL;
    else if (g_ascii_strcasecmp(tok, "opacity") == 0) e->target = NS_CSS_ANIM_TARGET_OPACITY;
    else if (g_ascii_strcasecmp(tok, "transform") == 0) e->target = NS_CSS_ANIM_TARGET_TRANSFORM;
    else if (g_ascii_strcasecmp(tok, "color") == 0) e->target = NS_CSS_ANIM_TARGET_COLOR;
    else if (g_ascii_strcasecmp(tok, "background-color") == 0 ||
             g_ascii_strcasecmp(tok, "background") == 0)
        e->target = NS_CSS_ANIM_TARGET_BG_COLOR;
    else {
        e->target = NS_CSS_ANIM_TARGET_OTHER;
        e->name = ascii_lower(tok, strlen(tok));
    }
}

/* Applies a longhand list to entries, cycling items when the list is shorter. */
static void
anim_apply_longhand(ns_css_anim_list *out, const ns_css_value *v, ns_css_prop prop)
{
    if (!v || v->kind != NS_CSS_V_KEYWORD || !v->u.keyword || out->n == 0) return;
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = anim_list_split(v->u.keyword, items, (int)G_N_ELEMENTS(items));
    if (n == 0) return;
    for (int i = 0; i < out->n; i++) {
        ns_css_anim_entry *e = &out->entries[i];
        const char *item = items[i % n];
        double sec;
        switch (prop) {
        case NS_CSS_ANIMATION_DURATION:
        case NS_CSS_TRANSITION_DURATION:
            if (g_ascii_strcasecmp(item, "auto") == 0) {
                e->duration_ms = 0;
                e->duration_auto = TRUE;
            } else if (css_time_seconds(item, item + strlen(item), &sec) && isfinite(sec)) {
                e->duration_ms = MAX(sec, 0.0) * 1000.0;
                e->duration_auto = FALSE;
            }
            break;
        case NS_CSS_ANIMATION_DELAY:
        case NS_CSS_TRANSITION_DELAY:
            if (css_time_seconds(item, item + strlen(item), &sec) && isfinite(sec))
                e->delay_ms = sec * 1000.0;
            break;
        case NS_CSS_ANIMATION_TIMING_FUNCTION:
        case NS_CSS_TRANSITION_TIMING_FUNCTION:
            timing_item_parse(item, &e->timing);
            break;
        case NS_CSS_ANIMATION_ITERATION_COUNT:
            if (g_ascii_strcasecmp(item, "infinite") == 0) {
                e->iterations = INFINITY;
            } else {
                double num = g_ascii_strtod(item, NULL);
                e->iterations = num < 0 ? 0 : num;
            }
            break;
        case NS_CSS_ANIMATION_DIRECTION:
            if (g_ascii_strcasecmp(item, "reverse") == 0) e->direction = NS_CSS_ANIM_DIR_REVERSE;
            else if (g_ascii_strcasecmp(item, "alternate") == 0) e->direction = NS_CSS_ANIM_DIR_ALTERNATE;
            else if (g_ascii_strcasecmp(item, "alternate-reverse") == 0)
                e->direction = NS_CSS_ANIM_DIR_ALTERNATE_REVERSE;
            else e->direction = NS_CSS_ANIM_DIR_NORMAL;
            break;
        case NS_CSS_ANIMATION_FILL_MODE:
            if (g_ascii_strcasecmp(item, "forwards") == 0) e->fill = NS_CSS_ANIM_FILL_FORWARDS;
            else if (g_ascii_strcasecmp(item, "backwards") == 0) e->fill = NS_CSS_ANIM_FILL_BACKWARDS;
            else if (g_ascii_strcasecmp(item, "both") == 0) e->fill = NS_CSS_ANIM_FILL_BOTH;
            else e->fill = NS_CSS_ANIM_FILL_NONE;
            break;
        case NS_CSS_ANIMATION_PLAY_STATE:
            e->paused = g_ascii_strcasecmp(item, "paused") == 0;
            break;
        case NS_CSS_TRANSITION_BEHAVIOR:
            e->allow_discrete = g_ascii_strcasecmp(item, "allow-discrete") == 0;
            break;
        default:
            break;
        }
    }
    for (int i = 0; i < n; i++) g_free(items[i]);
}

void
ns_css_anim_list_clear(ns_css_anim_list *list)
{
    if (!list) return;
    for (int i = 0; i < list->n; i++) g_free(list->entries[i].name);
    list->n = 0;
}

/* Returns the number of comma-separated items in a longhand's keyword value. */
static int
anim_longhand_count(const ns_css_value *v)
{
    if (!v || v->kind != NS_CSS_V_KEYWORD || !v->u.keyword) return 0;
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = anim_list_split(v->u.keyword, items, (int)G_N_ELEMENTS(items));
    for (int i = 0; i < n; i++) g_free(items[i]);
    return n;
}

/* Builds n animation or transition entries from the style's longhand values. */
static void
anim_build_list(const ns_style *s, gboolean is_animation, int n,
                ns_css_anim_list *out)
{
    memset(out, 0, sizeof *out);
    if (n > NS_CSS_ANIM_ENTRIES_MAX) n = NS_CSS_ANIM_ENTRIES_MAX;
    for (int i = 0; i < n; i++) anim_entry_init(&out->entries[i]);
    out->n = n;
    if (n == 0) return;
    const ns_css_value *names =
        s->values[is_animation ? NS_CSS_ANIMATION_NAME : NS_CSS_TRANSITION_PROPERTY];
    if (names && names->kind == NS_CSS_V_KEYWORD && names->u.keyword) {
        char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
        int k = anim_list_split(names->u.keyword, items, (int)G_N_ELEMENTS(items));
        for (int i = 0; i < n && k > 0; i++)
            anim_entry_set_target(&out->entries[i], items[i % k], is_animation);
        for (int i = 0; i < k; i++) g_free(items[i]);
    } else if (is_animation) {
        for (int i = 0; i < n; i++) out->entries[i].name = NULL;
    }
    if (is_animation) {
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_DURATION], NS_CSS_ANIMATION_DURATION);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_DELAY], NS_CSS_ANIMATION_DELAY);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_TIMING_FUNCTION],
                            NS_CSS_ANIMATION_TIMING_FUNCTION);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_ITERATION_COUNT],
                            NS_CSS_ANIMATION_ITERATION_COUNT);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_DIRECTION], NS_CSS_ANIMATION_DIRECTION);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_FILL_MODE], NS_CSS_ANIMATION_FILL_MODE);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_PLAY_STATE], NS_CSS_ANIMATION_PLAY_STATE);
    } else {
        anim_apply_longhand(out, s->values[NS_CSS_TRANSITION_DURATION], NS_CSS_TRANSITION_DURATION);
        anim_apply_longhand(out, s->values[NS_CSS_TRANSITION_DELAY], NS_CSS_TRANSITION_DELAY);
        anim_apply_longhand(out, s->values[NS_CSS_TRANSITION_TIMING_FUNCTION],
                            NS_CSS_TRANSITION_TIMING_FUNCTION);
        anim_apply_longhand(out, s->values[NS_CSS_TRANSITION_BEHAVIOR], NS_CSS_TRANSITION_BEHAVIOR);
    }
}

/* Returns the longhand property list for animation or transition shorthands. */
static const ns_css_prop *
anim_longhand_props(gboolean is_animation, gsize *n)
{
    static const ns_css_prop anim[] = {
        NS_CSS_ANIMATION_NAME, NS_CSS_ANIMATION_DURATION, NS_CSS_ANIMATION_DELAY,
        NS_CSS_ANIMATION_TIMING_FUNCTION, NS_CSS_ANIMATION_ITERATION_COUNT,
        NS_CSS_ANIMATION_DIRECTION, NS_CSS_ANIMATION_FILL_MODE,
        NS_CSS_ANIMATION_PLAY_STATE,
    };
    static const ns_css_prop trans[] = {
        NS_CSS_TRANSITION_PROPERTY, NS_CSS_TRANSITION_DURATION,
        NS_CSS_TRANSITION_DELAY, NS_CSS_TRANSITION_TIMING_FUNCTION,
        NS_CSS_TRANSITION_BEHAVIOR,
    };
    *n = is_animation ? G_N_ELEMENTS(anim) : G_N_ELEMENTS(trans);
    return is_animation ? anim : trans;
}

/* Reports whether a style sets animation-name or any transition longhand. */
gboolean
ns_css_style_has_anim(const ns_style *s)
{
    if (!s) return FALSE;
    if (s->values[NS_CSS_ANIMATION_NAME]) return TRUE;
    gsize count;
    const ns_css_prop *lh = anim_longhand_props(FALSE, &count);
    for (gsize i = 0; i < count; i++)
        if (s->values[lh[i]]) return TRUE;
    return FALSE;
}

/* Builds the effective animation/transition list sized by the name/property list. */
void
ns_css_anim_effective(const ns_style *s, gboolean is_animation, ns_css_anim_list *out)
{
    memset(out, 0, sizeof *out);
    if (!s) return;
    int n;
    if (is_animation) {
        n = anim_longhand_count(s->values[NS_CSS_ANIMATION_NAME]);
    } else {
        n = anim_longhand_count(s->values[NS_CSS_TRANSITION_PROPERTY]);
        if (!s->values[NS_CSS_TRANSITION_PROPERTY]) {
            gsize count;
            const ns_css_prop *lh = anim_longhand_props(FALSE, &count);
            for (gsize i = 0; i < count; i++)
                n = MAX(n, anim_longhand_count(s->values[lh[i]]));
        }
    }
    anim_build_list(s, is_animation, n, out);
}

/* Builds entries sized by the longest longhand list; flags mismatched list lengths. */
void
ns_css_anim_lists(const ns_style *s, gboolean is_animation, ns_css_anim_list *out,
                  gboolean *out_mismatch)
{
    memset(out, 0, sizeof *out);
    if (out_mismatch) *out_mismatch = FALSE;
    if (!s) return;
    gsize count;
    const ns_css_prop *lh = anim_longhand_props(is_animation, &count);
    int n = 0;
    for (gsize i = 0; i < count; i++)
        n = MAX(n, anim_longhand_count(s->values[lh[i]]));
    for (gsize i = 0; i < count; i++) {
        int c = anim_longhand_count(s->values[lh[i]]);
        if (c > 0 && c != n && out_mismatch) *out_mismatch = TRUE;
    }
    anim_build_list(s, is_animation, n, out);
}

/* Appends a space-separated part to a shorthand string and frees the part. */
static void
anim_append_part(GString *out, char *part)
{
    if (out->len > 0 && out->str[out->len - 1] != ' ' && out->str[out->len - 1] != ',')
        g_string_append_c(out, ' ');
    g_string_append(out, part);
    g_free(part);
}

/* Serializes animation/transition entries as shorthands, omitting default components. */
char *
ns_css_anim_shorthand_serialize(const ns_css_anim_list *list, gboolean is_animation)
{
    GString *out = g_string_new(NULL);
    if (!list || list->n == 0) return g_string_free(out, FALSE);
    for (int i = 0; i < list->n; i++) {
        const ns_css_anim_entry *e = &list->entries[i];
        if (i) g_string_append(out, ", ");
        GString *entry = g_string_new(NULL);
        if (is_animation) {
            if (!e->duration_auto || e->delay_ms != 0)
                anim_append_part(entry, anim_entry_longhand_text(e, NS_CSS_ANIMATION_DURATION));
            if (e->timing.kind != NS_CSS_TIMING_EASE)
                anim_append_part(entry, ns_css_timing_serialize(&e->timing));
            if (e->delay_ms != 0)
                anim_append_part(entry, css_time_text(e->delay_ms));
            if (e->iterations != 1)
                anim_append_part(entry, anim_entry_longhand_text(e, NS_CSS_ANIMATION_ITERATION_COUNT));
            if (e->direction != NS_CSS_ANIM_DIR_NORMAL)
                anim_append_part(entry, anim_entry_longhand_text(e, NS_CSS_ANIMATION_DIRECTION));
            if (e->fill != NS_CSS_ANIM_FILL_NONE)
                anim_append_part(entry, anim_entry_longhand_text(e, NS_CSS_ANIMATION_FILL_MODE));
            if (e->paused)
                anim_append_part(entry, g_strdup("paused"));
            if (e->name)
                anim_append_part(entry, ns_css_ident_serialize(e->name));
            if (entry->len == 0) g_string_append(entry, "none");
        } else {
            if (e->target != NS_CSS_ANIM_TARGET_ALL)
                anim_append_part(entry, g_strdup(anim_target_text(e)));
            if (e->duration_ms != 0 || e->delay_ms != 0)
                anim_append_part(entry, css_time_text(e->duration_ms));
            if (e->timing.kind != NS_CSS_TIMING_EASE)
                anim_append_part(entry, ns_css_timing_serialize(&e->timing));
            if (e->delay_ms != 0)
                anim_append_part(entry, css_time_text(e->delay_ms));
            if (e->allow_discrete)
                anim_append_part(entry, g_strdup("allow-discrete"));
            if (entry->len == 0) g_string_append(entry, "all");
        }
        g_string_append(out, entry->str);
        g_string_free(entry, TRUE);
    }
    return g_string_free(out, FALSE);
}

/* Canonicalizes animation/transition shorthand text by parsing and re-serializing it. */
static char *
ns_css_animation_shorthand_canonical(const char *text, gboolean is_animation)
{
    ns_css_value *v = parse_anim_value(text, is_animation);
    if (!v) return NULL;
    char *r = ns_css_anim_shorthand_serialize(&v->u.anim, is_animation);
    ns_css_value_free(v);
    return r;
}

