static void style_memo_forget(const ns_node *node);

/* Drops all cached state and dirty marks referring to a node about to be freed. */
void
ns_css_forget_node(const ns_node *node)
{
    if (g_css_focus_node == node) g_css_focus_node = NULL;
    if (g_css_focus_visible_node == node) g_css_focus_visible_node = NULL;
    if (g_css_hover_node == node) g_css_hover_node = NULL;
    if (g_css_active_node == node) g_css_active_node = NULL;
    if (g_incr_prev_focus == node || g_incr_prev_hover == node ||
        g_incr_prev_active == node) {
        g_incr_prev_focus = NULL;
        g_incr_prev_hover = NULL;
        g_incr_prev_active = NULL;
        g_incr_prev_doc = NULL;
    }
    if (g_incr_dirty) g_hash_table_remove(g_incr_dirty, node);
    if (g_incr_self_dirty) g_hash_table_remove(g_incr_self_dirty, node);
    if (g_incr_exclude) g_hash_table_remove(g_incr_exclude, node);
    if (g_incr_desc_inv) g_hash_table_remove(g_incr_desc_inv, node);
    if (g_incr_has_walked) g_hash_table_remove(g_incr_has_walked, node);
    if (g_incr_path) g_hash_table_remove(g_incr_path, node);
    if (g_incr_before_delta) g_hash_table_remove(g_incr_before_delta, node);
    style_memo_forget(node);
}

/* True if the last cascade ran as an incremental pass. */
gboolean
ns_css_last_cascade_continued(void)
{
    return g_incr_pass_active;
}

static gboolean incr_node_matches_keys(const ns_node *n, GHashTable *keyset);
static gboolean incr_node_matches_attr_preds(const ns_node *n,
                                             const GPtrArray *preds);

/* Marks anchor and its following element siblings dirty for :has() re-evaluation. */
static void
incr_mark_has_region(ns_node *anchor)
{
    if (!anchor) return;
    if (!g_incr_dirty)
        g_incr_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    for (ns_node *n = anchor; n; n = n->next_sibling)
        if (n->kind == NS_NODE_ELEMENT)
            g_hash_table_add(g_incr_dirty, n);
}

/* Adds descendant invalidation keys to node's set for targeted subtree restyle. */
static void
incr_desc_keys_merge(ns_node *node, GHashTable *keys)
{
    if (!keys || g_hash_table_size(keys) == 0) return;
    if (!g_incr_desc_inv)
        g_incr_desc_inv = g_hash_table_new_full(
            g_direct_hash, g_direct_equal, NULL,
            (GDestroyNotify)g_hash_table_destroy);
    GHashTable *set = g_hash_table_lookup(g_incr_desc_inv, node);
    if (!set) {
        set = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
        g_hash_table_insert(g_incr_desc_inv, node, set);
    }
    GHashTableIter it;
    gpointer k;
    g_hash_table_iter_init(&it, keys);
    while (g_hash_table_iter_next(&it, &k, NULL))
        if (!g_hash_table_contains(set, k))
            g_hash_table_add(set, g_strdup(k));
}

static void
incr_mark_self_dirty(ns_node *node)
{
    if (!node || node->kind != NS_NODE_ELEMENT) return;
    if (!g_incr_self_dirty)
        g_incr_self_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    g_hash_table_add(g_incr_self_dirty, node);
}

/* Marks a possible :has() anchor dirty when :has() arguments cannot be keyed. */
static void
incr_mark_loose_has_anchor(ns_node *anchor)
{
    if (!anchor || anchor->kind != NS_NODE_ELEMENT) return;
    if (g_has_loose_self) incr_mark_self_dirty(anchor);
    if (g_has_loose_desc && g_hash_table_size(g_has_loose_desc) > 0) {
        incr_mark_self_dirty(anchor);
        incr_desc_keys_merge(anchor, g_has_loose_desc);
    }
}

/* Walks a change's ancestors and preceding siblings, dirtying possible :has() subjects. */
static void
incr_mark_has_subjects(ns_node *changed)
{
    if (!changed || !g_incr_eligible || g_has_cq_loose) return;
    gboolean keyed = (g_has_cq_keys && g_hash_table_size(g_has_cq_keys) > 0) ||
                     (g_has_cq_attrs && g_has_cq_attrs->len > 0) ||
                     (g_has_self_keys && g_hash_table_size(g_has_self_keys) > 0) ||
                     (g_has_self_attrs && g_has_self_attrs->len > 0);
    gboolean loose = g_has_loose_self ||
                     (g_has_loose_desc && g_hash_table_size(g_has_loose_desc) > 0);
    if (!keyed && !loose) return;
    if (!g_incr_dirty)
        g_incr_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    if (!g_incr_has_walked)
        g_incr_has_walked = g_hash_table_new(g_direct_hash, g_direct_equal);
    for (ns_node *a = changed; a; a = a->parent) {
        if (a != changed && g_hash_table_contains(g_incr_has_walked, a))
            break;
        g_hash_table_add(g_incr_has_walked, a);
        if (a->kind == NS_NODE_ELEMENT && keyed &&
            (incr_node_matches_keys(a, g_has_cq_keys) ||
             incr_node_matches_attr_preds(a, g_has_cq_attrs)))
            incr_mark_has_region(a);
        if (a->kind == NS_NODE_ELEMENT && keyed &&
            (incr_node_matches_keys(a, g_has_self_keys) ||
             incr_node_matches_attr_preds(a, g_has_self_attrs)))
            incr_mark_self_dirty(a);
        if (loose) incr_mark_loose_has_anchor(a);
        if (!g_has_sibling_args) continue;
        guint scanned = 0;
        for (ns_node *s = a->prev_sibling; s; s = s->prev_sibling) {
            if (s->kind != NS_NODE_ELEMENT) continue;
            if (++scanned > 256) {
                if (a->parent)
                    g_hash_table_add(g_incr_dirty, a->parent);
                break;
            }
            if (keyed && (incr_node_matches_keys(s, g_has_cq_keys) ||
                          incr_node_matches_attr_preds(s, g_has_cq_attrs)))
                incr_mark_has_region(s);
            if (keyed && (incr_node_matches_keys(s, g_has_self_keys) ||
                          incr_node_matches_attr_preds(s, g_has_self_attrs)))
                incr_mark_self_dirty(s);
            if (loose && g_has_loose_sibling) incr_mark_loose_has_anchor(s);
        }
    }
}

void
ns_css_set_render_zoom(double zoom)
{
    g_incr_zoom = zoom > 0 ? zoom : 1.0;
}

/* Marks a subtree for the next incremental restyle and dirties affected :has() subjects. */
void
ns_css_mark_restyle_dirty(ns_node *parent)
{
    if (!parent) return;
    if (!g_incr_dirty)
        g_incr_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    g_hash_table_add(g_incr_dirty, parent);
    incr_mark_has_subjects(parent);
}

static gboolean incr_pc_is_structural(ns_css_pseudo k)
{
    switch (k) {
    case NS_CSS_PC_FIRST_CHILD: case NS_CSS_PC_LAST_CHILD:
    case NS_CSS_PC_ONLY_CHILD:  case NS_CSS_PC_ONLY_OF_TYPE:
    case NS_CSS_PC_FIRST_OF_TYPE: case NS_CSS_PC_LAST_OF_TYPE:
    case NS_CSS_PC_EMPTY:
    case NS_CSS_PC_NTH_CHILD:   case NS_CSS_PC_NTH_LAST_CHILD:
    case NS_CSS_PC_NTH_OF_TYPE: case NS_CSS_PC_NTH_LAST_OF_TYPE:
        return TRUE;
    default:
        return FALSE;
    }
}

static gboolean
incr_pc_is_user_state(ns_css_pseudo k)
{
    switch (k) {
    case NS_CSS_PC_HOVER: case NS_CSS_PC_ACTIVE: case NS_CSS_PC_FOCUS:
    case NS_CSS_PC_FOCUS_VISIBLE: case NS_CSS_PC_FOCUS_WITHIN:
        return TRUE;
    default:
        return FALSE;
    }
}

static gboolean incr_selector_has_structural(const ns_css_selector *sel, int d);

/* True if a compound or nested selector uses structural pseudo-classes; deep nesting counts. */
static gboolean
incr_simple_has_structural(const ns_css_simple *c, int d)
{
    if (!c) return FALSE;
    if (d > 6) return TRUE;
    if (c->pseudos)
        for (guint i = 0; i < c->pseudos->len; i++) {
            const ns_css_pseudo_pred *p =
                &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
            if (incr_pc_is_structural(p->kind)) return TRUE;
            if (p->of_group)
                for (guint gi = 0; gi < p->of_group->len; gi++)
                    if (incr_selector_has_structural(
                            g_ptr_array_index(p->of_group, gi), d + 1))
                        return TRUE;
        }
    GPtrArray *gls[3] = { c->matches_any, c->matches_none, c->has_groups };
    for (int g = 0; g < 3; g++) {
        if (!gls[g]) continue;
        for (guint gi = 0; gi < gls[g]->len; gi++) {
            const GPtrArray *grp = g_ptr_array_index(gls[g], gi);
            for (guint si = 0; grp && si < grp->len; si++)
                if (incr_selector_has_structural(
                        g_ptr_array_index(grp, si), d + 1))
                    return TRUE;
        }
    }
    return FALSE;
}

static gboolean
incr_selector_has_structural(const ns_css_selector *sel, int d)
{
    if (!sel || !sel->compounds) return FALSE;
    if (d > 6) return TRUE;
    for (guint i = 0; i < sel->compounds->len; i++)
        if (incr_simple_has_structural(g_ptr_array_index(sel->compounds, i), d))
            return TRUE;
    return FALSE;
}

static void incr_scan_selector_flags(const ns_css_selector *sel, int d);

/* Records use of :nth-last-*, focus, hover and active, recursing into nested selectors. */
static void
incr_scan_simple_flags(const ns_css_simple *c, int d)
{
    if (!c) return;
    if (d > 6) {
        g_struct_nth_last = TRUE;
        return;
    }
    if (c->pseudos)
        for (guint i = 0; i < c->pseudos->len; i++) {
            const ns_css_pseudo_pred *p =
                &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
            switch (p->kind) {
            case NS_CSS_PC_NTH_LAST_CHILD:
            case NS_CSS_PC_NTH_LAST_OF_TYPE:
                g_struct_nth_last = TRUE;
                break;
            case NS_CSS_PC_FOCUS:
            case NS_CSS_PC_FOCUS_VISIBLE: g_state_has_focus = TRUE; break;
            case NS_CSS_PC_FOCUS_WITHIN: g_state_has_focus_within = TRUE; break;
            case NS_CSS_PC_HOVER:        g_state_has_hover = TRUE; break;
            case NS_CSS_PC_ACTIVE:       g_state_has_active = TRUE; break;
            default: break;
            }
            if (p->of_group)
                for (guint gi = 0; gi < p->of_group->len; gi++)
                    incr_scan_selector_flags(
                        g_ptr_array_index(p->of_group, gi), d + 1);
        }
    GPtrArray *gls[3] = { c->matches_any, c->matches_none, c->has_groups };
    for (int g = 0; g < 3; g++) {
        if (!gls[g]) continue;
        for (guint gi = 0; gi < gls[g]->len; gi++) {
            const GPtrArray *grp = g_ptr_array_index(gls[g], gi);
            for (guint si = 0; grp && si < grp->len; si++)
                incr_scan_selector_flags(g_ptr_array_index(grp, si), d + 1);
        }
    }
}

static void
incr_scan_selector_flags(const ns_css_selector *sel, int d)
{
    if (!sel || !sel->compounds) return;
    for (guint i = 0; i < sel->compounds->len; i++)
        incr_scan_simple_flags(g_ptr_array_index(sel->compounds, i), d);
}

/* Adds #id, .class and %tag keys for a compound to keys; TRUE if any were added. */
static gboolean
incr_add_compound_keys(GHashTable *keys, const ns_css_simple *c)
{
    gboolean any = FALSE;
    if (!c) return FALSE;
    if (c->id && *c->id) {
        g_hash_table_add(keys, g_strconcat("#", c->id, NULL));
        any = TRUE;
    }
    if (c->classes)
        for (guint i = 0; i < c->classes->len; i++) {
            const char *cls = g_ptr_array_index(c->classes, i);
            if (cls && *cls) {
                g_hash_table_add(keys, g_strconcat(".", cls, NULL));
                any = TRUE;
            }
        }
    if (c->type && *c->type && strcmp(c->type, "*") != 0) {
        char *t = g_ascii_strdown(c->type, -1);
        g_hash_table_add(keys, g_strconcat("%", t, NULL));
        g_free(t);
        any = TRUE;
    }
    return any;
}

static void
incr_attr_dep_free(gpointer data)
{
    ns_attr_pred_clear(data);
    g_free(data);
}

/* Deep-copies borrowed attribute predicates in place so the array owns them. */
static void
incr_own_attr_deps(GPtrArray *attrs)
{
    if (!attrs) return;
    for (guint i = 0; i < attrs->len; i++) {
        const ns_css_attr_pred *source = g_ptr_array_index(attrs, i);
        ns_css_attr_pred *copy = g_new0(ns_css_attr_pred, 1);
        *copy = *source;
        copy->name = g_strdup(source->name);
        copy->namespace_uri = g_strdup(source->namespace_uri);
        copy->value = g_strdup(source->value);
        attrs->pdata[i] = copy;
    }
}

static gboolean
incr_add_positive_compound_deps(GHashTable *keys, GPtrArray *attrs,
                                const ns_css_simple *c, int depth);

/* Maps a pseudo-class to the attribute whose change affects it; "" if none, NULL if unknown. */
static const char *
incr_state_pseudo_attr(ns_css_pseudo k)
{
    switch (k) {
    case NS_CSS_PC_DISABLED:
    case NS_CSS_PC_ENABLED:       return "disabled";
    case NS_CSS_PC_CHECKED:       return "data-nd-checked";
    case NS_CSS_PC_REQUIRED:
    case NS_CSS_PC_OPTIONAL:      return "required";
    case NS_CSS_PC_READ_ONLY:
    case NS_CSS_PC_READ_WRITE:    return "readonly";
    case NS_CSS_PC_LINK:
    case NS_CSS_PC_VISITED:
    case NS_CSS_PC_ANY_LINK:
    case NS_CSS_PC_HOVER:
    case NS_CSS_PC_ACTIVE:
    case NS_CSS_PC_FOCUS:
    case NS_CSS_PC_FOCUS_VISIBLE:
    case NS_CSS_PC_FOCUS_WITHIN:
    case NS_CSS_PC_TARGET:
    case NS_CSS_PC_TARGET_WITHIN:
    case NS_CSS_PC_FIRST_CHILD:
    case NS_CSS_PC_LAST_CHILD:
    case NS_CSS_PC_ONLY_CHILD:
    case NS_CSS_PC_ONLY_OF_TYPE:
    case NS_CSS_PC_FIRST_OF_TYPE:
    case NS_CSS_PC_LAST_OF_TYPE:
    case NS_CSS_PC_EMPTY:
    case NS_CSS_PC_NTH_CHILD:
    case NS_CSS_PC_NTH_LAST_CHILD:
    case NS_CSS_PC_NTH_OF_TYPE:
    case NS_CSS_PC_NTH_LAST_OF_TYPE:
    case NS_CSS_PC_ROOT:
    case NS_CSS_PC_SCOPE:
    case NS_CSS_PC_DEFINED:       return "";
    default:                      return NULL;
    }
}

/* Records keys and attrs of compounds left of + or ~ so sibling changes can invalidate. */
static void
incr_collect_sib_left(const ns_css_simple *c)
{
    gboolean handled = incr_add_compound_keys(g_sib_keys, c);
    if (c->attrs)
        for (guint i = 0; i < c->attrs->len; i++) {
            const ns_css_attr_pred *a =
                &g_array_index(c->attrs, ns_css_attr_pred, i);
            if (a->name && *a->name) {
                char *low = g_ascii_strdown(a->name, -1);
                g_hash_table_add(g_sib_attrs, g_strdup(low));
                if (a->op != NS_CSS_ATTR_PRESENT)
                    g_hash_table_add(g_sib_value_attrs, low);
                else
                    g_free(low);
                handled = TRUE;
            }
        }
    if (c->pseudos)
        for (guint i = 0; i < c->pseudos->len; i++) {
            const ns_css_pseudo_pred *p =
                &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
            const char *attr = incr_state_pseudo_attr(p->kind);
            if (attr == NULL) { g_sib_loose = TRUE; }
            else if (*attr) {
                g_hash_table_add(g_sib_attrs, g_strdup(attr));
                g_hash_table_add(g_sib_value_attrs, g_strdup(attr));
            }
            if (p->kind == NS_CSS_PC_FOCUS ||
                p->kind == NS_CSS_PC_FOCUS_VISIBLE ||
                p->kind == NS_CSS_PC_FOCUS_WITHIN ||
                p->kind == NS_CSS_PC_HOVER ||
                p->kind == NS_CSS_PC_ACTIVE)
                g_state_sib = TRUE;
            handled = TRUE;
        }
    if (c->matches_any || c->matches_none || c->has_groups)
        g_sib_loose = TRUE;
    (void)handled;
}

static void incr_collect_attr_keys_selector(const ns_css_selector *sel, int depth);

/* Collects attribute names selectors depend on, including ones implied by pseudo-classes. */
static void
incr_collect_attr_keys_simple(const ns_css_simple *c, int depth)
{
    if (!c || depth > 6) return;
    if (c->attrs)
        for (guint i = 0; i < c->attrs->len; i++) {
            const ns_css_attr_pred *a =
                &g_array_index(c->attrs, ns_css_attr_pred, i);
            if (a->name && *a->name)
                g_hash_table_add(g_attr_keys, g_ascii_strdown(a->name, -1));
        }
    if (c->pseudos)
        for (guint i = 0; i < c->pseudos->len; i++) {
            const ns_css_pseudo_pred *p =
                &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
            const char *attr = incr_state_pseudo_attr(p->kind);
            if (attr && *attr)
                g_hash_table_add(g_attr_keys, g_strdup(attr));
            if (p->kind == NS_CSS_PC_LANG) {
                g_hash_table_add(g_attr_keys, g_strdup("lang"));
                g_hash_table_add(g_attr_keys, g_strdup("xml:lang"));
            } else if (p->kind == NS_CSS_PC_DIR) {
                g_hash_table_add(g_attr_keys, g_strdup("dir"));
            } else if (p->kind == NS_CSS_PC_OPEN) {
                g_hash_table_add(g_attr_keys, g_strdup("open"));
            } else if (p->kind == NS_CSS_PC_POPOVER_OPEN) {
                g_hash_table_add(g_attr_keys, g_strdup("data-nd-popover-open"));
            } else if (p->kind == NS_CSS_PC_MODAL) {
                g_hash_table_add(g_attr_keys, g_strdup("data-nd-modal"));
            }
            if (p->of_group)
                for (guint gi = 0; gi < p->of_group->len; gi++)
                    incr_collect_attr_keys_selector(
                        g_ptr_array_index(p->of_group, gi), depth + 1);
        }
    GPtrArray *groups[3] = { c->matches_any, c->matches_none, c->has_groups };
    for (guint i = 0; i < G_N_ELEMENTS(groups); i++)
        if (groups[i])
            for (guint gi = 0; gi < groups[i]->len; gi++) {
                const GPtrArray *group = g_ptr_array_index(groups[i], gi);
                for (guint si = 0; group && si < group->len; si++)
                    incr_collect_attr_keys_selector(
                        g_ptr_array_index(group, si), depth + 1);
            }
}

static void
incr_collect_attr_keys_selector(const ns_css_selector *sel, int depth)
{
    if (!sel || !sel->compounds || depth > 6) return;
    for (guint i = 0; i < sel->compounds->len; i++)
        incr_collect_attr_keys_simple(g_ptr_array_index(sel->compounds, i),
                                      depth);
}

/* Indexes a sheet's selectors into structural and sibling invalidation keys and flags. */
static void
incr_collect_struct_keys(const ns_css_stylesheet *sh)
{
    if (!sh || !sh->rules) return;
    for (guint ri = 0; ri < sh->rules->len; ri++) {
        const ns_css_rule *r = g_ptr_array_index(sh->rules, ri);
        if (!r || !r->selectors) continue;
        for (guint si = 0; si < r->selectors->len; si++) {
            const ns_css_selector *sel = g_ptr_array_index(r->selectors, si);
            if (!sel || !sel->compounds) continue;
            incr_collect_attr_keys_selector(sel, 0);
            incr_scan_selector_flags(sel, 0);
            guint nc = sel->compounds->len;
            for (guint ci = 0; ci < nc; ci++) {
                const ns_css_simple *c = g_ptr_array_index(sel->compounds, ci);
                ns_css_comb left = NS_CSS_COMB_NONE;
                if (sel->combinators && ci < sel->combinators->len)
                    left = g_array_index(sel->combinators, ns_css_comb, ci);
                ns_css_comb right = NS_CSS_COMB_NONE;
                if (sel->combinators && ci + 1 < sel->combinators->len)
                    right = g_array_index(sel->combinators, ns_css_comb, ci + 1);
                if (right == NS_CSS_COMB_ADJACENT || right == NS_CSS_COMB_SIBLING)
                    incr_collect_sib_left(c);
                gboolean sib_subject = (left == NS_CSS_COMB_ADJACENT ||
                                        left == NS_CSS_COMB_SIBLING);
                if (!incr_simple_has_structural(c, 0) && !sib_subject)
                    continue;
                if (incr_add_positive_compound_deps(
                        g_struct_keys, g_struct_attrs, c, 0))
                    continue;
                gboolean sib_ctx = TRUE, found = FALSE;
                for (int j = (int)ci - 1; j >= 0; j--) {
                    ns_css_comb cb = NS_CSS_COMB_NONE;
                    if (sel->combinators &&
                        (guint)(j + 1) < sel->combinators->len)
                        cb = g_array_index(sel->combinators, ns_css_comb, j + 1);
                    const ns_css_simple *jc =
                        g_ptr_array_index(sel->compounds, j);
                    if (sib_ctx && (cb == NS_CSS_COMB_ADJACENT ||
                                    cb == NS_CSS_COMB_SIBLING)) {
                        if (incr_add_positive_compound_deps(
                                g_struct_keys, g_struct_attrs, jc, 0)) {
                            found = TRUE; break;
                        }
                    } else {
                        sib_ctx = FALSE;
                        if (incr_add_positive_compound_deps(
                                g_struct_anc_keys, g_struct_anc_attrs, jc, 0)) {
                            found = TRUE; break;
                        }
                    }
                }
                if (!found) g_struct_loose = TRUE;
            }
        }
    }
}

static void incr_collect_name_keys_selector(const ns_css_selector *sel,
                                            int depth);

static void
incr_collect_name_keys_group(const GPtrArray *group, int depth)
{
    for (guint i = 0; group && i < group->len; i++)
        incr_collect_name_keys_selector(g_ptr_array_index(group, i), depth);
}

/* Collects lowercased ids and classes used; [class]/[id] or :target make the set loose. */
static void
incr_collect_name_keys_simple(const ns_css_simple *c, int depth)
{
    if (!c) return;
    if (depth > 6) {
        g_class_keys_loose = TRUE;
        g_id_keys_loose = TRUE;
        return;
    }
    if (c->id && *c->id)
        g_hash_table_add(g_id_keys, g_ascii_strdown(c->id, -1));
    for (guint i = 0; c->classes && i < c->classes->len; i++) {
        const char *cls = g_ptr_array_index(c->classes, i);
        if (cls && *cls)
            g_hash_table_add(g_class_keys, g_ascii_strdown(cls, -1));
    }
    for (guint i = 0; c->attrs && i < c->attrs->len; i++) {
        const ns_css_attr_pred *a =
            &g_array_index(c->attrs, ns_css_attr_pred, i);
        if (!a->name) continue;
        if (g_ascii_strcasecmp(a->name, "class") == 0)
            g_class_keys_loose = TRUE;
        else if (g_ascii_strcasecmp(a->name, "id") == 0)
            g_id_keys_loose = TRUE;
    }
    for (guint i = 0; c->pseudos && i < c->pseudos->len; i++) {
        const ns_css_pseudo_pred *pc =
            &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
        if (pc->kind == NS_CSS_PC_TARGET || pc->kind == NS_CSS_PC_TARGET_WITHIN)
            g_id_keys_loose = TRUE;
        if (pc->of_group) incr_collect_name_keys_group(pc->of_group, depth + 1);
    }
    GPtrArray *groups[3] = { c->matches_any, c->matches_none, c->has_groups };
    for (guint g = 0; g < G_N_ELEMENTS(groups); g++)
        for (guint gi = 0; groups[g] && gi < groups[g]->len; gi++)
            incr_collect_name_keys_group(g_ptr_array_index(groups[g], gi),
                                         depth + 1);
}

static void
incr_collect_name_keys_selector(const ns_css_selector *sel, int depth)
{
    for (guint i = 0; sel && sel->compounds && i < sel->compounds->len; i++)
        incr_collect_name_keys_simple(g_ptr_array_index(sel->compounds, i),
                                      depth);
}

/* Collects class and id keys from a sheet's selectors and @scope bounds. */
static void
incr_collect_name_keys(const ns_css_stylesheet *sh)
{
    for (guint ri = 0; sh && sh->rules && ri < sh->rules->len; ri++) {
        const ns_css_rule *r = g_ptr_array_index(sh->rules, ri);
        if (!r) continue;
        incr_collect_name_keys_group(r->selectors, 0);
        for (guint si = 0; r->scopes && si < r->scopes->len; si++) {
            const ns_css_scope *scope = g_ptr_array_index(r->scopes, si);
            incr_collect_name_keys_group(scope->roots, 0);
            incr_collect_name_keys_group(scope->limits, 0);
        }
    }
}

/* ASCII-lowercased membership test of a length-delimited name in keys. */
static gboolean
incr_name_in_keys(const char *name, gsize len, GHashTable *keys)
{
    char stack[64];
    char *low = len < sizeof stack ? stack : g_malloc(len + 1);
    for (gsize i = 0; i < len; i++) low[i] = g_ascii_tolower(name[i]);
    low[len] = '\0';
    gboolean hit = g_hash_table_contains(keys, low);
    if (low != stack) g_free(low);
    return hit;
}

/* True if any class token in value is used by some selector. */
static gboolean
incr_class_tokens_in_keys(const char *value)
{
    for (const char *p = value; p && *p; ) {
        while (*p && g_ascii_isspace((guchar)*p)) p++;
        const char *tok = p;
        while (*p && !g_ascii_isspace((guchar)*p)) p++;
        if (p > tok && incr_name_in_keys(tok, (gsize)(p - tok), g_class_keys))
            return TRUE;
    }
    return FALSE;
}

static gboolean
incr_id_in_keys(const char *value)
{
    return value && incr_name_in_keys(value, strlen(value), g_id_keys);
}

/* True if a class/id change touches no names any selector uses, so restyle can be skipped. */
static gboolean
incr_name_change_unused(const ns_node *target, const char *name,
                        const char *old_value)
{
    if (!g_struct_ready || !name) return FALSE;
    if (g_ascii_strcasecmp(name, "class") == 0)
        return g_class_keys && !g_class_keys_loose &&
               !incr_class_tokens_in_keys(old_value) &&
               !incr_class_tokens_in_keys(ns_element_get_attr(target, "class"));
    if (g_ascii_strcasecmp(name, "id") == 0)
        return g_id_keys && !g_id_keys_loose &&
               !incr_id_in_keys(old_value) &&
               !incr_id_in_keys(ns_element_get_attr(target, "id"));
    return FALSE;
}

static void incr_desc_features_build(const ns_css_stylesheet *ua,
                                     const ns_css_stylesheet *const *author,
                                     gsize n);

/* Rebuilds the incremental restyle invalidation indexes when the sheet signature changes. */
static void
incr_ensure_struct_keys(const ns_css_stylesheet *ua,
                        const ns_css_stylesheet *const *author, gsize n,
                        guint64 sig)
{
    if (g_struct_ready && g_struct_sig == sig) return;
    if (g_struct_keys) g_hash_table_remove_all(g_struct_keys);
    else g_struct_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                               g_free, NULL);
    if (g_struct_anc_keys) g_hash_table_remove_all(g_struct_anc_keys);
    else g_struct_anc_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                   g_free, NULL);
    if (g_struct_attrs) g_ptr_array_set_size(g_struct_attrs, 0);
    else g_struct_attrs = g_ptr_array_new_with_free_func(incr_attr_dep_free);
    if (g_struct_anc_attrs) g_ptr_array_set_size(g_struct_anc_attrs, 0);
    else g_struct_anc_attrs =
        g_ptr_array_new_with_free_func(incr_attr_dep_free);
    if (g_sib_keys) g_hash_table_remove_all(g_sib_keys);
    else g_sib_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                            g_free, NULL);
    if (g_sib_attrs) g_hash_table_remove_all(g_sib_attrs);
    else g_sib_attrs = g_hash_table_new_full(g_str_hash, g_str_equal,
                                             g_free, NULL);
    if (g_sib_value_attrs) g_hash_table_remove_all(g_sib_value_attrs);
    else g_sib_value_attrs = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                   g_free, NULL);
    if (g_attr_keys) g_hash_table_remove_all(g_attr_keys);
    else g_attr_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                             g_free, NULL);
    if (g_class_keys) g_hash_table_remove_all(g_class_keys);
    else g_class_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                              g_free, NULL);
    if (g_id_keys) g_hash_table_remove_all(g_id_keys);
    else g_id_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                           g_free, NULL);
    g_class_keys_loose = FALSE;
    g_id_keys_loose = FALSE;
    g_struct_loose = FALSE;
    g_sib_loose = FALSE;
    g_struct_nth_last = FALSE;
    g_state_sib = FALSE;
    g_state_has_focus = FALSE;
    g_state_has_focus_within = FALSE;
    g_state_has_hover = FALSE;
    g_state_has_active = FALSE;
    incr_collect_struct_keys(ua);
    for (gsize i = 0; i < n; i++)
        incr_collect_struct_keys(author[i]);
    incr_own_attr_deps(g_struct_attrs);
    incr_own_attr_deps(g_struct_anc_attrs);
    incr_desc_features_build(ua, author, n);
    g_struct_sig = sig;
    g_struct_ready = TRUE;
    if (g_getenv("NS_PROFILE"))
        g_printerr("[profile] restyle-index structural=%u ancestors=%u "
                   "sibling=%u loose=%d nth-last=%d\n",
                   g_hash_table_size(g_struct_keys),
                   g_hash_table_size(g_struct_anc_keys),
                   g_hash_table_size(g_sib_keys), g_struct_loose,
                   g_struct_nth_last);
}

/* Tests for prefix+name (optionally lowercased) in a key set, avoiding heap use when short. */
static gboolean
incr_key_set_has(GHashTable *set, char prefix, const char *name, gsize len,
                 gboolean fold)
{
    char stack[128];
    char *key = len + 2 <= sizeof stack ? stack : g_malloc(len + 2);
    key[0] = prefix;
    for (gsize i = 0; i < len; i++)
        key[i + 1] = fold ? g_ascii_tolower(name[i]) : name[i];
    key[len + 1] = '\0';
    gboolean hit = g_hash_table_contains(set, key);
    if (key != stack) g_free(key);
    return hit;
}

/* True if n's tag, id or any class is in the key set. */
static gboolean
incr_node_matches_keys(const ns_node *n, GHashTable *keyset)
{
    if (!n || n->kind != NS_NODE_ELEMENT || !keyset ||
        g_hash_table_size(keyset) == 0)
        return FALSE;
    if (n->name && incr_key_set_has(keyset, '%', n->name, strlen(n->name),
                                    TRUE))
        return TRUE;
    const char *id = ns_element_get_attr(n, "id");
    if (id && *id && incr_key_set_has(keyset, '#', id, strlen(id), FALSE))
        return TRUE;
    guint n_tokens = 0;
    const ns_class_token *toks = ns_node_class_tokens(n, &n_tokens);
    for (guint i = 0; i < n_tokens; i++)
        if (incr_key_set_has(keyset, '.', toks[i].p, toks[i].len, FALSE))
            return TRUE;
    return FALSE;
}

/* True if any of n's attributes satisfies one of the predicates. */
static gboolean
incr_node_matches_attr_preds(const ns_node *n, const GPtrArray *preds)
{
    if (!n || n->kind != NS_NODE_ELEMENT || !preds) return FALSE;
    gboolean html_doc = !(n->flags & NS_NODE_XML_DOC) &&
                        !(n->flags & (NS_NODE_FOREIGN_NS | NS_NODE_SVG_NS));
    for (guint i = 0; i < preds->len; i++) {
        const ns_css_attr_pred *wanted = g_ptr_array_index(preds, i);
        if (!wanted || !wanted->name) continue;
        for (const ns_attr *attr = n->attrs; attr; attr = attr->next) {
            const char *attr_namespace = attr->namespace_uri;
            if (attr_namespace && !*attr_namespace) attr_namespace = NULL;
            const char *wanted_namespace = wanted->namespace_uri;
            if (wanted_namespace && !*wanted_namespace)
                wanted_namespace = NULL;
            if (!wanted->namespace_any &&
                ((wanted_namespace == NULL) != (attr_namespace == NULL) ||
                 (wanted_namespace && strcmp(wanted_namespace,
                                             attr_namespace) != 0)))
                continue;
            const char *local_name = ns_attr_local_name(attr);
            if (html_doc
                    ? g_ascii_strcasecmp(local_name, wanted->name) != 0
                    : strcmp(local_name, wanted->name) != 0)
                continue;
            if (ns_css_attr_value_matches(wanted,
                                           attr->value ? attr->value : "",
                                           html_doc))
                return TRUE;
        }
    }
    return FALSE;
}

static ns_node *
incr_prev_element_from(ns_node *from)
{
    for (ns_node *s = from; s; s = s->prev_sibling)
        if (s->kind == NS_NODE_ELEMENT) return s;
    return NULL;
}

static ns_node *
incr_prev_same_type_from(ns_node *from, const char *tag)
{
    if (!tag) return NULL;
    for (ns_node *s = from; s; s = s->prev_sibling)
        if (s->kind == NS_NODE_ELEMENT && s->name &&
            g_ascii_strcasecmp(s->name, tag) == 0)
            return s;
    return NULL;
}

/* Marks n self-dirty with the descendant keys for feature; FALSE if keying is unavailable. */
static gboolean
incr_mark_self_feature_only(ns_node *n, const char *feature)
{
    if (!n || n->kind != NS_NODE_ELEMENT || !g_desc_features ||
        g_desc_features_loose)
        return FALSE;
    gpointer keys = g_hash_table_lookup(g_desc_features, feature);
    if (keys == DESC_ALL) return FALSE;
    incr_mark_self_dirty(n);
    if (keys) incr_desc_keys_merge(n, keys);
    return TRUE;
}

/* Like incr_mark_self_feature_only, but also dirties affected :has() subjects. */
static gboolean
incr_mark_self_with_feature(ns_node *n, const char *feature)
{
    if (!incr_mark_self_feature_only(n, feature)) return FALSE;
    incr_mark_has_subjects(n);
    return TRUE;
}

/* Marks n for structural restyle, falling back to a full subtree restyle. */
static void
incr_mark_struct_node(ns_node *n)
{
    if (!incr_mark_self_feature_only(n, ":struct"))
        ns_css_mark_restyle_dirty(n);
}

/* Structurally marks up to 256 following element siblings; FALSE if more remain. */
static gboolean
incr_mark_following_struct(ns_node *from)
{
    int marked = 0;
    for (ns_node *s = from; s; s = s->next_sibling)
        if (s->kind == NS_NODE_ELEMENT) {
            if (++marked > 256) return FALSE;
            incr_mark_struct_node(s);
        }
    return TRUE;
}

/* Marks parent's children for structural restyle, or the whole subtree if not keyable. */
void
ns_css_mark_children_restyle(ns_node *parent)
{
    if (!parent) return;
    guint elements = 0;
    for (const ns_node *c = parent->first_child; c; c = c->next_sibling)
        if (c->kind == NS_NODE_ELEMENT) elements++;
    gpointer keys = g_desc_features
        ? g_hash_table_lookup(g_desc_features, ":struct") : NULL;
    if (parent->kind != NS_NODE_ELEMENT || !g_desc_features ||
        g_desc_features_loose || keys == DESC_ALL || elements > 512) {
        ns_css_mark_restyle_dirty(parent);
        return;
    }
    incr_mark_self_dirty(parent);
    incr_mark_has_subjects(parent->last_child ? parent->last_child : parent);
    incr_mark_has_subjects(parent);
    for (ns_node *c = parent->first_child; c; c = c->next_sibling)
        if (c->kind == NS_NODE_ELEMENT) incr_mark_struct_node(c);
}

/* Marks up to 256 following element siblings dirty; FALSE if more remain. */
static gboolean
incr_mark_following_siblings(ns_node *from)
{
    int marked = 0;
    for (ns_node *s = from; s; s = s->next_sibling)
        if (s->kind == NS_NODE_ELEMENT) {
            if (++marked > 256) return FALSE;
            ns_css_mark_restyle_dirty(s);
        }
    return TRUE;
}

/* Structurally marks the children of a parent with at most two element children. */
static void
incr_mark_small_family(ns_node *parent)
{
    int elements = 0;
    for (const ns_node *c = parent->first_child; c; c = c->next_sibling)
        if (c->kind == NS_NODE_ELEMENT && ++elements > 2) return;
    for (ns_node *c = parent->first_child; c; c = c->next_sibling)
        if (c->kind == NS_NODE_ELEMENT) incr_mark_struct_node(c);
}

/* Marks a node whose user-action state changed, plus later siblings if selectors need it. */
static void
incr_mark_state_node(const ns_node *n)
{
    if (!n) return;
    if (!incr_mark_self_with_feature((ns_node *)n, ":state"))
        ns_css_mark_restyle_dirty((ns_node *)n);
    if (!g_state_sib) return;
    for (ns_node *s = n->next_sibling; s; s = s->next_sibling)
        if (s->kind == NS_NODE_ELEMENT)
            ns_css_mark_restyle_dirty(s);
}

static gboolean
incr_chain_contains(const ns_node *chain, const ns_node *n)
{
    for (const ns_node *a = chain; a; a = a->parent)
        if (a == n) return TRUE;
    return FALSE;
}

/* Marks ancestors entering or leaving a hover/active chain, skipping shared ones. */
static void
incr_mark_state_chain(const ns_node *oldn, const ns_node *newn,
                      gboolean relevant)
{
    if (oldn == newn || !relevant) return;
    for (const ns_node *a = oldn; a; a = a->parent)
        if (!incr_chain_contains(newn, a)) incr_mark_state_node(a);
    for (const ns_node *b = newn; b; b = b->parent)
        if (!incr_chain_contains(oldn, b)) incr_mark_state_node(b);
}

/* Marks nodes affected by a focus move; whole ancestor chains if :focus-within is used. */
static void
incr_mark_state_focus(const ns_node *oldn, const ns_node *newn)
{
    if (oldn == newn) return;
    if (g_state_has_focus_within) {
        incr_mark_state_chain(oldn, newn, TRUE);
        return;
    }
    if (!g_state_has_focus) return;
    incr_mark_state_node(oldn);
    incr_mark_state_node(newn);
}

/* Restyles parent when it became empty or single-child under a structurally keyed ancestor. */
static void
incr_mark_empty_transition(ns_node *parent, ns_node *added, ns_node *removed)
{
    gboolean became_single = added && parent->first_child == added &&
                             parent->last_child == added;
    gboolean became_empty = removed && !parent->first_child;
    if (!became_single && !became_empty) return;
    for (const ns_node *a = parent; a; a = a->parent)
        if (incr_node_matches_keys(a, g_struct_anc_keys) ||
            incr_node_matches_attr_preds(a, g_struct_anc_attrs)) {
            ns_css_mark_restyle_dirty(parent);
            return;
        }
}

/* Invalidates structural selectors such as :empty when a text node's emptiness flips. */
void
ns_css_mark_text_emptiness_change(ns_node *text)
{
    ns_node *parent = text ? text->parent : NULL;
    if (!parent || parent->kind != NS_NODE_ELEMENT) return;
    incr_mark_has_subjects(parent);
    if (!g_struct_ready || g_struct_loose ||
        incr_node_matches_keys(parent, g_struct_keys) ||
        incr_node_matches_attr_preds(parent, g_struct_attrs)) {
        ns_css_mark_restyle_dirty(parent);
        return;
    }
    for (const ns_node *a = parent; a; a = a->parent)
        if (incr_node_matches_keys(a, g_struct_anc_keys) ||
            incr_node_matches_attr_preds(a, g_struct_anc_attrs)) {
            ns_css_mark_restyle_dirty(parent);
            return;
        }
}

/* Marks restyle needs after a child insertion or removal (structural and :has()). */
void
ns_css_mark_childlist_change(ns_node *parent, ns_node *added, ns_node *removed,
                             ns_node *prev_sibling, ns_node *next_sibling)
{
    if (!parent) return;
    incr_mark_has_subjects(parent);
    incr_mark_has_subjects(added);
    incr_mark_has_subjects(removed);
    incr_mark_has_subjects(prev_sibling);
    incr_mark_has_subjects(next_sibling);
    if (!g_struct_ready || g_struct_loose || g_struct_nth_last ||
        incr_node_matches_keys(parent, g_struct_keys) ||
        incr_node_matches_attr_preds(parent, g_struct_attrs)) {
        ns_css_mark_children_restyle(parent);
        return;
    }
    if (added && added->kind == NS_NODE_ELEMENT) {
        ns_css_mark_restyle_dirty(added);
        ns_node *prev_el = incr_prev_element_from(added->prev_sibling);
        if (added->next_sibling) {
            if (!incr_mark_following_struct(added->next_sibling)) {
                ns_css_mark_restyle_dirty(parent);
                return;
            }
        } else if (prev_el) {
            incr_mark_struct_node(prev_el);
        }
        ns_node *prev_type =
            incr_prev_same_type_from(added->prev_sibling, added->name);
        if (prev_type && prev_type != prev_el)
            incr_mark_struct_node(prev_type);
        incr_mark_small_family(parent);
    }
    if (removed && removed->kind == NS_NODE_ELEMENT) {
        if (next_sibling) {
            if (!incr_mark_following_struct(next_sibling)) {
                ns_css_mark_restyle_dirty(parent);
                return;
            }
        } else {
            ns_node *new_last = incr_prev_element_from(prev_sibling);
            if (new_last) incr_mark_struct_node(new_last);
        }
        ns_node *prev_type =
            incr_prev_same_type_from(prev_sibling, removed->name);
        if (prev_type) incr_mark_struct_node(prev_type);
        incr_mark_small_family(parent);
    }
    incr_mark_empty_transition(parent, added, removed);
}

/* True if any old class token is a key used left of a sibling combinator. */
static gboolean
incr_old_class_is_sib(const char *old_value)
{
    if (!old_value || !*old_value || !g_sib_keys ||
        g_hash_table_size(g_sib_keys) == 0)
        return FALSE;
    char **toks = g_strsplit_set(old_value, " \t\r\n\f", -1);
    gboolean hit = FALSE;
    for (int i = 0; toks && toks[i] && !hit; i++) {
        if (!*toks[i]) continue;
        char *key = g_strconcat(".", toks[i], NULL);
        if (g_hash_table_contains(g_sib_keys, key)) hit = TRUE;
        g_free(key);
    }
    g_strfreev(toks);
    return hit;
}

/* True if an id/class change (old or new value) affects sibling-combinator selectors. */
static gboolean
incr_attr_key_change_is_sib(const ns_node *target, const char *name,
                            const char *old_value)
{
    if (!target || !name || !g_sib_keys) return FALSE;
    if (g_ascii_strcasecmp(name, "id") == 0) {
        const char *value = ns_element_get_attr(target, "id");
        char *new_key = value && *value ? g_strconcat("#", value, NULL) : NULL;
        char *old_key = old_value && *old_value ?
            g_strconcat("#", old_value, NULL) : NULL;
        gboolean hit = (new_key && g_hash_table_contains(g_sib_keys, new_key)) ||
                       (old_key && g_hash_table_contains(g_sib_keys, old_key));
        g_free(new_key);
        g_free(old_key);
        return hit;
    }
    if (g_ascii_strcasecmp(name, "class") != 0) return FALSE;
    if (incr_node_matches_keys(target, g_sib_keys)) return TRUE;
    return incr_old_class_is_sib(old_value);
}

static char *
incr_lower_key(char prefix, const char *name)
{
    char *low = g_ascii_strdown(name, -1);
    char *key = g_strdup_printf("%c%s", prefix, low);
    g_free(low);
    return key;
}

/* Picks one lowercased invalidation key (id, class, tag or attr) for a subject compound. */
static char *
incr_desc_subject_key(const ns_css_simple *c)
{
    if (!c || c->never_match) return NULL;
    if (c->id && *c->id) return incr_lower_key('#', c->id);
    for (guint i = 0; c->classes && i < c->classes->len; i++) {
        const char *cls = g_ptr_array_index(c->classes, i);
        if (cls && *cls) return incr_lower_key('.', cls);
    }
    if (c->type && *c->type && strcmp(c->type, "*") != 0 &&
        !c->type_has_colon && !c->namespace_uri)
        return incr_lower_key('%', c->type);
    for (guint i = 0; c->attrs && i < c->attrs->len; i++) {
        const ns_css_attr_pred *a =
            &g_array_index(c->attrs, ns_css_attr_pred, i);
        if (a->name && *a->name && !strchr(a->name, ':'))
            return incr_lower_key('[', a->name);
    }
    return NULL;
}

static void
incr_desc_value_free(gpointer v)
{
    if (v && v != DESC_ALL) g_hash_table_destroy(v);
}

/* Adds the subject keys a feature invalidates; no keys means it invalidates everything. */
static void
incr_desc_feature_add(char *feature, const GPtrArray *keys)
{
    gpointer cur = g_hash_table_lookup(g_desc_features, feature);
    if (cur == DESC_ALL) {
        g_free(feature);
        return;
    }
    if (!keys || keys->len == 0) {
        g_hash_table_replace(g_desc_features, feature, DESC_ALL);
        return;
    }
    if (!cur) {
        cur = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
        g_hash_table_insert(g_desc_features, feature, cur);
    } else {
        g_free(feature);
    }
    for (guint i = 0; i < keys->len; i++) {
        const char *key = g_ptr_array_index(keys, i);
        if (!g_hash_table_contains(cur, key))
            g_hash_table_add(cur, g_strdup(key));
    }
}

/* Returns keys identifying a selector subject, via its :is() arms if needed; NULL if none. */
static GPtrArray *
incr_desc_subject_keys(const ns_css_simple *subject)
{
    GPtrArray *keys = g_ptr_array_new_with_free_func(g_free);
    char *direct = incr_desc_subject_key(subject);
    if (direct) {
        g_ptr_array_add(keys, direct);
        return keys;
    }
    for (guint gi = 0; subject->matches_any && gi < subject->matches_any->len;
         gi++) {
        const GPtrArray *group = g_ptr_array_index(subject->matches_any, gi);
        gboolean complete = group && group->len > 0;
        for (guint si = 0; complete && si < group->len; si++) {
            const ns_css_selector *arm = g_ptr_array_index(group, si);
            char *key = NULL;
            if (arm && arm->compounds && arm->compounds->len > 0)
                key = incr_desc_subject_key(g_ptr_array_index(
                    arm->compounds, arm->compounds->len - 1));
            if (key) g_ptr_array_add(keys, key);
            else complete = FALSE;
        }
        if (complete) return keys;
        g_ptr_array_set_size(keys, 0);
    }
    g_ptr_array_free(keys, TRUE);
    return NULL;
}

/* Returns a "*N" key when the subject is N child-combinator steps below (N <= 4). */
static GPtrArray *
incr_desc_depth_keys(const ns_css_selector *sel, guint from)
{
    guint last = sel->compounds->len - 1;
    if (from >= last || last - from > 4 || !sel->combinators) return NULL;
    for (guint k = from + 1; k <= last; k++)
        if (k >= sel->combinators->len ||
            g_array_index(sel->combinators, ns_css_comb, k) !=
                NS_CSS_COMB_CHILD)
            return NULL;
    GPtrArray *keys = g_ptr_array_new_with_free_func(g_free);
    g_ptr_array_add(keys, g_strdup_printf("*%u", last - from));
    return keys;
}

static void incr_desc_collect_selector(const ns_css_selector *sel,
                                       const GPtrArray *keys, int depth);
static void incr_desc_collect_identity(const ns_css_simple *c,
                                       const GPtrArray *keys, int depth);
static void incr_desc_collect_compound(const ns_css_simple *c,
                                       const GPtrArray *keys, int depth);
static void incr_desc_collect_sibling_chain(const ns_css_selector *sel,
                                            const GPtrArray *keys);

/* Collects descendant features from a compound's nested :is/:not/of-S selectors. */
static void
incr_desc_collect_groups(const ns_css_simple *c, const GPtrArray *keys,
                         int depth, gboolean identity)
{
    for (guint i = 0; c->pseudos && i < c->pseudos->len; i++) {
        const ns_css_pseudo_pred *p =
            &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
        for (guint gi = 0; p->of_group && gi < p->of_group->len; gi++)
            incr_desc_collect_selector(g_ptr_array_index(p->of_group, gi),
                                       keys, depth + 1);
    }
    GPtrArray *groups[2] = { c->matches_any, c->matches_none };
    for (guint g = 0; g < G_N_ELEMENTS(groups); g++) {
        for (guint gi = 0; groups[g] && gi < groups[g]->len; gi++) {
            const GPtrArray *group = g_ptr_array_index(groups[g], gi);
            for (guint si = 0; group && si < group->len; si++) {
                const ns_css_selector *sel = g_ptr_array_index(group, si);
                if (!identity) {
                    incr_desc_collect_selector(sel, keys, depth + 1);
                    continue;
                }
                if (!sel || !sel->compounds || sel->compounds->len == 0)
                    continue;
                guint last = sel->compounds->len - 1;
                incr_desc_collect_sibling_chain(sel, keys);
                for (guint ci = 0; ci < last; ci++)
                    incr_desc_collect_compound(
                        g_ptr_array_index(sel->compounds, ci), keys,
                        depth + 1);
                incr_desc_collect_identity(
                    g_ptr_array_index(sel->compounds, last), keys, depth + 1);
            }
        }
    }
}

/* Registers a compound's id, class, attr, structural and state features against keys. */
static void
incr_desc_collect_features(const ns_css_simple *c, const GPtrArray *keys)
{
    if (c->id && *c->id)
        incr_desc_feature_add(incr_lower_key('#', c->id), keys);
    for (guint i = 0; c->classes && i < c->classes->len; i++) {
        const char *cls = g_ptr_array_index(c->classes, i);
        if (cls && *cls)
            incr_desc_feature_add(incr_lower_key('.', cls), keys);
    }
    for (guint i = 0; c->attrs && i < c->attrs->len; i++) {
        const ns_css_attr_pred *a =
            &g_array_index(c->attrs, ns_css_attr_pred, i);
        if (!a->name || !*a->name) continue;
        const char *colon = strchr(a->name, ':');
        incr_desc_feature_add(incr_lower_key('[', colon ? colon + 1 : a->name),
                              keys);
    }
    for (guint i = 0; c->pseudos && i < c->pseudos->len; i++) {
        ns_css_pseudo kind =
            g_array_index(c->pseudos, ns_css_pseudo_pred, i).kind;
        if (incr_pc_is_structural(kind))
            incr_desc_feature_add(g_strdup(":struct"), keys);
        else if (incr_pc_is_user_state(kind))
            incr_desc_feature_add(g_strdup(":state"), keys);
    }
}

/* Collects features of a non-subject compound; deep nesting makes the index loose. */
static void
incr_desc_collect_compound(const ns_css_simple *c, const GPtrArray *keys,
                           int depth)
{
    if (!c) return;
    if (depth > 6) {
        g_desc_features_loose = TRUE;
        return;
    }
    incr_desc_collect_features(c, keys);
    incr_desc_collect_groups(c, keys, depth, FALSE);
}

/* Collects features from a subject compound's nested groups; deep nesting goes loose. */
static void
incr_desc_collect_identity(const ns_css_simple *c, const GPtrArray *keys,
                           int depth)
{
    if (!c) return;
    if (depth > 6) {
        g_desc_features_loose = TRUE;
        return;
    }
    incr_desc_collect_groups(c, keys, depth, TRUE);
}

/* Returns the last sibling combinator index; *descends if a descendant step follows it. */
static guint
incr_desc_last_sibling_comb(const ns_css_selector *sel, gboolean *descends)
{
    guint at = 0;
    *descends = FALSE;
    for (guint i = 1; sel && sel->combinators && i < sel->combinators->len;
         i++) {
        ns_css_comb comb = g_array_index(sel->combinators, ns_css_comb, i);
        if (comb == NS_CSS_COMB_ADJACENT || comb == NS_CSS_COMB_SIBLING) {
            at = i;
            *descends = FALSE;
        } else if (at && (comb == NS_CSS_COMB_DESCENDANT ||
                          comb == NS_CSS_COMB_CHILD)) {
            *descends = TRUE;
        }
    }
    return at;
}

/* Registers :struct when a sibling combinator is followed by descendant steps. */
static void
incr_desc_collect_sibling_chain(const ns_css_selector *sel,
                                const GPtrArray *keys)
{
    gboolean descends = FALSE;
    if (incr_desc_last_sibling_comb(sel, &descends) && descends)
        incr_desc_feature_add(g_strdup(":struct"), keys);
}

/* Collects descendant features of every compound in a nested selector. */
static void
incr_desc_collect_selector(const ns_css_selector *sel, const GPtrArray *keys,
                           int depth)
{
    incr_desc_collect_sibling_chain(sel, keys);
    for (guint i = 0; sel && sel->compounds && i < sel->compounds->len; i++)
        incr_desc_collect_compound(g_ptr_array_index(sel->compounds, i),
                                   keys, depth);
}

/* Indexes which ancestor features of a rule selector invalidate which subjects. */
static void
incr_desc_collect_rule_selector(const ns_css_selector *sel)
{
    if (!sel || !sel->compounds || sel->compounds->len == 0) return;
    guint last = sel->compounds->len - 1;
    const ns_css_simple *subject = g_ptr_array_index(sel->compounds, last);
    if (!subject || subject->never_match) return;
    GPtrArray *subject_keys = incr_desc_subject_keys(subject);
    gboolean descends = FALSE;
    guint sib = incr_desc_last_sibling_comb(sel, &descends);
    if (sib && descends) {
        GPtrArray *keys = subject_keys ? g_ptr_array_ref(subject_keys)
                                       : incr_desc_depth_keys(sel, sib);
        incr_desc_feature_add(g_strdup(":struct"), keys);
        if (keys) g_ptr_array_unref(keys);
    }
    for (guint i = 0; i < last; i++) {
        const ns_css_simple *c = g_ptr_array_index(sel->compounds, i);
        if (!c) continue;
        if (subject_keys) {
            incr_desc_collect_compound(c, subject_keys, 0);
            continue;
        }
        GPtrArray *keys = incr_desc_depth_keys(sel, i);
        incr_desc_collect_features(c, keys);
        incr_desc_collect_groups(c, NULL, 0, FALSE);
        if (keys) g_ptr_array_unref(keys);
    }
    incr_desc_collect_identity(subject, subject_keys, 0);
    if (subject_keys) g_ptr_array_unref(subject_keys);
}

/* Builds descendant-invalidation features for a sheet's selectors and @scope bounds. */
static void
incr_desc_collect_sheet(const ns_css_stylesheet *sh)
{
    for (guint ri = 0; sh && sh->rules && ri < sh->rules->len; ri++) {
        const ns_css_rule *r = g_ptr_array_index(sh->rules, ri);
        if (!r) continue;
        for (guint si = 0; r->selectors && si < r->selectors->len; si++)
            incr_desc_collect_rule_selector(g_ptr_array_index(r->selectors, si));
        for (guint si = 0; r->scopes && si < r->scopes->len; si++) {
            const ns_css_scope *scope = g_ptr_array_index(r->scopes, si);
            const GPtrArray *lists[2] = { scope->roots, scope->limits };
            for (guint li = 0; li < G_N_ELEMENTS(lists); li++)
                for (guint xi = 0; lists[li] && xi < lists[li]->len; xi++)
                    incr_desc_collect_selector(
                        g_ptr_array_index(lists[li], xi), NULL, 0);
        }
    }
}

typedef struct ns_css_incr_sheet_keys {
    GHashTable *desc_features;
    gboolean    desc_loose;
    GHashTable *class_keys;
    GHashTable *id_keys;
    gboolean    class_loose;
    gboolean    id_loose;
} incr_sheet_keys;

static void
incr_sheet_keys_free(struct ns_css_incr_sheet_keys *k)
{
    if (!k) return;
    g_hash_table_destroy(k->desc_features);
    g_hash_table_destroy(k->class_keys);
    g_hash_table_destroy(k->id_keys);
    g_free(k);
}

/* Returns the sheet's cached descendant-feature and class/id key sets, building them once. */
static incr_sheet_keys *
incr_sheet_keys_for(const ns_css_stylesheet *sh)
{
    if (sh->incr_keys) return sh->incr_keys;
    incr_sheet_keys *k = g_new0(incr_sheet_keys, 1);
    GHashTable *outer_features = g_desc_features;
    gboolean outer_desc_loose = g_desc_features_loose;
    GHashTable *outer_class = g_class_keys, *outer_id = g_id_keys;
    gboolean outer_class_loose = g_class_keys_loose;
    gboolean outer_id_loose = g_id_keys_loose;
    g_desc_features = g_hash_table_new_full(g_str_hash, g_str_equal, g_free,
                                            incr_desc_value_free);
    g_desc_features_loose = FALSE;
    g_class_keys = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
    g_id_keys = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
    g_class_keys_loose = FALSE;
    g_id_keys_loose = FALSE;
    incr_desc_collect_sheet(sh);
    incr_collect_name_keys(sh);
    k->desc_features = g_desc_features;
    k->desc_loose = g_desc_features_loose;
    k->class_keys = g_class_keys;
    k->id_keys = g_id_keys;
    k->class_loose = g_class_keys_loose;
    k->id_loose = g_id_keys_loose;
    g_desc_features = outer_features;
    g_desc_features_loose = outer_desc_loose;
    g_class_keys = outer_class;
    g_id_keys = outer_id;
    g_class_keys_loose = outer_class_loose;
    g_id_keys_loose = outer_id_loose;
    ((ns_css_stylesheet *)sh)->incr_keys = k;
    return k;
}

static void
incr_key_set_union(GHashTable *into, GHashTable *from)
{
    GHashTableIter it;
    gpointer key;
    g_hash_table_iter_init(&it, from);
    while (g_hash_table_iter_next(&it, &key, NULL))
        if (!g_hash_table_contains(into, key))
            g_hash_table_add(into, g_strdup(key));
}

/* Merges a sheet's cached invalidation keys into the global restyle indexes. */
static void
incr_sheet_keys_merge(const ns_css_stylesheet *sh)
{
    if (!sh) return;
    incr_sheet_keys *k = incr_sheet_keys_for(sh);
    g_desc_features_loose |= k->desc_loose;
    g_class_keys_loose |= k->class_loose;
    g_id_keys_loose |= k->id_loose;
    incr_key_set_union(g_class_keys, k->class_keys);
    incr_key_set_union(g_id_keys, k->id_keys);
    GHashTableIter it;
    gpointer feature, keys;
    g_hash_table_iter_init(&it, k->desc_features);
    while (g_hash_table_iter_next(&it, &feature, &keys)) {
        gpointer cur = g_hash_table_lookup(g_desc_features, feature);
        if (cur == DESC_ALL) continue;
        if (keys == DESC_ALL) {
            g_hash_table_replace(g_desc_features, g_strdup(feature), DESC_ALL);
            continue;
        }
        if (!cur) {
            cur = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
            g_hash_table_insert(g_desc_features, g_strdup(feature), cur);
        }
        incr_key_set_union(cur, keys);
    }
}

/* Rebuilds the global descendant-feature index from the UA and author sheets. */
static void
incr_desc_features_build(const ns_css_stylesheet *ua,
                         const ns_css_stylesheet *const *author, gsize n)
{
    if (g_desc_features) g_hash_table_remove_all(g_desc_features);
    else g_desc_features = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                 g_free, incr_desc_value_free);
    g_desc_features_loose = FALSE;
    incr_sheet_keys_merge(ua);
    for (gsize i = 0; i < n; i++) incr_sheet_keys_merge(author[i]);
}

/* True for attributes whose changes matter only to selectors, not element state or hints. */
static gboolean
incr_attr_self_only_name(const char *name)
{
    static const char *const element_state[] = {
        "id", "lang", "dir", "disabled", "checked", "selected", "open",
        "href", "contenteditable", "value", "type", "placeholder",
        "required", "readonly", "multiple", "min", "max", "step", "pattern",
        "minlength", "maxlength", "popover", "slot", "part", "exportparts",
        "is", "name", "form", "inert", "muted",
    };
    if (!name || !*name || strchr(name, ':')) return FALSE;
    if (g_ascii_strncasecmp(name, "data-nd-", 8) == 0) return FALSE;
    if (is_presentational_attr_name(name)) return FALSE;
    for (gsize i = 0; i < G_N_ELEMENTS(element_state); i++)
        if (g_ascii_strcasecmp(name, element_state[i]) == 0) return FALSE;
    return TRUE;
}

/* Adds a feature's invalidation keys to inv (frees feature); FALSE if it invalidates all. */
static gboolean
incr_desc_feature_merge(GHashTable *inv, char *feature)
{
    gpointer keys = g_hash_table_lookup(g_desc_features, feature);
    g_free(feature);
    if (!keys) return TRUE;
    if (keys == DESC_ALL) return FALSE;
    GHashTableIter it;
    gpointer k;
    g_hash_table_iter_init(&it, keys);
    while (g_hash_table_iter_next(&it, &k, NULL))
        if (!g_hash_table_contains(inv, k))
            g_hash_table_add(inv, g_strdup(k));
    return TRUE;
}

static gboolean
incr_class_list_has(const char *list, const char *tok, gsize len)
{
    for (const char *p = list; p && *p; ) {
        while (*p && g_ascii_isspace((guchar)*p)) p++;
        const char *start = p;
        while (*p && !g_ascii_isspace((guchar)*p)) p++;
        if ((gsize)(p - start) == len && memcmp(start, tok, len) == 0)
            return TRUE;
    }
    return FALSE;
}

/* Merges keys for classes in from but not in other; FALSE if any invalidates all. */
static gboolean
incr_desc_merge_class_diff(GHashTable *inv, const char *from, const char *other)
{
    for (const char *p = from; p && *p; ) {
        while (*p && g_ascii_isspace((guchar)*p)) p++;
        const char *start = p;
        while (*p && !g_ascii_isspace((guchar)*p)) p++;
        gsize len = (gsize)(p - start);
        if (len == 0 || incr_class_list_has(other, start, len)) continue;
        char *tok = g_strndup(start, len);
        gboolean ok = incr_desc_feature_merge(inv, incr_lower_key('.', tok));
        g_free(tok);
        if (!ok) return FALSE;
    }
    return TRUE;
}

/* Targets restyle for an attribute change via descendant keys; FALSE if full one needed. */
static gboolean
incr_mark_attr_self(ns_node *target, const char *name, const char *old_value)
{
    if (!g_desc_features || g_desc_features_loose ||
        !incr_attr_self_only_name(name))
        return FALSE;
    GHashTable *inv = g_hash_table_new_full(g_str_hash, g_str_equal,
                                            g_free, NULL);
    gboolean ok = incr_desc_feature_merge(inv, incr_lower_key('[', name));
    if (ok && g_ascii_strcasecmp(name, "class") == 0) {
        const char *now = ns_element_get_attr(target, "class");
        ok = incr_desc_merge_class_diff(inv, old_value, now) &&
             incr_desc_merge_class_diff(inv, now, old_value);
    }
    if (ok) {
        incr_mark_self_dirty(target);
        incr_desc_keys_merge(target, inv);
        incr_mark_has_subjects(target);
    }
    g_hash_table_destroy(inv);
    return ok;
}

/* Marks restyle needs after an attribute change, including sibling-combinator effects. */
void
ns_css_mark_attr_dirty(ns_node *target, const char *name, const char *old_value)
{
    if (!target) return;
    if (!ns_css_attr_may_affect_style(target, name)) return;
    if (incr_name_change_unused(target, name, old_value)) return;
    if (name && old_value &&
        g_strcmp0(ns_element_get_attr(target, name), old_value) == 0)
        return;
    if (!g_struct_ready) {
        ns_css_mark_restyle_dirty(target->parent ? target->parent : target);
        return;
    }
    gboolean sib = g_sib_loose ||
        incr_attr_key_change_is_sib(target, name, old_value);
    if (!sib && name && g_sib_attrs) {
        char *low = g_ascii_strdown(name, -1);
        if (g_hash_table_contains(g_sib_attrs, low)) {
            gboolean value_sensitive = g_sib_value_attrs &&
                g_hash_table_contains(g_sib_value_attrs, low);
            gboolean was_present = old_value != NULL;
            gboolean is_present = ns_element_get_attr(target, name) != NULL;
            sib = value_sensitive || was_present != is_present;
        }
        g_free(low);
    }
    if (!incr_mark_attr_self(target, name, old_value))
        ns_css_mark_restyle_dirty(target);
    if (sib && target->next_sibling &&
        !incr_mark_following_siblings(target->next_sibling))
        ns_css_mark_restyle_dirty(target->parent ? target->parent : target);
}

/* True if any selector or intrinsic behavior may depend on the named attribute. */
gboolean
ns_css_attr_may_affect_style(const ns_node *target, const char *name)
{
    (void)target;
    if (!name || !*name || !g_struct_ready || !g_attr_keys) return TRUE;
    if (is_presentational_attr_name(name)) return TRUE;
    char *low = g_ascii_strdown(name, -1);
    gboolean affects = g_hash_table_contains(g_attr_keys, low);
    static const char *const intrinsic[] = {
        "class", "id", "style", "hidden", "lang", "xml:lang", "dir",
        "width", "height", "src", "srcset", "sizes", "href", "type",
        "value", "checked", "selected", "open", "disabled", "readonly",
        "required", "placeholder", "multiple", "size", "rows", "cols",
        "rowspan", "colspan", "span", "start", "reversed", "wrap",
        "contenteditable", "inert", "popover", "popovertarget", "slot",
        "name", "form", "list", "min", "max", "step", "media",
    };
    for (guint i = 0; !affects && i < G_N_ELEMENTS(intrinsic); i++)
        affects = strcmp(low, intrinsic[i]) == 0;
    g_free(low);
    return affects;
}

/* True if an attribute change needs only restyle, not layout reading the attribute. */
gboolean
ns_css_attr_only_restyles(const ns_node *target, const char *name)
{
    if (!name || !*name) return FALSE;
    if (g_ascii_strcasecmp(name, "style") == 0) return TRUE;
    if (g_ascii_strcasecmp(name, "class") == 0)
        return !(target && target->name &&
                 (g_ascii_strcasecmp(target->name, "input") == 0 ||
                  g_ascii_strcasecmp(target->name, "button") == 0 ||
                  g_ascii_strcasecmp(target->name, "select") == 0 ||
                  g_ascii_strcasecmp(target->name, "textarea") == 0));
    if (is_presentational_attr_name(name)) return FALSE;
    static const char *const read_by_layout[] = {
        "id", "hidden", "lang", "xml:lang", "dir", "width", "height", "src",
        "srcset", "sizes", "href", "type", "value", "checked", "selected",
        "open", "disabled", "readonly", "required", "placeholder",
        "multiple", "size", "rows", "cols", "rowspan", "colspan", "span",
        "start", "reversed", "wrap", "contenteditable", "inert", "popover",
        "popovertarget", "slot", "name", "form", "list", "min", "max",
        "step", "media", "label", "align", "poster",
        "controls", "usemap", "coords", "shape", "target",
    };
    for (guint i = 0; i < G_N_ELEMENTS(read_by_layout); i++)
        if (g_ascii_strcasecmp(name, read_by_layout[i]) == 0) return FALSE;
    return !g_str_has_prefix(name, "data-");
}

static gboolean
incr_add_positive_subject_deps(GHashTable *keys, GPtrArray *attrs,
                               const ns_css_selector *sel, int depth);

/* Adds one positive key (id, class, attr or tag) for a compound, or for all :is() arms. */
static gboolean
incr_add_positive_compound_deps(GHashTable *keys, GPtrArray *attrs,
                                const ns_css_simple *c, int depth)
{
    if (!c || depth > 6) return FALSE;
    if (c->id && *c->id) {
        g_hash_table_add(keys, g_strconcat("#", c->id, NULL));
        return TRUE;
    }
    if (c->classes && c->classes->len > 0) {
        const char *cls = g_ptr_array_index(c->classes, 0);
        if (cls && *cls) {
            g_hash_table_add(keys, g_strconcat(".", cls, NULL));
            return TRUE;
        }
    }
    if (c->attrs && c->attrs->len > 0) {
        g_ptr_array_add(attrs, &g_array_index(c->attrs, ns_css_attr_pred, 0));
        return TRUE;
    }
    if (c->type && *c->type && strcmp(c->type, "*") != 0) {
        char *type = g_ascii_strdown(c->type, -1);
        g_hash_table_add(keys, g_strconcat("%", type, NULL));
        g_free(type);
        return TRUE;
    }
    if (!c->matches_any) return FALSE;
    for (guint gi = 0; gi < c->matches_any->len; gi++) {
        const GPtrArray *group = g_ptr_array_index(c->matches_any, gi);
        if (!group || group->len == 0) continue;
        GHashTable *group_keys = g_hash_table_new_full(
            g_str_hash, g_str_equal, g_free, NULL);
        GPtrArray *group_attrs = g_ptr_array_new();
        gboolean complete = TRUE;
        for (guint si = 0; si < group->len; si++)
            if (!incr_add_positive_subject_deps(
                    group_keys, group_attrs,
                    g_ptr_array_index(group, si), depth + 1)) {
                complete = FALSE;
                break;
            }
        if (complete) {
            GHashTableIter it;
            gpointer key;
            g_hash_table_iter_init(&it, group_keys);
            while (g_hash_table_iter_next(&it, &key, NULL))
                g_hash_table_add(keys, g_strdup(key));
            for (guint ai = 0; ai < group_attrs->len; ai++)
                g_ptr_array_add(attrs, g_ptr_array_index(group_attrs, ai));
            g_hash_table_destroy(group_keys);
            g_ptr_array_free(group_attrs, TRUE);
            return TRUE;
        }
        g_hash_table_destroy(group_keys);
        g_ptr_array_free(group_attrs, TRUE);
    }
    return FALSE;
}

static gboolean
incr_add_positive_subject_deps(GHashTable *keys, GPtrArray *attrs,
                               const ns_css_selector *sel, int depth)
{
    if (!sel || !sel->compounds || sel->compounds->len == 0)
        return FALSE;
    const ns_css_simple *subject =
        g_ptr_array_index(sel->compounds, sel->compounds->len - 1);
    return incr_add_positive_compound_deps(keys, attrs, subject, depth);
}

static gboolean incr_selector_uses_has(const ns_css_selector *sel, int depth);

/* True if a compound or nested selector uses :has(); deep nesting counts as yes. */
static gboolean
incr_simple_uses_has(const ns_css_simple *c, int depth)
{
    if (!c) return FALSE;
    if (depth > 6) return TRUE;
    if (c->has_groups && c->has_groups->len > 0) return TRUE;
    if (c->pseudos)
        for (guint i = 0; i < c->pseudos->len; i++) {
            const ns_css_pseudo_pred *p =
                &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
            if (p->of_group)
                for (guint gi = 0; gi < p->of_group->len; gi++)
                    if (incr_selector_uses_has(
                            g_ptr_array_index(p->of_group, gi), depth + 1))
                        return TRUE;
        }
    GPtrArray *groups[2] = { c->matches_any, c->matches_none };
    for (guint g = 0; g < G_N_ELEMENTS(groups); g++) {
        if (!groups[g]) continue;
        for (guint gi = 0; gi < groups[g]->len; gi++) {
            const GPtrArray *group = g_ptr_array_index(groups[g], gi);
            for (guint si = 0; group && si < group->len; si++)
                if (incr_selector_uses_has(
                        g_ptr_array_index(group, si), depth + 1))
                    return TRUE;
        }
    }
    return FALSE;
}

static gboolean
incr_selector_uses_has(const ns_css_selector *sel, int depth)
{
    if (!sel || !sel->compounds) return FALSE;
    for (guint i = 0; i < sel->compounds->len; i++)
        if (incr_simple_uses_has(
                g_ptr_array_index(sel->compounds, i), depth))
            return TRUE;
    return FALSE;
}

/* True if a :has() argument uses sibling combinators or nested selector groups. */
static gboolean
incr_has_group_uses_siblings(const GPtrArray *group)
{
    for (guint si = 0; group && si < group->len; si++) {
        const ns_css_selector *sel = g_ptr_array_index(group, si);
        if (!sel) continue;
        for (guint ci = 0; sel->combinators && ci < sel->combinators->len; ci++) {
            ns_css_comb comb = g_array_index(sel->combinators, ns_css_comb, ci);
            if (comb == NS_CSS_COMB_ADJACENT || comb == NS_CSS_COMB_SIBLING)
                return TRUE;
        }
        for (guint ci = 0; sel->compounds && ci < sel->compounds->len; ci++) {
            const ns_css_simple *c = g_ptr_array_index(sel->compounds, ci);
            if (!c) continue;
            if (c->matches_any || c->matches_none || c->has_groups)
                return TRUE;
            for (guint pi = 0; c->pseudos && pi < c->pseudos->len; pi++)
                if (g_array_index(c->pseudos, ns_css_pseudo_pred, pi).of_group)
                    return TRUE;
        }
    }
    return FALSE;
}

/* Records an unkeyable :has() anchor as self, descendant-keyed or fully loose. */
static void
incr_note_loose_has_anchor(const ns_css_simple *c, gboolean identity,
                           const char *subject_key)
{
    for (guint gi = 0; c->has_groups && gi < c->has_groups->len; gi++)
        if (incr_has_group_uses_siblings(g_ptr_array_index(c->has_groups, gi)))
            g_has_loose_sibling = TRUE;
    if (identity) {
        g_has_loose_self = TRUE;
    } else if (subject_key) {
        if (!g_hash_table_contains(g_has_loose_desc, subject_key))
            g_hash_table_add(g_has_loose_desc, g_strdup(subject_key));
    } else {
        g_has_cq_loose = TRUE;
    }
}

static gboolean incr_collect_has_anchors_selector(const ns_css_selector *sel,
                                                  int depth, gboolean identity,
                                                  const char *subject_key);

/* Collects keys for compounds bearing :has(), recursing into nested selectors. */
static gboolean
incr_collect_has_anchors_simple(const ns_css_simple *c, int depth,
                                gboolean identity, const char *subject_key)
{
    if (!c || depth > 6) return FALSE;
    gboolean found = FALSE;
    if (c->has_groups && c->has_groups->len > 0) {
        found = TRUE;
        for (guint gi = 0; gi < c->has_groups->len; gi++)
            if (incr_has_group_uses_siblings(
                    g_ptr_array_index(c->has_groups, gi)))
                g_has_sibling_args = TRUE;
        if (!incr_add_positive_compound_deps(
                identity ? g_has_self_keys : g_has_cq_keys,
                identity ? g_has_self_attrs : g_has_cq_attrs, c, depth))
            incr_note_loose_has_anchor(c, identity, subject_key);
    }
    if (c->pseudos)
        for (guint i = 0; i < c->pseudos->len; i++) {
            const ns_css_pseudo_pred *p =
                &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
            if (!p->of_group) continue;
            for (guint gi = 0; gi < p->of_group->len; gi++)
                found |= incr_collect_has_anchors_selector(
                    g_ptr_array_index(p->of_group, gi), depth + 1, FALSE,
                    NULL);
        }
    GPtrArray *groups[2] = { c->matches_any, c->matches_none };
    for (guint g = 0; g < G_N_ELEMENTS(groups); g++) {
        if (!groups[g]) continue;
        for (guint gi = 0; gi < groups[g]->len; gi++) {
            const GPtrArray *group = g_ptr_array_index(groups[g], gi);
            for (guint si = 0; group && si < group->len; si++)
                found |= incr_collect_has_anchors_selector(
                    g_ptr_array_index(group, si), depth + 1, identity,
                    subject_key);
        }
    }
    return found;
}

static gboolean
incr_collect_has_anchors_selector(const ns_css_selector *sel, int depth,
                                  gboolean identity, const char *subject_key)
{
    if (!sel || !sel->compounds || depth > 6) return FALSE;
    gboolean found = FALSE;
    guint last = sel->compounds->len - 1;
    for (guint i = 0; i < sel->compounds->len; i++)
        found |= incr_collect_has_anchors_simple(
            g_ptr_array_index(sel->compounds, i), depth,
            identity && i == last, subject_key);
    return found;
}

/* Indexes :has() anchors in a sheet's selectors for incremental invalidation. */
static void
incr_collect_has_cq_keys(const ns_css_stylesheet *sh)
{
    if (!sh || !sh->rules) return;
    for (guint ri = 0; ri < sh->rules->len; ri++) {
        const ns_css_rule *r = g_ptr_array_index(sh->rules, ri);
        if (!r || !r->selectors) continue;
        for (guint si = 0; si < r->selectors->len; si++) {
            const ns_css_selector *sel = g_ptr_array_index(r->selectors, si);
            if (!sel || !sel->compounds || sel->compounds->len == 0) continue;
            if (!incr_selector_uses_has(sel, 0)) continue;
            char *subject_key = incr_desc_subject_key(
                g_ptr_array_index(sel->compounds, sel->compounds->len - 1));
            if (!incr_collect_has_anchors_selector(sel, 0, TRUE, subject_key))
                g_has_cq_loose = TRUE;
            g_free(subject_key);
        }
    }
}

static gint
incr_u64_cmp(gconstpointer a, gconstpointer b)
{
    guint64 x = *(const guint64 *)a, y = *(const guint64 *)b;
    return x < y ? -1 : x > y;
}

/* Hashes sheet serials for style reuse; *out_keys_sig also covers shadow-scoped templates. */
static guint64
incr_sheet_sig(const ns_css_stylesheet *ua,
               const ns_css_stylesheet *const *author, gsize n,
               guint64 *out_keys_sig)
{
    guint64 h = 1469598103934665603ULL;
    guint64 unscoped = 0;
    GArray *templates = NULL;
    for (gsize i = 0; i < n; i++) {
        if (author[i] && author[i]->host_scope) {
            if (!templates)
                templates = g_array_new(FALSE, FALSE, sizeof(guint64));
            g_array_append_val(templates, author[i]->host_scope_template);
            continue;
        }
        h ^= author[i] ? author[i]->serial : 0;
        h *= 1099511628211ULL;
        unscoped++;
    }
    guint64 vals[3] = { ua ? ua->serial : 0, unscoped,
                        ns_css_registered_property_serial() };
    for (int i = 0; i < 3; i++) { h ^= vals[i]; h *= 1099511628211ULL; }
    guint64 styles_sig = h;
    if (templates) {
        g_array_sort(templates, incr_u64_cmp);
        for (guint i = 0; i < templates->len; i++) {
            guint64 t = g_array_index(templates, guint64, i);
            if (i > 0 && t == g_array_index(templates, guint64, i - 1))
                continue;
            h ^= t;
            h *= 1099511628211ULL;
        }
        g_array_free(templates, TRUE);
    }
    *out_keys_sig = h;
    return styles_sig;
}

/* Hashes shadow-scoped sheets per host scope id, with their positions; NULL if none. */
static GHashTable *
incr_host_sheet_keys(const ns_css_stylesheet *const *author, gsize n)
{
    GHashTable *keys = NULL;
    guint64 slot = 0;
    for (gsize i = 0; i < n; i++) {
        const ns_css_stylesheet *sh = author[i];
        if (!sh || !sh->host_scope) {
            slot++;
            continue;
        }
        if (!keys)
            keys = g_hash_table_new_full(g_str_hash, g_str_equal, g_free,
                                         g_free);
        guint64 *k = g_hash_table_lookup(keys, sh->host_scope);
        if (!k) {
            k = g_new(guint64, 1);
            *k = 1469598103934665603ULL;
            g_hash_table_insert(keys, g_strdup(sh->host_scope), k);
        }
        *k = (*k ^ sh->serial) * 1099511628211ULL;
        *k = (*k ^ slot) * 1099511628211ULL;
    }
    return keys;
}

/* Adds host scopes whose sheet hash differs or vanished between maps to changed. */
static void
incr_note_changed_hosts(GHashTable *changed, GHashTable *from, GHashTable *to)
{
    if (!from) return;
    GHashTableIter it;
    gpointer k, v;
    g_hash_table_iter_init(&it, from);
    while (g_hash_table_iter_next(&it, &k, &v)) {
        const guint64 *other = to ? g_hash_table_lookup(to, k) : NULL;
        if (!other || *other != *(const guint64 *)v)
            g_hash_table_add(changed, k);
    }
}

/* True if n's host scope or any of its adopted scopes is in the changed set. */
static gboolean
incr_host_scope_changed(const ns_node *n, GHashTable *changed)
{
    const char *id = ns_element_get_attr(n, NS_HOST_SCOPE_ATTR);
    if (id && g_hash_table_contains(changed, id)) return TRUE;
    const char *adopt = ns_element_get_attr(n, NS_ADOPT_SCOPE_ATTR);
    if (!adopt) return FALSE;
    GHashTableIter it;
    gpointer k;
    g_hash_table_iter_init(&it, changed);
    while (g_hash_table_iter_next(&it, &k, NULL))
        if (word_list_contains(adopt, k)) return TRUE;
    return FALSE;
}

/* Marks elements whose shadow-scoped stylesheets changed for restyle. */
static void
incr_mark_changed_hosts(ns_node *doc, GHashTable *prev, GHashTable *now)
{
    GHashTable *changed = g_hash_table_new(g_str_hash, g_str_equal);
    incr_note_changed_hosts(changed, now, prev);
    incr_note_changed_hosts(changed, prev, now);
    if (g_hash_table_size(changed) > 0) {
        ns_node *n = doc;
        while (n) {
            if (n->kind == NS_NODE_ELEMENT &&
                incr_host_scope_changed(n, changed))
                ns_css_mark_restyle_dirty(n);
            if (n->first_child) {
                n = n->first_child;
                continue;
            }
            while (n && n != doc && !n->next_sibling) n = n->parent;
            n = (n && n != doc) ? n->next_sibling : NULL;
        }
    }
    g_hash_table_destroy(changed);
}

static GHashTable *g_style_share;
static GByteArray *g_share_scratch;
static guint64 g_style_share_next_id;

typedef struct {
    guint32  hash;
    guint32  len;
    guint8  *data;
} share_key_t;

static guint
share_key_hash(gconstpointer p)
{
    return ((const share_key_t *)p)->hash;
}

static gboolean
share_key_equal(gconstpointer a, gconstpointer b)
{
    const share_key_t *x = a, *y = b;
    return x->hash == y->hash && x->len == y->len &&
           memcmp(x->data, y->data, x->len) == 0;
}

static void
share_key_free(gpointer p)
{
    share_key_t *k = p;
    g_free(k->data);
    g_free(k);
}

/* Multiply-xor hash of a byte buffer folded to 32 bits. */
static guint32
share_key_hash_bytes(const guint8 *d, guint32 n)
{
    guint64 h = 0x9E3779B97F4A7C15ULL ^ n;
    guint32 i = 0;
    for (; i + 8 <= n; i += 8) {
        guint64 w;
        memcpy(&w, d + i, sizeof w);
        h = (h ^ w) * 0xFF51AFD7ED558CCDULL;
        h ^= h >> 32;
    }
    guint64 tail = 0;
    for (guint32 k = 0; i + k < n; k++)
        tail |= (guint64)d[i + k] << (8 * k);
    h = (h ^ tail) * 0xC4CEB9FE1A85EC53ULL;
    h ^= h >> 29;
    return (guint32)(h ^ (h >> 32));
}

typedef struct {
    ns_css_pseudo_element pe;
    GArray *m;
    GArray *v;
    GArray *p;
} ns_pe_gather;

static ns_var_map *
ns_style_vars_clone(ns_var_map *vars)
{
    return ns_var_map_ref(vars);
}

/* Clones a style sharing values by refcount, recursing into pseudo-element styles. */
static ns_style *
ns_style_clone_shared(const ns_style *s)
{
    if (!s) return NULL;
    ns_style *c = ns_style_alloc();
    c->share_id = s->share_id;
    c->display  = s->display;
    c->specified_inline = s->specified_inline;
    c->currentcolor_bits = s->currentcolor_bits;
    for (int i = 0; i < NS_CSS_PROP_COUNT; i++) {
        c->values[i] = s->values[i];
        if (c->values[i]) c->values[i]->ref++;
    }
    c->before       = ns_style_clone_shared(s->before);
    c->after        = ns_style_clone_shared(s->after);
    c->first_letter = ns_style_clone_shared(s->first_letter);
    c->first_line   = ns_style_clone_shared(s->first_line);
    c->placeholder  = ns_style_clone_shared(s->placeholder);
    c->selection    = ns_style_clone_shared(s->selection);
    c->marker       = ns_style_clone_shared(s->marker);
    c->backdrop     = ns_style_clone_shared(s->backdrop);
    c->file_selector_button = ns_style_clone_shared(
        s->file_selector_button);
    c->vars = ns_style_vars_clone(s->vars);
    return c;
}

/* Appends a count header plus room for n entries to the share key buffer. */
static guint8 *
share_key_grow(GByteArray *b, guint n_entries, gsize entry_size)
{
    guint at = b->len;
    g_byte_array_set_size(b, at + sizeof(guint) + n_entries * entry_size);
    memcpy(b->data + at, &n_entries, sizeof n_entries);
    return b->data + at + sizeof(guint);
}

static guint8 *
share_key_put(guint8 *p, const void *src, gsize n)
{
    memcpy(p, src, n);
    return p + n;
}

/* Serializes match entries' cascade-order fields, rule, value and prop into the share key. */
static void
share_key_put_matches(GByteArray *b, const GArray *arr)
{
    const gsize order_len = offsetof(match_entry, inline_style) +
                            sizeof(gboolean);
    guint n = arr ? arr->len : 0;
    guint8 *p = share_key_grow(b, n, order_len + sizeof(void *) * 2 +
                                     sizeof(ns_css_prop));
    for (guint i = 0; i < n; i++) {
        const match_entry *e = &g_array_index((GArray *)arr, match_entry, i);
        p = share_key_put(p, e, order_len);
        p = share_key_put(p, &e->rule, sizeof e->rule);
        p = share_key_put(p, &e->value, sizeof e->value);
        p = share_key_put(p, &e->prop, sizeof e->prop);
    }
}

/* Serializes custom property matches' cascade-order fields, rule, name and text. */
static void
share_key_put_vars(GByteArray *b, const GArray *arr)
{
    const gsize order_len = offsetof(var_match, inline_style) +
                            sizeof(gboolean);
    guint n = arr ? arr->len : 0;
    guint8 *p = share_key_grow(b, n, order_len + sizeof(void *) * 3);
    for (guint i = 0; i < n; i++) {
        const var_match *e = &g_array_index((GArray *)arr, var_match, i);
        p = share_key_put(p, e, order_len);
        p = share_key_put(p, &e->rule, sizeof e->rule);
        p = share_key_put(p, &e->name, sizeof e->name);
        p = share_key_put(p, &e->text, sizeof e->text);
    }
}

/* Serializes pending matches' cascade-order fields, inline flag, rule and decl. */
static void
share_key_put_pending(GByteArray *b, const GArray *arr)
{
    const gsize order_len = offsetof(pending_match, decl_order_base) +
                            sizeof(int);
    guint n = arr ? arr->len : 0;
    guint8 *p = share_key_grow(b, n, order_len + sizeof(gboolean) +
                                     sizeof(void *) * 2);
    for (guint i = 0; i < n; i++) {
        const pending_match *e = &g_array_index((GArray *)arr, pending_match, i);
        p = share_key_put(p, e, order_len);
        p = share_key_put(p, &e->inline_style, sizeof e->inline_style);
        p = share_key_put(p, &e->rule, sizeof e->rule);
        p = share_key_put(p, &e->pd, sizeof e->pd);
    }
}

static gboolean
container_relative_unit(ns_css_unit unit)
{
    return unit == NS_CSS_UNIT_CQW || unit == NS_CSS_UNIT_CQH ||
           unit == NS_CSS_UNIT_CQI || unit == NS_CSS_UNIT_CQB ||
           unit == NS_CSS_UNIT_CQMIN || unit == NS_CSS_UNIT_CQMAX;
}

/* True if text contains a cq* container unit (case-insensitive substring scan). */
static gboolean
text_has_container_unit(const char *text)
{
    if (!text) return FALSE;
    static const char *units[] = {
        "cqw", "cqh", "cqi", "cqb", "cqmin", "cqmax"
    };
    for (const char *p = text; *p; p++) {
        if (g_ascii_tolower(p[0]) != 'c' || g_ascii_tolower(p[1]) != 'q')
            continue;
        for (guint i = 0; i < G_N_ELEMENTS(units); i++)
            if (g_ascii_strncasecmp(p, units[i], strlen(units[i])) == 0)
                return TRUE;
    }
    return FALSE;
}

/* True if any match sets font-size in a container-relative unit. */
static gboolean
share_matches_need_container(const GArray *matches)
{
    if (!matches) return FALSE;
    for (guint i = 0; i < matches->len; i++) {
        const match_entry *e = &g_array_index((GArray *)matches,
                                               match_entry, i);
        if (e->prop == NS_CSS_FONT_SIZE && e->value &&
            e->value->kind == NS_CSS_V_LENGTH &&
            container_relative_unit(e->value->u.length.unit))
            return TRUE;
    }
    return FALSE;
}

/* True if any custom property value text uses a cq* unit. */
static gboolean
share_vars_need_container(const GArray *matches)
{
    if (!matches) return FALSE;
    for (guint i = 0; i < matches->len; i++) {
        const var_match *e = &g_array_index((GArray *)matches, var_match, i);
        if (text_has_container_unit(e->text)) return TRUE;
    }
    return FALSE;
}

/* True if any pending declaration's raw value uses a cq* unit. */
static gboolean
share_pending_need_container(const GArray *matches)
{
    if (!matches) return FALSE;
    for (guint i = 0; i < matches->len; i++) {
        const pending_match *e = &g_array_index((GArray *)matches,
                                                 pending_match, i);
        if (e->pd && text_has_container_unit(e->pd->raw_vtext)) return TRUE;
    }
    return FALSE;
}

/* True if the style-sharing key must include the container stack (cq units used). */
static gboolean
share_key_needs_container(const GArray *matches,
                          const GArray *var_matches,
                          const GArray *pending_matches,
                          const ns_pe_gather *pe_g, int n_pe)
{
    if (share_matches_need_container(matches) ||
        share_vars_need_container(var_matches) ||
        share_pending_need_container(pending_matches))
        return TRUE;
    for (int i = 0; i < n_pe; i++)
        if (share_matches_need_container(pe_g[i].m) ||
            share_vars_need_container(pe_g[i].v) ||
            share_pending_need_container(pe_g[i].p))
            return TRUE;
    return FALSE;
}

/* Serializes parent style, root font, container context and all matches into a share key. */
static void
style_share_key(GByteArray *b,
                const ns_style *parent_style, double root_px,
                const GArray *matches, const GArray *var_matches,
                const GArray *pending_matches,
                const ns_pe_gather *pe_g, int n_pe)
{
    g_byte_array_set_size(b, 0);
    guint64 parent_id = parent_style ? parent_style->share_id : 0;
    g_byte_array_append(b, (const guint8 *)&parent_id, sizeof parent_id);
    g_byte_array_append(b, (const guint8 *)&root_px, sizeof root_px);
    guint cq_len = g_cq_stack &&
        share_key_needs_container(matches, var_matches, pending_matches,
                                  pe_g, n_pe)
        ? g_cq_stack->len : 0;
    g_byte_array_append(b, (const guint8 *)&cq_len, sizeof cq_len);
    if (cq_len)
        g_byte_array_append(b, (const guint8 *)g_cq_stack->data,
                            cq_len * (guint)sizeof(ns_cq_container));
    share_key_put_matches(b, matches);
    share_key_put_vars(b, var_matches);
    share_key_put_pending(b, pending_matches);
    for (int i = 0; i < n_pe; i++) {
        guint pe = (guint)pe_g[i].pe;
        g_byte_array_append(b, (const guint8 *)&pe, sizeof pe);
        share_key_put_matches(b, pe_g[i].m);
        share_key_put_vars(b, pe_g[i].v);
        share_key_put_pending(b, pe_g[i].p);
    }
}

/* True for elements where display: contents acts as none (replaced, controls, outer svg). */
static gboolean
element_cannot_be_unboxed(const ns_node *el)
{
    if (el->kind != NS_NODE_ELEMENT || !el->name) return FALSE;
    if (el->flags & NS_NODE_SVG_NS)
        return strcmp(el->name, "svg") == 0 && el->parent &&
               !(el->parent->flags & NS_NODE_SVG_NS);
    if (el->flags & NS_NODE_FOREIGN_NS) return FALSE;
    static const char *const unusual[] = {
        "audio", "br", "canvas", "embed", "frame", "frameset", "iframe",
        "img", "input", "meter", "object", "progress", "select",
        "textarea", "video", "wbr",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(unusual); i++)
        if (g_ascii_strcasecmp(el->name, unusual[i]) == 0) return TRUE;
    return FALSE;
}

/* Forces display: none for display: contents on elements that cannot be unboxed. */
static gboolean
display_contents_to_none(const ns_node *el, ns_style *s)
{
    if (s->display.box != NS_DISPLAY_BOX_CONTENTS ||
        !element_cannot_be_unboxed(el))
        return FALSE;
    ns_css_value_free(s->values[NS_CSS_DISPLAY]);
    s->values[NS_CSS_DISPLAY] = keyword_value("none");
    s->display = ns_css_display_from_keyword("none");
    return TRUE;
}

/* Hides noscript elements when scripting is enabled for their document. */
static gboolean
scripted_noscript_to_none(const ns_node *el, ns_style *s)
{
    if (!ns_node_is_element_named(el, "noscript") ||
        ns_display_is_none(s->display))
        return FALSE;
    const ns_node *root = ns_node_root(el);
    if (root && (root->flags & NS_NODE_SCRIPTING_DISABLED)) return FALSE;
    ns_css_value_free(s->values[NS_CSS_DISPLAY]);
    s->values[NS_CSS_DISPLAY] = keyword_value("none");
    s->display = ns_css_display_from_keyword("none");
    return TRUE;
}

static gboolean
display_forced_none(const ns_node *el, ns_style *s)
{
    return display_contents_to_none(el, s) || scripted_noscript_to_none(el, s);
}

/* Drops author box decorations on checkbox/radio inputs unless appearance is none. */
static void
strip_native_widget_decorations(const ns_node *el, ns_style *s)
{
    if (!ns_node_is_element_named(el, "input")) return;
    const char *type = ns_element_get_attr(el, "type");
    if (!type || (g_ascii_strcasecmp(type, "checkbox") != 0 &&
                  g_ascii_strcasecmp(type, "radio") != 0))
        return;
    const ns_css_value *ap = s->values[NS_CSS_APPEARANCE];
    if (ap && ap->kind == NS_CSS_V_KEYWORD && ap->u.keyword &&
        strcmp(ap->u.keyword, "none") == 0)
        return;
    static const ns_css_prop stripped[] = {
        NS_CSS_BACKGROUND_COLOR, NS_CSS_BACKGROUND_IMAGE,
        NS_CSS_BORDER_TOP_WIDTH, NS_CSS_BORDER_RIGHT_WIDTH,
        NS_CSS_BORDER_BOTTOM_WIDTH, NS_CSS_BORDER_LEFT_WIDTH,
        NS_CSS_BORDER_TOP_STYLE, NS_CSS_BORDER_RIGHT_STYLE,
        NS_CSS_BORDER_BOTTOM_STYLE, NS_CSS_BORDER_LEFT_STYLE,
        NS_CSS_BORDER_TOP_COLOR, NS_CSS_BORDER_RIGHT_COLOR,
        NS_CSS_BORDER_BOTTOM_COLOR, NS_CSS_BORDER_LEFT_COLOR,
        NS_CSS_BORDER_TOP_LEFT_RADIUS, NS_CSS_BORDER_TOP_RIGHT_RADIUS,
        NS_CSS_BORDER_BOTTOM_RIGHT_RADIUS, NS_CSS_BORDER_BOTTOM_LEFT_RADIUS,
        NS_CSS_PADDING_TOP, NS_CSS_PADDING_RIGHT,
        NS_CSS_PADDING_BOTTOM, NS_CSS_PADDING_LEFT,
        NS_CSS_BOX_SHADOW,
    };
    for (gsize i = 0; i < G_N_ELEMENTS(stripped); i++) {
        if (s->values[stripped[i]]) {
            ns_css_value_free(s->values[stripped[i]]);
            s->values[stripped[i]] = NULL;
        }
    }
}

static double
frame_edge_px(const ns_style *s, ns_css_prop prop)
{
    const ns_css_value *v = s->values[prop];
    if (!v || v->kind != NS_CSS_V_LENGTH || v->u.length.unit != NS_CSS_UNIT_PX)
        return 0;
    return v->u.length.v;
}

/* Returns a border width in px, or 0 when the border style is none or hidden. */
static double
frame_border_px(const ns_style *s, ns_css_prop width_prop,
                ns_css_prop style_prop)
{
    const ns_css_value *st = s->values[style_prop];
    if (!st || (st->kind == NS_CSS_V_KEYWORD && st->u.keyword &&
                (strcmp(st->u.keyword, "none") == 0 ||
                 strcmp(st->u.keyword, "hidden") == 0)))
        return 0;
    return frame_edge_px(s, width_prop);
}

/* Derives an iframe's content-box viewport size from its px width/height style. */
static gboolean
frame_viewport_from_style(const ns_style *s, double *w, double *h)
{
    if (!s) return FALSE;
    const ns_css_value *wv = s->values[NS_CSS_WIDTH];
    const ns_css_value *hv = s->values[NS_CSS_HEIGHT];
    if (!wv || wv->kind != NS_CSS_V_LENGTH ||
        wv->u.length.unit != NS_CSS_UNIT_PX ||
        !hv || hv->kind != NS_CSS_V_LENGTH ||
        hv->u.length.unit != NS_CSS_UNIT_PX)
        return FALSE;
    double fw = wv->u.length.v, fh = hv->u.length.v;
    if (ns_css_keyword_is(s->values[NS_CSS_BOX_SIZING], "border-box")) {
        fw -= frame_edge_px(s, NS_CSS_PADDING_LEFT) +
              frame_edge_px(s, NS_CSS_PADDING_RIGHT) +
              frame_border_px(s, NS_CSS_BORDER_LEFT_WIDTH,
                              NS_CSS_BORDER_LEFT_STYLE) +
              frame_border_px(s, NS_CSS_BORDER_RIGHT_WIDTH,
                              NS_CSS_BORDER_RIGHT_STYLE);
        fh -= frame_edge_px(s, NS_CSS_PADDING_TOP) +
              frame_edge_px(s, NS_CSS_PADDING_BOTTOM) +
              frame_border_px(s, NS_CSS_BORDER_TOP_WIDTH,
                              NS_CSS_BORDER_TOP_STYLE) +
              frame_border_px(s, NS_CSS_BORDER_BOTTOM_WIDTH,
                              NS_CSS_BORDER_BOTTOM_STYLE);
    }
    if (fw <= 0 || fh <= 0) return FALSE;
    *w = fw;
    *h = fh;
    return TRUE;
}

/* Tests for prefix plus lowercased name in a descendant invalidation key set. */
static gboolean
incr_desc_set_has(GHashTable *set, char prefix, const char *name, gsize len)
{
    char stack[128];
    char *key = len + 2 <= sizeof stack ? stack : g_malloc(len + 2);
    key[0] = prefix;
    for (gsize i = 0; i < len; i++) key[i + 1] = g_ascii_tolower(name[i]);
    key[len + 1] = '\0';
    gboolean hit = g_hash_table_contains(set, key);
    if (key != stack) g_free(key);
    return hit;
}

/* True if node matches an ancestor's pending descendant-invalidation set, incl. depth keys. */
static gboolean
incr_desc_inv_matches(const ns_node *node, int node_depth)
{
    if (!g_desc_inv_stack || g_desc_inv_stack->len == 0) return FALSE;
    const char *id = ns_element_get_attr(node, "id");
    guint n_tokens = 0;
    const ns_class_token *toks = ns_node_class_tokens(node, &n_tokens);
    for (guint si = 0; si < g_desc_inv_stack->len; si++) {
        GHashTable *set = g_ptr_array_index(g_desc_inv_stack, si);
        int rel = node_depth -
                  g_array_index(g_desc_inv_depths, int, si);
        if (rel >= 1 && rel <= 4) {
            char depth_key[4] = { '*', (char)('0' + rel), '\0', '\0' };
            if (g_hash_table_contains(set, depth_key)) return TRUE;
        }
        if (node->name &&
            incr_desc_set_has(set, '%', node->name, strlen(node->name)))
            return TRUE;
        if (id && *id && incr_desc_set_has(set, '#', id, strlen(id)))
            return TRUE;
        for (guint i = 0; i < n_tokens; i++)
            if (incr_desc_set_has(set, '.', toks[i].p, toks[i].len))
                return TRUE;
        for (const ns_attr *a = node->attrs; a; a = a->next) {
            const char *local_name = ns_attr_local_name(a);
            if (local_name && *local_name &&
                incr_desc_set_has(set, '[', local_name, strlen(local_name)))
                return TRUE;
        }
    }
    return FALSE;
}

/* True if two custom property tables have identical names and values. */
static gboolean
incr_var_tables_same(GHashTable *x, GHashTable *y)
{
    guint nx = x ? g_hash_table_size(x) : 0;
    guint ny = y ? g_hash_table_size(y) : 0;
    if (nx != ny) return FALSE;
    if (nx == 0) return TRUE;
    GHashTableIter it;
    gpointer k, v;
    g_hash_table_iter_init(&it, x);
    while (g_hash_table_iter_next(&it, &k, &v)) {
        gpointer other;
        if (!g_hash_table_lookup_extended(y, k, NULL, &other) ||
            g_strcmp0(v, other) != 0)
            return FALSE;
    }
    return TRUE;
}

static const ns_var_map *
incr_var_map_skip_empty(const ns_var_map *m)
{
    while (m && (!m->own || g_hash_table_size(m->own) == 0)) m = m->parent;
    return m;
}

/* Compares var map chains level by level, skipping empty levels, up to 16 deep. */
static gboolean
incr_var_maps_same(const ns_var_map *a, const ns_var_map *b)
{
    for (int level = 0; level < 16; level++) {
        a = incr_var_map_skip_empty(a);
        b = incr_var_map_skip_empty(b);
        if (a == b) return TRUE;
        if (!a || !b || !incr_var_tables_same(a->own, b->own)) return FALSE;
        a = a->parent;
        b = b->parent;
    }
    return FALSE;
}

static gboolean incr_style_same(const ns_style *a, const ns_style *b);

/* True if all pseudo-element sub-styles of a and b are equal. */
static gboolean
incr_pseudo_styles_same(const ns_style *a, const ns_style *b)
{
    const ns_style *pa[] = { a->before, a->after, a->first_letter,
                             a->first_line, a->placeholder, a->selection,
                             a->marker, a->backdrop, a->file_selector_button };
    const ns_style *pb[] = { b->before, b->after, b->first_letter,
                             b->first_line, b->placeholder, b->selection,
                             b->marker, b->backdrop, b->file_selector_button };
    for (gsize i = 0; i < G_N_ELEMENTS(pa); i++)
        if (!incr_style_same(pa[i], pb[i])) return FALSE;
    return TRUE;
}

/* Value-by-value style equality including display, currentcolor bits and vars. */
static gboolean
incr_style_same(const ns_style *a, const ns_style *b)
{
    if (a == b) return TRUE;
    if (!a || !b || memcmp(&a->display, &b->display, sizeof a->display) != 0 ||
        a->specified_inline != b->specified_inline ||
        a->currentcolor_bits != b->currentcolor_bits)
        return FALSE;
    for (int i = 0; i < NS_CSS_PROP_COUNT; i++) {
        const ns_css_value *x = a->values[i], *y = b->values[i];
        if (x == y) continue;
        if (!x || !y || x->kind != y->kind || !ns_css_value_equal(x, y))
            return FALSE;
    }
    return incr_var_maps_same(a->vars, b->vars);
}

/* Deep style equality including pseudo-element styles. */
gboolean
ns_css_style_equal(const ns_style *a, const ns_style *b)
{
    return incr_style_same(a, b) && incr_pseudo_styles_same(a, b);
}

/* Adds each key node and its ancestors to the incremental dirty-path set. */
static void
incr_path_add_ancestors(GHashTable *keys)
{
    if (!keys) return;
    GHashTableIter it;
    gpointer k;
    g_hash_table_iter_init(&it, keys);
    while (g_hash_table_iter_next(&it, &k, NULL))
        for (ns_node *n = k; n && !g_hash_table_contains(g_incr_path, n);
             n = n->parent)
            g_hash_table_add(g_incr_path, n);
}

/* Rebuilds the set of nodes on paths to any dirty, excluded or invalidated node. */
static void
incr_path_build(void)
{
    if (!g_incr_path)
        g_incr_path = g_hash_table_new(g_direct_hash, g_direct_equal);
    g_hash_table_remove_all(g_incr_path);
    incr_path_add_ancestors(g_incr_dirty);
    incr_path_add_ancestors(g_incr_self_dirty);
    incr_path_add_ancestors(g_incr_exclude);
    incr_path_add_ancestors(g_incr_desc_inv);
}

/* Finds the nearest non-contents ancestor style below root to use as layout parent. */
static const ns_style *
incr_bulk_layout_parent(const ns_node *from, const ns_node *root,
                        const ns_style *root_layout_parent, GHashTable *out)
{
    for (const ns_node *a = from; a; a = a->parent) {
        if (a->kind != NS_NODE_ELEMENT) continue;
        const ns_style *st = g_hash_table_lookup(out, a);
        if (a == root) {
            return st && !ns_display_is_contents(ns_css_display_of(st))
                   ? st : root_layout_parent;
        }
        if (st && !ns_display_is_contents(ns_css_display_of(st))) return st;
    }
    return root_layout_parent;
}

/* Cascades a node lacking a previous style, priming the ancestor filter with its chain. */
static void
incr_bulk_fallback(ns_node *root, ns_node *node,
                   const ns_css_stylesheet *ua,
                   const ns_css_stylesheet *const *author, gsize n_author,
                   const ns_style *root_layout_parent, double *root_px,
                   GHashTable *layer_ranks, GHashTable *out)
{
    GPtrArray *chain = g_ptr_array_new();
    for (ns_node *a = node->parent; a && a != root; a = a->parent)
        if (a->kind == NS_NODE_ELEMENT && a->first_child)
            g_ptr_array_add(chain, a);
    if (g_ancestor_filter_active)
        for (guint i = chain->len; i-- > 0; )
            css_ancestor_filter_update(g_ptr_array_index(chain, i), 1);
    const ns_style *parent_style = NULL;
    for (const ns_node *a = node->parent; a; a = a->parent)
        if (a->kind == NS_NODE_ELEMENT) {
            parent_style = g_hash_table_lookup(out, a);
            break;
        }
    const ns_style *layout_parent =
        incr_bulk_layout_parent(node->parent, root, root_layout_parent, out);
    cascade_walk(node, ua, author, n_author, parent_style, layout_parent,
                 root_px, layer_ranks, out, FALSE);
    if (g_ancestor_filter_active)
        for (guint i = 0; i < chain->len; i++)
            css_ancestor_filter_update(g_ptr_array_index(chain, i), -1);
    g_ptr_array_free(chain, TRUE);
}

/* Reuses previous styles across a clean subtree, cascading only nodes lacking one. */
static void
incr_bulk_reuse(ns_node *root, const ns_css_stylesheet *ua,
                const ns_css_stylesheet *const *author, gsize n_author,
                const ns_style *root_layout_parent, double *root_px,
                GHashTable *layer_ranks, GHashTable *out)
{
    ns_node *n = root->first_child;
    while (n) {
        gboolean descend = FALSE;
        if (n->kind == NS_NODE_ELEMENT) {
            ns_style *prev = g_hash_table_lookup(g_incr_prev_styles, n);
            if (prev) {
                prev->ref++;
                g_hash_table_insert(out, n, prev);
                g_incr_reused++;
                descend = n->first_child != NULL;
            } else {
                incr_bulk_fallback(root, n, ua, author, n_author,
                                   root_layout_parent, root_px, layer_ranks,
                                   out);
            }
        } else if (n->kind == NS_NODE_DOCUMENT) {
            incr_bulk_fallback(root, n, ua, author, n_author,
                               root_layout_parent, root_px, layer_ranks, out);
        }
        if (descend) {
            n = n->first_child;
            continue;
        }
        while (n != root && !n->next_sibling) n = n->parent;
        if (n == root) break;
        n = n->next_sibling;
    }
}

typedef struct {
    guint8   *data;
    guint32   len;
    guint32   hash;
    guint64   layout_parent_id;
    double    root_line_px;
    guint32   mutation_gen;
    ns_style *style;
} style_memo_entry;

static GHashTable *g_style_memo;

static void
style_memo_entry_free(gpointer p)
{
    style_memo_entry *e = p;
    if (!e) return;
    g_free(e->data);
    ns_style_free(e->style);
    g_free(e);
}

static void
style_memo_clear(void)
{
    if (g_style_memo) g_hash_table_remove_all(g_style_memo);
}

static void
style_memo_forget(const ns_node *node)
{
    if (g_style_memo) g_hash_table_remove(g_style_memo, node);
}

static double
style_memo_root_line(const ns_style *parent_style)
{
    return parent_style ? g_root_line_px : 0.0;
}

/* True if node's memo matches the share key, layout parent, root line and generation. */
static gboolean
style_memo_hit(const ns_node *node, const ns_style *prev,
              const share_key_t *key, const ns_style *parent_style,
              const ns_style *layout_parent)
{
    style_memo_entry *e = g_style_memo ? g_hash_table_lookup(g_style_memo, node)
                                     : NULL;
    return e && e->style == prev && e->mutation_gen == prev->mutation_gen &&
           e->hash == key->hash &&
           e->len == key->len &&
           e->layout_parent_id == (layout_parent ? layout_parent->share_id : 0) &&
           e->root_line_px == style_memo_root_line(parent_style) &&
           memcmp(e->data, key->data, key->len) == 0;
}

/* Records node's style with its share key for later memo hits; capped at 8192 entries. */
static void
style_memo_store(const ns_node *node, ns_style *style, const share_key_t *key,
                const ns_style *parent_style, const ns_style *layout_parent)
{
    if (!g_style_memo)
        g_style_memo = g_hash_table_new_full(g_direct_hash, g_direct_equal,
                                            NULL, style_memo_entry_free);
    if (g_hash_table_size(g_style_memo) >= 8192)
        g_hash_table_remove_all(g_style_memo);
    style_memo_entry *e = g_new(style_memo_entry, 1);
    e->data = g_memdup2(key->data, key->len);
    e->len = key->len;
    e->hash = key->hash;
    e->layout_parent_id = layout_parent ? layout_parent->share_id : 0;
    e->root_line_px = style_memo_root_line(parent_style);
    e->mutation_gen = style->mutation_gen;
    e->style = style;
    style->ref++;
    g_hash_table_replace(g_style_memo, (gpointer)node, e);
}

/* Styles a subtree via reuse, sharing, memo or full cascade, keeping scope/filter stacks. */
static void
cascade_walk(ns_node *node,
             const ns_css_stylesheet *ua,
             const ns_css_stylesheet *const *author, gsize n_author,
             const ns_style *parent_style,
             const ns_style *layout_parent,
             double *root_px,
             GHashTable *layer_ranks,
             GHashTable *out,
             gboolean under_dirty)
{
    static int depth;
    if (depth >= NS_CSS_MAX_CASCADE_DEPTH) return;
    depth++;
    const char *host_scope = node->kind == NS_NODE_ELEMENT
        ? ns_element_get_attr(node, NS_HOST_SCOPE_ATTR) : NULL;
    if (host_scope) {
        if (!g_host_scope_stack) g_host_scope_stack = g_ptr_array_new();
        g_ptr_array_add(g_host_scope_stack, (gpointer)host_scope);
    }
    const char *adopt_scope = node->kind == NS_NODE_ELEMENT
        ? ns_element_get_attr(node, NS_ADOPT_SCOPE_ATTR) : NULL;
    if (adopt_scope) {
        if (!g_adopt_scope_stack) g_adopt_scope_stack = g_ptr_array_new();
        g_ptr_array_add(g_adopt_scope_stack, (gpointer)adopt_scope);
    }
    double frame_vw = 0, frame_vh = 0;
    gboolean frame_viewport = FALSE;
    if (node->kind == NS_NODE_DOCUMENT && node->parent && g_frame_viewport_cb) {
        double fw = 0, fh = 0;
        if (!frame_viewport_from_style(parent_style, &fw, &fh))
            g_frame_viewport_cb(node->parent, &fw, &fh);
        if (fw > 0 && fh > 0 &&
            (fabs(fw - g_viewport_w) > 0.01 ||
             fabs(fh - g_viewport_h) > 0.01)) {
            frame_vw = g_viewport_w;
            frame_vh = g_viewport_h;
            g_viewport_w = fw;
            g_viewport_h = fh;
            frame_viewport = TRUE;
        }
    }
    const ns_style *child_parent_style = parent_style;
    const ns_style *child_layout_parent = layout_parent;
    gboolean nd_recurse_dirty = under_dirty;
    gboolean nd_bulk = FALSE;
    if (node->kind == NS_NODE_ELEMENT) {
        gboolean nd_node_dirty = under_dirty ||
            (g_incr_dirty && g_hash_table_contains(g_incr_dirty, node)) ||
            (g_incr_exclude && g_hash_table_contains(g_incr_exclude, node));
        ns_style *nd_prev =
            (g_incr_pass_active && !nd_node_dirty && g_incr_prev_styles)
            ? g_hash_table_lookup(g_incr_prev_styles, node) : NULL;
        ns_style *nd_self_prev = NULL;
        if (nd_prev &&
            ((g_incr_self_dirty &&
              g_hash_table_contains(g_incr_self_dirty, node)) ||
             incr_desc_inv_matches(node, depth))) {
            nd_self_prev = nd_prev;
            nd_prev = NULL;
        }
        ns_style *nd_old = nd_self_prev;
        if (!nd_old && !nd_prev && g_incr_pass_active && g_incr_prev_styles)
            nd_old = g_hash_table_lookup(g_incr_prev_styles, node);
        gboolean share_put = FALSE;
        ns_style *s;
        gboolean memo_store = FALSE;
        share_key_t memo_key = { 0 };
        if (nd_prev) {
            s = nd_prev;
            s->ref++;
            g_incr_reused++;
            nd_bulk = !under_dirty && g_incr_path &&
                      !g_hash_table_contains(g_incr_path, node) &&
                      (!g_desc_inv_stack || g_desc_inv_stack->len == 0) &&
                      (!g_cq_map || g_hash_table_size(g_cq_map) == 0);
        } else {
        s = ns_style_alloc();
        g_incr_recomputed++;
        nd_node_dirty = TRUE;
        static GArray *sc_matches, *sc_var, *sc_pending;
        static GPtrArray *sc_owned;
        static GArray *sc_pe_m[9], *sc_pe_v[9], *sc_pe_p[9];
        if (!sc_matches) {
            sc_matches  = g_array_new(FALSE, FALSE, sizeof(match_entry));
            sc_var      = g_array_new(FALSE, FALSE, sizeof(var_match));
            sc_pending  = g_array_new(FALSE, FALSE, sizeof(pending_match));
            sc_owned    = g_ptr_array_new_with_free_func(
                              (GDestroyNotify)ns_css_value_free);
        }
        GArray *matches = sc_matches;
        GArray *var_matches = sc_var;
        GArray *pending_matches = sc_pending;
        GPtrArray *owned_values = sc_owned;
        g_array_set_size(matches, 0);
        g_array_set_size(var_matches, 0);
        g_array_set_size(pending_matches, 0);
        g_ptr_array_set_size(owned_values, 0);
        guint pe_mask = ua ? ua->pseudo_mask : 0;
        for (gsize i = 0; i < n_author; i++)
            if (author[i]) pe_mask |= author[i]->pseudo_mask;
        ns_pe_gather pe_g[NS_CSS_PE_FILE_SELECTOR_BUTTON];
        int n_pe = 0;
        gather_dest dests[NS_CSS_PE_FILE_SELECTOR_BUTTON + 1];
        dests[0].pe = NS_CSS_PE_NONE;
        dests[0].out = matches;
        dests[0].var_out = var_matches;
        dests[0].pending_out = pending_matches;
        for (int pi = 0; pe_mask && pi < 9; pi++) {
            ns_css_pseudo_element pe = (pi == 0) ? NS_CSS_PE_BEFORE :
                                       (pi == 1) ? NS_CSS_PE_AFTER :
                                       (pi == 2) ? NS_CSS_PE_FIRST_LETTER :
                                       (pi == 3) ? NS_CSS_PE_FIRST_LINE :
                                       (pi == 4) ? NS_CSS_PE_SELECTION :
                                       (pi == 5) ? NS_CSS_PE_MARKER :
                                       (pi == 6) ? NS_CSS_PE_BACKDROP :
                                       (pi == 7) ? NS_CSS_PE_PLACEHOLDER :
                                                   NS_CSS_PE_FILE_SELECTOR_BUTTON;
            if (!(pe_mask & (1u << pe))) continue;
            ns_pe_gather *pg = &pe_g[n_pe];
            pg->pe = pe;
            if (!sc_pe_m[n_pe]) {
                sc_pe_m[n_pe] = g_array_new(FALSE, FALSE, sizeof(match_entry));
                sc_pe_v[n_pe] = g_array_new(FALSE, FALSE, sizeof(var_match));
                sc_pe_p[n_pe] = g_array_new(FALSE, FALSE, sizeof(pending_match));
            }
            pg->m = sc_pe_m[n_pe];
            pg->v = sc_pe_v[n_pe];
            pg->p = sc_pe_p[n_pe];
            g_array_set_size(pg->m, 0);
            g_array_set_size(pg->v, 0);
            g_array_set_size(pg->p, 0);
            dests[n_pe + 1].pe = pe;
            dests[n_pe + 1].out = pg->m;
            dests[n_pe + 1].var_out = pg->v;
            dests[n_pe + 1].pending_out = pg->p;
            n_pe++;
        }
        css_el_keys el_keys;
        css_el_keys_build(node, &el_keys);
        g_ancestor_filter_subject = node;
        gather_matches_multi(ua, NS_CSS_ORIGIN_UA, 0, node, &el_keys, dests,
                             (guint)n_pe + 1,
                             layer_ranks);
        for (gsize i = 0; i < n_author; i++)
            if (cascade_sheet_applies(i) &&
                cascade_sheet_in_host_scope(author[i]))
                gather_matches_multi(author[i], NS_CSS_ORIGIN_AUTHOR,
                                     (int)(i + 1), node, &el_keys, dests,
                                     (guint)n_pe + 1, layer_ranks);

        char *pres_css = presentational_hints_css(node);
        const ns_css_stylesheet *pres_sheet = NULL;
        if (pres_css) {
            pres_sheet = ns_css_cached_decl_sheet(pres_css);
            g_free(pres_css);
        }
        if (pres_sheet) {
            for (guint ri = 0; ri < pres_sheet->rules->len; ri++) {
                ns_css_rule *r = g_ptr_array_index(pres_sheet->rules, ri);
                for (guint di = 0; di < r->decls->len; di++) {
                    ns_css_decl *d = &g_array_index(r->decls, ns_css_decl, di);
                    match_entry e = {
                        .origin = NS_CSS_ORIGIN_PRESENTATIONAL,
                        .spec_a = 0, .spec_b = 0, .spec_c = 0,
                        .layer_order = NS_CSS_LAYER_NONE,
                        .source_order = INT_MIN,
                        .decl_order = d->order,
                        .important = d->important,
                        .rule = r,
                        .value = d->value,
                        .prop  = d->prop,
                    };
                    g_array_append_val(matches, e);
                }
                if (r->vars) {
                    GHashTableIter it; gpointer k, v; int di_v = 0;
                    g_hash_table_iter_init(&it, r->vars);
                    while (g_hash_table_iter_next(&it, &k, &v)) {
                        var_match vm = {
                            .origin = NS_CSS_ORIGIN_PRESENTATIONAL,
                            .spec_a = 0, .spec_b = 0, .spec_c = 0,
                            .sheet_index = 0,
                            .layer_order = NS_CSS_LAYER_NONE,
                            .source_order = INT_MIN,
                            .decl_order = di_v++,
                            .important = r->var_important &&
                                g_hash_table_contains(r->var_important, k),
                            .rule = r,
                            .name = (const char *)k,
                            .text = (const char *)v,
                        };
                        g_array_append_val(var_matches, vm);
                    }
                }
                if (r->pending) {
                    for (guint pi = 0; pi < r->pending->len; pi++) {
                        ns_css_pending_decl *pd =
                            &g_array_index(r->pending, ns_css_pending_decl, pi);
                        pending_match pm = {
                            .origin = NS_CSS_ORIGIN_PRESENTATIONAL,
                            .spec_a = 0, .spec_b = 0, .spec_c = 0,
                            .sheet_index = 0,
                            .layer_order = NS_CSS_LAYER_NONE,
                            .source_order = INT_MIN,
                            .decl_order_base = pd->order,
                            .rule = r,
                            .pd = pd,
                        };
                        g_array_append_val(pending_matches, pm);
                    }
                }
            }
        }

        const char *inline_css = ns_element_get_attr(node, "style");
        const ns_css_stylesheet *inline_sheet = NULL;
        if (inline_css && *inline_css)
            inline_sheet = ns_css_cached_decl_sheet(inline_css);
        if (inline_sheet) {
            for (guint ri = 0; ri < inline_sheet->rules->len; ri++) {
                ns_css_rule *r = g_ptr_array_index(inline_sheet->rules, ri);
                for (guint di = 0; di < r->decls->len; di++) {
                    ns_css_decl *d = &g_array_index(r->decls, ns_css_decl, di);
                    match_entry e = {
                        .origin = NS_CSS_ORIGIN_AUTHOR,
                        .spec_a = 1000, .spec_b = 0, .spec_c = 0,
                        .layer_order = NS_CSS_LAYER_NONE,
                        .source_order = INT_MAX,
                        .decl_order = d->order,
                        .important = d->important,
                        .inline_style = TRUE,
                        .rule = r,
                        .value = d->value,
                        .prop  = d->prop,
                    };
                    g_array_append_val(matches, e);
                }
                if (r->vars) {
                    GHashTableIter it; gpointer k, v; int di_v = 0;
                    g_hash_table_iter_init(&it, r->vars);
                    while (g_hash_table_iter_next(&it, &k, &v)) {
                        var_match vm = {
                            .origin = NS_CSS_ORIGIN_AUTHOR,
                            .spec_a = 1000, .spec_b = 0, .spec_c = 0,
                            .sheet_index = 0,
                            .layer_order = NS_CSS_LAYER_NONE,
                            .source_order = INT_MAX,
                            .decl_order = di_v++,
                            .important = r->var_important &&
                                g_hash_table_contains(r->var_important, k),
                            .inline_style = TRUE,
                            .rule = r,
                            .name = (const char *)k,
                            .text = (const char *)v,
                        };
                        g_array_append_val(var_matches, vm);
                    }
                }
                if (r->pending) {
                    for (guint pi = 0; pi < r->pending->len; pi++) {
                        ns_css_pending_decl *pd =
                            &g_array_index(r->pending, ns_css_pending_decl, pi);
                        pending_match pm = {
                            .origin = NS_CSS_ORIGIN_AUTHOR,
                            .spec_a = 1000, .spec_b = 0, .spec_c = 0,
                            .sheet_index = 0,
                            .layer_order = NS_CSS_LAYER_NONE,
                            .source_order = INT_MAX,
                            .decl_order_base = pd->order,
                            .inline_style = TRUE,
                            .rule = r,
                            .pd = pd,
                        };
                        g_array_append_val(pending_matches, pm);
                    }
                }
            }
        }

        share_key_t probe;
        gboolean have_key = FALSE;
        const ns_style *shared = NULL;
        if (g_style_share) {
            style_share_key(g_share_scratch, parent_style, *root_px, matches,
                            var_matches, pending_matches, pe_g, n_pe);
            probe.data = g_share_scratch->data;
            probe.len  = g_share_scratch->len;
            probe.hash = share_key_hash_bytes(probe.data, probe.len);
            have_key = TRUE;
            shared = g_hash_table_lookup(g_style_share, &probe);
            gboolean uses_attr = pending_uses_attr(pending_matches);
            for (int i = 0; i < n_pe && !uses_attr; i++)
                uses_attr = pending_uses_attr(pe_g[i].p);
            if (uses_attr) {
                have_key = FALSE;
                shared = NULL;
                ns_css_incremental_exclude(node, TRUE);
            }
        }
        gboolean memo_ok = nd_old && have_key &&
                           !ns_node_is_element_named(node, "input");
        gboolean memo_hit = memo_ok &&
                            style_memo_hit(node, nd_old, &probe, parent_style,
                                          layout_parent);
        if (memo_ok && !memo_hit) {
            memo_store = TRUE;
            memo_key = probe;
        }
        if (memo_hit) {
            ns_style_free(s);
            s = nd_old;
            s->ref++;
            g_array_set_size(matches, 0);
            g_array_set_size(var_matches, 0);
            g_array_set_size(pending_matches, 0);
            g_ptr_array_set_size(owned_values, 0);
        } else if (shared) {
            ns_style_free(s);
            s = ns_style_clone_shared(shared);
            if (display_forced_none(node, s))
                s->share_id = ++g_style_share_next_id;
            g_array_set_size(matches, 0);
            g_array_set_size(var_matches, 0);
            g_array_set_size(pending_matches, 0);
            g_ptr_array_set_size(owned_values, 0);
        } else {
            s->share_id = ++g_style_share_next_id;
            s->vars = build_vars_for_element(parent_style, var_matches);
            resolve_pending_into_matches(pending_matches, s->vars,
                                         matches, owned_values, node,
                                         *root_px);

            cascade_for(matches, s, parent_style, layout_parent,
                    node->parent &&
                        node->parent->kind == NS_NODE_DOCUMENT, *root_px);
            compute_registered_vars(s, parent_style, *root_px);
            strip_native_widget_decorations(node, s);
            if (display_forced_none(node, s)) have_key = FALSE;
            g_array_set_size(matches, 0);
            g_array_set_size(var_matches, 0);
            g_array_set_size(pending_matches, 0);
            g_ptr_array_set_size(owned_values, 0);

            for (int gi = 0; gi < n_pe; gi++) {
                ns_css_pseudo_element pe = pe_g[gi].pe;
                GArray *pm = pe_g[gi].m;
                GArray *pe_vars = pe_g[gi].v;
                GArray *pe_pending = pe_g[gi].p;
                if (pm->len == 0 && pe_pending->len == 0) continue;
                GPtrArray *pe_owned =
                    g_ptr_array_new_with_free_func(
                        (GDestroyNotify)ns_css_value_free);
                ns_style *ps = ns_style_alloc();
                ps->vars = build_vars_for_element(s, pe_vars);
                resolve_pending_into_matches(pe_pending, ps->vars, pm, pe_owned, node,
                                             *root_px);
                cascade_for(pm, ps, s,
                            pe == NS_CSS_PE_BEFORE || pe == NS_CSS_PE_AFTER
                                ? s : NULL,
                            FALSE, *root_px);
                compute_registered_vars(ps, s, *root_px);
                gboolean keep = TRUE;
                if (pe == NS_CSS_PE_BEFORE || pe == NS_CSS_PE_AFTER)
                    keep = ps->values[NS_CSS_CONTENT] != NULL;
                if (keep) {
                    if (pe == NS_CSS_PE_BEFORE)            s->before       = ps;
                    else if (pe == NS_CSS_PE_AFTER)        s->after        = ps;
                    else if (pe == NS_CSS_PE_FIRST_LETTER) s->first_letter = ps;
                    else if (pe == NS_CSS_PE_FIRST_LINE)   s->first_line   = ps;
                    else if (pe == NS_CSS_PE_SELECTION)    s->selection    = ps;
                    else if (pe == NS_CSS_PE_MARKER)       s->marker       = ps;
                    else if (pe == NS_CSS_PE_BACKDROP)     s->backdrop     = ps;
                    else if (pe == NS_CSS_PE_PLACEHOLDER)  s->placeholder  = ps;
                    else s->file_selector_button = ps;
                } else {
                    ns_style_free(ps);
                }
                g_ptr_array_free(pe_owned, TRUE);
            }
            share_put = have_key && !nd_self_prev;
        }
        if (nd_old && s != nd_old && incr_style_same(s, nd_old) &&
            incr_pseudo_styles_same(s, nd_old)) {
            ns_style_free(s);
            s = nd_old;
            s->ref++;
        }
        if (share_put) {
            share_key_t *k = g_new(share_key_t, 1);
            k->len  = probe.len;
            k->hash = probe.hash;
            k->data = g_memdup2(probe.data, probe.len);
            g_hash_table_insert(g_style_share, k, s);
        }
        if (memo_store)
            style_memo_store(node, s, &memo_key, parent_style,
                            layout_parent);
        }
        gboolean nd_self_same = nd_self_prev && s == nd_self_prev;
        if (g_delta_out) {
            if (g_hash_table_lookup(g_incr_prev_styles, node) == s) {
                ns_style_free(s);
            } else {
                ns_css_style_change *c = g_new(ns_css_style_change, 1);
                c->node = node;
                c->style = s;
                g_ptr_array_add(g_delta_out, c);
            }
        } else {
            g_hash_table_insert(out, node, s);
        }
        child_parent_style = s;
        child_layout_parent = ns_display_is_contents(ns_css_display_of(s))
            ? layout_parent : s;
        if (*root_px <= 0 &&
            s->values[NS_CSS_FONT_SIZE] &&
            s->values[NS_CSS_FONT_SIZE]->kind == NS_CSS_V_LENGTH &&
            s->values[NS_CSS_FONT_SIZE]->u.length.unit == NS_CSS_UNIT_PX)
            *root_px = s->values[NS_CSS_FONT_SIZE]->u.length.v;
        if (!parent_style && g_root_line_px <= 0) {
            double root_font_px = *root_px > 0 ? *root_px : 16.0;
            g_root_line_px = style_line_height_px(s, root_font_px,
                                                   root_font_px,
                                                   normal_line_height_px(root_font_px),
                                                   normal_line_height_px(root_font_px));
        }
        nd_recurse_dirty = nd_node_dirty && !nd_self_same;
    }
    gboolean inv_pushed = FALSE;
    if (g_incr_desc_inv && node->kind == NS_NODE_ELEMENT) {
        GHashTable *inv = g_hash_table_lookup(g_incr_desc_inv, node);
        if (inv) {
            if (!g_desc_inv_stack) {
                g_desc_inv_stack = g_ptr_array_new();
                g_desc_inv_depths = g_array_new(FALSE, FALSE, sizeof(int));
            }
            g_ptr_array_add(g_desc_inv_stack, inv);
            g_array_append_val(g_desc_inv_depths, depth);
            inv_pushed = TRUE;
        }
    }
    gboolean pushed = FALSE;
    if (g_cq_map && g_cq_stack) {
        ns_cq_container *info = g_hash_table_lookup(g_cq_map, node);
        if (info) {
            g_array_append_val(g_cq_stack, *info);
            pushed = TRUE;
        }
    }
    const ns_node *outer_cascade_doc = g_cascade_doc;
    if (node->kind == NS_NODE_DOCUMENT && !(node->flags & NS_NODE_FRAGMENT) &&
        g_author_sheet_docs)
        g_cascade_doc = node;
    gboolean filter_element = g_ancestor_filter_active &&
                              node->kind == NS_NODE_ELEMENT && node->first_child;
    guint8 *outer_filter = NULL;
    if (g_ancestor_filter_active && node->kind == NS_NODE_DOCUMENT &&
        node->parent) {
        outer_filter = g_memdup2(g_ancestor_filter, sizeof g_ancestor_filter);
        memset(g_ancestor_filter, 0, sizeof g_ancestor_filter);
    }
    if (filter_element) css_ancestor_filter_update(node, 1);
    if (nd_bulk && g_delta_out) {
    } else if (nd_bulk)
        incr_bulk_reuse(node, ua, author, n_author, child_layout_parent,
                        root_px, layer_ranks, out);
    else
        for (ns_node *c = node->first_child; c; c = c->next_sibling)
            cascade_walk(c, ua, author, n_author, child_parent_style,
                         child_layout_parent, root_px,
                         layer_ranks, out, nd_recurse_dirty);
    if (filter_element) css_ancestor_filter_update(node, -1);
    if (inv_pushed) {
        g_ptr_array_set_size(g_desc_inv_stack, g_desc_inv_stack->len - 1);
        g_array_set_size(g_desc_inv_depths, g_desc_inv_depths->len - 1);
    }
    if (outer_filter) {
        memcpy(g_ancestor_filter, outer_filter, sizeof g_ancestor_filter);
        g_free(outer_filter);
    }
    if (pushed) g_array_set_size(g_cq_stack, g_cq_stack->len - 1);
    g_cascade_doc = outer_cascade_doc;
    if (frame_viewport) {
        g_viewport_w = frame_vw;
        g_viewport_h = frame_vh;
    }
    if (host_scope)
        g_ptr_array_set_size(g_host_scope_stack, g_host_scope_stack->len - 1);
    if (adopt_scope)
        g_ptr_array_set_size(g_adopt_scope_stack,
                             g_adopt_scope_stack->len - 1);
    depth--;
}

/* Appends all descendant text in tree order to out. */
static void
append_text_children(const ns_node *n, GString *out, int depth)
{
    if (depth >= 512) return;
    for (const ns_node *c = n->first_child; c; c = c->next_sibling) {
        if (c->kind == NS_NODE_TEXT && c->text)
            g_string_append(out, c->text);
        else if (c->kind == NS_NODE_ELEMENT)
            append_text_children(c, out, depth + 1);
    }
}

static int g_host_scope_counter;

/* Returns, assigning if needed, the host scope id for a style element in a shadow root. */
static char *
style_host_scope_id(ns_node *style_el)
{
    ns_node *root = NULL;
    for (ns_node *a = style_el; a; a = a->parent) {
        if (a->kind == NS_NODE_ELEMENT &&
            ns_element_get_attr(a, NS_SHADOW_ATTR) != NULL) {
            root = a;
            break;
        }
    }
    if (!root || !root->parent) return NULL;
    ns_node *host = root->parent;
    const char *existing = ns_element_get_attr(host, NS_HOST_SCOPE_ATTR);
    if (existing) return g_strdup(existing);
    char buf[32];
    g_snprintf(buf, sizeof buf, "%d", ++g_host_scope_counter);
    ns_element_set_attr(host, NS_HOST_SCOPE_ATTR, buf);
    return g_strdup(buf);
}

/* Returns, assigning if needed, a scope id on the root element of a nested frame document. */
static char *
style_iframe_scope_id(ns_node *style_el)
{
    ns_node *root = NULL;
    for (ns_node *a = style_el; a; a = a->parent) {
        if (a->kind == NS_NODE_ELEMENT && a->parent &&
            a->parent->kind == NS_NODE_DOCUMENT && a->parent->parent) {
            root = a;
            break;
        }
    }
    if (!root) return NULL;
    const char *existing = ns_element_get_attr(root, NS_HOST_SCOPE_ATTR);
    if (existing) return g_strdup(existing);
    char buf[32];
    g_snprintf(buf, sizeof buf, "%d", ++g_host_scope_counter);
    ns_element_set_attr(root, NS_HOST_SCOPE_ATTR, buf);
    return g_strdup(buf);
}

/* Rewrites :host, :host(), :host-context() and ::slotted() into host-scope attr selectors. */
static char *
rewrite_host_selectors(const char *css, const char *host_id)
{
    GString *out = g_string_new(NULL);
    char marker[96];
    g_snprintf(marker, sizeof marker, "[" NS_HOST_SCOPE_ATTR "=\"%s\"]", host_id);
    for (const char *p = css; *p; ) {
        if (p[0] == ':' && g_ascii_strncasecmp(p, "::slotted(", 10) == 0) {
            const char *inner = p + 10;
            const char *q = inner;
            int depth = 1;
            while (*q && depth) {
                if (*q == '(') depth++;
                else if (*q == ')') { depth--; if (!depth) break; }
                q++;
            }
            g_string_append(out, marker);
            g_string_append(out, " > ");
            g_string_append_len(out, inner, (gssize)(q - inner));
            p = (*q == ')') ? q + 1 : q;
            continue;
        }
        if (p[0] == ':' && g_ascii_strncasecmp(p, ":host", 5) == 0) {
            const char *after = p + 5;
            if (g_ascii_strncasecmp(after, "-context(", 9) == 0) {
                const char *q = after + 9;
                int depth = 1;
                while (*q && depth) {
                    if (*q == '(') depth++;
                    else if (*q == ')') depth--;
                    q++;
                }
                g_string_append(out, marker);
                p = q;
                continue;
            }
            if (*after == '(') {
                const char *inner = after + 1;
                const char *q = inner;
                int depth = 1;
                while (*q && depth) {
                    if (*q == '(') depth++;
                    else if (*q == ')') { depth--; if (!depth) break; }
                    q++;
                }
                g_string_append(out, marker);
                g_string_append_len(out, inner, (gssize)(q - inner));
                p = (*q == ')') ? q + 1 : q;
                continue;
            }
            if (!is_ident(*after) && *after != '-') {
                g_string_append(out, marker);
                p = after;
                continue;
            }
        }
        g_string_append_c(out, *p);
        p++;
    }
    return g_string_free(out, FALSE);
}

/* Returns the length of a selector's first compound, up to a top-level combinator or comma. */
static gsize
selector_first_compound_len(const char *s)
{
    gsize i = 0;
    int depth = 0;
    while (s[i]) {
        char c = s[i];
        if (c == '(' || c == '[') depth++;
        else if (c == ')' || c == ']') { if (depth) depth--; }
        else if (!depth && (ns_is_ascii_ws(c) || c == '>' || c == '+' || c == '~' ||
                            c == ','))
            break;
        i++;
    }
    return i;
}

/* True if the first compound starts with html or :root. */
static gboolean
selector_first_compound_targets_root(const char *s, gsize clen)
{
    if (clen >= 4 && g_ascii_strncasecmp(s, "html", 4) == 0 &&
        (clen == 4 || !is_ident(s[4])))
        return TRUE;
    if (clen >= 5 && g_ascii_strncasecmp(s, ":root", 5) == 0 &&
        (clen == 5 || !is_ident(s[5])))
        return TRUE;
    return FALSE;
}

/* Returns the compound's length before any pseudo-element (:: or legacy single colon). */
static gsize
selector_compound_simple_len(const char *s, gsize clen)
{
    static const char *const legacy[] = {
        "before", "after", "first-line", "first-letter", NULL
    };
    int depth = 0;
    for (gsize i = 0; i < clen; i++) {
        char c = s[i];
        if (c == '(' || c == '[') depth++;
        else if (c == ')' || c == ']') { if (depth) depth--; }
        else if (!depth && c == ':') {
            if (i + 1 < clen && s[i + 1] == ':') return i;
            for (int k = 0; legacy[k]; k++) {
                gsize n = strlen(legacy[k]);
                if (i + 1 + n <= clen &&
                    g_ascii_strncasecmp(s + i + 1, legacy[k], n) == 0 &&
                    (i + 1 + n == clen || !is_ident(s[i + 1 + n])))
                    return i;
            }
        }
    }
    return clen;
}

/* True if the first compound could match a frame's root (*, class, id, attr or pseudo). */
static gboolean
selector_first_compound_may_be_root(const char *s, gsize clen)
{
    if (!clen) return FALSE;
    if (s[0] == '*') return TRUE;
    return s[0] == '.' || s[0] == '#' || s[0] == '[' || s[0] == ':';
}

/* Scopes one selector to a shadow host or frame using the scope marker attribute. */
static void
scope_one_selector(GString *out, const char *sel, gsize len,
                   const char *marker, const char *host_id,
                   gboolean frame_scope)
{
    while (len && ns_is_ascii_ws(*sel)) { sel++; len--; }
    while (len && ns_is_ascii_ws(sel[len - 1])) len--;
    if (!len) return;
    char *s = g_strndup(sel, len);
    gsize clen = selector_first_compound_len(s);
    gsize simple = selector_compound_simple_len(s, clen);
    if (strstr(s, ":host") || strstr(s, "::slotted")) {
        char *r = rewrite_host_selectors(s, host_id);
        g_string_append(out, r);
        g_free(r);
    } else if (selector_first_compound_targets_root(s, clen)) {
        g_string_append_len(out, s, (gssize)simple);
        g_string_append(out, marker);
        g_string_append(out, s + simple);
    } else {
        g_string_append(out, marker);
        g_string_append_c(out, ' ');
        g_string_append(out, s);
        if (frame_scope && selector_first_compound_may_be_root(s, clen)) {
            g_string_append(out, ", ");
            g_string_append_len(out, s, (gssize)simple);
            g_string_append(out, marker);
            g_string_append(out, s + simple);
        }
    }
    g_free(s);
}

/* Rewrites every rule's selectors with the scope marker, recursing into group at-rules. */
static void
scope_rule_list(GString *out, const char *p, const char *end,
                const char *marker, const char *host_id, int depth,
                gboolean frame_scope)
{
    if (depth >= NS_CSS_MAX_AT_NESTING) {
        g_string_append_len(out, p, (gssize)(end - p));
        return;
    }
    while (p < end) {
        while (p < end && ns_is_ascii_ws(*p)) p++;
        if (p >= end) break;
        if (p + 1 < end && p[0] == '/' && p[1] == '*') {
            p += 2;
            while (p + 1 < end && !(p[0] == '*' && p[1] == '/')) p++;
            if (p + 1 < end) p += 2;
            continue;
        }
        if (*p == '}') { p++; continue; }
        if (*p == '@') {
            const char *prelude = p;
            char term = 0;
            const char *seg = css_scan_segment(p, end, &term);
            if (term == '{') {
                gboolean group =
                    g_ascii_strncasecmp(prelude, "@media", 6) == 0 ||
                    g_ascii_strncasecmp(prelude, "@supports", 9) == 0 ||
                    g_ascii_strncasecmp(prelude, "@container", 10) == 0 ||
                    g_ascii_strncasecmp(prelude, "@layer", 6) == 0 ||
                    g_ascii_strncasecmp(prelude, "@scope", 6) == 0;
                const char *be = css_skip_to_block_end(seg, end);
                if (group) {
                    g_string_append_len(out, prelude, (gssize)(seg - prelude));
                    g_string_append_c(out, '{');
                    const char *body_s = seg + 1;
                    scope_rule_list(out, body_s, css_block_body_end(body_s, be),
                                    marker, host_id, depth + 1, frame_scope);
                    g_string_append_c(out, '}');
                } else {
                    g_string_append_len(out, prelude, (gssize)(be - prelude));
                }
                p = be;
            } else {
                g_string_append_len(out, prelude, (gssize)(seg - prelude));
                if (term == ';' && seg < end) { g_string_append_c(out, ';'); p = seg + 1; }
                else p = seg;
            }
            continue;
        }
        char term = 0;
        const char *seg = css_scan_segment(p, end, &term);
        if (term != '{') { p = (seg < end) ? seg + 1 : end; continue; }
        const char *be = css_skip_to_block_end(seg, end);
        const char *selend = seg;
        const char *q = p, *segstart = p;
        char quote = 0;
        int paren = 0, bracket = 0;
        gboolean first = TRUE;
        for (; q <= selend; q++) {
            if (q == selend || (!quote && !paren && !bracket && *q == ',')) {
                if (!first) g_string_append(out, ", ");
                first = FALSE;
                scope_one_selector(out, segstart, (gsize)(q - segstart),
                                   marker, host_id, frame_scope);
                segstart = q + 1;
                if (q == selend) break;
            } else if (quote) {
                if (*q == '\\' && q + 1 < selend) q++;
                else if (*q == quote) quote = 0;
            } else if (*q == '\\' && q + 1 < selend) q++;
            else if (*q == '"' || *q == '\'') quote = *q;
            else if (*q == '(') paren++;
            else if (*q == ')') { if (paren) paren--; }
            else if (*q == '[') bracket++;
            else if (*q == ']') { if (bracket) bracket--; }
        }
        g_string_append_c(out, '{');
        const char *body_s = seg + 1;
        const char *body_e = css_block_body_end(body_s, be);
        g_string_append_len(out, body_s, (gssize)(body_e - body_s));
        g_string_append_c(out, '}');
        p = be;
    }
}

/* Returns flattened CSS scoped to host_id through attribute markers; caller frees. */
static char *
scope_shadow_css(const char *flat_css, const char *host_id, gboolean frame_scope)
{
    GString *out = g_string_new(NULL);
    char marker[96];
    g_snprintf(marker, sizeof marker, "[" NS_HOST_SCOPE_ATTR "=\"%s\"]", host_id);
    scope_rule_list(out, flat_css, flat_css + strlen(flat_css), marker, host_id, 0,
                    frame_scope);
    return g_string_free(out, FALSE);
}

/* Returns a style element's CSS if its media matches, scoped for shadow roots or frames. */
static char *
style_element_final_css(ns_node *style)
{
    if (!ns_node_is_element_named(style, "style")) return NULL;
    const char *media = ns_element_get_attr(style, "media");
    if (media && *media && !ns_css_media_query_matches(media)) return NULL;
    GString *buf = g_string_new(NULL);
    append_text_children(style, buf, 0);
    if (buf->len == 0) {
        g_string_free(buf, TRUE);
        return NULL;
    }
    gboolean frame_scope = FALSE;
    char *host_id = style_host_scope_id(style);
    if (!host_id) {
        host_id = style_iframe_scope_id(style);
        frame_scope = host_id != NULL;
    }
    if (host_id) {
        char *flat = css_flatten_nesting(buf->str, (gssize)buf->len);
        char *rewritten = scope_shadow_css(flat, host_id, frame_scope);
        g_free(flat);
        g_free(host_id);
        g_string_free(buf, TRUE);
        return rewritten;
    }
    return g_string_free(buf, FALSE);
}

char *
ns_css_style_element_text(ns_node *style)
{
    return style_element_final_css(style);
}

typedef struct {
    char *css;
    ns_css_stylesheet *sheet;
    GPtrArray *media;
} ns_style_el_cached;

typedef struct {
    ns_css_stylesheet *sheet;
    GPtrArray *media;
    guint64 stamp;
} ns_merged_style_cached;

typedef struct {
    const char *base;
    const char *css;
    gsize       len;
    guint       hash;
} ns_merged_style_key;

typedef struct {
    GBytes *bytes;
    ns_css_stylesheet *sheet;
    GPtrArray *media;
} ns_import_sheet_cached;

typedef struct {
    ns_css_stylesheet *sheet;
    GPtrArray *media;
} ns_link_sheet_cached;

/* Parses CSS while recording the media queries it evaluated, optionally forcing a layer. */
static ns_css_stylesheet *
css_parse_recording_media(const char *css, gssize len, const char *layer_name,
                          GPtrArray **out_media)
{
    GPtrArray *media = ns_css_media_record_new();
    GPtrArray *outer = ns_css_media_record_swap(media);
    ns_css_stylesheet *sh = ns_css_stylesheet_parse(css, len);
    ns_css_media_record_swap(outer);
    if (sh && layer_name)
        ns_css_stylesheet_force_layer(sh, layer_name);
    if (!sh) {
        g_ptr_array_unref(media);
        media = NULL;
    }
    *out_media = media;
    return sh;
}

static int g_css_relayout_depth;
static GPtrArray *g_evicted_sheets;

/* Frees a sheet the caches dropped. A style pass may still hold it in its
 * sheet list (a frame at another viewport re-parses the same URL), so during
 * a pass it is kept until the outermost pass ends. */
static void
ns_cached_stylesheet_free(gpointer data)
{
    ns_css_stylesheet *sh = data;
    if (!sh) return;
    if (g_css_relayout_depth > 0) {
        if (!g_evicted_sheets) g_evicted_sheets = g_ptr_array_new();
        g_ptr_array_add(g_evicted_sheets, sh);
        return;
    }
    sh->cached = FALSE;
    ns_css_stylesheet_free(sh);
}

static GHashTable *g_style_el_cache;
static GHashTable *g_merged_style_cache;
static GHashTable *g_link_sheet_cache;
static GHashTable *g_import_sheet_cache;
static guint64 g_merged_style_cache_clock;

static void
ns_style_el_cached_free(gpointer data)
{
    ns_style_el_cached *e = data;
    if (!e) return;
    g_free(e->css);
    ns_cached_stylesheet_free(e->sheet);
    if (e->media) g_ptr_array_unref(e->media);
    g_free(e);
}

/* Builds a merged-style cache key with an FNV hash over the CSS and base URL. */
static ns_merged_style_key
ns_merged_style_key_make(const char *css, gsize len, const char *base)
{
    ns_merged_style_key k = {
        .base = base,
        .css = css,
        .len = len,
    };
    guint h = 2166136261u;
    for (gsize i = 0; i < len; i++) {
        h ^= (guchar)css[i];
        h *= 16777619u;
    }
    h ^= base ? g_str_hash(base) * 31u : 0;
    k.hash = h;
    return k;
}

static guint
ns_merged_style_key_hash(gconstpointer p)
{
    return ((const ns_merged_style_key *)p)->hash;
}

static gboolean
ns_merged_style_key_equal(gconstpointer pa, gconstpointer pb)
{
    const ns_merged_style_key *a = pa, *b = pb;
    return a->hash == b->hash && a->len == b->len &&
           g_strcmp0(a->base, b->base) == 0 &&
           memcmp(a->css, b->css, a->len) == 0;
}

static void
ns_merged_style_key_free(gpointer data)
{
    ns_merged_style_key *k = data;
    g_free((char *)k->base);
    g_free((char *)k->css);
    g_free(k);
}

static void
ns_merged_style_cached_free(gpointer data)
{
    ns_merged_style_cached *e = data;
    if (!e) return;
    ns_cached_stylesheet_free(e->sheet);
    if (e->media) g_ptr_array_unref(e->media);
    g_free(e);
}


static void
ns_import_sheet_cached_free(gpointer data)
{
    ns_import_sheet_cached *e = data;
    if (!e) return;
    g_bytes_unref(e->bytes);
    ns_cached_stylesheet_free(e->sheet);
    if (e->media) g_ptr_array_unref(e->media);
    g_free(e);
}

static void
ns_link_sheet_cached_free(gpointer data)
{
    ns_link_sheet_cached *e = data;
    if (!e) return;
    ns_cached_stylesheet_free(e->sheet);
    if (e->media) g_ptr_array_unref(e->media);
    g_free(e);
}

/* Evicts least recently used merged sheets down to 48 once the cache exceeds 64. */
static void
ns_merged_style_cache_trim(void)
{
    if (!g_merged_style_cache ||
        g_hash_table_size(g_merged_style_cache) <= 64)
        return;
    while (g_hash_table_size(g_merged_style_cache) > 48) {
        GHashTableIter it;
        gpointer key, value, victim = NULL;
        guint64 oldest = G_MAXUINT64;
        g_hash_table_iter_init(&it, g_merged_style_cache);
        while (g_hash_table_iter_next(&it, &key, &value)) {
            ns_merged_style_cached *e = value;
            if (e->stamp < oldest) {
                oldest = e->stamp;
                victim = key;
            }
        }
        if (!victim) break;
        g_hash_table_remove(g_merged_style_cache, victim);
    }
}

void
ns_css_relayout_enter(void)
{
    g_css_relayout_depth++;
}

void
ns_css_relayout_leave(void)
{
    if (g_css_relayout_depth > 0) g_css_relayout_depth--;
    if (g_css_relayout_depth > 0 || !g_evicted_sheets) return;
    for (guint i = 0; i < g_evicted_sheets->len; i++)
        ns_cached_stylesheet_free(g_ptr_array_index(g_evicted_sheets, i));
    g_ptr_array_set_size(g_evicted_sheets, 0);
}

/* Empties all parsed stylesheet caches, e.g. after media preferences change. */
void
ns_css_stylesheet_cache_drop(void)
{
    if (g_style_el_cache) g_hash_table_remove_all(g_style_el_cache);
    if (g_merged_style_cache) g_hash_table_remove_all(g_merged_style_cache);
    if (g_link_sheet_cache) g_hash_table_remove_all(g_link_sheet_cache);
    if (g_import_sheet_cache) g_hash_table_remove_all(g_import_sheet_cache);
}

/* Bounds the stylesheet caches at the start of an outermost style pass. */
void
ns_css_style_element_cache_begin(void)
{
    if (g_css_relayout_depth > 1) return;
    if (g_style_el_cache && g_hash_table_size(g_style_el_cache) > 2048)
        g_hash_table_remove_all(g_style_el_cache);
    ns_merged_style_cache_trim();
    if (g_link_sheet_cache && g_hash_table_size(g_link_sheet_cache) > 256)
        g_hash_table_remove_all(g_link_sheet_cache);
    if (g_import_sheet_cache && g_hash_table_size(g_import_sheet_cache) > 256)
        g_hash_table_remove_all(g_import_sheet_cache);
}

/* Returns a cached parse of merged style text per base URL; reparses if media changed. */
ns_css_stylesheet *
ns_css_merged_styles_cached(const char *css, gssize len, const char *base_url)
{
    if (!css || len == 0) return NULL;
    if (len < 0) len = (gssize)strlen(css);
    if (!g_merged_style_cache)
        g_merged_style_cache =
            g_hash_table_new_full(ns_merged_style_key_hash,
                                  ns_merged_style_key_equal,
                                  ns_merged_style_key_free,
                                  ns_merged_style_cached_free);
    ns_merged_style_key probe =
        ns_merged_style_key_make(css, (gsize)len, base_url);
    ns_merged_style_cached *hit =
        g_hash_table_lookup(g_merged_style_cache, &probe);
    if (hit && ns_css_media_record_holds(hit->media)) {
        hit->stamp = ++g_merged_style_cache_clock;
        return hit->sheet;
    }
    GPtrArray *media = NULL;
    ns_css_stylesheet *sh = css_parse_recording_media(css, len, NULL, &media);
    if (!sh) return NULL;
    sh->cached = TRUE;
    ns_merged_style_cached *entry = g_new0(ns_merged_style_cached, 1);
    entry->sheet = sh;
    entry->media = media;
    entry->stamp = ++g_merged_style_cache_clock;
    ns_merged_style_key *key = g_new(ns_merged_style_key, 1);
    *key = probe;
    key->base = g_strdup(base_url);
    char *copy = g_malloc((gsize)len + 1);
    memcpy(copy, css, (gsize)len);
    copy[len] = '\0';
    key->css = copy;
    g_hash_table_replace(g_merged_style_cache, key, entry);
    return sh;
}

/* Returns a URL-keyed cached parse of a linked sheet, owned by the cache. */
ns_css_stylesheet *
ns_css_stylesheet_parse_url_cached(const char *url, const char *css, gssize len)
{
    if (!css) return NULL;
    if (!url || !*url) return ns_css_stylesheet_parse(css, len);
    if (!g_link_sheet_cache)
        g_link_sheet_cache =
            g_hash_table_new_full(g_str_hash, g_str_equal,
                                  g_free, ns_link_sheet_cached_free);
    ns_link_sheet_cached *hit = g_hash_table_lookup(g_link_sheet_cache, url);
    if (hit && ns_css_media_record_holds(hit->media))
        return hit->sheet;
    GPtrArray *media = NULL;
    ns_css_stylesheet *sh = css_parse_recording_media(css, len, NULL, &media);
    if (!sh) return NULL;
    sh->cached = TRUE;
    ns_link_sheet_cached *entry = g_new0(ns_link_sheet_cached, 1);
    entry->sheet = sh;
    entry->media = media;
    g_hash_table_replace(g_link_sheet_cache, g_strdup(url), entry);
    return sh;
}

/* Parses CSS bytes into a new sheet, forcing it into layer_name if given. */
static ns_css_stylesheet *
ns_css_stylesheet_parse_in_layer(GBytes *bytes, const char *layer_name)
{
    gsize len = 0;
    const char *data = g_bytes_get_data(bytes, &len);
    ns_css_stylesheet *sh = ns_css_stylesheet_parse(data, (gssize)len);
    if (sh && layer_name)
        ns_css_stylesheet_force_layer(sh, layer_name);
    return sh;
}

/* Returns a cached @import sheet keyed by layer and URL; reparses on bytes/media change. */
ns_css_stylesheet *
ns_css_stylesheet_parse_import_cached(const char *url, const char *layer_name,
                                      GBytes *bytes)
{
    if (!bytes) return NULL;
    if (!url || !*url) return ns_css_stylesheet_parse_in_layer(bytes, layer_name);
    if (!g_import_sheet_cache)
        g_import_sheet_cache =
            g_hash_table_new_full(g_str_hash, g_str_equal,
                                  g_free, ns_import_sheet_cached_free);
    char *key = g_strdup_printf("%c%zu:%s|%s",
                                layer_name ? 'L' : '-',
                                layer_name ? strlen(layer_name) : (gsize)0,
                                layer_name ? layer_name : "", url);
    ns_import_sheet_cached *hit = g_hash_table_lookup(g_import_sheet_cache, key);
    if (hit && (hit->bytes == bytes || g_bytes_equal(hit->bytes, bytes)) &&
        ns_css_media_record_holds(hit->media)) {
        g_free(key);
        return hit->sheet;
    }
    gsize data_len = 0;
    const char *data = g_bytes_get_data(bytes, &data_len);
    GPtrArray *media = NULL;
    ns_css_stylesheet *sh = css_parse_recording_media(data, (gssize)data_len,
                                                      layer_name, &media);
    if (!sh) {
        g_free(key);
        return NULL;
    }
    sh->cached = TRUE;
    ns_import_sheet_cached *entry = g_new0(ns_import_sheet_cached, 1);
    entry->bytes = g_bytes_ref(bytes);
    entry->sheet = sh;
    entry->media = media;
    g_hash_table_replace(g_import_sheet_cache, key, entry);
    return sh;
}

/* Finds a selector's host/adopt scope marker in ancestor compounds; FALSE if none or mixed. */
static gboolean
css_selector_host_scope(const ns_css_selector *sel, const char **host)
{
    guint n = sel->compounds ? sel->compounds->len : 0;
    for (guint k = 0; k < n; k++) {
        if (k + 1 < n) {
            ns_css_comb comb =
                g_array_index(sel->combinators, ns_css_comb, k + 1);
            if (comb != NS_CSS_COMB_DESCENDANT && comb != NS_CSS_COMB_CHILD)
                continue;
        }
        const ns_css_simple *c = g_ptr_array_index(sel->compounds, k);
        for (guint i = 0; c->attrs && i < c->attrs->len; i++) {
            const ns_css_attr_pred *a =
                &g_array_index(c->attrs, ns_css_attr_pred, i);
            if (!a->name || !a->value || !*a->value || a->namespace_uri ||
                a->namespace_any || a->case_insensitive)
                continue;
            gboolean marker =
                (a->op == NS_CSS_ATTR_EQ &&
                 g_ascii_strcasecmp(a->name, NS_HOST_SCOPE_ATTR) == 0) ||
                (a->op == NS_CSS_ATTR_WORD &&
                 g_ascii_strcasecmp(a->name, NS_ADOPT_SCOPE_ATTR) == 0);
            if (!marker) continue;
            if (*host && strcmp(*host, a->value) != 0) return FALSE;
            *host = a->value;
            return TRUE;
        }
    }
    return FALSE;
}

/* Hashes CSS text skipping host scope ids, so identical shadow sheets share a template. */
static guint64
css_host_scope_template(const char *css)
{
    static const char host_marker[] = NS_HOST_SCOPE_ATTR "=\"";
    static const char adopt_marker[] = NS_ADOPT_SCOPE_ATTR "~=\"";
    guint64 h = 1469598103934665603ULL;
    for (const char *p = css; *p; p++) {
        h = (h ^ (guchar)*p) * 1099511628211ULL;
        if (*p != '[') continue;
        gsize skip = 0;
        if (strncmp(p + 1, host_marker, sizeof host_marker - 1) == 0)
            skip = sizeof host_marker - 1;
        else if (strncmp(p + 1, adopt_marker, sizeof adopt_marker - 1) == 0)
            skip = sizeof adopt_marker - 1;
        if (!skip) continue;
        p += skip;
        while (p[1] && p[1] != '"') p++;
    }
    return h;
}

/* Sets the sheet's host scope when every rule is scoped to the same single host. */
static void
css_sheet_find_host_scope(ns_css_stylesheet *sh, const char *css)
{
    if ((sh->imports && sh->imports->len) ||
        (sh->layer_names && sh->layer_names->len) ||
        (sh->layers && g_hash_table_size(sh->layers)) ||
        (sh->font_faces && sh->font_faces->len) ||
        (sh->keyframes && sh->keyframes->len) ||
        (sh->property_rules && sh->property_rules->len) ||
        sh->page_rule || !sh->rules || sh->rules->len == 0)
        return;
    const char *host = NULL;
    for (guint i = 0; i < sh->rules->len; i++) {
        const ns_css_rule *r = g_ptr_array_index(sh->rules, i);
        if (!r || r->layer_name || r->scopes || !r->selectors ||
            r->selectors->len == 0)
            return;
        for (guint j = 0; j < r->selectors->len; j++)
            if (!css_selector_host_scope(g_ptr_array_index(r->selectors, j),
                                         &host))
                return;
    }
    sh->host_scope = g_strdup(host);
    sh->host_scope_template = css_host_scope_template(css);
}

/* Returns the cached sheet for a style element, reparsing on text/media change; takes css. */
static ns_css_stylesheet *
style_sheet_cached_take(ns_node *style, char *css)
{
    if (!g_style_el_cache)
        g_style_el_cache = g_hash_table_new_full(g_direct_hash, g_direct_equal,
                                                 NULL, ns_style_el_cached_free);
    ns_style_el_cached *e = g_hash_table_lookup(g_style_el_cache, style);
    if (e && strcmp(e->css, css) == 0 && ns_css_media_record_holds(e->media)) {
        g_free(css);
        return e->sheet;
    }
    GPtrArray *media = NULL;
    ns_css_stylesheet *sh = css_parse_recording_media(css, -1, NULL, &media);
    if (!sh) {
        g_free(css);
        return NULL;
    }
    sh->cached = TRUE;
    css_sheet_find_host_scope(sh, css);
    ns_style_el_cached *ne = g_new0(ns_style_el_cached, 1);
    ne->css = css;
    ne->sheet = sh;
    ne->media = media;
    g_hash_table_replace(g_style_el_cache, style, ne);
    return sh;
}

ns_css_stylesheet *
ns_css_stylesheet_from_style_text_cached(ns_node *style, const char *css)
{
    return css ? style_sheet_cached_take(style, g_strdup(css)) : NULL;
}

/* Computes styles for doc, applying each author sheet only to its owning document. */
GHashTable *
ns_css_compute_scoped(ns_node *doc,
                      const ns_css_stylesheet *const *author_sheets,
                      const ns_node *const *sheet_docs, gsize n_sheets)
{
    const ns_node *const *outer_docs = g_author_sheet_docs;
    const ns_node *outer_doc = g_cascade_doc;
    g_author_sheet_docs = sheet_docs;
    g_cascade_doc = doc;
    GHashTable *styles = ns_css_compute(doc, author_sheets, n_sheets);
    g_author_sheet_docs = outer_docs;
    g_cascade_doc = outer_doc;
    return styles;
}

/* Computes styles for every node of doc, incrementally when possible; NULL in delta mode. */
static GHashTable *
ns_css_compute(ns_node *doc,
               const ns_css_stylesheet *const *author_sheets,
               gsize n_sheets)
{
    GHashTable *out = g_hash_table_new_full(g_direct_hash, g_direct_equal,
                                            NULL, (GDestroyNotify)ns_style_free);

    g_pragma_valid = FALSE;
    GPtrArray *delta_request = g_delta_request;
    g_delta_request = NULL;

    const ns_css_stylesheet *cached_ua = ua_sheet_for(doc);

    gboolean profile = g_getenv("NS_PROFILE") != NULL;
    gint64 t0 = profile ? g_get_monotonic_time() : 0;
    (void)ns_css_rule_index_ensure(cached_ua);
    for (gsize i = 0; i < n_sheets; i++)
        (void)ns_css_rule_index_ensure(author_sheets[i]);
    gint64 t_idx = profile ? g_get_monotonic_time() : 0;

    GHashTable *layer_ranks = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                    g_free, NULL);
    css_layer_rank_add_sheet(layer_ranks, cached_ua);
    for (gsize i = 0; i < n_sheets; i++)
        css_layer_rank_add_sheet(layer_ranks, author_sheets[i]);
    css_layer_ranks_finalize(layer_ranks);

    g_registered_props = g_hash_table_new(g_str_hash, g_str_equal);
    css_collect_property_rules(g_registered_props, cached_ua);
    for (gsize i = 0; i < n_sheets; i++)
        css_collect_property_rules(g_registered_props, author_sheets[i]);
    if (g_js_registered_props) {
        GHashTableIter it;
        gpointer k, v;
        g_hash_table_iter_init(&it, g_js_registered_props);
        while (g_hash_table_iter_next(&it, &k, &v))
            g_hash_table_replace(g_registered_props, k, v);
    }

    double root_px = 0;
    g_root_line_px = 0;
    if (g_decl_sheet_cache && g_hash_table_size(g_decl_sheet_cache) >= 8192) {
        g_hash_table_remove_all(g_decl_sheet_cache);
        style_memo_clear();
    }
    if (!g_cq_stack)
        g_cq_stack = g_array_new(FALSE, FALSE, sizeof(ns_cq_container));
    g_array_set_size(g_cq_stack, 0);
    if (!g_share_scratch)
        g_share_scratch = g_byte_array_sized_new(512);
    g_style_share = g_hash_table_new_full(share_key_hash, share_key_equal,
                                          share_key_free, NULL);
    g_var_adjust_cache = g_hash_table_new_full(
        g_direct_hash, g_direct_equal,
        (GDestroyNotify)ns_var_map_unref, (GDestroyNotify)ns_var_map_unref);
    g_has_memo = g_hash_table_new_full(has_memo_hash, has_memo_equal,
                                       g_free, NULL);
    g_pending_parse_cache = g_hash_table_new_full(
        g_str_hash, g_str_equal, g_free,
        (GDestroyNotify)ns_css_declarations_free);
    css_sibling_positions_begin();

    guint64 keys_sig = 0;
    guint64 sig = incr_sheet_sig(cached_ua, author_sheets, n_sheets,
                                 &keys_sig);
    if (keys_sig != g_incr_has_sig) {
        if (g_has_cq_keys) g_hash_table_remove_all(g_has_cq_keys);
        else g_has_cq_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                   g_free, NULL);
        if (g_has_self_keys) g_hash_table_remove_all(g_has_self_keys);
        else g_has_self_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                     g_free, NULL);
        if (g_has_self_attrs) g_ptr_array_set_size(g_has_self_attrs, 0);
        else g_has_self_attrs =
            g_ptr_array_new_with_free_func(incr_attr_dep_free);
        if (g_has_cq_attrs) g_ptr_array_set_size(g_has_cq_attrs, 0);
        else g_has_cq_attrs =
            g_ptr_array_new_with_free_func(incr_attr_dep_free);
        g_has_cq_loose = FALSE;
        g_has_loose_self = FALSE;
        g_has_loose_sibling = FALSE;
        g_has_sibling_args = FALSE;
        if (g_has_loose_desc) g_hash_table_remove_all(g_has_loose_desc);
        else g_has_loose_desc = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                      g_free, NULL);
        incr_collect_has_cq_keys(cached_ua);
        for (gsize i = 0; i < n_sheets; i++)
            incr_collect_has_cq_keys(author_sheets[i]);
        incr_own_attr_deps(g_has_cq_attrs);
        incr_own_attr_deps(g_has_self_attrs);
        g_incr_eligible = !g_has_cq_loose;
        g_incr_has_sig = keys_sig;
    }
    gboolean incr_usable = g_getenv("NS_NO_INCR_RESTYLE") == NULL
        && g_incr_eligible
        && fabs(g_incr_zoom - 1.0) <= 0.001;
    guint64 cq_sig = cq_map_signature(g_cq_map);
    gboolean incr_want = incr_usable;
    g_incr_pass_active = incr_want
        && g_incr_prev_styles != NULL
        && g_incr_prev_doc == doc
        && g_incr_prev_sig == sig
        && g_incr_prev_cq_sig == cq_sig
        && g_incr_prev_vw == g_viewport_w
        && g_incr_prev_vh == g_viewport_h;
    g_incr_reused = 0;
    g_incr_recomputed = 0;
    if (!g_incr_pass_active) style_memo_clear();
    g_delta_out = NULL;
    if (delta_request && g_incr_pass_active && g_incr_prev_styles &&
        incr_struct_hash(doc) == g_incr_struct_hash)
        g_delta_out = delta_request;
    if (!g_incr_pass_active && !g_cq_map)
        g_container_units_seen = FALSE;

    incr_ensure_struct_keys(cached_ua, author_sheets, n_sheets, keys_sig);
    if (g_incr_pass_active) {
        incr_mark_state_focus(g_incr_prev_focus, g_css_focus_node);
        incr_mark_state_chain(g_incr_prev_hover, g_css_hover_node,
                              g_state_has_hover);
        incr_mark_state_chain(g_incr_prev_active, g_css_active_node,
                              g_state_has_active);
    }

    GHashTable *host_sheets = incr_host_sheet_keys(author_sheets, n_sheets);
    if (g_incr_pass_active)
        incr_mark_changed_hosts(doc, g_incr_prev_host_sheets, host_sheets);
    guint incr_marked = g_incr_dirty ? g_hash_table_size(g_incr_dirty) : 0;
    if (g_incr_pass_active) incr_path_build();
    else if (g_incr_path) g_hash_table_remove_all(g_incr_path);
    memset(g_ancestor_filter, 0, sizeof g_ancestor_filter);
    g_ancestor_filter_active = TRUE;
    cascade_walk(doc, cached_ua, author_sheets, n_sheets, NULL, NULL,
                 &root_px, layer_ranks, out, FALSE);
    g_ancestor_filter_active = FALSE;
    g_ancestor_filter_subject = NULL;

    if (incr_want && g_delta_out) {
        if (g_incr_before_styles) g_hash_table_destroy(g_incr_before_styles);
        g_incr_before_styles = NULL;
        if (g_incr_before_delta) g_hash_table_remove_all(g_incr_before_delta);
        else g_incr_before_delta = g_hash_table_new_full(
            g_direct_hash, g_direct_equal, NULL, (GDestroyNotify)ns_style_free);
        for (guint i = 0; i < g_delta_out->len; i++) {
            ns_css_style_change *c = g_ptr_array_index(g_delta_out, i);
            ns_style *old = g_hash_table_lookup(g_incr_prev_styles, c->node);
            if (old) {
                old->ref++;
                g_hash_table_replace(g_incr_before_delta, (gpointer)c->node,
                                     old);
            }
            c->style->ref++;
            g_hash_table_replace(g_incr_prev_styles, (gpointer)c->node,
                                 c->style);
        }
    } else if (incr_want) {
        GHashTable *new_prev = g_hash_table_new_full(
            g_direct_hash, g_direct_equal, NULL, (GDestroyNotify)ns_style_free);
        GHashTableIter pit; gpointer pk, pv;
        g_hash_table_iter_init(&pit, out);
        while (g_hash_table_iter_next(&pit, &pk, &pv)) {
            ((ns_style *)pv)->ref++;
            g_hash_table_insert(new_prev, pk, pv);
        }
        if (g_incr_before_styles) g_hash_table_destroy(g_incr_before_styles);
        g_incr_before_styles = g_incr_prev_styles;
        g_incr_prev_styles = new_prev;
        g_clear_pointer(&g_incr_before_delta, g_hash_table_destroy);
        g_incr_struct_hash = incr_struct_hash(doc);
    }
    if (incr_want) {
        g_incr_serial++;
        g_incr_prev_doc = doc;
        g_incr_prev_sig = sig;
        if (g_incr_prev_host_sheets)
            g_hash_table_destroy(g_incr_prev_host_sheets);
        g_incr_prev_host_sheets = host_sheets;
        host_sheets = NULL;
        g_incr_prev_cq_sig = cq_sig;
        g_incr_prev_vw = g_viewport_w;
        g_incr_prev_vh = g_viewport_h;
        g_incr_prev_focus = g_css_focus_node;
        g_incr_prev_hover = g_css_hover_node;
        g_incr_prev_active = g_css_active_node;
        if (g_getenv("NS_PROFILE"))
            g_printerr("[incr] active=%d marked=%u reused=%u recomputed=%u\n",
                       g_incr_pass_active, incr_marked, g_incr_reused,
                       g_incr_recomputed);
    } else if (g_incr_prev_styles && !incr_usable) {
        g_hash_table_destroy(g_incr_prev_styles);
        g_incr_prev_styles = NULL;
        g_incr_prev_doc = NULL;
        g_clear_pointer(&g_incr_before_delta, g_hash_table_destroy);
        g_incr_serial++;
        if (g_incr_before_styles) g_hash_table_destroy(g_incr_before_styles);
        g_incr_before_styles = NULL;
    }
    if (host_sheets) g_hash_table_destroy(host_sheets);
    if (g_incr_dirty) g_hash_table_remove_all(g_incr_dirty);
    if (g_incr_self_dirty) g_hash_table_remove_all(g_incr_self_dirty);
    if (g_incr_has_walked) g_hash_table_remove_all(g_incr_has_walked);
    if (g_incr_desc_inv) g_hash_table_remove_all(g_incr_desc_inv);
    if (g_desc_inv_stack) {
        g_ptr_array_set_size(g_desc_inv_stack, 0);
        g_array_set_size(g_desc_inv_depths, 0);
    }

    g_hash_table_destroy(g_has_memo);
    g_has_memo = NULL;
    g_hash_table_destroy(g_pending_parse_cache);
    g_pending_parse_cache = NULL;
    css_sibling_positions_end();
    g_hash_table_destroy(g_style_share);
    g_style_share = NULL;
    g_hash_table_destroy(g_var_adjust_cache);
    g_var_adjust_cache = NULL;
    g_hash_table_destroy(layer_ranks);
    g_hash_table_destroy(g_registered_props);
    g_registered_props = NULL;
    gint64 t_cascade = profile ? g_get_monotonic_time() : 0;
    if (profile)
        g_printerr("[profile]   css.idx=%.1fms css.cascade=%.1fms\n",
                   (t_idx - t0) / 1000.0,
                   (t_cascade - t_idx) / 1000.0);
    if (g_delta_out) {
        g_delta_out = NULL;
        g_hash_table_destroy(out);
        return NULL;
    }
    return out;
}

/* Scales a computed length font-size by factor, copy-on-write. */
void
ns_css_style_scale_font_size(ns_style *s, double factor)
{
    if (!s || !s->values[NS_CSS_FONT_SIZE] ||
        s->values[NS_CSS_FONT_SIZE]->kind != NS_CSS_V_LENGTH)
        return;
    ns_css_value_cow(s, NS_CSS_FONT_SIZE)->u.length.v *= factor;
}
